fn immutable_artifact_verification_failure(error: impl std::fmt::Display) -> StepOutput {
    StepOutput {
        result: StepResult::Failed {
            summary: format!("immutable Artifact input could not be verified: {error}"),
        },
        summary: Some("immutable Artifact input could not be verified".to_string()),
        output: None,
    }
}

fn artifact_snapshot_capture_failure(error: impl std::fmt::Display) -> StepOutput {
    StepOutput {
        result: StepResult::Failed {
            summary: format!("artifact snapshot capture failed: {error}"),
        },
        summary: Some("artifact snapshot capture failed".to_string()),
        output: None,
    }
}

fn worker_failure_output(error: String) -> StepOutput {
    StepOutput {
        result: StepResult::Failed {
            summary: error.clone(),
        },
        summary: Some(error),
        output: None,
    }
}

fn gate_approval_request(step_name: &str, evidence: &GateEvidence) -> StepApprovalRequestDraft {
    let mut body = format!(
        "Assessment gate '{step_name}' requires a human decision for the unresolved evidence below.\n"
    );
    for disposition in evidence
        .adjudication
        .dispositions
        .iter()
        .filter(|disposition| disposition.disposition == DispositionKind::Unresolved)
    {
        let finding = evidence
            .assessments
            .get(&disposition.source_step)
            .and_then(|assessment| {
                assessment
                    .findings
                    .iter()
                    .find(|finding| finding.id == disposition.finding_id)
            });
        body.push_str(&format!(
            "\n- `{}:{}`\n  - Finding: {}\n  - Rationale: {}\n  - Assessment evidence: `{}`\n  - Adjudication evidence: `{}`\n",
            disposition.source_step,
            disposition.finding_id,
            finding
                .map(|finding| finding.summary.as_str())
                .unwrap_or("Unavailable"),
            disposition.rationale,
            finding
                .map(|finding| finding.evidence.to_string())
                .unwrap_or_else(|| "null".to_string()),
            disposition.evidence,
        ));
    }
    StepApprovalRequestDraft {
        schema_version: 1,
        title: format!("Resolve assessment gate '{step_name}'"),
        body,
        state: None,
    }
}

