impl PendingWorkerReservation {
    fn new(
        registry: CancellationRegistry,
        identity: WorkerIdentity,
        completion: watch::Sender<bool>,
    ) -> Self {
        Self {
            registry,
            identity,
            completion: Some(completion),
        }
    }

    fn mark_launched(mut self) -> Result<watch::Sender<bool>, EnsembleError> {
        if !mark_worker_launched(&self.registry, &self.identity) {
            return Err(AgentError::PromptError {
                reason: format!(
                    "worker reservation disappeared before launch for issue '{}' step '{}'",
                    self.identity.issue_id, self.identity.step_name
                ),
            }
            .into());
        }
        Ok(self
            .completion
            .take()
            .expect("pending worker reservation owns its completion signal"))
    }
}

impl Drop for PendingWorkerReservation {
    fn drop(&mut self) {
        if self.completion.is_some() {
            rollback_worker_reservation(&self.registry, &self.identity);
            if let Some(completion) = self.completion.take() {
                let _ = completion.send(true);
            }
        }
    }
}

const INTERACTION_RESUME_REASON_PREFIX: &str = "interaction_resume:";

fn terminal_transition_retry_due(
    transition: &PendingTerminalTransition,
    max_backoff_ms: u64,
    now: chrono::DateTime<Utc>,
) -> bool {
    let Some(last_attempted_at) = transition.last_attempted_at else {
        return true;
    };
    let elapsed_ms = now
        .signed_duration_since(last_attempted_at)
        .num_milliseconds();
    let delay_ms =
        i64::try_from(calculate_backoff(transition.attempt, max_backoff_ms)).unwrap_or(i64::MAX);
    elapsed_ms >= delay_ms
}

fn interaction_id_from_resume_reason(reason: Option<&str>) -> Option<&str> {
    reason?.strip_prefix(INTERACTION_RESUME_REASON_PREFIX)
}

