#[derive(Clone, Default)]
pub(crate) struct QuiescingLatch(Arc<std::sync::Mutex<bool>>);

struct DispatchPermit;

/// The terminal result of a bounded scheduler run.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum DrainOutcome {
    Success,
    WaitingForHuman,
    PartialDrain,
}

/// Stable summary of residual scheduler ownership at a bounded-run boundary.
#[derive(Debug, Clone, Default, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub struct ResidualWorkSummary {
    pub runnable: Vec<String>,
    pub retrying: Vec<String>,
    pub externally_waiting: Vec<String>,
    pub delivery_or_finalization: Vec<String>,
    pub parked: Vec<String>,
}

#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub struct DrainResult {
    pub outcome: DrainOutcome,
    #[serde(default)]
    pub residual: ResidualWorkSummary,
}

impl QuiescingLatch {
    pub(crate) fn request(&self) {
        *self
            .0
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner()) = true;
    }

    fn is_requested(&self) -> bool {
        *self
            .0
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
    }

    /// Linearizes candidate and retry dispatch against a concurrent quiescence request.
    fn begin_dispatch(&self) -> Option<DispatchPermit> {
        (!*self
            .0
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner()))
        .then_some(DispatchPermit)
    }
}

pub struct OrchestratorRuntimeParts {
    pub state: Arc<RwLock<OrchestratorState>>,
    pub config: Arc<RwLock<EnsembleConfig>>,
    pub tracker: Arc<dyn IssueTracker>,
    pub agent_runner: Arc<dyn AgentRunner>,
    pub acceptance_runner: Arc<dyn AcceptanceCommandRunner>,
    pub workspace_mgr: WorkspaceManager,
    pub refresh_requested: Arc<tokio::sync::Notify>,
    pub cancellation_registry: CancellationRegistry,
    pub event_bus: EventBus,
    pub transcript_event_bus: TranscriptEventBus,
    pub workspace_root: std::path::PathBuf,
}

pub(super) struct RunningHistoryRecordInput<'a> {
    outcome: &'a str,
    last_error: Option<String>,
    running_entry: &'a crate::tracker::model::RunningEntry,
    run: &'a PipelineRun,
    completed_at: chrono::DateTime<Utc>,
    artifacts: Option<RunArtifacts>,
}

struct WaitingHistoryRecordInput<'a> {
    outcome: &'a str,
    last_error: Option<String>,
    waiting_entry: &'a WaitingOnHumanEntry,
    run: &'a PipelineRun,
    completed_at: chrono::DateTime<Utc>,
    artifacts: Option<RunArtifacts>,
}

struct RejectedGateOwnerSnapshot {
    run: PipelineRun,
    waiting: WaitingOnHumanEntry,
    retry: Option<RetryEntry>,
    running: Option<RunningEntry>,
    claimed: bool,
    resume_requested: bool,
}

impl Orchestrator {
    fn action_mutation_lock(&self, issue_id: &str) -> Arc<tokio::sync::Mutex<()>> {
        let mut locks = self
            .action_mutation_locks
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        locks.retain(|_, lock| lock.strong_count() > 0);
        if let Some(lock) = locks.get(issue_id).and_then(std::sync::Weak::upgrade) {
            return lock;
        }
        let lock = Arc::new(tokio::sync::Mutex::new(()));
        locks.insert(issue_id.to_string(), Arc::downgrade(&lock));
        lock
    }
    fn drain_snapshot(state: &OrchestratorState) -> ResidualWorkSummary {
        let mut summary = ResidualWorkSummary {
            runnable: state.running.keys().cloned().collect(),
            retrying: state.retry_attempts.keys().cloned().collect(),
            externally_waiting: state.waiting_on_human.keys().cloned().collect(),
            delivery_or_finalization: state
                .delivery
                .keys()
                .chain(state.finalize.keys())
                .cloned()
                .collect(),
            parked: state.parked_runs.keys().cloned().collect(),
        };
        summary.runnable.sort();
        summary.retrying.sort();
        summary.externally_waiting.sort();
        summary.delivery_or_finalization.sort();
        summary.delivery_or_finalization.dedup();
        summary.parked.sort();
        summary
    }

    /// Drive the same tick loop without installing the daemon watcher.
    pub async fn run_once(&mut self, deadline: Duration) -> DrainResult {
        {
            let config = self.config.read().await;
            let mut state = self.state.write().await;
            state.poll_interval_ms = config.polling.interval_ms;
            state.max_concurrent_agents = config.concurrency.max_concurrent_agents;
            state.init_state_lists(&config);
        }
        let started = std::time::Instant::now();
        let mut consecutive_empty = 0_u8;
        loop {
            self.handle_tick().await;
            while let Ok(event) = self.worker_rx.lock().await.try_recv() {
                self.handle_worker_event(event).await;
            }
            self.handle_retry_fires().await;
            let state = self.state.read().await;
            let summary = Self::drain_snapshot(&state);
            drop(state);
            if summary.runnable.is_empty()
                && summary.retrying.is_empty()
                && summary.externally_waiting.is_empty()
                && summary.delivery_or_finalization.is_empty()
                && summary.parked.is_empty()
            {
                consecutive_empty = consecutive_empty.saturating_add(1);
                if consecutive_empty == 2 {
                    return DrainResult {
                        outcome: DrainOutcome::Success,
                        residual: summary,
                    };
                }
            } else {
                consecutive_empty = 0;
                if !summary.externally_waiting.is_empty()
                    && summary.runnable.is_empty()
                    && summary.retrying.is_empty()
                    && summary.delivery_or_finalization.is_empty()
                    && summary.parked.is_empty()
                {
                    return DrainResult {
                        outcome: DrainOutcome::WaitingForHuman,
                        residual: summary,
                    };
                }
            }
            if started.elapsed() >= deadline {
                return DrainResult {
                    outcome: DrainOutcome::PartialDrain,
                    residual: summary,
                };
            }
            tokio::time::sleep(Duration::from_millis(10)).await;
        }
    }

    fn park_exhausted_recovery(
        state: &mut OrchestratorState,
        config: &EnsembleConfig,
        request: ParkedRecoveryRequest<'_>,
        transitions: &mut Vec<PipelineTransitionInput>,
    ) -> Option<(String, u32, String)> {
        config.scheduler.recovery.as_ref()?;
        state.parked_runs.insert(
            request.issue_id.to_string(),
            ParkedRunEntry {
                issue_id: request.issue_id.to_string(),
                identifier: request.entry.identifier.clone(),
                condition_key: "runtime.scheduler.recovery_exhausted".to_string(),
                attempt: request.attempt,
                reason: request.reason.to_string(),
                parked_at: Utc::now(),
            },
        );
        state.add_runtime_seconds(request.entry);
        if let Some(input) = Self::transition_input_for_run(
            state,
            request.issue_id,
            &request.entry.identifier,
            PipelineTransitionKind::RunParked,
            Some(request.step.to_string()),
            Some(request.reason.to_string()),
            None,
        ) {
            transitions.push(input);
        }
        Some((
            request.entry.identifier.clone(),
            request.attempt,
            request.reason.to_string(),
        ))
    }

    fn automatic_recovery_max_attempts(config: &EnsembleConfig) -> u32 {
        config
            .scheduler
            .recovery
            .as_ref()
            .map(|recovery| recovery.max_attempts)
            .unwrap_or(config.max_cycles)
    }

    fn effective_step_timeout_ms(timeout_ms: Option<u64>, config: &EnsembleConfig) -> u64 {
        timeout_ms.unwrap_or(config.agent.turn_timeout_ms)
    }

    fn finalization_attempt_is_current(
        attempt: Option<&RunningAttemptIdentity>,
        state: &OrchestratorState,
        issue_id: &str,
    ) -> bool {
        attempt.is_some_and(|attempt| attempt.is_current(state, issue_id))
    }

    /// Create a new Orchestrator.
    pub fn new(
        config: Arc<RwLock<EnsembleConfig>>,
        tracker: Arc<dyn IssueTracker>,
        agent_runner: Arc<dyn AgentRunner>,
        workspace_mgr: WorkspaceManager,
        config_dir: &Path,
        shutdown_rx: mpsc::Receiver<()>,
    ) -> Self {
        let (concurrency, poll_interval_ms) = {
            let config_guard = futures::executor::block_on(config.read());
            let concurrency = config_guard.concurrency.clone();
            let poll_interval_ms = config_guard.polling.interval_ms;
            (concurrency, poll_interval_ms)
        };
        let state = Arc::new(RwLock::new(OrchestratorState::new(
            poll_interval_ms,
            &concurrency,
        )));
        let refresh_requested = Arc::new(tokio::sync::Notify::new());
        Self::new_with_state(
            OrchestratorRuntimeParts {
                state,
                config,
                tracker,
                agent_runner,
                acceptance_runner: Arc::new(ShellAcceptanceCommandRunner),
                workspace_mgr,
                refresh_requested,
                cancellation_registry: new_cancellation_registry(),
                event_bus: EventBus::new(),
                transcript_event_bus: TranscriptEventBus::new(),
                workspace_root: config_dir.to_path_buf(),
            },
            config_dir,
            shutdown_rx,
        )
    }

    /// Create a new Orchestrator using externally managed state and refresh signaling.
    pub fn new_with_state(
        parts: OrchestratorRuntimeParts,
        config_dir: &Path,
        shutdown_rx: mpsc::Receiver<()>,
    ) -> Self {
        let history_store = futures::executor::block_on(HistoryStore::new(
            parts.workspace_root.join(".ensemble").join("history.db"),
        ))
        .map_err(|error| {
            warn!(
                error = %error,
                "failed to initialize sqlite history store; continuing without durable history or timeline persistence"
            );
            error
        })
        .ok();
        Self::new_with_state_and_history(parts, config_dir, shutdown_rx, history_store)
    }

    pub(crate) fn new_with_state_and_history(
        parts: OrchestratorRuntimeParts,
        config_dir: &Path,
        shutdown_rx: mpsc::Receiver<()>,
        history_store: Option<HistoryStore>,
    ) -> Self {
        let (worker_tx, worker_rx) = mpsc::channel(1000);
        let (command_tx, command_rx) = mpsc::channel(100);
        let timeline_persistence = history_store.clone().map(TimelinePersistence::new);
        let attention_reporter = history_store.clone().map(AttentionReporter::new);

        Self {
            state: parts.state,
            config: parts.config,
            tracker: parts.tracker,
            agent_runner: parts.agent_runner,
            acceptance_runner: parts.acceptance_runner,
            delivery_remote: Arc::new(CliDeliveryRemote),
            interaction_store: InteractionStore::new(config_dir.to_path_buf()),
            workspace_mgr: Arc::new(parts.workspace_mgr),
            refresh_requested: parts.refresh_requested,
            cancellation_registry: parts.cancellation_registry,
            history_write_lock: Arc::new(tokio::sync::Mutex::new(())),
            action_mutation_locks: Arc::new(std::sync::Mutex::new(HashMap::new())),
            history_store,
            attention_reporter,
            attention_reconciled_on_startup: AtomicBool::new(false),
            pipeline_journal: PipelineRunJournal::new(config_dir.to_path_buf()),
            pipeline_journal_restored: AtomicBool::new(false),
            pending_run_started_transitions: Box::new(std::sync::Mutex::new(HashMap::new())),
            pending_immutable_launches: std::sync::Mutex::new(HashMap::new()),
            pending_acceptance_transitions: std::sync::Mutex::new(HashMap::new()),
            pending_ownership_leases: std::sync::Mutex::new(HashMap::new()),
            event_bus: parts.event_bus,
            timeline_persistence,
            transcript_persistence: Some(TranscriptPersistence::new_with_event_bus(
                parts.workspace_root,
                parts.transcript_event_bus,
            )),
            worker_tx,
            worker_rx: Arc::new(tokio::sync::Mutex::new(worker_rx)),
            command_tx,
            command_rx,
            shutdown_rx,
            quiescing: QuiescingLatch::default(),
            #[cfg(test)]
            finalization_commit_test_barriers: None,
            #[cfg(test)]
            finalization_run_count: AtomicUsize::new(0),
        }
    }

    #[cfg(test)]
    fn set_finalization_commit_test_barriers(
        &mut self,
        before_commit: Arc<tokio::sync::Barrier>,
        resume_commit: Arc<tokio::sync::Barrier>,
    ) {
        self.finalization_commit_test_barriers = Some((before_commit, resume_commit));
    }

    #[cfg(test)]
    async fn wait_for_finalization_commit_test_barriers(&self) {
        if let Some((before_commit, resume_commit)) = &self.finalization_commit_test_barriers {
            before_commit.wait().await;
            resume_commit.wait().await;
        }
    }

    /// Get a reference to the orchestrator state for API consumers.
    pub fn state(&self) -> Arc<RwLock<OrchestratorState>> {
        Arc::clone(&self.state)
    }

    pub(crate) fn worker_event_receiver_owner(
        &self,
    ) -> Arc<tokio::sync::Mutex<mpsc::Receiver<OrchestratorWorkerEvent>>> {
        Arc::clone(&self.worker_rx)
    }

    pub(crate) fn quiescing_latch_owner(&self) -> QuiescingLatch {
        self.quiescing.clone()
    }

    pub(crate) fn command_sender_owner(&self) -> mpsc::Sender<OrchestratorCommand> {
        self.command_tx.clone()
    }

    #[cfg(test)]
    pub(crate) fn persist_timeline_for_test(
        &self,
        record: crate::timeline::model::TimelineEventRecord,
    ) {
        self.timeline_persistence
            .as_ref()
            .expect("test orchestrator should have timeline persistence")
            .send(record);
    }

    #[cfg(test)]
    pub(crate) fn persist_transcript_for_test(&self, request: TranscriptPersistRequest) {
        self.transcript_persistence
            .as_ref()
            .expect("test orchestrator should have transcript persistence")
            .send(request);
    }

    async fn handle_command(&self, command: OrchestratorCommand) {
        match command {
            OrchestratorCommand::QueueManualStepRetry { command, response } => {
                if self.quiescing.is_requested() {
                    let _ = response.send(Err(ManualStepRetryError::RuntimeUnavailable));
                    return;
                }
                let retry_limits = {
                    let state = self.state.read().await;
                    if state.get_pipeline_run(&command.issue_id).is_none() {
                        let _ = response.send(Err(ManualStepRetryError::NoPipelineRun));
                        return;
                    }
                    state
                        .get_pipeline_config(&command.issue_id)
                        .map(|config| (config.agent.max_retry_backoff_ms, config.max_cycles))
                };
                let Some((max_backoff_ms, max_cycles)) = retry_limits else {
                    let _ = response.send(Err(ManualStepRetryError::RuntimeUnavailable));
                    return;
                };
                let result = queue_manual_step_retry(
                    &self.state,
                    &self.pipeline_journal,
                    &self.interaction_store,
                    ManualStepRetryRequest {
                        issue_id: &command.issue_id,
                        identifier: &command.identifier,
                        step_name: &command.step_name,
                        max_backoff_ms,
                        max_cycles,
                    },
                )
                .await;
                let _ = response.send(result);
            }
            OrchestratorCommand::QueueManualWholeIssueRetry { command, response } => {
                if self.quiescing.is_requested() {
                    let _ = response.send(Err(ManualStepRetryError::RuntimeUnavailable));
                    return;
                }
                let result = queue_manual_whole_issue_retry(
                    &self.state,
                    &self.pipeline_journal,
                    &self.interaction_store,
                    ManualWholeIssueRetryRequest {
                        issue_id: &command.issue_id,
                        identifier: &command.identifier,
                    },
                )
                .await;
                let _ = response.send(result);
            }
            OrchestratorCommand::ApproveFinalize { command, response } => {
                if self.quiescing.is_requested() {
                    let _ = response.send(Err(FinalizeApprovalError::RuntimeUnavailable));
                    return;
                }
                let result = self
                    .approve_finalize_delivery(&command.issue_id, &command.identifier)
                    .await;
                let _ = response.send(result);
            }
            OrchestratorCommand::RetryFinalize { command, response } => {
                if self.quiescing.is_requested() {
                    let _ = response.send(Err(FinalizeRetryError::RuntimeUnavailable));
                    return;
                }
                let result = self
                    .retry_finalize_delivery(&command.issue_id, &command.identifier)
                    .await;
                let _ = response.send(result);
            }
        }
    }

    /// Run the orchestrator main loop.
    pub async fn run(&mut self) -> bool {
        let run_id = new_run_id();
        let run_span = tracing::info_span!("ensemble_run", run_id = %run_id, mode = "orchestrator");
        let _run_guard = run_span.enter();

        // Initialize state from config
        {
            let (poll_interval_ms, max_concurrent_agents, config_clone) = {
                let config = self.config.read().await;
                (
                    config.polling.interval_ms,
                    config.concurrency.max_concurrent_agents,
                    config.clone(),
                )
            };
            let mut state = self.state.write().await;
            state.poll_interval_ms = poll_interval_ms;
            state.max_concurrent_agents = max_concurrent_agents;
            state.init_state_lists(&config_clone);
        }

        self.restore_pipeline_runs_from_journal().await;
        self.reconcile_parked_recovery_attention().await;
        self.reconcile_pending_terminal_transitions().await;

        // Startup terminal workspace cleanup
        {
            let (terminal_states, retained_issue_ids) = {
                let config = self.config.read().await;
                let state = self.state.read().await;
                let mut retained = state
                    .pending_terminal_transitions
                    .keys()
                    .cloned()
                    .collect::<HashSet<_>>();
                retained.extend(state.delivery.keys().cloned());
                (config.tracker.terminal_states.clone(), retained)
            };
            startup_terminal_cleanup(
                self.tracker.as_ref(),
                &terminal_states,
                &self.workspace_mgr,
                &retained_issue_ids,
            )
            .await;
        }

        info!("orchestrator started, entering main loop");

        // Immediate first tick
        if !self.quiescing.is_requested() {
            // Keep the large tick state machine out of the long-lived orchestrator future.
            Box::pin(self.handle_tick()).await;
        }

        // Main event loop
        let shutdown_quiesced = loop {
            let poll_interval = {
                let state = self.state.read().await;
                Duration::from_millis(state.poll_interval_ms)
            };

            // Calculate next retry sleep duration
            let retry_sleep = {
                let state = self.state.read().await;
                retry::next_retry_time(&state).map(|due_at| {
                    let now = current_time_ms();
                    if due_at <= now {
                        Duration::from_millis(0)
                    } else {
                        Duration::from_millis(due_at - now)
                    }
                })
            };

            tokio::select! {
                biased;

                // Shutdown signal
                _ = self.shutdown_rx.recv() => {
                    let quiesced = self.cancel_active_runs().await;
                    info!("received shutdown signal, stopping orchestrator");
                    break quiesced;
                }

                Some(command) = self.command_rx.recv() => {
                    self.handle_command(command).await;
                }

                // Poll timer
                _ = sleep(poll_interval) => {
                    if !self.quiescing.is_requested() {
                        debug!("poll tick");
                        Box::pin(self.handle_tick()).await;
                    }
                }

                // Manual refresh signal
                _ = self.refresh_requested.notified() => {
                    if !self.quiescing.is_requested() {
                        debug!("manual refresh tick");
                        Box::pin(self.handle_tick()).await;
                    }
                }

                // Worker events
                Some(event) = recv_worker_event(&self.worker_rx) => {
                    Box::pin(self.handle_worker_event(event)).await;
                }

                // Retry timer (if any)
                _ = async {
                    match retry_sleep {
                        Some(d) => sleep(d).await,
                        None => futures::future::pending::<()>().await,
                    }
                } => {
                    if !self.quiescing.is_requested() {
                        debug!("retry timer fired");
                        self.handle_retry_fires().await;
                    }
                }
            }
        };

        info!("orchestrator stopped, flushing timeline persistence");
        if let Some(mut persistence) = self.timeline_persistence.take() {
            persistence.flush().await;
        }
        info!("timeline persistence flushed");
        info!("orchestrator stopped, flushing transcript persistence");
        if let Some(mut persistence) = self.transcript_persistence.take() {
            persistence.flush().await;
        }
        info!("transcript persistence flushed");

        info!("orchestrator stopped");
        shutdown_quiesced
    }

    /// Handle a poll tick: reconcile, validate, fetch, dispatch.
    fn handle_tick(&self) -> std::pin::Pin<Box<dyn std::future::Future<Output = ()> + Send + '_>> {
        Box::pin(self.handle_tick_inner())
    }

    async fn handle_tick_inner(&self) {
        if self.quiescing.is_requested() {
            return;
        }

        let tick_started_at = std::time::Instant::now();
        info!(event = ORCH_TICK_STARTED, "orchestrator tick started");

        // Cleanup expired completed entries
        {
            let mut state = self.state.write().await;
            state.cleanup_expired_completed();
        }

        // Initialize state lists lazily (for tests that don't call run())
        {
            let state = self.state.read().await;
            if state.active_states_lower.is_empty() {
                drop(state);
                let config = self.config.read().await;
                let mut state = self.state.write().await;
                state.init_state_lists(&config);
            }
        }

        // Record tick timestamp for poll countdown
        {
            let mut state = self.state.write().await;
            state.last_tick_at = Some(Utc::now());
        }

        Box::pin(self.reconcile_pending_run_started_transitions()).await;
        self.reconcile_pending_immutable_launches().await;
        self.reconcile_pending_acceptance_transitions().await;
        self.restore_pipeline_runs_from_journal().await;
        self.reconcile_parked_recovery_attention().await;
        self.reconcile_pending_terminal_transitions().await;
        self.hydrate_waiting_on_human_from_store().await;
        self.process_interaction_thread_commands().await;
        let has_delivery = !self.state.read().await.delivery.is_empty();
        if has_delivery {
            Box::pin(self.reconcile_and_recover_deliveries()).await;
        }
        self.process_finalize_retries().await;

        // Pre-compute lowercase state lists once per tick
        let (active_lower, reconcile_active_lower, terminal_lower) = {
            let state = self.state.read().await;
            let config = self.config.read().await;
            (
                state.active_states_lower.clone(),
                build_reconcile_active_states_lower(&config),
                state.terminal_states_lower.clone(),
            )
        };

        let resume_issue_ids = {
            let state = self.state.read().await;
            state.resume_requested.iter().cloned().collect::<Vec<_>>()
        };
        if !resume_issue_ids.is_empty() {
            match self
                .tracker
                .fetch_issue_states_by_ids(&resume_issue_ids)
                .await
            {
                Ok(issues) => {
                    for issue in issues {
                        let still_requested = {
                            let state = self.state.read().await;
                            state.is_resume_requested(&issue.id)
                        };
                        if !still_requested {
                            continue;
                        }

                        match self.resume_blocked_issue(&issue).await {
                            Ok(()) => {
                                let mut state = self.state.write().await;
                                state.clear_resume_request(&issue.id);
                            }
                            Err(error) => {
                                warn!(
                                    issue_id = %issue.id,
                                    issue_identifier = %issue.identifier,
                                    error = %error,
                                    "failed to process explicit resume request"
                                );
                            }
                        }
                    }
                }
                Err(error) => {
                    warn!(
                        issue_ids = ?resume_issue_ids,
                        error = %error,
                        "failed to refresh explicit resume requests"
                    );
                }
            }
        }

        for issue_id in pending_reconciliation_issue_ids(&self.cancellation_registry) {
            self.resume_pending_reconciliation(&issue_id, &reconcile_active_lower, &terminal_lower)
                .await;
        }

        // 1. Reconcile stalled runs
        let stall_timeout_ms = {
            let config = self.config.read().await;
            config.agent.stall_timeout_ms
        };
        let stalled_issue_ids = {
            let state = self.state.read().await;
            reconcile_stalled_runs(&state, stall_timeout_ms).stalled_issue_ids
        };
        for issue_id in stalled_issue_ids {
            self.reconcile_stalled_issue(&issue_id, stall_timeout_ms)
                .await;
        }

        // 2. Reconcile tracker states
        {
            let state = self.state.read().await;
            let reconcile_result = reconcile_tracker_states(
                &state,
                self.tracker.as_ref(),
                &reconcile_active_lower,
                &terminal_lower,
            )
            .await;

            drop(state);

            {
                let mut state = self.state.write().await;
                for issue in reconcile_result.updates {
                    let id = issue.id.clone();
                    state.update_issue_snapshot(&id, issue);
                }
            }

            // Terminal: terminate and clean workspace
            for issue in reconcile_result.terminate_cleanup {
                self.reconcile_tracker_candidate(
                    &issue.id,
                    &reconcile_active_lower,
                    &terminal_lower,
                    TrackerReconcileDisposition::Terminal,
                )
                .await;
            }

            // Non-active: terminate without cleanup
            for issue in reconcile_result.terminate_no_cleanup {
                self.reconcile_tracker_candidate(
                    &issue.id,
                    &reconcile_active_lower,
                    &terminal_lower,
                    TrackerReconcileDisposition::Inactive,
                )
                .await;
            }
        }

        // Give already-claimed pipelines the first opportunity to consume
        // newly available worker capacity before admitting new issues.
        if let Some(permit) = self.quiescing.begin_dispatch() {
            self.dispatch_ready_active_pipelines(&permit).await;
        }

        // Durable journal owners always win. Only after they have had an
        // opportunity to resume may an adapter supply a remotely-owned orphan.
        Box::pin(self.dispatch_recovered_claims_before_fresh_work()).await;

        // 3. Fetch candidate issues
        let mut candidates = match self.tracker.fetch_candidate_issues().await {
            Ok(issues) => issues,
            Err(e) => {
                warn!(error = %e, "failed to fetch candidate issues, skipping dispatch");
                info!(
                    event = ORCH_TICK_FINISHED,
                    duration_ms = elapsed_ms(tick_started_at),
                    "orchestrator tick finished with fetch error"
                );
                return;
            }
        };

        let selected_candidates = {
            let config = self.config.read().await;
            if config.uses_workflow_selection() {
                match WorkflowSelector::compile(&config.workflow_selection, &config.scheduler.lanes)
                {
                    Ok(selector) => {
                        let mut selected = candidates
                            .iter()
                            .filter_map(|issue| {
                                selector
                                    .select(issue, &config.tracker.terminal_states)
                                    .map(|workflow| (issue.clone(), workflow))
                            })
                            .collect::<Vec<_>>();
                        sort_selected_candidates(&mut selected);
                        Some(selected)
                    }
                    Err(error) => {
                        warn!(error = %error, "failed to compile workflow selector");
                        return;
                    }
                }
            } else {
                sort_for_dispatch(&mut candidates);
                None
            }
        };

        // 5. Dispatch eligible issues while slots remain.
        let dispatch_candidates = selected_candidates
            .as_ref()
            .map(|selected| {
                selected
                    .iter()
                    .map(|(issue, workflow)| (issue, Some(workflow.clone())))
                    .collect::<Vec<_>>()
            })
            .unwrap_or_else(|| candidates.iter().map(|issue| (issue, None)).collect());
        for (issue, selected) in dispatch_candidates {
            if self.quiescing.is_requested() {
                break;
            }

            {
                let max_workers = self.config.read().await.concurrency.max_concurrent_agents;
                if !has_available_worker_slots(
                    live_worker_count(&self.cancellation_registry),
                    max_workers,
                ) {
                    break;
                }
            }

            Box::pin(self.consider_candidate_for_dispatch(
                issue,
                &active_lower,
                &terminal_lower,
                selected,
            ))
            .await;
        }

        info!(
            event = ORCH_TICK_FINISHED,
            duration_ms = elapsed_ms(tick_started_at),
            "orchestrator tick finished"
        );
    }

    async fn consider_candidate_for_dispatch(
        &self,
        issue: &Issue,
        active_lower: &[String],
        terminal_lower: &[String],
        selected: Option<SelectedWorkflow>,
    ) {
        let eligible = {
            let state = self.state.read().await;
            if selected.is_some() {
                is_dispatch_structurally_eligible(issue, &state, terminal_lower)
            } else {
                is_dispatch_eligible(issue, &state, active_lower, terminal_lower)
            }
        };

        let restored_pipeline_ready = {
            let state = self.state.read().await;
            Self::restored_pipeline_ready_for_dispatch(&state, &issue.id)
        };

        if restored_pipeline_ready {
            Box::pin(self.dispatch_issue(issue, None)).await;
            return;
        }

        {
            let config = self.config.read().await;
            let capacity_available = if let Some(selected) = selected.as_ref() {
                if selected.lane_idle_only && live_worker_count(&self.cancellation_registry) > 0 {
                    return;
                }
                has_available_lane_worker_capacity(
                    &self.cancellation_registry,
                    &selected.lane,
                    selected.lane_capacity,
                )
            } else {
                self.state_worker_capacity_available(issue, &config).await
            };
            if !capacity_available {
                return;
            }
        }

        if eligible.is_some() {
            return;
        }

        match self.restore_pipeline_run_for_candidate(issue).await {
            Ok(CandidateRestoreOutcome::ReadyForDispatch) => {
                Box::pin(self.dispatch_issue(issue, None)).await;
            }
            Ok(CandidateRestoreOutcome::NotRestored) => {
                let refreshed = if let Some(expected) = selected.as_ref() {
                    Box::pin(self.refresh_selected_candidate_for_claim(
                        issue,
                        expected,
                        terminal_lower,
                    ))
                    .await
                } else {
                    Some((issue.clone(), None))
                };
                if let Some((fresh_issue, fresh_selected)) = refreshed {
                    if let Some(owned_issue) =
                        Box::pin(self.claim_candidate_for_dispatch(&fresh_issue)).await
                    {
                        if let Some(selected) = fresh_selected {
                            Box::pin(self.dispatch_selected_issue(&owned_issue, None, selected))
                                .await;
                        } else {
                            Box::pin(self.dispatch_issue(&owned_issue, None)).await;
                        }
                    }
                }
            }
            Ok(CandidateRestoreOutcome::Parked) => {}
            Err(error @ EnsembleError::Agent(AgentError::DurableSequenceUnavailable { .. })) => {
                warn!(
                    issue_id = %issue.id,
                    identifier = %issue.identifier,
                    error = %error,
                    "failed to restore live pipeline journal before dispatch, leaving issue undispatched"
                );
            }
            Err(error) => {
                if self.tracker.has_remote_ownership_policy() {
                    warn!(
                        issue_id = %issue.id,
                        identifier = %issue.identifier,
                        error = %error,
                        "failed to restore live pipeline journal before remote-owned dispatch; leaving issue undispatched"
                    );
                } else {
                    warn!(
                        issue_id = %issue.id,
                        identifier = %issue.identifier,
                        error = %error,
                        "failed to restore live pipeline journal before dispatch, falling back to fresh dispatch"
                    );
                    Box::pin(self.dispatch_issue(issue, None)).await;
                }
            }
        }
    }

    async fn refresh_selected_candidate_for_claim(
        &self,
        issue: &Issue,
        expected: &SelectedWorkflow,
        terminal_states: &[String],
    ) -> Option<(Issue, Option<SelectedWorkflow>)> {
        let mut refreshed = match self
            .tracker
            .fetch_issue_states_by_ids(std::slice::from_ref(&issue.id))
            .await
        {
            Ok(refreshed) => refreshed,
            Err(error) => {
                warn!(issue_id = %issue.id, error = %error, "selected candidate refresh failed");
                return None;
            }
        };
        if refreshed.len() != 1 {
            return None;
        }
        let fresh = refreshed.pop()?;
        {
            let state = self.state.read().await;
            if is_dispatch_structurally_eligible(&fresh, &state, terminal_states).is_some() {
                return None;
            }
        }
        let config = self.config.read().await;
        let selector = match WorkflowSelector::compile(
            &config.workflow_selection,
            &config.scheduler.lanes,
        ) {
            Ok(selector) => selector,
            Err(error) => {
                warn!(issue_id = %issue.id, error = %error, "selected candidate refresh could not compile workflow rules");
                return None;
            }
        };
        let selected = selector.select(&fresh, terminal_states)?;
        if selected.rule != expected.rule
            || selected.pipeline != expected.pipeline
            || selected.lane != expected.lane
        {
            return None;
        }
        if !has_available_lane_worker_capacity(
            &self.cancellation_registry,
            &selected.lane,
            selected.lane_capacity,
        ) {
            return None;
        }
        Some((fresh, Some(selected)))
    }

    async fn dispatch_recovered_claims_before_fresh_work(&self) {
        let recovered = match self.tracker.recover_owned_claims().await {
            Ok(recovered) => recovered,
            Err(error) => {
                warn!(error = %error, "failed to recover remote-owned claims before fresh dispatch");
                return;
            }
        };

        for (issue, lease) in recovered {
            let already_owned = {
                let state = self.state.read().await;
                state.get_pipeline_run(&issue.id).is_some()
                    || state.is_running(&issue.id)
                    || state.is_claimed(&issue.id)
                    || state.delivery.contains_key(&issue.id)
            };
            if already_owned {
                continue;
            }

            let selected = {
                let config = self.config.read().await;
                if config.uses_workflow_selection() {
                    let terminal_states = config.tracker.terminal_states.clone();
                    let Ok(selector) = WorkflowSelector::compile(
                        &config.workflow_selection,
                        &config.scheduler.lanes,
                    ) else {
                        return;
                    };
                    drop(config);
                    let state = self.state.read().await;
                    if is_dispatch_structurally_eligible(&issue, &state, &terminal_states).is_some()
                    {
                        continue;
                    }
                    drop(state);
                    let Some(selected) = selector.select(&issue, &terminal_states) else {
                        continue;
                    };
                    if !has_available_lane_worker_capacity(
                        &self.cancellation_registry,
                        &selected.lane,
                        selected.lane_capacity,
                    ) {
                        return;
                    }
                    Some(selected)
                } else {
                    if !self.state_worker_capacity_available(&issue, &config).await {
                        return;
                    }
                    None
                }
            };

            let mut owned_issue = issue;
            owned_issue.branch_name = lease.branch_name.clone();
            self.pending_ownership_leases
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner())
                .insert(owned_issue.id.clone(), lease);
            if let Some(selected) = selected {
                Box::pin(self.dispatch_selected_issue(&owned_issue, None, selected)).await;
            } else {
                Box::pin(self.dispatch_issue(&owned_issue, None)).await;
            }
        }
    }

    /// Requests adapter-owned remote ownership only after the existing journal
    /// has proved there is no local run to restore. Tracker-specific evidence
    /// stays at the adapter boundary; dispatch receives at most an opaque
    /// workspace branch identity.
    async fn claim_candidate_for_dispatch(&self, issue: &Issue) -> Option<Issue> {
        match self.tracker.claim_issue(issue).await {
            Ok(OwnershipClaim::Unavailable) => {
                let mut issue = issue.clone();
                issue.branch_name = self.tracker.workspace_branch_name(&issue);
                Some(issue)
            }
            Ok(OwnershipClaim::Acquired(lease) | OwnershipClaim::Recovered(lease)) => {
                let mut owned = issue.clone();
                owned.branch_name = lease.branch_name.clone();
                self.pending_ownership_leases
                    .lock()
                    .unwrap_or_else(|poisoned| poisoned.into_inner())
                    .insert(issue.id.clone(), lease);
                Some(owned)
            }
            Ok(OwnershipClaim::NotEligible) => None,
            Ok(OwnershipClaim::Conflict(conflict)) => {
                warn!(
                    issue_id = %issue.id,
                    identifier = %issue.identifier,
                    ?conflict,
                    "remote ownership conflict left candidate undispatched"
                );
                None
            }
            Err(error) => {
                warn!(
                    issue_id = %issue.id,
                    identifier = %issue.identifier,
                    error = %error,
                    "remote ownership claim failed; leaving candidate undispatched"
                );
                None
            }
        }
    }

    async fn restore_pipeline_run_for_candidate(
        &self,
        issue: &Issue,
    ) -> Result<CandidateRestoreOutcome, EnsembleError> {
        {
            let state = self.state.read().await;
            if Self::restored_pipeline_ready_for_dispatch(&state, &issue.id) {
                return Ok(CandidateRestoreOutcome::ReadyForDispatch);
            }
            if state.get_pipeline_run(&issue.id).is_some()
                || state.is_running(&issue.id)
                || state.is_claimed(&issue.id)
            {
                return Ok(CandidateRestoreOutcome::Parked);
            }
        }

        let record = self
            .pipeline_journal
            .latest_live_record_for_issue(&issue.id)
            .await
            .map_err(|error| AgentError::IoError {
                reason: format!(
                    "failed to read pipeline transition journal for issue '{}': {error}",
                    issue.id
                ),
            })?;

        let Some(record) = record else {
            return Ok(CandidateRestoreOutcome::NotRestored);
        };

        let config_snapshot = {
            let config = self.config.read().await;
            Arc::new(config.clone())
        };
        let issues_by_id = HashMap::from([(issue.id.clone(), issue.clone())]);
        self.restore_pipeline_run_record(&record, config_snapshot, &issues_by_id)
            .await?;

        let state = self.state.read().await;
        if Self::restored_pipeline_ready_for_dispatch(&state, &issue.id) {
            Ok(CandidateRestoreOutcome::ReadyForDispatch)
        } else if state.get_pipeline_run(&issue.id).is_some()
            || state.is_claimed(&issue.id)
            || state.is_waiting_on_human(&issue.id)
            || state.retry_attempts.contains_key(&issue.id)
        {
            Ok(CandidateRestoreOutcome::Parked)
        } else {
            Ok(CandidateRestoreOutcome::NotRestored)
        }
    }

    fn restored_pipeline_ready_for_dispatch(state: &OrchestratorState, issue_id: &str) -> bool {
        if state.pending_terminal_transitions.contains_key(issue_id)
            || state.finalize.contains_key(issue_id)
            || state.delivery.contains_key(issue_id)
        {
            return false;
        }
        let Some(run) = state.get_pipeline_run(issue_id) else {
            return false;
        };

        state.is_claimed(issue_id)
            && !state.is_running(issue_id)
            && !state.is_waiting_on_human(issue_id)
            && !state.retry_attempts.contains_key(issue_id)
            && !Self::pipeline_has_waiting_step(run)
    }

    fn pipeline_has_waiting_step(run: &PipelineRun) -> bool {
        run.step_states.values().any(|state| {
            matches!(
                state,
                StepState::BlockedOnHuman { .. } | StepState::AwaitingApproval { .. }
            )
        })
    }

    /// Dispatch a single issue: build DAG, create PipelineRun, dispatch initial steps.
    async fn dispatch_issue(&self, issue: &Issue, attempt: Option<u32>) {
        let Some(permit) = self.quiescing.begin_dispatch() else {
            return;
        };
        self.dispatch_issue_with_permit(issue, attempt, &permit)
            .await;
    }

    async fn dispatch_selected_issue(
        &self,
        issue: &Issue,
        attempt: Option<u32>,
        selected: SelectedWorkflow,
    ) {
        let Some(permit) = self.quiescing.begin_dispatch() else {
            return;
        };
        self.dispatch_issue_with_owned_retry(issue, attempt, None, Some(&selected), &permit)
            .await;
    }

    async fn dispatch_issue_with_permit(
        &self,
        issue: &Issue,
        attempt: Option<u32>,
        permit: &DispatchPermit,
    ) {
        self.dispatch_issue_with_owned_retry(issue, attempt, None, None, permit)
            .await;
    }

    async fn dispatch_retry_issue_with_permit(
        &self,
        issue: &Issue,
        retry_entry: &RetryEntry,
        permit: &DispatchPermit,
    ) {
        self.dispatch_issue_with_owned_retry(
            issue,
            Some(retry_entry.attempt),
            Some(retry_entry),
            None,
            permit,
        )
        .await;
    }

    async fn dispatch_issue_with_owned_retry(
        &self,
        issue: &Issue,
        attempt: Option<u32>,
        expected_retry: Option<&RetryEntry>,
        selected: Option<&SelectedWorkflow>,
        permit: &DispatchPermit,
    ) {
        let cycle = attempt.unwrap_or(1);

        {
            let state = self.state.read().await;
            if state.get_pipeline_run(&issue.id).is_some() {
                drop(state);

                let (config_snapshot, action, effective_cycle, effective_attempt, finalize_attempt) = {
                    let mut state = self.state.write().await;
                    if expected_retry.is_some_and(|expected| {
                        state.retry_attempts.get(&issue.id) != Some(expected)
                    }) {
                        return;
                    }
                    let existing_cycle = state
                        .get_pipeline_run(&issue.id)
                        .map(|run| run.cycle)
                        .unwrap_or(cycle);
                    let effective_cycle = attempt.unwrap_or(existing_cycle);
                    let effective_attempt =
                        attempt.or_else(|| (effective_cycle > 1).then_some(effective_cycle));
                    state.add_running(issue, effective_attempt);
                    let config = state.get_pipeline_config(&issue.id).cloned();
                    let action = state
                        .get_pipeline_run_mut(&issue.id)
                        .map(|run| {
                            run.cycle = effective_cycle;
                            run.start()
                        })
                        .unwrap_or(PipelineAction::Waiting);
                    let finalize_attempt = RunningAttemptIdentity::capture(&state, &issue.id);
                    (
                        config,
                        action,
                        effective_cycle,
                        effective_attempt,
                        finalize_attempt,
                    )
                };

                let Some(config_snapshot) = config_snapshot else {
                    warn!(
                        issue_id = %issue.id,
                        identifier = %issue.identifier,
                        "existing pipeline run has no config snapshot, skipping dispatch"
                    );
                    return;
                };

                info!(
                    event = ISSUE_DISPATCH_STARTED,
                    issue_id = %issue.id,
                    identifier = %issue.identifier,
                    cycle = effective_cycle,
                    "resuming with existing pipeline"
                );

                match action {
                    PipelineAction::Succeeded => {
                        info!(
                            issue_id = %issue.id,
                            "restored pipeline already succeeded"
                        );
                        match self.run_acceptance_phase(issue, &config_snapshot).await {
                            AcceptancePhaseOutcome::Passed => {}
                            AcceptancePhaseOutcome::Failed { reason, owner } => {
                                self.schedule_acceptance_failure(
                                    issue,
                                    &config_snapshot,
                                    &reason,
                                    &owner,
                                )
                                .await;
                                return;
                            }
                            AcceptancePhaseOutcome::RetainedForRecovery => return,
                        }
                        let finalize_state = self
                            .finalize_and_stage_terminal_transition(
                                &issue.id,
                                &issue.identifier,
                                &config_snapshot,
                            )
                            .await;
                        let completed_at = Utc::now();
                        let (terminal_issue, terminal_outcome, target_state, history_record) = {
                            let mut state = self.state.write().await;
                            if !Self::finalization_attempt_is_current(
                                finalize_attempt.as_ref(),
                                &state,
                                &issue.id,
                            ) {
                                warn!(
                                    issue_id = %issue.id,
                                    "discarding stale finalization result because the running attempt changed"
                                );
                                return;
                            }
                            let history_record = state
                                .running
                                .get(&issue.id)
                                .zip(state.get_pipeline_run(&issue.id))
                                .map(|(entry, run)| {
                                    self.build_history_record(RunningHistoryRecordInput {
                                        outcome: HISTORY_OUTCOME_SUCCEEDED,
                                        last_error: None,
                                        running_entry: entry,
                                        run,
                                        completed_at,
                                        artifacts: state.artifacts.get(&issue.id).cloned(),
                                    })
                                });
                            let running_entry = state.get_running(&issue.id).cloned();
                            let terminal_issue = running_entry
                                .as_ref()
                                .map(|entry| entry.issue.clone())
                                .unwrap_or_else(|| issue.clone());

                            if finalize_state.status == FinalizeStatus::Succeeded
                                || finalize_state.status == FinalizeStatus::NotRequired
                            {
                                (
                                    Some(terminal_issue),
                                    Some(TerminalOutcome::Succeeded),
                                    Some(config_snapshot.on_success.clone()),
                                    history_record,
                                )
                            } else {
                                let is_terminal_failure =
                                    finalize_state.status == FinalizeStatus::SkippedHeadless;
                                if let Some(entry) = state.remove_running(&issue.id) {
                                    state.add_runtime_seconds(&entry);
                                }
                                state.set_finalize_state(&issue.id, finalize_state);
                                if !is_terminal_failure {
                                    state.remove_pipeline_run(&issue.id);
                                }
                                (
                                    is_terminal_failure.then_some(terminal_issue),
                                    is_terminal_failure.then_some(TerminalOutcome::Failed),
                                    is_terminal_failure.then(|| config_snapshot.on_failure.clone()),
                                    None,
                                )
                            }
                        };

                        if let (Some(issue), Some(outcome), Some(target_state)) =
                            (terminal_issue, terminal_outcome, target_state)
                        {
                            self.begin_terminal_transition(
                                &issue,
                                outcome,
                                target_state,
                                history_record,
                            )
                            .await;
                        }
                    }
                    PipelineAction::Dispatch(requests) => {
                        let recovered_interaction = match self
                            .recovered_interaction_response(&issue.id)
                            .await
                        {
                            Ok(interaction) => interaction,
                            Err(error) => {
                                warn!(
                                    issue_id = %issue.id,
                                    error = %error,
                                    "failed to recover durable interaction response; retaining pipeline owner"
                                );
                                return;
                            }
                        };
                        for req in requests {
                            if !self
                                .state_worker_capacity_available(issue, &config_snapshot)
                                .await
                            {
                                return;
                            }
                            let workspace_path =
                                match self.prepare_step_workspace(issue, &config_snapshot).await {
                                    Ok(path) => path,
                                    Err(error) => {
                                        warn!(
                                            issue_id = %issue.id,
                                            step = %req.step_name,
                                            error = %error,
                                            "failed to prepare step workspace"
                                        );
                                        let mut state = self.state.write().await;
                                        if let Some(run) = state.get_pipeline_run_mut(&issue.id) {
                                            run.step_failed(&req.step_name, error.to_string());
                                        }
                                        let terminal =
                                            state.remove_running(&issue.id).map(|entry| {
                                                self.schedule_whole_issue_failure_retry(
                                                    &mut state,
                                                    &config_snapshot,
                                                    entry,
                                                    &error.to_string(),
                                                    ScheduledRetryPipeline::Release,
                                                )
                                            });
                                        drop(state);
                                        self.commit_whole_issue_failure_retry(terminal).await;
                                        return;
                                    }
                                };

                            let step_outputs = {
                                let state = self.state.read().await;
                                state
                                    .get_pipeline_run(&issue.id)
                                    .and_then(|run| run.output_context_for(&req.step_name))
                                    .unwrap_or_default()
                            };

                            if let Err(error) = self
                                .dispatch_step(
                                    issue,
                                    Arc::clone(&config_snapshot),
                                    StepDispatchContext {
                                        step_name: &req.step_name,
                                        agent_name: &req.agent_name,
                                        step_kind: req.step_kind,
                                        tracker_state: req.tracker_state.as_deref(),
                                        attempt: effective_attempt,
                                        timeout_ms: Self::effective_step_timeout_ms(
                                            req.timeout_ms,
                                            &config_snapshot,
                                        ),
                                        interaction_response: recovered_interaction
                                            .as_ref()
                                            .filter(|(_, step_name, _, _)| {
                                                step_name == &req.step_name
                                            })
                                            .and_then(|(_, _, response, _)| response.clone()),
                                        interaction_resume_id: recovered_interaction
                                            .as_ref()
                                            .filter(|(_, step_name, _, _)| {
                                                step_name == &req.step_name
                                            })
                                            .map(|(interaction_id, _, _, _)| {
                                                interaction_id.as_str()
                                            }),
                                        interaction_to_retire: recovered_interaction
                                            .as_ref()
                                            .filter(|(_, step_name, _, awaiting_resume)| {
                                                step_name == &req.step_name && *awaiting_resume
                                            })
                                            .map(|(interaction_id, _, _, _)| {
                                                interaction_id.as_str()
                                            }),
                                        interaction_retirement_rollback: None,
                                        workspace_path,
                                        step_outputs,
                                    },
                                    permit,
                                )
                                .await
                            {
                                self.handle_step_dispatch_error(
                                    issue,
                                    &req.step_name,
                                    &config_snapshot,
                                    &error,
                                )
                                .await;
                                return;
                            }
                        }
                    }
                    PipelineAction::Waiting
                    | PipelineAction::AwaitingAction { .. }
                    | PipelineAction::Failed { .. }
                    | PipelineAction::BlockedOnHuman { .. }
                    | PipelineAction::AwaitingApproval { .. } => {}
                }

                info!(
                    event = ISSUE_DISPATCH_COMPLETED,
                    issue_id = %issue.id,
                    identifier = %issue.identifier,
                    cycle = effective_cycle,
                    "existing pipeline dispatch setup completed"
                );
                return;
            }
        }

        let (dag, config_snapshot) = {
            let config = self.config.read().await;
            let effective = if let Some(selected) = selected {
                match config.resolve_selected_workflow(
                    &selected.rule,
                    &selected.pipeline,
                    &selected.lane,
                ) {
                    Ok(effective) => effective,
                    Err(error) => {
                        warn!(issue_id = %issue.id, error = %error, "failed to resolve selected workflow");
                        return;
                    }
                }
            } else {
                config.clone()
            };
            match build_dag(&effective.steps) {
                Ok(d) => (d, Arc::new(effective)),
                Err(e) => {
                    warn!(issue_id = %issue.id, error = %e, "failed to build step DAG, skipping dispatch");
                    return;
                }
            }
        };

        let ownership_lease = self
            .pending_ownership_leases
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .get(&issue.id)
            .cloned();
        let mut pipeline_run = PipelineRun::new(issue.id.clone(), cycle, dag);
        if let Some(selected) = selected {
            pipeline_run.set_selected_workflow(SelectedWorkflowSnapshot {
                rule: selected.rule.clone(),
                pipeline: selected.pipeline.clone(),
                lane: selected.lane.clone(),
            });
        }
        if let Some(lease) = ownership_lease.clone() {
            pipeline_run.set_ownership_lease(lease);
        }
        if let Some(branch_name) = issue.branch_name.clone() {
            pipeline_run.set_workspace_branch_name(branch_name);
        }
        let acceptance_plan = match ResolvedAcceptancePlan::from_config(&config_snapshot) {
            Ok(plan) => plan,
            Err(error) => {
                warn!(issue_id = %issue.id, error = %error, "failed to freeze acceptance plan");
                return;
            }
        };
        pipeline_run.resolved_acceptance_plan = Some(acceptance_plan);
        let action = pipeline_run.start();

        info!(
            event = ISSUE_DISPATCH_STARTED,
            issue_id = %issue.id,
            identifier = %issue.identifier,
            cycle = cycle,
            "dispatching issue with pipeline"
        );

        let run_started_transition = {
            let mut state = self.state.write().await;
            if expected_retry
                .is_some_and(|expected| state.retry_attempts.get(&issue.id) != Some(expected))
            {
                return;
            }
            state.add_running(issue, attempt);
            state.insert_pipeline_run(&issue.id, pipeline_run, Arc::clone(&config_snapshot));
            Self::transition_input_for_run(
                &state,
                &issue.id,
                &issue.identifier,
                PipelineTransitionKind::RunStarted,
                None,
                None,
                None,
            )
        };
        if let Some(input) = run_started_transition {
            if ownership_lease.is_some() {
                let transaction = self
                    .pipeline_journal
                    .begin_issue_transition(&issue.id)
                    .await;
                if let Err(error) = transaction.append(input.clone()).await {
                    match transaction.latest_record_matches(&input).await {
                        Ok(true) => {}
                        Ok(false) => {
                            warn!(
                                issue_id = %issue.id,
                                identifier = %issue.identifier,
                                error = %error,
                                "remote ownership transition was not journaled"
                            );
                            let mut state = self.state.write().await;
                            state.release_claim(&issue.id);
                            state.remove_pipeline_run(&issue.id);
                            return;
                        }
                        Err(reconciliation_error) => {
                            warn!(
                                issue_id = %issue.id,
                                identifier = %issue.identifier,
                                append_error = %error,
                                reconciliation_error = %reconciliation_error,
                                "remote ownership transition remains ambiguous; retaining the owner"
                            );
                            self.pending_run_started_transitions
                                .lock()
                                .unwrap_or_else(|poisoned| poisoned.into_inner())
                                .insert(
                                    issue.id.clone(),
                                    PendingRunStartedTransition {
                                        expected: input,
                                        issue: issue.clone(),
                                        attempt,
                                    },
                                );
                            self.refresh_requested.notify_one();
                            return;
                        }
                    }
                }
                drop(transaction);
                self.pending_ownership_leases
                    .lock()
                    .unwrap_or_else(|poisoned| poisoned.into_inner())
                    .remove(&issue.id);
            } else {
                self.append_pipeline_transition(input).await;
            }
        }

        // Process initial dispatch requests
        if let PipelineAction::Dispatch(requests) = action {
            for req in requests {
                if !self
                    .state_worker_capacity_available(issue, &config_snapshot)
                    .await
                {
                    return;
                }
                let workspace_path =
                    match self.prepare_step_workspace(issue, &config_snapshot).await {
                        Ok(path) => path,
                        Err(error) => {
                            warn!(
                                issue_id = %issue.id,
                                step = %req.step_name,
                                error = %error,
                                "failed to prepare step workspace"
                            );
                            let mut state = self.state.write().await;
                            if let Some(run) = state.get_pipeline_run_mut(&issue.id) {
                                run.step_failed(&req.step_name, error.to_string());
                            }
                            let terminal = state.remove_running(&issue.id).map(|entry| {
                                self.schedule_whole_issue_failure_retry(
                                    &mut state,
                                    &config_snapshot,
                                    entry,
                                    &error.to_string(),
                                    ScheduledRetryPipeline::Release,
                                )
                            });
                            drop(state);
                            self.commit_whole_issue_failure_retry(terminal).await;
                            return;
                        }
                    };

                if let Err(error) = self
                    .dispatch_step(
                        issue,
                        Arc::clone(&config_snapshot),
                        StepDispatchContext {
                            step_name: &req.step_name,
                            agent_name: &req.agent_name,
                            step_kind: req.step_kind,
                            tracker_state: req.tracker_state.as_deref(),
                            attempt,
                            timeout_ms: Self::effective_step_timeout_ms(
                                req.timeout_ms,
                                &config_snapshot,
                            ),
                            interaction_response: None,
                            interaction_resume_id: None,
                            interaction_to_retire: None,
                            interaction_retirement_rollback: None,
                            workspace_path,
                            step_outputs: StepOutputTemplateContext::default(),
                        },
                        permit,
                    )
                    .await
                {
                    self.handle_step_dispatch_error(
                        issue,
                        &req.step_name,
                        &config_snapshot,
                        &error,
                    )
                    .await;
                    return;
                }
            }
        }

        info!(
            event = ISSUE_DISPATCH_COMPLETED,
            issue_id = %issue.id,
            identifier = %issue.identifier,
            cycle = cycle,
            "issue dispatch setup completed"
        );
    }

    async fn reconcile_pending_run_started_transitions(&self) {
        let pending = self
            .pending_run_started_transitions
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .values()
            .cloned()
            .collect::<Vec<_>>();
        for pending in pending {
            let issue_id = pending.issue.id.clone();
            let transaction = self
                .pipeline_journal
                .begin_issue_transition(&issue_id)
                .await;
            let visibility = transaction.latest_record_matches(&pending.expected).await;
            drop(transaction);
            match visibility {
                Ok(is_exact) => {
                    let owner_is_current = {
                        let state = self.state.read().await;
                        state
                            .get_running(&issue_id)
                            .is_some_and(|running| running.run_id == pending.expected.run_id)
                            && state.get_pipeline_run(&issue_id).is_some_and(|run| {
                                pending.expected.snapshot.as_ref() == Some(&run.to_snapshot())
                            })
                    };
                    self.pending_run_started_transitions
                        .lock()
                        .unwrap_or_else(|poisoned| poisoned.into_inner())
                        .remove(&issue_id);
                    if !owner_is_current {
                        continue;
                    }
                    if is_exact {
                        self.pending_ownership_leases
                            .lock()
                            .unwrap_or_else(|poisoned| poisoned.into_inner())
                            .remove(&issue_id);
                    } else {
                        let mut state = self.state.write().await;
                        state.release_claim(&issue_id);
                        state.remove_pipeline_run(&issue_id);
                    }
                    Box::pin(self.dispatch_issue(&pending.issue, pending.attempt)).await;
                }
                Err(error) => warn!(
                    issue_id,
                    error = %error,
                    "remote ownership transition remains ambiguous; retaining the owner"
                ),
            }
        }
    }

    async fn reconcile_pending_immutable_launches(&self) {
        let identities = self
            .pending_immutable_launches
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .keys()
            .cloned()
            .collect::<Vec<_>>();
        for identity in identities {
            let Some(pending) = self
                .pending_immutable_launches
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner())
                .remove(&identity)
            else {
                continue;
            };
            let transaction = self
                .pipeline_journal
                .begin_issue_transition(&pending.issue.id)
                .await;
            match transaction.latest_record_matches(&pending.expected).await {
                Ok(true) => self.release_immutable_launch(pending).await,
                Ok(false) => {
                    self.rollback_unconfirmed_immutable_launch(pending, &transaction)
                        .await;
                }
                Err(error) => {
                    warn!(
                        issue_id = %pending.issue.id,
                        step = %pending.identity.step_name,
                        error = %error,
                        "immutable worker launch remains ambiguous; retaining its closed gate"
                    );
                    self.pending_immutable_launches
                        .lock()
                        .unwrap_or_else(|poisoned| poisoned.into_inner())
                        .insert(identity, pending);
                }
            }
        }
    }

    async fn release_immutable_launch(&self, pending: PendingImmutableLaunch) {
        let PendingImmutableLaunch {
            identity,
            reservation,
            start_gate,
            local_event_rx,
            ..
        } = pending;
        match reservation.mark_launched() {
            Ok(completion_tx) => {
                tokio::spawn(bridge_worker_events(
                    local_event_rx,
                    self.worker_tx.clone(),
                    self.cancellation_registry.clone(),
                    identity,
                    completion_tx,
                ));
                let _ = start_gate.send(());
            }
            Err(error) => {
                warn!(error = %error, "durably committed immutable worker could not be released");
            }
        }
    }

    async fn rollback_unconfirmed_immutable_launch(
        &self,
        pending: PendingImmutableLaunch,
        transaction: &crate::orchestrator::pipeline_journal::PipelineIssueJournalTransaction<'_>,
    ) {
        let PendingImmutableLaunch {
            issue,
            identity,
            previous_step_state,
            running_session_id,
            evidence,
            previous_evidence,
            retired_interaction,
            ..
        } = pending;
        let rollback_transition = {
            let mut state = self.state.write().await;
            let Some(run) = state.get_pipeline_run_mut(&issue.id) else {
                return;
            };
            if run.step_states.get(&identity.step_name)
                != Some(&StepState::Running {
                    session_id: running_session_id,
                })
            {
                return;
            }
            run.step_states
                .insert(identity.step_name.clone(), previous_step_state.clone());
            run.clear_active_scheduler_reservation(&identity.step_name);
            run.clear_immutable_consumer_launch_commitment(&identity.step_name);
            run.restore_artifact_access_evidence(&evidence, previous_evidence);
            let kind = match previous_step_state {
                StepState::BlockedOnHuman { .. } => {
                    Some(PipelineTransitionKind::StepBlockedOnHuman)
                }
                StepState::AwaitingApproval { .. } => {
                    Some(PipelineTransitionKind::StepAwaitingApproval)
                }
                _ => None,
            };
            kind.and_then(|kind| {
                Self::transition_input_for_run(
                    &state,
                    &issue.id,
                    &issue.identifier,
                    kind,
                    Some(identity.step_name.clone()),
                    Some("immutable worker launch was not durably committed".to_string()),
                    None,
                )
            })
        };
        let restores_interaction = retired_interaction.is_some();
        if let Some((previous, retired)) = retired_interaction {
            if let Err(error) = self
                .interaction_store
                .restore_waiting_state_after_failed_transition(&retired, &previous)
                .await
            {
                warn!(issue_id = %issue.id, interaction_id = %previous.id, error = %error, "failed to restore interaction after unconfirmed immutable launch");
            }
        }
        if restores_interaction {
            self.state.write().await.remove_running(&issue.id);
        }
        if let Some(transition) = rollback_transition {
            if let Err(error) = transaction.append(transition).await {
                warn!(issue_id = %issue.id, step = %identity.step_name, error = %error, "failed to persist unconfirmed immutable launch rollback");
            }
        }
    }

    fn dispatch_ready_active_pipelines<'a>(
        &'a self,
        permit: &'a DispatchPermit,
    ) -> Pin<Box<dyn Future<Output = ()> + Send + 'a>> {
        Box::pin(async move {
            let mut active_issue_ids = {
                let state = self.state.read().await;
                state
                    .running
                    .values()
                    .map(|entry| (entry.identifier.clone(), entry.issue_id.clone()))
                    .collect::<Vec<_>>()
            };
            active_issue_ids.sort();

            for (_, issue_id) in &active_issue_ids {
                if let Some(action) = self.apply_pending_step_actions(issue_id).await {
                    self.handle_applied_action_outcome(issue_id, action, permit)
                        .await;
                }
            }

            for (_, issue_id) in active_issue_ids {
                if self
                    .pending_run_started_transitions
                    .lock()
                    .unwrap_or_else(|poisoned| poisoned.into_inner())
                    .contains_key(&issue_id)
                {
                    continue;
                }
                let max_workers = self.config.read().await.concurrency.max_concurrent_agents;
                if !has_available_worker_slots(
                    live_worker_count(&self.cancellation_registry),
                    max_workers,
                ) {
                    break;
                }
                self.dispatch_ready_steps_for_issue(&issue_id, permit).await;
            }
        })
    }

    /// Execute durable configured effects before normal ready-step dispatch.
    /// Failures leave the pending snapshot and issue ownership in place so the
    /// next scheduler tick retries the effect, never its producer.
    async fn apply_pending_step_actions(&self, issue_id: &str) -> Option<PipelineAction> {
        let action_lock = self.action_mutation_lock(issue_id);
        let _action_guard = action_lock.lock().await;
        loop {
            let (identifier, step_name, pending, transition) = {
                let state = self.state.read().await;
                let run = state.get_pipeline_run(issue_id)?;
                let (step_name, pending) = run.workflow_steps().find_map(|step| {
                    run.pending_action(&step.name)
                        .cloned()
                        .map(|pending| (step.name.clone(), pending))
                })?;
                let identifier = state
                    .get_running(issue_id)
                    .map(|entry| entry.identifier.clone())
                    .unwrap_or_else(|| issue_id.to_string());
                let transition = Self::transition_input_for_snapshot(
                    &state,
                    run,
                    PipelineTransitionTarget {
                        issue_id,
                        identifier: &identifier,
                    },
                    PipelineTransitionKind::ActionPending,
                    Some(step_name.clone()),
                    Some(pending.identity.clone()),
                    None,
                )?;
                (identifier, step_name, pending, transition)
            };
            if let Err(error) = self.pipeline_journal.append(transition).await {
                warn!(issue_id = %issue_id, step = %step_name, error = %error, "failed to checkpoint configured action before execution");
                return None;
            }
            let receipt = match pending.action.clone() {
                ResolvedStepAction::TrackerComment { body } => self
                    .tracker
                    .publish_comment(
                        issue_id,
                        TrackerCommentPublication {
                            marker: pending.identity.clone(),
                            body,
                        },
                    )
                    .await
                    .map(|receipt| StepActionReceipt::TrackerComment {
                        receipt: receipt.receipt,
                    })
                    .map_err(|error| error.to_string()),
                ResolvedStepAction::OperatorAttention {
                    kind,
                    summary,
                    remedy,
                    references,
                } => {
                    let Some(reporter) = self.attention_reporter.as_ref() else {
                        warn!(issue_id = %issue_id, step = %step_name, "configured attention action requires durable history storage");
                        return None;
                    };
                    let observation = AttentionIdentity::new(&pending.identity, issue_id, kind)
                        .and_then(|identity| {
                            AttentionPresentation::new(summary, remedy, references).and_then(
                                |presentation| {
                                    AttentionEvidence::new(&pending.source_output_digest).map(
                                        |evidence| {
                                            AttentionUpsert::new(identity, presentation, evidence)
                                        },
                                    )
                                },
                            )
                        });
                    match observation {
                        Ok(observation) => reporter
                            .upsert_open(observation)
                            .await
                            .map(|item| StepActionReceipt::OperatorAttention {
                                receipt: item.identity.producer_key,
                            })
                            .map_err(|error| error.to_string()),
                        Err(error) => Err(error.to_string()),
                    }
                }
            };
            let receipt = match receipt {
                Ok(receipt) => receipt,
                Err(error) => {
                    warn!(issue_id = %issue_id, step = %step_name, error = %error, "configured action remains pending for retry");
                    return None;
                }
            };
            let (candidate, transition, action) = {
                let state = self.state.read().await;
                let run = state.get_pipeline_run(issue_id)?;
                let mut candidate = run.clone();
                let action = candidate.acknowledge_action(&step_name, &pending.identity, receipt);
                if candidate
                    .pending_action(&step_name)
                    .is_some_and(|current| current.identity == pending.identity)
                {
                    return None;
                }
                let transition = Self::transition_input_for_snapshot(
                    &state,
                    &candidate,
                    PipelineTransitionTarget {
                        issue_id,
                        identifier: &identifier,
                    },
                    PipelineTransitionKind::ActionApplied,
                    Some(step_name.clone()),
                    Some(pending.identity.clone()),
                    None,
                )?;
                (candidate, transition, action)
            };
            if let Err(error) = self.pipeline_journal.append(transition).await {
                warn!(issue_id = %issue_id, step = %step_name, error = %error, "effect completed but receipt was not durable; marker reconciliation will retry it");
                return None;
            }
            let mut state = self.state.write().await;
            let still_pending = state
                .get_pipeline_run(issue_id)
                .and_then(|run| run.pending_action(&step_name))
                .is_some_and(|current| current.identity == pending.identity);
            if still_pending {
                state.pipeline_runs.insert(issue_id.to_string(), candidate);
                drop(state);
                if !matches!(action, PipelineAction::AwaitingAction { .. }) {
                    return Some(action);
                }
            } else {
                return None;
            }
        }
    }

    // Keep action continuation out of the active-pipeline dispatcher so its failure and terminal
    // lifecycle branches do not inflate every scheduler dispatch frame.
    fn handle_applied_action_outcome<'a>(
        &'a self,
        issue_id: &'a str,
        action: PipelineAction,
        permit: &'a DispatchPermit,
    ) -> Pin<Box<dyn Future<Output = ()> + Send + 'a>> {
        Box::pin(self.handle_applied_action_outcome_inner(issue_id, action, permit))
    }

    async fn handle_applied_action_outcome_inner(
        &self,
        issue_id: &str,
        action: PipelineAction,
        permit: &DispatchPermit,
    ) {
        match action {
            PipelineAction::Succeeded => {
                let issue = self
                    .state
                    .read()
                    .await
                    .get_running(issue_id)
                    .map(|entry| entry.issue.clone());
                if let Some(issue) = issue {
                    self.dispatch_issue_with_permit(&issue, None, permit).await;
                }
            }
            PipelineAction::Failed { step, reason } => {
                self.handle_pipeline_step_failure(issue_id, &step, reason, false)
                    .await;
            }
            PipelineAction::AwaitingApproval {
                step,
                approval_state,
            } => {
                let issue = self
                    .state
                    .read()
                    .await
                    .get_running(issue_id)
                    .map(|entry| entry.issue.clone());
                if let Err(error) = self
                    .handle_post_step_approval(
                        issue_id,
                        &step,
                        approval_state,
                        None,
                        issue.as_ref(),
                    )
                    .await
                {
                    self.handle_pipeline_step_failure(
                        issue_id,
                        &step,
                        format!("failed to create post-step approval checkpoint: {error}"),
                        false,
                    )
                    .await;
                }
            }
            PipelineAction::Waiting
            | PipelineAction::AwaitingAction { .. }
            | PipelineAction::Dispatch(_)
            | PipelineAction::BlockedOnHuman { .. } => {}
        }
    }

    async fn state_worker_capacity_available(
        &self,
        issue: &Issue,
        config: &EnsembleConfig,
    ) -> bool {
        let (issue_state, selected_lane) = {
            let state = self.state.read().await;
            (
                state
                    .get_running(&issue.id)
                    .map(|entry| entry.issue.state.clone())
                    .unwrap_or_else(|| issue.state.clone()),
                state
                    .get_pipeline_run(&issue.id)
                    .and_then(PipelineRun::selected_workflow)
                    .map(|selected| selected.lane.clone()),
            )
        };
        if let Some(lane) = selected_lane {
            return config
                .scheduler
                .lanes
                .get(&lane)
                .is_some_and(|lane_config| {
                    has_available_lane_worker_capacity(
                        &self.cancellation_registry,
                        &lane,
                        lane_config.capacity,
                    )
                });
        }
        has_available_state_worker_capacity(
            &self.cancellation_registry,
            &issue_state,
            &config.agent.max_concurrent_agents_by_state,
        )
    }

    async fn dispatch_ready_steps_for_issue(&self, issue_id: &str, permit: &DispatchPermit) {
        let Some((issue, config_snapshot, attempt, requests)) = ({
            let mut state = self.state.write().await;
            let context = state
                .get_running(issue_id)
                .zip(state.get_pipeline_config(issue_id))
                .map(|(entry, config)| (entry.issue.clone(), config.clone(), entry.retry_attempt));
            match (context, state.get_pipeline_run_mut(issue_id)) {
                (Some((issue, config, attempt)), Some(run)) => match run.start() {
                    PipelineAction::Dispatch(requests) => Some((issue, config, attempt, requests)),
                    _ => None,
                },
                _ => None,
            }
        }) else {
            return;
        };

        for request in requests {
            if !self
                .state_worker_capacity_available(&issue, &config_snapshot)
                .await
            {
                return;
            }
            let workspace_path = match self.prepare_step_workspace(&issue, &config_snapshot).await {
                Ok(path) => path,
                Err(error) => {
                    let error = StepDispatchError::ordinary(error);
                    self.handle_step_dispatch_error(
                        &issue,
                        &request.step_name,
                        &config_snapshot,
                        &error,
                    )
                    .await;
                    return;
                }
            };
            let step_outputs = {
                let state = self.state.read().await;
                state
                    .get_pipeline_run(issue_id)
                    .and_then(|run| run.output_context_for(&request.step_name))
                    .unwrap_or_default()
            };
            match self
                .dispatch_step(
                    &issue,
                    Arc::clone(&config_snapshot),
                    StepDispatchContext {
                        step_name: &request.step_name,
                        agent_name: &request.agent_name,
                        step_kind: request.step_kind,
                        tracker_state: request.tracker_state.as_deref(),
                        attempt,
                        timeout_ms: Self::effective_step_timeout_ms(
                            request.timeout_ms,
                            &config_snapshot,
                        ),
                        interaction_response: None,
                        interaction_resume_id: None,
                        interaction_to_retire: None,
                        interaction_retirement_rollback: None,
                        workspace_path,
                        step_outputs,
                    },
                    permit,
                )
                .await
            {
                Ok(StepDispatchOutcome::Spawned) => {}
                Ok(StepDispatchOutcome::Deferred) => break,
                Err(error) => {
                    self.handle_step_dispatch_error(
                        &issue,
                        &request.step_name,
                        &config_snapshot,
                        &error,
                    )
                    .await;
                    return;
                }
            }
        }
    }

    async fn recovered_interaction_response(
        &self,
        issue_id: &str,
    ) -> Result<Option<(String, String, Option<InteractionResponseEnvelope>, bool)>, EnsembleError>
    {
        let record = self
            .pipeline_journal
            .latest_live_record_for_issue(issue_id)
            .await
            .map_err(|error| AgentError::IoError {
                reason: format!(
                    "failed to read the durable pipeline owner for issue {issue_id}: {error}"
                ),
            })?;
        let Some(record) = record else {
            return Ok(None);
        };
        if !matches!(
            record.kind,
            PipelineTransitionKind::StepRunning | PipelineTransitionKind::StepLaunched
        ) {
            return Ok(None);
        }
        let Some(interaction_id) = interaction_id_from_resume_reason(record.reason.as_deref())
        else {
            return Ok(None);
        };
        let interaction = self
            .interaction_store
            .get(interaction_id)
            .await?
            .ok_or_else(|| AgentError::PromptError {
                reason: format!(
                    "durable pipeline owner for issue {issue_id} references missing interaction '{interaction_id}'"
                ),
            })?;
        if interaction.status != InteractionStatus::Resolved {
            return Err(AgentError::PromptError {
                reason: format!(
                    "durable pipeline owner for issue {issue_id} references interaction '{interaction_id}' that is not resolved"
                ),
            }
            .into());
        }
        let response = match interaction.resume_strategy {
            InteractionResumeStrategy::RerunStep => {
                let response =
                    interaction
                        .response
                        .clone()
                        .ok_or_else(|| AgentError::PromptError {
                            reason: format!(
                                "resolved interaction '{interaction_id}' for issue {issue_id} has no response"
                            ),
                        })?;
                let resolved_at =
                    interaction
                        .resolved_at
                        .ok_or_else(|| AgentError::PromptError {
                            reason: format!(
                                "resolved interaction '{interaction_id}' for issue {issue_id} has no resolution timestamp"
                            ),
                        })?;
                Some(InteractionResponseEnvelope::new(
                    interaction.schema_version,
                    interaction.id.clone(),
                    interaction.kind.clone(),
                    response,
                    resolved_at,
                ))
            }
            InteractionResumeStrategy::AdvanceAfterStep => None,
        };
        Ok(Some((
            interaction.id.clone(),
            interaction.step_name,
            response,
            interaction.awaiting_resume,
        )))
    }

    async fn handle_step_dispatch_error(
        &self,
        issue: &Issue,
        step_name: &str,
        config_snapshot: &Arc<EnsembleConfig>,
        error: &StepDispatchError,
    ) {
        warn!(
            issue_id = %issue.id,
            step = step_name,
            error = %error,
            "failed to persist step dispatch"
        );
        let immutable_integrity_failure = error.kind == StepDispatchFailureKind::ImmutableIntegrity;
        if immutable_integrity_failure {
            let mut sibling_handles = mark_issue_for_drain(&self.cancellation_registry, &issue.id);
            if !self
                .await_worker_drain_with_event_pump(
                    &mut sibling_handles,
                    WORKER_DRAIN_TIMEOUT,
                    DrainEventMode::ApplyExceptIssue(&issue.id),
                )
                .await
            {
                warn!(issue_id = %issue.id, step = step_name, "immutable Artifact halt could not drain siblings");
                return;
            }
            remove_drained_workers(&self.cancellation_registry, &sibling_handles);
            let journal_transaction = self
                .pipeline_journal
                .begin_issue_transition(&issue.id)
                .await;
            let mut state = self.state.write().await;
            let Some(entry) = state.get_running(&issue.id) else {
                return;
            };
            let Some(run) = state.get_pipeline_run(&issue.id) else {
                return;
            };
            let mut halted_run = run.clone();
            halted_run.step_failed(step_name, error.to_string());
            let transition = PipelineTransitionInput {
                kind: PipelineTransitionKind::PipelineHalted,
                issue_id: issue.id.clone(),
                identifier: entry.identifier.clone(),
                run_id: entry.run_id.clone(),
                cycle: halted_run.cycle,
                step: Some(step_name.to_string()),
                reason: Some(error.to_string()),
                retry: None,
                snapshot: Some(halted_run.to_snapshot()),
                terminal_transition: None,
                delivery: None,
            };
            let transition_is_durable = match journal_transaction.append(transition.clone()).await {
                Ok(_) => true,
                Err(append_error) => {
                    match journal_transaction.latest_record_matches(&transition).await {
                        Ok(true) => true,
                        Ok(false) => {
                            warn!(
                                issue_id = %issue.id,
                                step = step_name,
                                error = %append_error,
                                "immutable Artifact halt was not durably committed; retaining running owner"
                            );
                            false
                        }
                        Err(reconciliation_error) => {
                            warn!(
                                issue_id = %issue.id,
                                step = step_name,
                                append_error = %append_error,
                                reconciliation_error = %reconciliation_error,
                                "immutable Artifact halt remains ambiguous; retaining running owner"
                            );
                            false
                        }
                    }
                }
            };
            if !transition_is_durable {
                return;
            }
            let Some(run) = state.get_pipeline_run_mut(&issue.id) else {
                return;
            };
            run.step_failed(step_name, error.to_string());
            let agent_name = run
                .step(step_name)
                .map(|step| step.agent.clone())
                .unwrap_or_default();
            let entry = state
                .remove_running(&issue.id)
                .expect("validated immutable halt owner is still running");
            state.add_runtime_seconds(&entry);
            state.add_waiting_on_human(WaitingOnHumanEntry {
                issue_id: issue.id.clone(),
                identifier: entry.identifier.clone(),
                interaction_request_id: format!("halted:{}:{step_name}", issue.id),
                step_name: step_name.to_string(),
                kind: InteractionKind::Handoff,
                prompt: error.to_string(),
                agent_name,
                retry_attempt: entry.retry_attempt,
                started_at: Some(entry.started_at),
                agent_input_tokens: entry.agent_input_tokens,
                agent_output_tokens: entry.agent_output_tokens,
                agent_total_tokens: entry.agent_total_tokens,
                requested_at: Utc::now(),
                run_id: entry.run_id.clone(),
                issue: Some(entry.issue),
            });
            return;
        }
        let terminal = {
            let mut state = self.state.write().await;
            let Some(run) = state.get_pipeline_run_mut(&issue.id) else {
                return;
            };
            if matches!(
                run.step_states.get(step_name),
                Some(StepState::Running { .. })
            ) {
                warn!(
                    issue_id = %issue.id,
                    step = step_name,
                    "retaining ambiguous running owner for restart reconciliation"
                );
                return;
            }
            if run.step_states.iter().any(|(name, step_state)| {
                name != step_name && matches!(step_state, StepState::Running { .. })
            }) {
                return;
            }

            run.step_failed(step_name, error.to_string());
            state.remove_running(&issue.id).map(|entry| {
                self.schedule_whole_issue_failure_retry(
                    &mut state,
                    config_snapshot,
                    entry,
                    &error.to_string(),
                    ScheduledRetryPipeline::Release,
                )
            })
        };
        self.commit_whole_issue_failure_retry(terminal).await;
    }

    async fn prepare_step_workspace(
        &self,
        issue: &Issue,
        config_snapshot: &Arc<EnsembleConfig>,
    ) -> Result<std::path::PathBuf, EnsembleError> {
        let branch_name = {
            let state = self.state.read().await;
            state
                .get_pipeline_run(&issue.id)
                .and_then(PipelineRun::workspace_branch_name)
                .map(str::to_owned)
                .or_else(|| issue.branch_name.clone())
        };
        let workspace = self
            .workspace_mgr
            .prepare_workspace_with_branch(&issue.id, &issue.identifier, branch_name.as_deref())
            .await?;

        if workspace.created_now {
            if let Some(ref script) = config_snapshot.hooks.after_create {
                crate::workspace::hooks::run_hook(
                    "after_create",
                    script,
                    &workspace.base_path,
                    config_snapshot.hooks.timeout_ms,
                )
                .await
                .map_err(|e| AgentError::PromptError {
                    reason: format!("after_create hook failed: {e}"),
                })?;
            }
        }

        Ok(workspace.base_path)
    }

    // Type-erase this lifecycle boundary so the acceptance state machine is not embedded in the
    // already-large worker-exit future.
    fn run_acceptance_phase<'a>(
        &'a self,
        issue: &'a Issue,
        config: &'a EnsembleConfig,
    ) -> Pin<Box<dyn Future<Output = AcceptancePhaseOutcome> + Send + 'a>> {
        Box::pin(self.run_acceptance_phase_inner(issue, config))
    }

    async fn run_acceptance_phase_inner(
        &self,
        issue: &Issue,
        config: &EnsembleConfig,
    ) -> AcceptancePhaseOutcome {
        let mut owned_worktrees = None;
        loop {
            let (baseline, mut candidate, run_id, owner) = {
                let state = self.state.read().await;
                let Some(run) = state.get_pipeline_run(&issue.id).cloned() else {
                    warn!(issue_id = %issue.id, "acceptance phase has no pipeline run");
                    return AcceptancePhaseOutcome::RetainedForRecovery;
                };
                let run_id = state
                    .running
                    .get(&issue.id)
                    .and_then(|entry| entry.run_id.clone())
                    .or_else(|| {
                        state
                            .waiting_on_human
                            .get(&issue.id)
                            .and_then(|entry| entry.run_id.clone())
                    })
                    .or_else(|| state.issue_run_ids.get(&issue.id).cloned());
                let Some(owner) = AcceptanceOwnerIdentity::capture(&state, &issue.id) else {
                    warn!(issue_id = %issue.id, "acceptance phase has no current owner");
                    return AcceptancePhaseOutcome::RetainedForRecovery;
                };
                (run.to_snapshot(), run, run_id, owner)
            };

            let plan = candidate
                .resolved_acceptance_plan
                .clone()
                .unwrap_or_else(|| legacy_command_plan(config));
            if let Err(error) = validate_acceptance_attempts(&candidate.to_snapshot(), config) {
                warn!(issue_id = %issue.id, error = %error, "acceptance evidence does not match config");
                return AcceptancePhaseOutcome::RetainedForRecovery;
            }
            let current_attempt = candidate
                .acceptance_attempts
                .iter()
                .position(|attempt| attempt.cycle == candidate.cycle);
            if plan.pre_final_len() == 0
                && (plan.required_pull_requests.is_empty() || current_attempt.is_some())
            {
                return AcceptancePhaseOutcome::Passed;
            }
            let check_to_run = if let Some(attempt_index) = current_attempt {
                let results = &candidate.acceptance_attempts[attempt_index].results;
                if results.len() >= plan.pre_final_len() {
                    if results[..plan.pre_final_len()]
                        .iter()
                        .all(|result| result.status == AcceptanceStatus::Passed)
                    {
                        return AcceptancePhaseOutcome::Passed;
                    }
                    let summary = results
                        .iter()
                        .find(|result| result.status != AcceptanceStatus::Passed)
                        .map(|result| result.summary.clone())
                        .unwrap_or_else(|| "acceptance failed".to_string());
                    return AcceptancePhaseOutcome::Failed {
                        reason: summary,
                        owner,
                    };
                }
                let index = results.len();
                if index < plan.commands.len() {
                    if candidate.resolved_acceptance_plan.is_some() && !plan.matches_config(config)
                    {
                        warn!(issue_id = %issue.id, "configuration changed before an unfinished acceptance command");
                        return AcceptancePhaseOutcome::RetainedForRecovery;
                    }
                    let Some(command) = config.acceptance.commands.get(index) else {
                        return AcceptancePhaseOutcome::RetainedForRecovery;
                    };
                    if command.name != plan.commands[index] {
                        return AcceptancePhaseOutcome::RetainedForRecovery;
                    }
                    Some(PreFinalAcceptanceCheck::Command(command.clone()))
                } else {
                    let index = index - plan.commands.len();
                    if let Some(rule) = plan.required_files.get(index) {
                        Some(PreFinalAcceptanceCheck::File(rule.clone()))
                    } else {
                        let index = index - plan.required_files.len();
                        plan.required_handoff_sections
                            .get(index)
                            .cloned()
                            .map(PreFinalAcceptanceCheck::Handoff)
                    }
                }
            } else {
                candidate
                    .acceptance_attempts
                    .push(crate::acceptance::AcceptanceAttempt {
                        cycle: candidate.cycle,
                        results: Vec::new(),
                    });
                None
            };
            let transition_kind = if check_to_run.is_some() {
                PipelineTransitionKind::AcceptanceCheckCompleted
            } else {
                PipelineTransitionKind::AcceptanceStarted
            };

            let result = match check_to_run.as_ref() {
                Some(PreFinalAcceptanceCheck::Command(command)) => {
                    let workspace_path = self.workspace_mgr.workspace_path(&issue.id);
                    Some(self.acceptance_runner.run(command, &workspace_path).await)
                }
                Some(PreFinalAcceptanceCheck::File(rule)) => {
                    let worktrees = owned_worktrees.get_or_insert_with(|| {
                        self.workspace_mgr
                            .owned_worktree_paths(&issue.id)
                            .unwrap_or_default()
                    });
                    Some(evaluate_file_requirement(rule, worktrees))
                }
                Some(PreFinalAcceptanceCheck::Handoff(rule)) => {
                    Some(evaluate_handoff_requirement(rule, &candidate.step_outputs))
                }
                None => None,
            };
            {
                let state = self.state.read().await;
                if !Self::acceptance_owner_matches_run(&state, &issue.id, &owner, &baseline) {
                    warn!(issue_id = %issue.id, "acceptance execution belongs to a stale running attempt");
                    return AcceptancePhaseOutcome::RetainedForRecovery;
                }
            }
            let reason = if let Some(result) = result {
                let Some(attempt) = candidate
                    .acceptance_attempts
                    .iter_mut()
                    .find(|attempt| attempt.cycle == candidate.cycle)
                else {
                    return AcceptancePhaseOutcome::RetainedForRecovery;
                };
                let summary = result.summary.clone();
                attempt.results.push(result);
                Some(summary)
            } else {
                None
            };
            let candidate_snapshot = candidate.to_snapshot();
            let transition = PipelineTransitionInput {
                kind: transition_kind,
                issue_id: issue.id.clone(),
                identifier: issue.identifier.clone(),
                run_id,
                cycle: candidate.cycle,
                step: None,
                reason,
                retry: None,
                snapshot: Some(candidate_snapshot.clone()),
                terminal_transition: None,
                delivery: None,
            };
            let journal_transaction = self
                .pipeline_journal
                .begin_issue_transition(&issue.id)
                .await;
            if let Err(error) = journal_transaction.append(transition.clone()).await {
                match journal_transaction.latest_record_matches(&transition).await {
                    Ok(true) => {}
                    Ok(false) => {
                        drop(journal_transaction);
                        warn!(issue_id = %issue.id, error = %error, "acceptance transition was not journaled; scheduling in-process recovery");
                        self.release_acceptance_owner_for_recovery(
                            &issue.id, &owner, &baseline, None,
                        )
                        .await;
                        return AcceptancePhaseOutcome::RetainedForRecovery;
                    }
                    Err(reconciliation_error) => {
                        warn!(issue_id = %issue.id, append_error = %error, reconciliation_error = %reconciliation_error, "acceptance transition outcome is ambiguous; retaining the active owner for recovery");
                        self.pending_acceptance_transitions
                            .lock()
                            .unwrap_or_else(|poisoned| poisoned.into_inner())
                            .insert(
                                issue.id.clone(),
                                PendingAcceptanceTransition {
                                    expected: transition,
                                    candidate: candidate_snapshot,
                                    owner,
                                    baseline,
                                },
                            );
                        self.refresh_requested.notify_one();
                        return AcceptancePhaseOutcome::RetainedForRecovery;
                    }
                }
            }
            drop(journal_transaction);

            let mut state = self.state.write().await;
            let owner_is_current =
                Self::acceptance_owner_matches_run(&state, &issue.id, &owner, &baseline);
            let Some(current) = state.get_pipeline_run_mut(&issue.id) else {
                return AcceptancePhaseOutcome::RetainedForRecovery;
            };
            if !owner_is_current {
                warn!(issue_id = %issue.id, "acceptance result belongs to a stale running attempt");
                return AcceptancePhaseOutcome::RetainedForRecovery;
            }
            current.acceptance_attempts = candidate.acceptance_attempts;
        }
    }

    async fn reconcile_pending_acceptance_transitions(&self) {
        let pending = self
            .pending_acceptance_transitions
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .values()
            .cloned()
            .collect::<Vec<_>>();
        for pending in pending {
            let issue_id = pending.expected.issue_id.clone();
            let journal_transaction = self
                .pipeline_journal
                .begin_issue_transition(&issue_id)
                .await;
            let visibility = journal_transaction
                .latest_record_matches(&pending.expected)
                .await;
            drop(journal_transaction);
            match visibility {
                Ok(is_exact) => {
                    let released = self
                        .release_acceptance_owner_for_recovery(
                            &issue_id,
                            &pending.owner,
                            &pending.baseline,
                            is_exact.then_some(&pending.candidate),
                        )
                        .await;
                    let owner_is_still_current = if released {
                        false
                    } else {
                        let state = self.state.read().await;
                        Self::acceptance_owner_matches_run(
                            &state,
                            &issue_id,
                            &pending.owner,
                            &pending.baseline,
                        )
                    };
                    if released || !owner_is_still_current {
                        self.pending_acceptance_transitions
                            .lock()
                            .unwrap_or_else(|poisoned| poisoned.into_inner())
                            .remove(&issue_id);
                    }
                }
                Err(error) => warn!(
                    issue_id,
                    error = %error,
                    "acceptance transition remains ambiguous; retaining the active owner"
                ),
            }
        }
    }

    fn acceptance_owner_matches_run(
        state: &OrchestratorState,
        issue_id: &str,
        owner: &AcceptanceOwnerIdentity,
        baseline: &PipelineRunSnapshot,
    ) -> bool {
        owner.is_current(state, issue_id)
            && state
                .get_pipeline_run(issue_id)
                .is_some_and(|run| run.to_snapshot() == *baseline)
    }

    async fn release_acceptance_owner_for_recovery(
        &self,
        issue_id: &str,
        owner: &AcceptanceOwnerIdentity,
        baseline: &PipelineRunSnapshot,
        replacement: Option<&PipelineRunSnapshot>,
    ) -> bool {
        if let AcceptanceOwnerIdentity::Waiting {
            interaction_request_id,
            ..
        } = owner
        {
            let is_current = {
                let state = self.state.read().await;
                Self::acceptance_owner_matches_run(&state, issue_id, owner, baseline)
            };
            if !is_current {
                return false;
            }
            let (previous, cleared) = match self
                .interaction_store
                .retire_waiting_state(interaction_request_id)
                .await
            {
                Ok(retired) => retired,
                Err(error) => {
                    warn!(issue_id, interaction_id = interaction_request_id, error = %error, "failed to retire acceptance recovery interaction owner");
                    return false;
                }
            };
            let released = {
                let mut state = self.state.write().await;
                let is_current =
                    Self::acceptance_owner_matches_run(&state, issue_id, owner, baseline);
                if is_current {
                    if let (Some(current), Some(replacement)) =
                        (state.get_pipeline_run_mut(issue_id), replacement)
                    {
                        current.acceptance_attempts = replacement.acceptance_attempts.clone();
                    }
                    state.remove_waiting_on_human(issue_id);
                }
                is_current
            };
            if released {
                self.refresh_requested.notify_one();
            } else if let Err(error) = self
                .interaction_store
                .restore_waiting_state_after_failed_transition(&cleared, &previous)
                .await
            {
                warn!(issue_id, interaction_id = interaction_request_id, error = %error, "failed to restore stale acceptance interaction owner");
            }
            return released;
        }

        let released = {
            let mut state = self.state.write().await;
            let is_current = Self::acceptance_owner_matches_run(&state, issue_id, owner, baseline);
            if !is_current {
                false
            } else {
                if let (Some(current), Some(replacement)) =
                    (state.get_pipeline_run_mut(issue_id), replacement)
                {
                    current.acceptance_attempts = replacement.acceptance_attempts.clone();
                }
                state.remove_running(issue_id);
                true
            }
        };
        if released {
            self.refresh_requested.notify_one();
        }
        released
    }

    // Keep terminal failure bookkeeping behind a separate poll boundary from acceptance checks.
    fn schedule_acceptance_failure<'a>(
        &'a self,
        issue: &'a Issue,
        config: &'a EnsembleConfig,
        reason: &'a str,
        owner: &'a AcceptanceOwnerIdentity,
    ) -> Pin<Box<dyn Future<Output = ()> + Send + 'a>> {
        Box::pin(self.schedule_acceptance_failure_inner(issue, config, reason, owner))
    }

    async fn schedule_acceptance_failure_inner(
        &self,
        issue: &Issue,
        config: &EnsembleConfig,
        reason: &str,
        owner: &AcceptanceOwnerIdentity,
    ) {
        let outcome = {
            let mut state = self.state.write().await;
            if !owner.is_current(&state, &issue.id) {
                warn!(issue_id = %issue.id, "acceptance failure belongs to a stale owner");
                return;
            }
            let fallback_run_id = state.issue_run_ids.get(&issue.id).cloned();
            let entry = state.remove_running(&issue.id).or_else(|| {
                state.remove_waiting_on_human(&issue.id).map(|waiting| {
                    Self::running_entry_from_waiting(waiting, issue, fallback_run_id)
                })
            });
            entry.map(|entry| {
                self.schedule_whole_issue_failure_retry(
                    &mut state,
                    config,
                    entry,
                    reason,
                    ScheduledRetryPipeline::Release,
                )
            })
        };
        self.commit_whole_issue_failure_retry(outcome).await;
    }

    /// Dispatch a single pipeline step after its workspace is ready.
    // Keep the #480 immutable preflight disposition out of callers that already retain event or
    // terminal-lifecycle state on a Tokio worker stack.
    fn dispatch_step<'a>(
        &'a self,
        issue: &'a Issue,
        config_snapshot: Arc<EnsembleConfig>,
        dispatch: StepDispatchContext<'a>,
        permit: &'a DispatchPermit,
    ) -> Pin<Box<dyn Future<Output = Result<StepDispatchOutcome, StepDispatchError>> + Send + 'a>>
    {
        Box::pin(self.dispatch_step_inner(issue, config_snapshot, dispatch, permit))
    }

    async fn dispatch_step_inner(
        &self,
        issue: &Issue,
        config_snapshot: Arc<EnsembleConfig>,
        dispatch: StepDispatchContext<'_>,
        _permit: &DispatchPermit,
    ) -> Result<StepDispatchOutcome, StepDispatchError> {
        if !self
            .select_current_authorization_evidence(issue, dispatch.step_name)
            .await?
        {
            return Ok(StepDispatchOutcome::Deferred);
        }
        let (
            worker_identity,
            issue_snapshot,
            immutable_inputs,
            immutable_input_count,
            artifact_access,
        ) = {
            let state = self.state.read().await;
            let running_entry =
                state
                    .get_running(&issue.id)
                    .ok_or_else(|| AgentError::PromptError {
                        reason: format!(
                            "cannot dispatch step '{}' without a running issue",
                            dispatch.step_name
                        ),
                    })?;
            let run_id = running_entry
                .run_id
                .clone()
                .ok_or_else(|| AgentError::PromptError {
                    reason: format!(
                        "cannot dispatch step '{}' without a stable run id",
                        dispatch.step_name
                    ),
                })?;
            let cycle = state
                .get_pipeline_run(&issue.id)
                .map(|run| run.cycle)
                .ok_or_else(|| AgentError::PromptError {
                    reason: format!(
                        "cannot dispatch step '{}' without a pipeline run",
                        dispatch.step_name
                    ),
                })?;
            let (immutable_inputs, immutable_input_count): (
                Vec<artifact::ArtifactSnapshot>,
                usize,
            ) = state
                .get_pipeline_run(&issue.id)
                .filter(|run| {
                    run.artifact_inputs_for(dispatch.step_name)
                        .is_some_and(|(_, access)| access == ArtifactAccess::Immutable)
                })
                .map(|run| {
                    let producers = run
                        .artifact_inputs_for(dispatch.step_name)
                        .expect("immutable Artifact access has resolved inputs")
                        .0;
                    (
                        producers
                            .iter()
                            .filter_map(|producer| run.artifact_snapshots.get(producer).cloned())
                            .collect(),
                        producers.len(),
                    )
                })
                .unwrap_or_default();
            let artifact_access = state
                .get_pipeline_run(&issue.id)
                .and_then(|run| run.artifact_inputs_for(dispatch.step_name))
                .map(|(_, access)| access)
                .unwrap_or_default();
            (
                WorkerIdentity {
                    issue_id: issue.id.clone(),
                    run_id,
                    cycle,
                    step_name: dispatch.step_name.to_string(),
                    started_at: running_entry.started_at,
                },
                running_entry.issue.clone(),
                immutable_inputs,
                immutable_input_count,
                artifact_access,
            )
        };
        let issue = &issue_snapshot;
        if immutable_inputs.len() != immutable_input_count {
            return Err(StepDispatchError::immutable_integrity(
                AgentError::PromptError {
                    reason: format!(
                        "immutable Artifact input is unavailable before step '{}'",
                        dispatch.step_name
                    ),
                },
            ));
        }
        let cancel_token = tokio_util::sync::CancellationToken::new();
        let (completion_tx, completion_rx) = watch::channel(false);
        let selected_lane = {
            let state = self.state.read().await;
            state
                .get_pipeline_run(&issue.id)
                .and_then(PipelineRun::selected_workflow)
                .map(|selected| selected.lane.clone())
        };
        let worker_capacity = if let Some(lane) = selected_lane.as_deref() {
            let Some(capacity) = config_snapshot
                .scheduler
                .lanes
                .get(lane)
                .map(|lane| lane.capacity)
            else {
                return Err(AgentError::PromptError {
                    reason: format!("selected scheduler lane '{lane}' no longer exists"),
                }
                .into());
            };
            WorkerCapacity::lane(lane, capacity)
        } else {
            WorkerCapacity::new(
                &issue.state,
                &config_snapshot.agent.max_concurrent_agents_by_state,
            )
        };
        let scheduler_reservation = {
            let (resource_requests, affected_paths, outputs) = {
                let state = self.state.read().await;
                let run =
                    state
                        .get_pipeline_run(&issue.id)
                        .ok_or_else(|| AgentError::PromptError {
                            reason: format!(
                                "cannot dispatch step '{}' without a pipeline run",
                                dispatch.step_name
                            ),
                        })?;
                let (resource_requests, affected_paths) = run
                    .scheduler_requirements_for(dispatch.step_name)
                    .ok_or_else(|| AgentError::PromptError {
                        reason: format!("pipeline run has no step '{}'", dispatch.step_name),
                    })?;
                (resource_requests, affected_paths, run.step_outputs.clone())
            };
            let repositories = config_snapshot
                .repos
                .iter()
                .enumerate()
                .map(|(index, repo)| repository_key(repo, index))
                .collect();
            let paths = affected_paths
                .as_ref()
                .map(|source| resolve_output_paths(source, &outputs, &repositories))
                .transpose()
                .map_err(|reason| AgentError::PromptError { reason })?
                .unwrap_or_default();
            SchedulerReservation {
                resources: resource_requests,
                paths,
            }
        };
        let resource_capacities = config_snapshot
            .scheduler
            .resources
            .iter()
            .map(|(name, config)| (name.clone(), config.capacity))
            .collect();
        match try_reserve_scheduler_worker_with_workspace_exclusivity(
            &self.cancellation_registry,
            worker_identity.clone(),
            cancel_token.clone(),
            completion_rx,
            config_snapshot.concurrency.max_concurrent_agents,
            config_snapshot.concurrency.max_step_parallelism,
            worker_capacity,
            &resource_capacities,
            scheduler_reservation.clone(),
            artifact_access == ArtifactAccess::Immutable,
        ) {
            Ok(()) => {}
            Err(
                WorkerReservationError::GlobalCapacityExhausted
                | WorkerReservationError::IssueCapacityExhausted
                | WorkerReservationError::CapacityBucketExhausted
                | WorkerReservationError::ResourceExhausted
                | WorkerReservationError::PathConflict
                | WorkerReservationError::IssueWorkspaceExclusive,
            ) => {
                debug!(
                    issue_id = %issue.id,
                    step = dispatch.step_name,
                    "worker capacity exhausted; leaving ready step pending"
                );
                return Ok(StepDispatchOutcome::Deferred);
            }
            Err(WorkerReservationError::DuplicateIdentity) => {
                return Err(AgentError::PromptError {
                    reason: format!(
                        "worker '{}' for issue '{}' already owns a reservation",
                        dispatch.step_name, issue.id
                    ),
                }
                .into());
            }
        }
        let reservation = PendingWorkerReservation::new(
            self.cancellation_registry.clone(),
            worker_identity.clone(),
            completion_tx,
        );
        if !immutable_inputs.is_empty() {
            let repositories = self
                .workspace_mgr
                .owned_worktree_paths(&issue.id)
                .map(|paths| paths.into_iter().collect::<BTreeMap<_, _>>())
                .map_err(|error| StepDispatchError::immutable_integrity(AgentError::PromptError {
                    reason: format!(
                        "immutable Artifact input could not be verified: prepared worktree unavailable: {error}"
                    ),
                }))?;
            let violations = artifact::verify_immutable_inputs(
                dispatch.step_name,
                &immutable_inputs,
                &repositories,
            )
            .await
            .map_err(|reason| {
                StepDispatchError::immutable_integrity(AgentError::PromptError {
                    reason: format!("immutable Artifact input could not be verified: {reason}"),
                })
            })?;
            if !violations.is_empty() {
                if let Some(run) = self.state.write().await.get_pipeline_run_mut(&issue.id) {
                    run.record_artifact_integrity_violations(violations.clone());
                }
                return Err(StepDispatchError::immutable_integrity(
                    AgentError::PromptError {
                        reason: format!(
                            "immutable Artifact input changed before step '{}': {}",
                            dispatch.step_name,
                            violations
                                .iter()
                                .map(|violation| format!(
                                    "{}:{} ({})",
                                    violation.producer_step,
                                    violation.repository,
                                    violation.artifact_identity
                                ))
                                .collect::<Vec<_>>()
                                .join(", ")
                        ),
                    },
                ));
            }
        }
        info!(
            event = STEP_STARTED,
            issue_id = %issue.id,
            identifier = %issue.identifier,
            step = dispatch.step_name,
            agent = dispatch.agent_name,
            "dispatching pipeline step"
        );

        if !self
            .apply_tracker_handoff_before_dispatch(
                issue,
                dispatch.step_name,
                dispatch.tracker_state,
            )
            .await?
        {
            return Ok(StepDispatchOutcome::Deferred);
        }

        // Reserve this issue's journal ordering before publishing the speculative
        // in-memory owner. The global state lock is not held during journal I/O.
        let journal_transaction = self
            .pipeline_journal
            .begin_issue_transition(&issue.id)
            .await;
        let artifact_access_evidence = (artifact_access == ArtifactAccess::Immutable).then(|| {
            artifact::ArtifactAccessEvidence {
                consumer_step: dispatch.step_name.to_string(),
                enforcement: immutable_artifact_access_enforcement(
                    config_snapshot.agents.get(dispatch.agent_name),
                ),
            }
        });

        // Mark step as running in pipeline
        let (
            run_id,
            sequence,
            attempt_num,
            step_running_transition,
            previous_step_state,
            running_session_id,
            previous_artifact_access_evidence,
        ) = {
            let mut state = self.state.write().await;
            let step_owner_is_current = state
                .get_pipeline_run(&issue.id)
                .and_then(|run| run.step_states.get(dispatch.step_name))
                .is_some_and(|step_state| match step_state {
                    StepState::Pending => true,
                    StepState::BlockedOnHuman {
                        interaction_request_id,
                    } => dispatch.interaction_resume_id == Some(interaction_request_id.as_str()),
                    _ => false,
                });
            let owner_is_current = state.get_running(&issue.id).is_some_and(|entry| {
                entry.run_id.as_deref() == Some(worker_identity.run_id.as_str())
                    && entry.started_at == worker_identity.started_at
            }) && state
                .get_pipeline_run(&issue.id)
                .is_some_and(|run| run.cycle == worker_identity.cycle && step_owner_is_current);
            if !owner_is_current {
                return Err(AgentError::PromptError {
                    reason: format!(
                        "worker reservation owner changed before step '{}' could launch",
                        dispatch.step_name
                    ),
                }
                .into());
            }
            let run_context = Self::run_context_for_issue(&mut state, &issue.id);
            let run =
                state
                    .get_pipeline_run_mut(&issue.id)
                    .ok_or_else(|| AgentError::PromptError {
                        reason: format!(
                            "cannot dispatch step '{}' without a pipeline run",
                            dispatch.step_name
                        ),
                    })?;
            let previous_artifact_access_evidence = artifact_access_evidence
                .as_ref()
                .and_then(|evidence| run.record_artifact_access_evidence(evidence.clone()));
            let previous_step_state = run.step_states.get(dispatch.step_name).cloned();
            let running_session_id = format!(
                "{}-{}-{}",
                issue.id, dispatch.step_name, dispatch.agent_name
            );
            run.set_active_scheduler_reservation(dispatch.step_name, scheduler_reservation);
            run.mark_running(dispatch.step_name, running_session_id.clone());
            let transition = Self::transition_input_for_run(
                &state,
                &issue.id,
                &issue.identifier,
                PipelineTransitionKind::StepRunning,
                Some(dispatch.step_name.to_string()),
                dispatch.interaction_resume_id.map(|interaction_id| {
                    format!("{INTERACTION_RESUME_REASON_PREFIX}{interaction_id}")
                }),
                None,
            );
            (
                run_context.0,
                run_context.1,
                run_context.2,
                transition,
                previous_step_state,
                running_session_id,
                previous_artifact_access_evidence,
            )
        };

        if let Some(input) = step_running_transition {
            let input_for_reconciliation = input.clone();
            if let Err(error) = journal_transaction.append(input).await {
                match journal_transaction
                    .latest_record_matches(&input_for_reconciliation)
                    .await
                {
                    Ok(true) => {}
                    Ok(false) => {
                        let mut state = self.state.write().await;
                        if state
                            .get_pipeline_run(&issue.id)
                            .and_then(|run| run.step_states.get(dispatch.step_name))
                            == Some(&StepState::Running {
                                session_id: running_session_id,
                            })
                        {
                            if let Some(previous_step_state) = previous_step_state {
                                let run = state.get_pipeline_run_mut(&issue.id).expect(
                                    "pipeline run was present while validating dispatch rollback",
                                );
                                run.step_states
                                    .insert(dispatch.step_name.to_string(), previous_step_state);
                                run.clear_active_scheduler_reservation(dispatch.step_name);
                                if let Some(evidence) = artifact_access_evidence.as_ref() {
                                    run.restore_artifact_access_evidence(
                                        evidence,
                                        previous_artifact_access_evidence.clone(),
                                    );
                                }
                            }
                        }
                        return Err(AgentError::PromptError {
                            reason: format!(
                                "failed to persist step '{}' dispatch: {error}",
                                dispatch.step_name
                            ),
                        }
                        .into());
                    }
                    Err(reconciliation_error) => {
                        warn!(
                            issue_id = %issue.id,
                            step = dispatch.step_name,
                            append_error = %error,
                            reconciliation_error = %reconciliation_error,
                            "step dispatch append outcome is ambiguous; retaining the speculative owner"
                        );
                        return Err(AgentError::PromptError {
                            reason: format!(
                                "failed to confirm step '{}' dispatch persistence after append error: {error}; reconciliation failed: {reconciliation_error}",
                                dispatch.step_name
                            ),
                        }
                        .into());
                    }
                }
            }
        }

        let retired_interaction = if let Some(interaction_id) = dispatch.interaction_to_retire {
            match self
                .interaction_store
                .retire_waiting_state(interaction_id)
                .await
            {
                Ok(retired) => Some(retired),
                Err(interaction_error) => {
                    let derived_rollback_transition = {
                        let mut state = self.state.write().await;
                        let run = state.get_pipeline_run_mut(&issue.id);
                        if let Some(run) = run {
                            if run.step_states.get(dispatch.step_name)
                                == Some(&StepState::Running {
                                    session_id: running_session_id.clone(),
                                })
                            {
                                if let Some(previous_step_state) = previous_step_state.clone() {
                                    run.step_states.insert(
                                        dispatch.step_name.to_string(),
                                        previous_step_state,
                                    );
                                    run.clear_active_scheduler_reservation(dispatch.step_name);
                                    if let Some(evidence) = artifact_access_evidence.as_ref() {
                                        run.restore_artifact_access_evidence(
                                            evidence,
                                            previous_artifact_access_evidence.clone(),
                                        );
                                    }
                                }
                            }
                        }
                        let rollback_kind = match previous_step_state {
                            Some(StepState::BlockedOnHuman { .. }) => {
                                Some(PipelineTransitionKind::StepBlockedOnHuman)
                            }
                            Some(StepState::AwaitingApproval { .. }) => {
                                Some(PipelineTransitionKind::StepAwaitingApproval)
                            }
                            _ => None,
                        };
                        rollback_kind.and_then(|kind| {
                            Self::transition_input_for_run(
                                &state,
                                &issue.id,
                                &issue.identifier,
                                kind,
                                Some(dispatch.step_name.to_string()),
                                Some(format!(
                                    "interaction '{}' retirement failed: {interaction_error}",
                                    interaction_id
                                )),
                                None,
                            )
                        })
                    };
                    let rollback_transition = dispatch
                        .interaction_retirement_rollback
                        .clone()
                        .or(derived_rollback_transition);
                    if let Some(rollback_transition) = rollback_transition {
                        if let Err(rollback_error) =
                            journal_transaction.append(rollback_transition).await
                        {
                            warn!(
                                issue_id = %issue.id,
                                step = dispatch.step_name,
                                interaction_id,
                                error = %rollback_error,
                                "failed to persist blocked owner after interaction retirement failure"
                            );
                        }
                    }
                    return Err(StepDispatchError::ordinary(EnsembleError::from(
                        interaction_error,
                    )));
                }
            }
        } else {
            None
        };

        self.publish_pipeline_event(
            run_id,
            sequence,
            attempt_num,
            PipelineEvent::StepStarted {
                issue_identifier: issue.identifier.clone(),
                timestamp: Utc::now(),
                step_name: dispatch.step_name.to_string(),
                agent_name: dispatch.agent_name.to_string(),
                detail: format!("step started (attempt {})", attempt_num),
            },
        )
        .await;

        // Spawn worker task. Immutable consumers wait behind a gate until a
        // `StepLaunched` snapshot commits their authority to run.
        let issue_clone = issue.clone();
        let step_name_owned = dispatch.step_name.to_string();
        let agent_name_owned = dispatch.agent_name.to_string();
        let interaction_response = dispatch.interaction_response.clone();
        let runner = Arc::clone(&self.agent_runner);
        let orchestrator_event_tx = self.worker_tx.clone();
        let workspace_path = dispatch.workspace_path.clone();
        let attempt = dispatch.attempt;
        let timeout_ms = dispatch.timeout_ms;
        let step_outputs = dispatch.step_outputs.clone();
        if artifact_access == ArtifactAccess::Immutable {
            let (start_gate, wait_for_launch) = oneshot::channel();
            let local_event_rx = spawn_agent_worker(
                runner,
                config_snapshot,
                issue_clone,
                agent_name_owned,
                step_name_owned,
                dispatch.step_kind,
                artifact_access,
                attempt,
                timeout_ms,
                interaction_response,
                workspace_path,
                cancel_token,
                step_outputs,
                Some(wait_for_launch),
            );

            let launch_transition = {
                let mut state = self.state.write().await;
                let Some(run) = state.get_pipeline_run_mut(&issue.id) else {
                    return Err(AgentError::PromptError {
                        reason: format!(
                            "cannot confirm immutable step '{}' launch without a pipeline run",
                            dispatch.step_name
                        ),
                    }
                    .into());
                };
                run.mark_immutable_consumer_launch_committed(dispatch.step_name);
                Self::transition_input_for_run(
                    &state,
                    &issue.id,
                    &issue.identifier,
                    PipelineTransitionKind::StepLaunched,
                    Some(dispatch.step_name.to_string()),
                    dispatch.interaction_resume_id.map(|interaction_id| {
                        format!("{INTERACTION_RESUME_REASON_PREFIX}{interaction_id}")
                    }),
                    None,
                )
            }
            .expect("running immutable step has a transition snapshot");
            let pending = PendingImmutableLaunch {
                issue: issue.clone(),
                expected: launch_transition.clone(),
                identity: worker_identity.clone(),
                reservation,
                start_gate,
                local_event_rx,
                previous_step_state: previous_step_state
                    .clone()
                    .expect("immutable launch has a prior step state"),
                running_session_id: running_session_id.clone(),
                evidence: artifact_access_evidence
                    .expect("immutable launch records access evidence"),
                previous_evidence: previous_artifact_access_evidence,
                retired_interaction,
            };
            match journal_transaction.append(launch_transition.clone()).await {
                Ok(_) => self.release_immutable_launch(pending).await,
                Err(error) => match journal_transaction
                    .latest_record_matches(&launch_transition)
                    .await
                {
                    Ok(true) => self.release_immutable_launch(pending).await,
                    Ok(false) => {
                        self.rollback_unconfirmed_immutable_launch(pending, &journal_transaction)
                            .await;
                        return Err(AgentError::PromptError {
                            reason: format!(
                                "failed to persist immutable step '{}' launch: {error}",
                                dispatch.step_name
                            ),
                        }
                        .into());
                    }
                    Err(reconciliation_error) => {
                        warn!(
                            issue_id = %issue.id,
                            step = dispatch.step_name,
                            append_error = %error,
                            reconciliation_error = %reconciliation_error,
                            "immutable worker launch remains ambiguous; retaining its closed gate"
                        );
                        self.pending_immutable_launches
                            .lock()
                            .unwrap_or_else(|poisoned| poisoned.into_inner())
                            .insert(worker_identity, pending);
                    }
                },
            }
            return Ok(StepDispatchOutcome::Spawned);
        }
        let bridge_registry = self.cancellation_registry.clone();
        let bridge_identity = worker_identity.clone();
        let completion_tx = reservation.mark_launched()?;
        let local_event_rx = spawn_agent_worker(
            runner,
            config_snapshot,
            issue_clone,
            agent_name_owned,
            step_name_owned,
            dispatch.step_kind,
            artifact_access,
            attempt,
            timeout_ms,
            interaction_response,
            workspace_path,
            cancel_token,
            step_outputs,
            None,
        );
        tokio::spawn(bridge_worker_events(
            local_event_rx,
            orchestrator_event_tx,
            bridge_registry,
            bridge_identity,
            completion_tx,
        ));
        Ok(StepDispatchOutcome::Spawned)
    }

    async fn apply_tracker_handoff_before_dispatch(
        &self,
        issue: &Issue,
        step_name: &str,
        tracker_state: Option<&str>,
    ) -> Result<bool, StepDispatchError> {
        let handoff = self
            .state
            .read()
            .await
            .get_pipeline_run(&issue.id)
            .and_then(|run| run.authorization_handoff(step_name));
        match handoff {
            Some(AuthorizationHandoffMode::WaitForEvent) => Ok(true),
            Some(AuthorizationHandoffMode::AutomaticTransition) => {
                let Some(target_state) = tracker_state else {
                    return Ok(false);
                };
                let pending = {
                    let mut state = self.state.write().await;
                    let Some(run) = state.get_pipeline_run_mut(&issue.id) else {
                        return Ok(false);
                    };
                    match run.automatic_transition_state(step_name) {
                        Some(AutomaticTransitionState::Applied {
                            target_state: applied,
                        }) if applied == target_state => return Ok(true),
                        Some(AutomaticTransitionState::Pending {
                            target_state: pending_target,
                            expected_state,
                        }) if pending_target == target_state => {
                            Some((expected_state.clone(), false, None))
                        }
                        _ => {
                            let previous = run.automatic_transition_state(step_name).cloned();
                            run.set_automatic_transition_pending(
                                step_name,
                                target_state.to_string(),
                                issue.state.clone(),
                            );
                            Some((issue.state.clone(), true, previous))
                        }
                    }
                };
                let Some((expected_state, newly_pending, previous_pending)) = pending else {
                    return Ok(false);
                };
                if newly_pending {
                    let transition = {
                        let state = self.state.read().await;
                        Self::transition_input_for_run(
                            &state,
                            &issue.id,
                            &issue.identifier,
                            PipelineTransitionKind::AutomaticTransitionPending,
                            Some(step_name.to_string()),
                            None,
                            None,
                        )
                    };
                    if let Some(transition) = transition {
                        let transaction = self
                            .pipeline_journal
                            .begin_issue_transition(&issue.id)
                            .await;
                        let pending_is_durable = match transaction.append(transition.clone()).await
                        {
                            Ok(_) => true,
                            Err(_) => transaction
                                .latest_record_matches(&transition)
                                .await
                                .unwrap_or(false),
                        };
                        drop(transaction);
                        if !pending_is_durable {
                            if let Some(run) =
                                self.state.write().await.get_pipeline_run_mut(&issue.id)
                            {
                                run.restore_automatic_transition_state(step_name, previous_pending);
                            }
                            return Ok(false);
                        }
                    } else {
                        return Ok(false);
                    }
                }
                let current = match self
                    .tracker
                    .fetch_issue_states_by_ids(std::slice::from_ref(&issue.id))
                    .await
                {
                    Ok(states) => states
                        .into_iter()
                        .find(|candidate| candidate.id == issue.id),
                    Err(_) => return Ok(false),
                };
                let Some(current) = current else {
                    return Ok(false);
                };
                if current.state != target_state {
                    if current.state != expected_state || !self.tracker.supports_writes() {
                        return Ok(false);
                    }
                    if self
                        .tracker
                        .set_issue_state(&issue.id, target_state)
                        .await
                        .is_err()
                    {
                        return Ok(false);
                    }
                }
                let original_current = current.clone();
                let transition = {
                    let mut state = self.state.write().await;
                    let Some(run) = state.get_pipeline_run_mut(&issue.id) else {
                        return Ok(false);
                    };
                    run.set_automatic_transition_applied(step_name, target_state.to_string());
                    let mut transitioned = current;
                    transitioned.state = target_state.to_string();
                    state.update_issue_snapshot(&issue.id, transitioned);
                    Self::transition_input_for_run(
                        &state,
                        &issue.id,
                        &issue.identifier,
                        PipelineTransitionKind::AutomaticTransitionApplied,
                        Some(step_name.to_string()),
                        None,
                        None,
                    )
                };
                let Some(transition) = transition else {
                    return Ok(false);
                };
                if self.pipeline_journal.append(transition).await.is_err() {
                    // The remote write may already have succeeded, but only a
                    // durable `AutomaticTransitionApplied` record opens the
                    // protected dispatch gate. Keep the in-memory owner at
                    // its durable Pending checkpoint so a crash or later tick
                    // revalidates the remote state without repeating the write.
                    let mut state = self.state.write().await;
                    if let Some(run) = state.get_pipeline_run_mut(&issue.id) {
                        run.set_automatic_transition_pending(
                            step_name,
                            target_state.to_string(),
                            expected_state,
                        );
                    }
                    state.update_issue_snapshot(&issue.id, original_current);
                    return Ok(false);
                }
                Ok(true)
            }
            None => {
                if let Some(state_name) = tracker_state {
                    if self.tracker.supports_writes()
                        && self
                            .tracker
                            .set_issue_state(&issue.id, state_name)
                            .await
                            .is_ok()
                    {
                        let mut transitioned = issue.clone();
                        transitioned.state = state_name.to_string();
                        self.state
                            .write()
                            .await
                            .update_issue_snapshot(&issue.id, transitioned);
                    }
                }
                Ok(true)
            }
        }
    }

    /// Re-read adapter evidence immediately before reservation. An unavailable
    /// or changed proof deliberately leaves the step pending without consuming
    /// agent capacity; the next poll can retry the read.
    async fn select_current_authorization_evidence(
        &self,
        issue: &Issue,
        step_name: &str,
    ) -> Result<bool, StepDispatchError> {
        let authorization_artifact = {
            let state = self.state.read().await;
            state.get_pipeline_run(&issue.id).and_then(|run| {
                run.authorization_for(step_name).and_then(|authorization| {
                    run.artifact_snapshots
                        .get(&authorization.artifact_step)
                        .cloned()
                })
            })
        };
        let Some(authorization_artifact) = authorization_artifact else {
            let configured = self
                .state
                .read()
                .await
                .get_pipeline_run(&issue.id)
                .is_some_and(|run| run.authorization_for(step_name).is_some());
            if configured {
                return Ok(false);
            }
            return Ok(true);
        };
        let events = match self.tracker.fetch_tracker_events(&issue.id).await {
            Ok(events) => events,
            Err(error) => {
                warn!(issue_id = %issue.id, step = step_name, error = %error, "authorization evidence is unavailable; retaining pending step");
                return Ok(false);
            }
        };
        let repositories = self
            .workspace_mgr
            .owned_worktree_paths(&issue.id)
            .map(|paths| paths.into_iter().collect::<BTreeMap<_, _>>())
            .map_err(|error| StepDispatchError::immutable_integrity(AgentError::PromptError {
                reason: format!(
                    "authorization Artifact could not be verified: prepared worktree unavailable: {error}"
                ),
            }))?;
        let violations = artifact::verify_immutable_inputs(
            step_name,
            std::slice::from_ref(&authorization_artifact),
            &repositories,
        )
        .await
        .map_err(|reason| {
            StepDispatchError::immutable_integrity(AgentError::PromptError {
                reason: format!("authorization Artifact could not be verified: {reason}"),
            })
        })?;
        if !violations.is_empty() {
            if let Some(run) = self.state.write().await.get_pipeline_run_mut(&issue.id) {
                run.record_artifact_integrity_violations(violations.clone());
            }
            return Err(StepDispatchError::immutable_integrity(
                AgentError::PromptError {
                    reason: format!(
                        "authorization Artifact changed before step '{}': {}",
                        step_name,
                        violations
                            .iter()
                            .map(|violation| format!(
                                "{}:{} ({})",
                                violation.producer_step,
                                violation.repository,
                                violation.artifact_identity
                            ))
                            .collect::<Vec<_>>()
                            .join(", ")
                    ),
                },
            ));
        }
        let transition = {
            let mut state = self.state.write().await;
            let Some(run) = state.get_pipeline_run_mut(&issue.id) else {
                return Ok(false);
            };
            let Some(evidence) = run.select_authorization_evidence(step_name, &events) else {
                run.clear_authorization_evidence(step_name);
                return Ok(false);
            };
            if run.authorization_evidence_is_current(step_name, &events) {
                return Ok(true);
            }
            run.record_authorization_evidence(step_name, evidence);
            Self::transition_input_for_run(
                &state,
                &issue.id,
                &issue.identifier,
                PipelineTransitionKind::AuthorizationEvidenceSelected,
                Some(step_name.to_string()),
                None,
                None,
            )
        };
        let Some(transition) = transition else {
            return Ok(false);
        };
        if let Err(error) = self.pipeline_journal.append(transition).await {
            warn!(issue_id = %issue.id, step = step_name, error = %error, "failed to persist authorization evidence; retaining pending step");
            if let Some(run) = self.state.write().await.get_pipeline_run_mut(&issue.id) {
                run.clear_authorization_evidence(step_name);
            }
            return Ok(false);
        }
        Ok(true)
    }

    /// Handle a worker event from the channel.
    async fn handle_worker_event(&self, owned_event: OrchestratorWorkerEvent) {
        let OrchestratorWorkerEvent {
            identity,
            event,
            workspace_capture,
        } = owned_event;
        let worker_exit_permit = if matches!(&event, WorkerEvent::WorkerExited { .. }) {
            let Some(permit) = self.quiescing.begin_dispatch() else {
                return;
            };
            Some(permit)
        } else {
            None
        };
        let event_matches_identity = match &event {
            WorkerEvent::AgentUpdate {
                issue_id,
                step_name,
                ..
            }
            | WorkerEvent::WorkerExited {
                issue_id,
                step_name,
                ..
            } => issue_id == &identity.issue_id && step_name == &identity.step_name,
        };
        if !event_matches_identity || !self.worker_identity_is_current(&identity).await {
            if let Some(permit) = worker_exit_permit.as_ref() {
                self.dispatch_ready_active_pipelines(permit).await;
            }
            return;
        }

        let reconciliation_owned = is_reconciliation_owned(&self.cancellation_registry, &identity);
        match event {
            WorkerEvent::AgentUpdate {
                issue_id,
                step_name,
                event: agent_event,
                timestamp,
            } => {
                if reconciliation_owned {
                    return;
                }
                self.handle_agent_update(&issue_id, &step_name, agent_event, timestamp)
                    .await;
            }
            WorkerEvent::WorkerExited { result, .. } => {
                self.handle_worker_exit_event(
                    result,
                    identity,
                    reconciliation_owned,
                    workspace_capture.is_some(),
                    worker_exit_permit
                        .as_ref()
                        .expect("worker exit has a dispatch permit"),
                )
                .await;
            }
        }
        drop(workspace_capture);
        if let Some(permit) = worker_exit_permit.as_ref() {
            self.dispatch_ready_active_pipelines(permit).await;
        }
    }

    // Do not retain the worker event, sibling-drain state, and the terminal lifecycle state
    // machine in one Tokio poll frame. This is the worker-exit boundary; downstream lifecycle
    // boundaries remain unchanged.
    fn handle_worker_exit_event<'a>(
        &'a self,
        result: WorkerResult,
        identity: WorkerIdentity,
        reconciliation_owned: bool,
        workspace_capture_held: bool,
        permit: &'a DispatchPermit,
    ) -> Pin<Box<dyn Future<Output = ()> + Send + 'a>> {
        Box::pin(async move {
            let issue_id = identity.issue_id.clone();
            let step_name = identity.step_name.clone();
            if reconciliation_owned {
                return;
            }
            if worker_result_halts_pipeline(&result) {
                let mut sibling_handles =
                    mark_issue_for_drain(&self.cancellation_registry, &issue_id);
                if !self
                    .await_worker_drain_with_event_pump(
                        &mut sibling_handles,
                        WORKER_DRAIN_TIMEOUT,
                        DrainEventMode::ApplyExceptIssue(&issue_id),
                    )
                    .await
                {
                    warn!(
                        issue_id = %issue_id,
                        step = %step_name,
                        siblings = sibling_handles.len(),
                        "parallel sibling drain timed out before failure disposition"
                    );
                    return;
                }
                remove_drained_workers(&self.cancellation_registry, &sibling_handles);
                if !self.worker_identity_is_current(&identity).await {
                    return;
                }
            }
            self.handle_worker_exit_with_permit(
                &issue_id,
                &step_name,
                result,
                workspace_capture_held,
                permit,
            )
            .await;
        })
    }

    #[cfg(test)]
    async fn handle_unowned_test_event(&self, event: WorkerEvent) {
        match event {
            WorkerEvent::AgentUpdate {
                issue_id,
                step_name,
                event,
                timestamp,
            } => {
                self.handle_agent_update(&issue_id, &step_name, event, timestamp)
                    .await;
            }
            WorkerEvent::WorkerExited {
                issue_id,
                step_name,
                result,
                ..
            } => {
                self.handle_worker_exit(&issue_id, &step_name, result).await;
            }
        }
    }

    async fn worker_identity_is_current(&self, identity: &WorkerIdentity) -> bool {
        let state = self.state.read().await;
        let Some(entry) = state.get_running(&identity.issue_id) else {
            return false;
        };
        let Some(run) = state.get_pipeline_run(&identity.issue_id) else {
            return false;
        };
        entry.run_id.as_deref() == Some(identity.run_id.as_str())
            && entry.started_at == identity.started_at
            && run.cycle == identity.cycle
            && matches!(
                run.step_states.get(&identity.step_name),
                Some(StepState::Running { .. })
            )
    }

    async fn cancel_and_drain_for_reconciliation(&self, issue_id: &str) -> Option<DrainedWorkers> {
        let owner = {
            let state = self.state.read().await;
            ReconciliationOwner::capture(&state, issue_id)
        };
        let mut handles = mark_issue_for_drain(&self.cancellation_registry, issue_id);
        if !self
            .await_worker_drain_with_event_pump(
                &mut handles,
                WORKER_DRAIN_TIMEOUT,
                DrainEventMode::ApplyExceptIssue(issue_id),
            )
            .await
        {
            warn!(
                issue_id = %issue_id,
                workers = handles.len(),
                "worker drain timed out; retaining reconciliation ownership"
            );
            return None;
        }
        Some(DrainedWorkers { owner, handles })
    }

    async fn issue_is_stalled(&self, issue_id: &str, stall_timeout_ms: i64) -> bool {
        let state = self.state.read().await;
        reconcile_stalled_runs(&state, stall_timeout_ms)
            .stalled_issue_ids
            .iter()
            .any(|stalled_issue_id| stalled_issue_id == issue_id)
    }

    async fn current_reconcile_disposition(
        &self,
        issue_id: &str,
        active_states_lower: &[String],
        terminal_states_lower: &[String],
        stall_timeout_ms: i64,
    ) -> Option<CurrentReconcileDisposition> {
        let refreshed = match self
            .tracker
            .fetch_issue_states_by_ids(&[issue_id.to_string()])
            .await
        {
            Ok(issues) => issues,
            Err(error) => {
                warn!(
                    issue_id = %issue_id,
                    error = %error,
                    "tracker candidate refresh failed, retaining runtime ownership"
                );
                return None;
            }
        };
        let Some(issue) = refreshed.into_iter().find(|issue| issue.id == issue_id) else {
            return Some(CurrentReconcileDisposition::Inactive);
        };
        self.state
            .write()
            .await
            .update_issue_snapshot(issue_id, issue.clone());
        match determine_reconcile_action(&issue, active_states_lower, terminal_states_lower) {
            ReconcileAction::TerminateAndCleanup(issue) => {
                Some(CurrentReconcileDisposition::Terminal {
                    identifier: issue.identifier,
                })
            }
            ReconcileAction::TerminateNoCleanup(_) => Some(CurrentReconcileDisposition::Inactive),
            ReconcileAction::UpdateSnapshot(_) => {
                if self.issue_is_stalled(issue_id, stall_timeout_ms).await {
                    Some(CurrentReconcileDisposition::Stalled)
                } else {
                    Some(CurrentReconcileDisposition::Active)
                }
            }
        }
    }

    async fn resume_pending_reconciliation(
        &self,
        issue_id: &str,
        active_states_lower: &[String],
        terminal_states_lower: &[String],
    ) {
        let stall_timeout_ms = self.config.read().await.agent.stall_timeout_ms;
        let Some(drained) = self.cancel_and_drain_for_reconciliation(issue_id).await else {
            return;
        };
        let Some(disposition) = self
            .current_reconcile_disposition(
                issue_id,
                active_states_lower,
                terminal_states_lower,
                stall_timeout_ms,
            )
            .await
        else {
            return;
        };
        self.commit_drained_reconciliation(issue_id, drained, disposition)
            .await;
    }

    async fn reconcile_tracker_candidate(
        &self,
        issue_id: &str,
        active_states_lower: &[String],
        terminal_states_lower: &[String],
        expected: TrackerReconcileDisposition,
    ) {
        let stall_timeout_ms = self.config.read().await.agent.stall_timeout_ms;
        let Some(disposition) = self
            .current_reconcile_disposition(
                issue_id,
                active_states_lower,
                terminal_states_lower,
                stall_timeout_ms,
            )
            .await
        else {
            return;
        };
        let expected_matches = matches!(
            (expected, disposition),
            (
                TrackerReconcileDisposition::Terminal,
                CurrentReconcileDisposition::Terminal { .. },
            ) | (
                TrackerReconcileDisposition::Inactive,
                CurrentReconcileDisposition::Inactive,
            )
        );
        if !expected_matches {
            return;
        }
        let Some(drained) = self.cancel_and_drain_for_reconciliation(issue_id).await else {
            return;
        };
        let Some(disposition) = self
            .current_reconcile_disposition(
                issue_id,
                active_states_lower,
                terminal_states_lower,
                stall_timeout_ms,
            )
            .await
        else {
            return;
        };
        self.commit_drained_reconciliation(issue_id, drained, disposition)
            .await;
    }

    async fn reconcile_stalled_issue(&self, issue_id: &str, stall_timeout_ms: i64) {
        if !self.issue_is_stalled(issue_id, stall_timeout_ms).await {
            return;
        }
        let Some(drained) = self.cancel_and_drain_for_reconciliation(issue_id).await else {
            return;
        };
        let (active_states_lower, terminal_states_lower) = {
            let config = self.config.read().await;
            (
                build_reconcile_active_states_lower(&config),
                config
                    .tracker
                    .terminal_states
                    .iter()
                    .map(|state| state.to_lowercase())
                    .collect::<Vec<_>>(),
            )
        };
        let Some(disposition) = self
            .current_reconcile_disposition(
                issue_id,
                &active_states_lower,
                &terminal_states_lower,
                stall_timeout_ms,
            )
            .await
        else {
            return;
        };
        self.commit_drained_reconciliation(issue_id, drained, disposition)
            .await;
    }

    async fn commit_drained_reconciliation(
        &self,
        issue_id: &str,
        drained: DrainedWorkers,
        disposition: CurrentReconcileDisposition,
    ) {
        match disposition {
            CurrentReconcileDisposition::Terminal { identifier } => {
                let result = {
                    let mut state = self.state.write().await;
                    if !drained.owner.is_current(&state, issue_id) {
                        warn!(
                            issue_id = %issue_id,
                            "terminal reconciliation owner changed before commit"
                        );
                        return;
                    }
                    let running_entry = state.remove_running(issue_id);
                    if let Some(entry) = running_entry.as_ref() {
                        state.add_runtime_seconds(entry);
                    }
                    let history_record = running_entry.as_ref().and_then(|entry| {
                        state.get_pipeline_run(issue_id).map(|run| {
                            self.build_history_record(RunningHistoryRecordInput {
                                outcome: HISTORY_OUTCOME_STOPPED,
                                last_error: None,
                                running_entry: entry,
                                run,
                                completed_at: Utc::now(),
                                artifacts: state.artifacts.get(issue_id).cloned(),
                            })
                        })
                    });
                    let waiting_entry = state.waiting_on_human.get(issue_id).cloned();
                    let identifier = waiting_entry
                        .as_ref()
                        .map(|entry| entry.identifier.clone())
                        .unwrap_or(identifier);
                    let interaction_request_id =
                        waiting_entry.map(|entry| entry.interaction_request_id);
                    let history_run_id = running_entry
                        .as_ref()
                        .and_then(|entry| entry.run_id.clone());
                    state.release_claim(issue_id);
                    state.remove_pipeline_run(issue_id);
                    (
                        identifier,
                        interaction_request_id,
                        history_record,
                        history_run_id,
                    )
                };
                remove_drained_workers(&self.cancellation_registry, &drained.handles);
                self.cancel_open_interaction(result.1).await;
                if let Err(error) = self.workspace_mgr.remove_workspace(issue_id).await {
                    warn!(
                        identifier = %result.0,
                        error = %error,
                        "failed to clean terminal workspace"
                    );
                }
                if let Some(record) = result.2 {
                    self.append_history_record(result.3.as_deref(), record)
                        .await;
                }
            }
            CurrentReconcileDisposition::Inactive => {
                let result = {
                    let mut state = self.state.write().await;
                    if !drained.owner.is_current(&state, issue_id) {
                        warn!(
                            issue_id = %issue_id,
                            "inactive reconciliation owner changed before commit"
                        );
                        return;
                    }
                    let running_entry = state.remove_running(issue_id);
                    if let Some(entry) = running_entry.as_ref() {
                        state.add_runtime_seconds(entry);
                    }
                    let history_record = running_entry.as_ref().and_then(|entry| {
                        state.get_pipeline_run(issue_id).map(|run| {
                            self.build_history_record(RunningHistoryRecordInput {
                                outcome: HISTORY_OUTCOME_STOPPED,
                                last_error: None,
                                running_entry: entry,
                                run,
                                completed_at: Utc::now(),
                                artifacts: state.artifacts.get(issue_id).cloned(),
                            })
                        })
                    });
                    let interaction_request_id = state
                        .waiting_on_human
                        .get(issue_id)
                        .map(|entry| entry.interaction_request_id.clone());
                    let history_run_id = running_entry
                        .as_ref()
                        .and_then(|entry| entry.run_id.clone());
                    state.release_claim(issue_id);
                    state.remove_pipeline_run(issue_id);
                    (interaction_request_id, history_record, history_run_id)
                };
                remove_drained_workers(&self.cancellation_registry, &drained.handles);
                self.cancel_open_interaction(result.0).await;
                if let Some(record) = result.1 {
                    self.append_history_record(result.2.as_deref(), record)
                        .await;
                }
            }
            retry_disposition @ (CurrentReconcileDisposition::Stalled
            | CurrentReconcileDisposition::Active) => {
                let error = if matches!(retry_disposition, CurrentReconcileDisposition::Stalled) {
                    "stall timeout"
                } else {
                    "worker cancelled during reconciliation"
                };
                let mut state = self.state.write().await;
                if !drained.owner.is_current(&state, issue_id) {
                    warn!(
                        issue_id = %issue_id,
                        "retry reconciliation owner changed before commit"
                    );
                    return;
                }
                let Some(retry_config) = state.get_pipeline_config(issue_id).cloned() else {
                    warn!(
                        issue_id = %issue_id,
                        "retaining stalled run because its config snapshot is missing"
                    );
                    return;
                };
                let terminal = state.remove_running(issue_id).map(|entry| {
                    self.schedule_whole_issue_failure_retry(
                        &mut state,
                        &retry_config,
                        entry,
                        error,
                        ScheduledRetryPipeline::Preserve,
                    )
                });
                drop(state);
                self.commit_whole_issue_failure_retry(terminal).await;
                remove_drained_workers(&self.cancellation_registry, &drained.handles);
            }
        }
    }

    async fn await_worker_drain_with_event_pump(
        &self,
        handles: &mut [WorkerDrainHandle],
        drain_timeout: Duration,
        event_mode: DrainEventMode<'_>,
    ) -> bool {
        let drain = await_worker_drain(handles, drain_timeout);
        tokio::pin!(drain);

        loop {
            tokio::select! {
                drained = &mut drain => return drained,
                Some(event) = recv_worker_event(&self.worker_rx) => {
                    if matches!(
                        event_mode,
                        DrainEventMode::ApplyExceptIssue(issue_id)
                            if event.identity.issue_id != issue_id
                    ) {
                        Box::pin(self.handle_worker_event(event)).await;
                    }
                }
            }
        }
    }

    async fn await_worker_quiescence_with_event_pump(
        &self,
        handles: &mut [WorkerDrainHandle],
        event_mode: DrainEventMode<'_>,
    ) -> bool {
        let drain = await_worker_quiescence(handles);
        tokio::pin!(drain);

        loop {
            tokio::select! {
                drained = &mut drain => return drained,
                Some(event) = recv_worker_event(&self.worker_rx) => {
                    if matches!(
                        event_mode,
                        DrainEventMode::ApplyExceptIssue(issue_id)
                            if event.identity.issue_id != issue_id
                    ) {
                        self.handle_worker_event(event).await;
                    }
                }
            }
        }
    }

    /// Wait for sibling agents to stop mutating an issue workspace while retaining their terminal
    /// events for normal pipeline processing after a producer snapshot is captured.
    async fn await_sibling_workspace_writers(
        &self,
        issue_id: &str,
        handles: &mut [WorkerDrainHandle],
    ) -> Result<Vec<OrchestratorWorkerEvent>, String> {
        let drain = await_worker_quiescence(handles);
        tokio::pin!(drain);
        let mut deferred_exits = Vec::new();

        loop {
            tokio::select! {
                quiesced = &mut drain => {
                    return quiesced
                        .then_some(deferred_exits)
                        .ok_or_else(|| "a concurrent workspace writer ended without reporting completion".to_string());
                }
                Some(event) = recv_worker_event(&self.worker_rx) => {
                    if event.identity.issue_id == issue_id
                        && matches!(event.event, WorkerEvent::WorkerExited { .. })
                    {
                        deferred_exits.push(event);
                    } else {
                        Box::pin(self.handle_worker_event(event)).await;
                    }
                }
            }
        }
    }

    /// Handle an agent update event.
    async fn handle_agent_update(
        &self,
        issue_id: &str,
        step_name: &str,
        event: AgentEvent,
        timestamp: chrono::DateTime<Utc>,
    ) {
        let mut state = self.state.write().await;
        let issue_identifier = state
            .running
            .get(issue_id)
            .map(|entry| entry.identifier.clone())
            .unwrap_or_else(|| issue_id.to_string());
        let (run_id, attempt_num) = Self::run_metadata_for_issue(&state, issue_id);
        let transcript_request = match &event {
            AgentEvent::TranscriptBlock { kind, payload } => {
                run_id.as_ref().map(|run_id| TranscriptPersistRequest {
                    run_id: run_id.clone(),
                    issue_identifier: issue_identifier.clone(),
                    step_name: step_name.to_string(),
                    attempt: attempt_num,
                    timestamp,
                    kind: transcript_kind_from_agent_kind(*kind),
                    payload: payload.clone(),
                    truncated: None,
                })
            }
            _ => None,
        };
        let flush_transcript_step = matches!(
            &event,
            AgentEvent::RunCompleted { .. }
                | AgentEvent::RunFailed { .. }
                | AgentEvent::TurnCompleted { .. }
                | AgentEvent::TurnFailed { .. }
                | AgentEvent::Cancelled { .. }
        )
        .then(|| {
            run_id
                .as_ref()
                .map(|run_id| (run_id.clone(), step_name.to_string()))
        })
        .flatten();
        let mut pipeline_event: Option<PipelineEvent> = None;

        // Handle special cases
        match &event {
            AgentEvent::SessionStarted {
                session_id,
                agent_pid,
            } => {
                state.update_session_info(issue_id, session_id, agent_pid.as_deref());
                pipeline_event = Some(PipelineEvent::SessionStarted {
                    issue_identifier: issue_identifier.clone(),
                    timestamp,
                    detail: format!("session started: {}", session_id),
                });
            }
            AgentEvent::PromptStarted => {
                state.increment_turn_count(issue_id);
            }
            AgentEvent::RunCompleted { usage: Some(u) } => {
                state.update_token_usage(issue_id, u.input_tokens, u.output_tokens, u.total_tokens);
            }
            AgentEvent::RunCompleted { usage: None } => {}
            AgentEvent::TurnCompleted { usage } => {
                pipeline_event = Some(PipelineEvent::TurnCompleted {
                    issue_identifier: issue_identifier.clone(),
                    timestamp,
                    turn: state
                        .running
                        .get(issue_id)
                        .map(|e| e.turn_count)
                        .unwrap_or(0),
                    detail: format!("turn completed (attempt {})", attempt_num),
                    conversation_index: None,
                    tokens_delta: crate::observability::events::TokensDelta {
                        input: usage.as_ref().map(|u| u.input_tokens).unwrap_or(0),
                        output: usage.as_ref().map(|u| u.output_tokens).unwrap_or(0),
                    },
                });
            }
            AgentEvent::RunFailed { reason, usage, .. } => {
                if let Some(u) = usage {
                    state.update_token_usage(
                        issue_id,
                        u.input_tokens,
                        u.output_tokens,
                        u.total_tokens,
                    );
                }
                pipeline_event = Some(PipelineEvent::Error {
                    issue_identifier: issue_identifier.clone(),
                    timestamp,
                    detail: reason.clone(),
                });
            }
            AgentEvent::OutputChunk { content, .. } => {
                pipeline_event = Some(PipelineEvent::Output {
                    issue_identifier: issue_identifier.clone(),
                    timestamp,
                    step_name: step_name.to_string(),
                    detail: content.chars().take(120).collect(),
                });
            }
            _ => {}
        }

        let sequence = pipeline_event
            .as_ref()
            .and(run_id.as_ref())
            .map(|run_id| state.next_timeline_sequence(run_id));

        // Common path: update agent event
        state.update_agent_event(
            issue_id,
            event.event_name(),
            event.message_for_state().as_deref(),
            timestamp,
        );
        drop(state);

        if let Some(request) = transcript_request {
            if let Some(ref persistence) = self.transcript_persistence {
                persistence.send(request);
            }
        }
        if let Some((run_id, step_name)) = flush_transcript_step {
            if let Some(ref persistence) = self.transcript_persistence {
                persistence.flush_step(run_id, step_name);
            }
        }

        if let Some(event) = pipeline_event {
            self.publish_pipeline_event(run_id, sequence, attempt_num, event)
                .await;
        }
    }

    // The immutable post-check awaits workspace drains and Git observations. Keep it out of the
    // worker-exit future so the expanded Artifact evidence cannot inflate the normal acceptance
    // and terminal-transition poll stack.
    fn verify_immutable_inputs_after_worker_exit<'a>(
        &'a self,
        issue_id: &'a str,
        step_name: &'a str,
        output: crate::pipeline::verdict::StepOutput,
        workspace_capture_held: bool,
    ) -> Pin<Box<dyn Future<Output = ImmutablePostcheckOutcome> + Send + 'a>> {
        Box::pin(self.verify_immutable_inputs_after_worker_exit_inner(
            issue_id,
            step_name,
            output,
            workspace_capture_held,
        ))
    }

    async fn verify_immutable_inputs_after_worker_exit_inner(
        &self,
        issue_id: &str,
        step_name: &str,
        mut output: crate::pipeline::verdict::StepOutput,
        workspace_capture_held: bool,
    ) -> (
        crate::pipeline::verdict::StepOutput,
        Vec<OrchestratorWorkerEvent>,
        bool,
    ) {
        let immutable_inputs: Vec<artifact::ArtifactSnapshot> = {
            let state = self.state.read().await;
            state
                .get_pipeline_run(issue_id)
                .filter(|run| {
                    run.artifact_inputs_for(step_name)
                        .is_some_and(|(_, access)| access == ArtifactAccess::Immutable)
                })
                .map(|run| {
                    run.artifact_inputs_for(step_name)
                        .expect("immutable Artifact access has resolved inputs")
                        .0
                        .iter()
                        .filter_map(|producer| run.artifact_snapshots.get(producer).cloned())
                        .collect()
                })
                .unwrap_or_default()
        };
        if immutable_inputs.is_empty() {
            return (output, Vec::new(), false);
        }

        let _capture_guard = if workspace_capture_held {
            None
        } else {
            Some(acquire_issue_workspace_capture(&self.cancellation_registry, issue_id).await)
        };
        let mut sibling_writers =
            sibling_worker_completion_handles(&self.cancellation_registry, issue_id, step_name);
        let deferred_exits = match self
            .await_sibling_workspace_writers(issue_id, &mut sibling_writers)
            .await
        {
            Ok(exits) => exits,
            Err(error) => {
                output = immutable_artifact_verification_failure(error);
                return (output, Vec::new(), true);
            }
        };
        let repositories = match self.workspace_mgr.owned_worktree_paths(issue_id) {
            Ok(paths) => paths.into_iter().collect(),
            Err(error) => {
                output = immutable_artifact_verification_failure(error);
                return (output, deferred_exits, true);
            }
        };
        let mut integrity_failed = false;
        match artifact::verify_immutable_inputs(step_name, &immutable_inputs, &repositories).await {
            Ok(violations) if violations.is_empty() => {}
            Ok(violations) => {
                integrity_failed = true;
                if let Some(run) = self.state.write().await.get_pipeline_run_mut(issue_id) {
                    run.record_artifact_integrity_violations(violations.clone());
                }
                output = crate::pipeline::verdict::StepOutput {
                    result: StepResult::Failed {
                        summary: format!(
                            "immutable Artifact input changed after step execution: {}",
                            violations
                                .iter()
                                .map(|violation| format!(
                                    "{}:{} ({})",
                                    violation.producer_step,
                                    violation.repository,
                                    violation.artifact_identity
                                ))
                                .collect::<Vec<_>>()
                                .join(", ")
                        ),
                    },
                    summary: Some("immutable Artifact input changed".to_string()),
                    output: None,
                };
            }
            Err(error) => {
                integrity_failed = true;
                output = immutable_artifact_verification_failure(error);
            }
        }
        (output, deferred_exits, integrity_failed)
    }

    // Producer capture and consumer verification both carry ArtifactSnapshot state. Type-erase
    // this #480 addition so it cannot enlarge the acceptance and terminal failure poll chain.
    fn process_artifacts_after_worker_exit<'a>(
        &'a self,
        issue_id: &'a str,
        step_name: &'a str,
        output: StepOutput,
        capture_artifact: bool,
        workspace_capture_held: bool,
    ) -> Pin<Box<dyn Future<Output = Box<ArtifactWorkerExitOutcome>> + Send + 'a>> {
        Box::pin(self.process_artifacts_after_worker_exit_inner(
            issue_id,
            step_name,
            output,
            capture_artifact,
            workspace_capture_held,
        ))
    }

    async fn process_artifacts_after_worker_exit_inner(
        &self,
        issue_id: &str,
        step_name: &str,
        mut output: StepOutput,
        capture_artifact: bool,
        workspace_capture_held: bool,
    ) -> Box<ArtifactWorkerExitOutcome> {
        let capture_request = if !capture_artifact
            || matches!(output.result, StepResult::Failed { .. })
        {
            None
        } else {
            let state = self.state.read().await;
            state.get_pipeline_run(issue_id).and_then(|run| {
                run.artifact_snapshot_selection_for(step_name)
                    .cloned()
                    .map(|selection| {
                        let running = state.running.get(issue_id);
                        let run_id = running
                            .and_then(|entry| entry.run_id.clone())
                            .or_else(|| state.issue_run_ids.get(issue_id).cloned())
                            .unwrap_or_else(|| issue_id.to_string());
                        let attempt = running.and_then(|entry| entry.retry_attempt).unwrap_or(1);
                        (run_id, run.cycle, attempt, selection)
                    })
            })
        };
        let mut captured_snapshot = None;
        let mut deferred_sibling_exits = Vec::new();
        if let Some((run_id, cycle, attempt, selection)) = capture_request {
            let capture_guard = if workspace_capture_held {
                None
            } else {
                Some(acquire_issue_workspace_capture(&self.cancellation_registry, issue_id).await)
            };
            let mut sibling_writers =
                sibling_worker_completion_handles(&self.cancellation_registry, issue_id, step_name);
            let capture_result = self
                .await_sibling_workspace_writers(issue_id, &mut sibling_writers)
                .await
                .and_then(|deferred_exits| {
                    deferred_sibling_exits = deferred_exits;
                    self.workspace_mgr
                        .owned_worktree_paths(issue_id)
                        .map(|paths| paths.into_iter().collect::<BTreeMap<_, _>>())
                        .map_err(|error| error.to_string())
                });
            match capture_result {
                Ok(repositories) => match artifact::capture(
                    &run_id,
                    cycle,
                    step_name,
                    attempt,
                    output.output.as_ref().unwrap_or(&serde_json::Value::Null),
                    &selection,
                    &repositories,
                )
                .await
                {
                    Ok(snapshot) => captured_snapshot = Some(snapshot),
                    Err(error) => {
                        output = artifact_snapshot_capture_failure(error);
                    }
                },
                Err(error) => output = artifact_snapshot_capture_failure(error),
            }
            drop(capture_guard);
        }
        let (output, postcheck_exits, integrity_failed) = self
            .verify_immutable_inputs_after_worker_exit(
                issue_id,
                step_name,
                output,
                workspace_capture_held,
            )
            .await;
        deferred_sibling_exits.extend(postcheck_exits);
        if integrity_failed {
            captured_snapshot = None;
        }
        Box::new(ArtifactWorkerExitOutcome {
            output,
            captured_snapshot,
            deferred_sibling_exits,
            integrity_failed,
        })
    }

    // Complete the #480 Artifact observation before re-entering the existing success/acceptance
    // state machine. The #512 durable transition snapshot is returned behind its own box, so it
    // cannot inflate the caller's acceptance and terminal-lifecycle worker frame.
    fn process_successful_worker_exit<'a>(
        &'a self,
        issue_id: &'a str,
        step_name: &'a str,
        issue_identifier: Option<&'a str>,
        output: StepOutput,
        has_approval_request: bool,
        workspace_capture_held: bool,
    ) -> Pin<Box<dyn Future<Output = Option<Box<SuccessfulWorkerExitAction>>> + Send + 'a>> {
        Box::pin(self.process_successful_worker_exit_inner(
            issue_id,
            step_name,
            issue_identifier,
            output,
            has_approval_request,
            workspace_capture_held,
        ))
    }

    async fn process_successful_worker_exit_inner(
        &self,
        issue_id: &str,
        step_name: &str,
        issue_identifier: Option<&str>,
        output: StepOutput,
        has_approval_request: bool,
        workspace_capture_held: bool,
    ) -> Option<Box<SuccessfulWorkerExitAction>> {
        let mut artifact_outcome = self
            .process_artifacts_after_worker_exit(
                issue_id,
                step_name,
                output,
                true,
                workspace_capture_held,
            )
            .await;
        while let Some(event) = artifact_outcome.deferred_sibling_exits.pop() {
            if self.worker_tx.send(event).await.is_err() {
                warn!(issue_id = %issue_id, "failed to restore deferred sibling worker exit");
            }
        }
        let captured_snapshot = artifact_outcome.captured_snapshot.take();
        let integrity_failed = artifact_outcome.integrity_failed;
        let output = artifact_outcome.output;
        let verdict_value = match &output.result {
            StepResult::Succeeded => "succeeded",
            StepResult::Failed { .. } => "failed",
            StepResult::Concern { .. } => "concern",
        };
        info!(
            issue_id = %issue_id,
            step = step_name,
            verdict_value,
            "received validated step result"
        );
        let mut state = self.state.write().await;
        let previous_run = match state.get_pipeline_run(issue_id) {
            Some(run) => run.clone(),
            None => {
                warn!(issue_id = %issue_id, "no pipeline run found for worker exit");
                return None;
            }
        };
        let mut candidate_run = previous_run.clone();
        if let Some(snapshot) = captured_snapshot {
            candidate_run.record_artifact_snapshot(step_name, snapshot);
        }
        let decisions_before_completion = candidate_run
            .route_decisions
            .keys()
            .cloned()
            .collect::<std::collections::HashSet<_>>();
        let action = candidate_run.step_completed(step_name, output, has_approval_request);
        let mut route_events = candidate_run
            .route_decisions
            .iter()
            .filter(|(route_step, _)| !decisions_before_completion.contains(*route_step))
            .map(|(route_step, decision)| RouteSelectionEvent {
                route_step: route_step.clone(),
                decision: decision.clone(),
                skipped_steps: candidate_run
                    .step_states
                    .iter()
                    .filter_map(|(step, state)| match state {
                        StepState::Skipped { provenance }
                            if provenance
                                .iter()
                                .any(|cause| cause.route_step == *route_step) =>
                        {
                            Some(step.clone())
                        }
                        _ => None,
                    })
                    .collect(),
            })
            .collect::<Vec<_>>();
        Self::sort_route_events(&candidate_run, &mut route_events);
        let transition_step = match &action {
            PipelineAction::AwaitingApproval { step, .. } => step,
            _ => step_name,
        };
        let config_snapshot = state.get_pipeline_config(issue_id).cloned();
        let (step_transition, route_transitions, route_candidate, route_previous_snapshot) =
            if route_events.is_empty() {
                state
                    .pipeline_runs
                    .insert(issue_id.to_string(), candidate_run);
                (
                    Self::transition_input_for_run(
                        &state,
                        issue_id,
                        issue_identifier.unwrap_or(issue_id),
                        Self::transition_kind_for_action(&action),
                        Some(transition_step.to_string()),
                        Some(verdict_value.to_string()),
                        None,
                    ),
                    Vec::new(),
                    None,
                    None,
                )
            } else {
                let step_transition = Self::transition_input_for_snapshot(
                    &state,
                    &previous_run,
                    PipelineTransitionTarget {
                        issue_id,
                        identifier: issue_identifier.unwrap_or(issue_id),
                    },
                    Self::transition_kind_for_action(&action),
                    Some(transition_step.to_string()),
                    Some(verdict_value.to_string()),
                    None,
                );
                let route_transitions = Self::route_transition_inputs(
                    &state,
                    issue_id,
                    issue_identifier.unwrap_or(issue_id),
                    &previous_run,
                    &candidate_run,
                    &route_events,
                );
                (
                    step_transition,
                    route_transitions,
                    Some(candidate_run),
                    Some(previous_run.to_snapshot()),
                )
            };
        Some(Box::new(SuccessfulWorkerExitAction {
            action,
            config_snapshot,
            step_transition,
            route_transitions,
            route_candidate,
            route_previous_snapshot,
            integrity_failed,
            route_events,
        }))
    }

    /// Handle a worker exit. Integrates with PipelineRun to drive step DAG.
    #[cfg(test)]
    async fn handle_worker_exit(&self, issue_id: &str, step_name: &str, result: WorkerResult) {
        let Some(permit) = self.quiescing.begin_dispatch() else {
            return;
        };
        self.handle_worker_exit_with_permit(issue_id, step_name, result, false, &permit)
            .await;
    }

    // Type-erase worker-exit handling so its large pipeline transition state machine is not
    // embedded in the long-lived orchestrator event future.
    fn handle_worker_exit_with_permit<'a>(
        &'a self,
        issue_id: &'a str,
        step_name: &'a str,
        result: WorkerResult,
        workspace_capture_held: bool,
        worker_exit_permit: &'a DispatchPermit,
    ) -> Pin<Box<dyn Future<Output = ()> + Send + 'a>> {
        Box::pin(self.handle_worker_exit_with_permit_inner(
            issue_id,
            step_name,
            result,
            workspace_capture_held,
            worker_exit_permit,
        ))
    }

    async fn handle_worker_exit_with_permit_inner(
        &self,
        issue_id: &str,
        step_name: &str,
        result: WorkerResult,
        workspace_capture_held: bool,
        worker_exit_permit: &DispatchPermit,
    ) {
        let action_lock = self.action_mutation_lock(issue_id);
        let action_mutation_guard = action_lock.lock().await;
        // Get the issue snapshot for potential re-dispatch
        let issue_snapshot = {
            let state = self.state.read().await;
            state.running.get(issue_id).map(|e| e.issue.clone())
        };

        match result {
            WorkerResult::Success {
                output,
                approval_request,
            } => {
                info!(
                    issue_id = %issue_id,
                    step = step_name,
                    "worker exited successfully"
                );

                let successful_action = self
                    .process_successful_worker_exit(
                        issue_id,
                        step_name,
                        issue_snapshot
                            .as_ref()
                            .map(|issue| issue.identifier.as_str()),
                        output,
                        approval_request.is_some(),
                        workspace_capture_held,
                    )
                    .await;

                if let Some(successful_action) = successful_action {
                    let SuccessfulWorkerExitAction {
                        action,
                        config_snapshot,
                        step_transition,
                        route_transitions,
                        route_candidate,
                        route_previous_snapshot,
                        integrity_failed,
                        route_events,
                    } = *successful_action;
                    let mut state = self.state.write().await;
                    let route_event_contexts = (0..route_events
                        .iter()
                        .map(|event| 1 + event.skipped_steps.len())
                        .sum())
                        .map(|_| Self::run_context_for_issue(&mut state, issue_id))
                        .collect::<Vec<_>>();
                    let action_is_pending_effect =
                        matches!(&action, PipelineAction::AwaitingAction { .. });
                    match action {
                        PipelineAction::Dispatch(requests) => {
                            // Collect output contexts while state lock is still held
                            let dispatch_contexts: Vec<(
                                DispatchRequest,
                                StepOutputTemplateContext,
                            )> = {
                                let run = route_candidate
                                    .as_ref()
                                    .or_else(|| state.get_pipeline_run(issue_id));
                                requests
                                    .into_iter()
                                    .map(|req| {
                                        let step_outputs = run
                                            .and_then(|r| r.output_context_for(&req.step_name))
                                            .unwrap_or_default();
                                        (req, step_outputs)
                                    })
                                    .collect()
                            };
                            // Need to drop state lock before dispatching
                            drop(state);
                            if let Err(error) = self
                                .append_successful_step_and_routes(
                                    step_transition,
                                    route_transitions,
                                    issue_snapshot.as_ref(),
                                    route_events,
                                    route_event_contexts,
                                    None,
                                )
                                .await
                            {
                                warn!(issue_id = %issue_id, error = %error, "failed to durably persist route selection before dispatch");
                                self.handle_pipeline_step_failure(
                                    issue_id,
                                    step_name,
                                    format!("failed to persist route selection: {error}; retry source step '{step_name}'"),
                                    false,
                                )
                                .await;
                                return;
                            }
                            if !self
                                .publish_route_candidate(
                                    issue_id,
                                    route_candidate,
                                    route_previous_snapshot.as_ref(),
                                )
                                .await
                            {
                                self.recover_unpublished_route_candidate(issue_id, step_name)
                                    .await;
                                return;
                            }
                            if let Some(ref issue) = issue_snapshot {
                                let Some(config_snapshot) = config_snapshot else {
                                    warn!(issue_id = %issue_id, "no config snapshot found for pipeline dispatch");
                                    return;
                                };
                                for (req, step_outputs) in dispatch_contexts {
                                    if !self
                                        .state_worker_capacity_available(issue, &config_snapshot)
                                        .await
                                    {
                                        return;
                                    }
                                    let workspace_path = match self
                                        .prepare_step_workspace(issue, &config_snapshot)
                                        .await
                                    {
                                        Ok(path) => path,
                                        Err(error) => {
                                            warn!(
                                                issue_id = %issue_id,
                                                step = %req.step_name,
                                                error = %error,
                                                "failed to prepare step workspace"
                                            );

                                            let mut state = self.state.write().await;
                                            if let Some(run) = state.get_pipeline_run_mut(issue_id)
                                            {
                                                run.step_failed(&req.step_name, error.to_string());
                                            }
                                            let terminal =
                                                state.remove_running(issue_id).map(|entry| {
                                                    self.schedule_whole_issue_failure_retry(
                                                        &mut state,
                                                        &config_snapshot,
                                                        entry,
                                                        &error.to_string(),
                                                        ScheduledRetryPipeline::Release,
                                                    )
                                                });
                                            drop(state);
                                            self.commit_whole_issue_failure_retry(terminal).await;
                                            return;
                                        }
                                    };

                                    if let Err(error) = self
                                        .dispatch_step(
                                            issue,
                                            Arc::clone(&config_snapshot),
                                            StepDispatchContext {
                                                step_name: &req.step_name,
                                                agent_name: &req.agent_name,
                                                step_kind: req.step_kind,
                                                tracker_state: req.tracker_state.as_deref(),
                                                attempt: None,
                                                timeout_ms: Self::effective_step_timeout_ms(
                                                    req.timeout_ms,
                                                    &config_snapshot,
                                                ),
                                                interaction_response: None,
                                                interaction_resume_id: None,
                                                interaction_to_retire: None,
                                                interaction_retirement_rollback: None,
                                                workspace_path,
                                                step_outputs,
                                            },
                                            worker_exit_permit,
                                        )
                                        .await
                                    {
                                        self.handle_step_dispatch_error(
                                            issue,
                                            &req.step_name,
                                            &config_snapshot,
                                            &error,
                                        )
                                        .await;
                                        return;
                                    }
                                }
                            }
                        }
                        PipelineAction::Succeeded => {
                            info!(issue_id = %issue_id, "pipeline succeeded");
                            let issue_identifier = issue_snapshot
                                .as_ref()
                                .map(|issue| issue.identifier.clone())
                                .unwrap_or_else(|| issue_id.to_string());
                            let finalize_attempt =
                                RunningAttemptIdentity::capture(&state, issue_id);
                            let acceptance_issue = issue_snapshot.clone().or_else(|| {
                                state.running.get(issue_id).map(|entry| entry.issue.clone())
                            });
                            let Some(config_snapshot) = config_snapshot else {
                                warn!(issue_id = %issue_id, "no config snapshot found for pipeline success");
                                return;
                            };
                            drop(state);
                            if let Err(error) = self
                                .append_successful_step_and_routes(
                                    step_transition,
                                    route_transitions,
                                    issue_snapshot.as_ref(),
                                    route_events,
                                    route_event_contexts,
                                    None,
                                )
                                .await
                            {
                                warn!(issue_id = %issue_id, error = %error, "failed to durably persist route selection before success");
                                self.handle_pipeline_step_failure(
                                    issue_id,
                                    step_name,
                                    format!("failed to persist route selection: {error}; retry source step '{step_name}'"),
                                    false,
                                )
                                .await;
                                return;
                            }
                            if !self
                                .publish_route_candidate(
                                    issue_id,
                                    route_candidate,
                                    route_previous_snapshot.as_ref(),
                                )
                                .await
                            {
                                self.recover_unpublished_route_candidate(issue_id, step_name)
                                    .await;
                                return;
                            }
                            let Some(acceptance_issue) = acceptance_issue else {
                                warn!(issue_id = %issue_id, "pipeline success has no issue identity for acceptance");
                                return;
                            };
                            match self
                                .run_acceptance_phase(&acceptance_issue, &config_snapshot)
                                .await
                            {
                                AcceptancePhaseOutcome::Passed => {}
                                AcceptancePhaseOutcome::Failed { reason, owner } => {
                                    self.schedule_acceptance_failure(
                                        &acceptance_issue,
                                        &config_snapshot,
                                        &reason,
                                        &owner,
                                    )
                                    .await;
                                    return;
                                }
                                AcceptancePhaseOutcome::RetainedForRecovery => return,
                            }
                            let finalize_state =
                                Box::pin(self.finalize_and_stage_terminal_transition(
                                    issue_id,
                                    &issue_identifier,
                                    &config_snapshot,
                                ))
                                .await;

                            let (tracker_state, terminal_outcome, terminal_issue, history) = {
                                let mut state = self.state.write().await;
                                if !Self::finalization_attempt_is_current(
                                    finalize_attempt.as_ref(),
                                    &state,
                                    issue_id,
                                ) {
                                    warn!(
                                        issue_id = %issue_id,
                                        "discarding stale finalization result because the running attempt changed"
                                    );
                                    return;
                                }
                                let completed_at = Utc::now();
                                let history_record = state
                                    .running
                                    .get(issue_id)
                                    .zip(state.get_pipeline_run(issue_id))
                                    .map(|(entry, run)| {
                                        self.build_history_record(RunningHistoryRecordInput {
                                            outcome: HISTORY_OUTCOME_SUCCEEDED,
                                            last_error: None,
                                            running_entry: entry,
                                            run,
                                            completed_at,
                                            artifacts: state.artifacts.get(issue_id).cloned(),
                                        })
                                    });
                                let running_entry = state.get_running(issue_id).cloned();
                                let terminal_issue = running_entry
                                    .as_ref()
                                    .map(|entry| entry.issue.clone())
                                    .or(issue_snapshot.clone());

                                if matches!(
                                    finalize_state.status,
                                    FinalizeStatus::Succeeded | FinalizeStatus::NotRequired
                                ) {
                                    (
                                        Some(config_snapshot.on_success.clone()),
                                        Some(TerminalOutcome::Succeeded),
                                        terminal_issue,
                                        history_record,
                                    )
                                } else {
                                    let is_terminal_failure =
                                        finalize_state.status == FinalizeStatus::SkippedHeadless;
                                    if let Some(entry) = state.remove_running(issue_id) {
                                        state.add_runtime_seconds(&entry);
                                    }
                                    state.set_finalize_state(issue_id, finalize_state);
                                    if !is_terminal_failure {
                                        state.remove_pipeline_run(issue_id);
                                    }
                                    (
                                        is_terminal_failure
                                            .then(|| config_snapshot.on_failure.clone()),
                                        is_terminal_failure.then_some(TerminalOutcome::Failed),
                                        terminal_issue,
                                        None,
                                    )
                                }
                            };

                            if let (Some(target_state), Some(outcome), Some(issue)) =
                                (tracker_state, terminal_outcome, terminal_issue)
                            {
                                self.begin_terminal_transition(
                                    &issue,
                                    outcome,
                                    target_state,
                                    history,
                                )
                                .await;
                            }
                        }
                        PipelineAction::Failed { step, reason } => {
                            let Some(config_snapshot) = config_snapshot else {
                                warn!(issue_id = %issue_id, "no config snapshot found for pipeline failure");
                                return;
                            };
                            warn!(
                                issue_id = %issue_id,
                                step = %step,
                                reason = %reason,
                                "pipeline failed"
                            );
                            let completed_at = Utc::now();
                            let mut final_failure = false;
                            let mut history_record = None;
                            let mut terminal_issue = None;
                            let mut rejection_comment = None;
                            let mut parked_recovery = None;
                            let mut post_failure_transitions = Vec::new();
                            if let Some(input) = step_transition {
                                post_failure_transitions.push(input);
                            }
                            let runtime_step = state
                                .get_pipeline_run(issue_id)
                                .and_then(|run| run.step(&step))
                                .cloned();
                            let step_config = config_snapshot.steps.iter().find(|s| s.name == step);
                            let on_failure = if integrity_failed {
                                OnFailure::Halt
                            } else {
                                runtime_step
                                    .as_ref()
                                    .map(|s| s.on_failure)
                                    .or_else(|| step_config.map(|s| s.on_failure))
                                    .unwrap_or_default()
                            };
                            match on_failure {
                                OnFailure::RetryStep => {
                                    if let Some(run) = state.get_pipeline_run_mut(issue_id) {
                                        run.retry_from_step(&step);
                                    }
                                    if let Some(entry) = state.remove_running(issue_id) {
                                        terminal_issue = Some(entry.issue.clone());
                                        let attempt = next_attempt(entry.retry_attempt);
                                        let retry_scheduled = schedule_failure_retry(
                                            &mut state,
                                            FailureRetryRequest {
                                                issue_id,
                                                identifier: &entry.identifier,
                                                attempt,
                                                max_backoff_ms: config_snapshot
                                                    .agent
                                                    .max_retry_backoff_ms,
                                                max_cycles: config_snapshot
                                                    .scheduler
                                                    .recovery
                                                    .as_ref()
                                                    .map(|recovery| recovery.max_attempts)
                                                    .unwrap_or(config_snapshot.max_cycles),
                                                error: &reason,
                                                retry_from_step: Some(step.clone()),
                                                with_fixup: false,
                                            },
                                        );
                                        final_failure = retry_scheduled.is_exhausted();
                                        if final_failure {
                                            parked_recovery = Self::park_exhausted_recovery(
                                                &mut state,
                                                &config_snapshot,
                                                ParkedRecoveryRequest {
                                                    issue_id,
                                                    entry: &entry,
                                                    step: &step,
                                                    attempt,
                                                    reason: &reason,
                                                },
                                                &mut post_failure_transitions,
                                            );
                                            final_failure = parked_recovery.is_none();
                                        }
                                        if final_failure {
                                            history_record =
                                                state.get_pipeline_run(issue_id).map(|run| {
                                                    rejection_comment =
                                                        Self::rejection_comment_for_step(
                                                            run, &step,
                                                        );
                                                    self.build_history_record(
                                                        RunningHistoryRecordInput {
                                                            outcome: HISTORY_OUTCOME_FAILED,
                                                            last_error: Some(reason.clone()),
                                                            running_entry: &entry,
                                                            run,
                                                            completed_at,
                                                            artifacts: state
                                                                .artifacts
                                                                .get(issue_id)
                                                                .cloned(),
                                                        },
                                                    )
                                                });
                                        }
                                        if let Some(retry_entry) = retry_scheduled.scheduled() {
                                            if let Some(input) = Self::transition_input_for_run(
                                                &state,
                                                issue_id,
                                                &entry.identifier,
                                                PipelineTransitionKind::StepRetryScheduled,
                                                Some(step.clone()),
                                                Some(reason.clone()),
                                                Some(retry_entry.clone()),
                                            ) {
                                                post_failure_transitions.push(input);
                                            }
                                        }
                                        if final_failure {
                                            state.running.insert(issue_id.to_string(), entry);
                                        } else {
                                            state.add_runtime_seconds(&entry);
                                        }
                                    }
                                }
                                OnFailure::Fixup => {
                                    let fixup_agent = runtime_step
                                        .as_ref()
                                        .and_then(|s| s.fixup_agent.as_deref())
                                        .or_else(|| {
                                            step_config.and_then(|s| s.fixup_agent.as_deref())
                                        });
                                    let Some(fixup_agent) = fixup_agent else {
                                        error!(
                                            issue_id = %issue_id,
                                            step = %step,
                                            "fixup step missing fixup_agent after config validation"
                                        );
                                        if let Some(entry) = state.remove_running(issue_id) {
                                            state.add_runtime_seconds(&entry);
                                        }
                                        state.remove_pipeline_run(issue_id);
                                        return;
                                    };

                                    if let Some(run) = state.get_pipeline_run_mut(issue_id) {
                                        run.retry_from_step_with_fixup(&step, fixup_agent);
                                    }
                                    if let Some(entry) = state.remove_running(issue_id) {
                                        terminal_issue = Some(entry.issue.clone());
                                        let attempt = next_attempt(entry.retry_attempt);
                                        let retry_scheduled = schedule_failure_retry(
                                            &mut state,
                                            FailureRetryRequest {
                                                issue_id,
                                                identifier: &entry.identifier,
                                                attempt,
                                                max_backoff_ms: config_snapshot
                                                    .agent
                                                    .max_retry_backoff_ms,
                                                max_cycles: config_snapshot
                                                    .scheduler
                                                    .recovery
                                                    .as_ref()
                                                    .map(|recovery| recovery.max_attempts)
                                                    .unwrap_or(config_snapshot.max_cycles),
                                                error: &reason,
                                                retry_from_step: Some(step.clone()),
                                                with_fixup: true,
                                            },
                                        );
                                        final_failure = retry_scheduled.is_exhausted();
                                        if final_failure {
                                            parked_recovery = Self::park_exhausted_recovery(
                                                &mut state,
                                                &config_snapshot,
                                                ParkedRecoveryRequest {
                                                    issue_id,
                                                    entry: &entry,
                                                    step: &step,
                                                    attempt,
                                                    reason: &reason,
                                                },
                                                &mut post_failure_transitions,
                                            );
                                            final_failure = parked_recovery.is_none();
                                        }
                                        if final_failure {
                                            history_record =
                                                state.get_pipeline_run(issue_id).map(|run| {
                                                    rejection_comment =
                                                        Self::rejection_comment_for_step(
                                                            run, &step,
                                                        );
                                                    self.build_history_record(
                                                        RunningHistoryRecordInput {
                                                            outcome: HISTORY_OUTCOME_FAILED,
                                                            last_error: Some(reason.clone()),
                                                            running_entry: &entry,
                                                            run,
                                                            completed_at,
                                                            artifacts: state
                                                                .artifacts
                                                                .get(issue_id)
                                                                .cloned(),
                                                        },
                                                    )
                                                });
                                        }
                                        if let Some(retry_entry) = retry_scheduled.scheduled() {
                                            if let Some(input) = Self::transition_input_for_run(
                                                &state,
                                                issue_id,
                                                &entry.identifier,
                                                PipelineTransitionKind::FixupRetryScheduled,
                                                Some(step.clone()),
                                                Some(reason.clone()),
                                                Some(retry_entry.clone()),
                                            ) {
                                                post_failure_transitions.push(input);
                                            }
                                        }
                                        if final_failure {
                                            state.running.insert(issue_id.to_string(), entry);
                                        } else {
                                            state.add_runtime_seconds(&entry);
                                        }
                                    }
                                }
                                OnFailure::Halt => {
                                    warn!(
                                        issue_id = %issue_id,
                                        step = %step,
                                        reason = %reason,
                                        "pipeline halted, waiting for manual intervention"
                                    );
                                    if let Some(entry) = state.remove_running(issue_id) {
                                        state.add_runtime_seconds(&entry);
                                        let agent_name = runtime_step
                                            .as_ref()
                                            .map(|s| s.agent.clone())
                                            .or_else(|| step_config.map(|s| s.agent.clone()))
                                            .unwrap_or_default();
                                        state.add_waiting_on_human(WaitingOnHumanEntry {
                                            issue_id: issue_id.to_string(),
                                            identifier: entry.identifier.clone(),
                                            interaction_request_id: format!(
                                                "halted:{issue_id}:{step}"
                                            ),
                                            step_name: step.clone(),
                                            kind: InteractionKind::Handoff,
                                            prompt: reason.clone(),
                                            agent_name,
                                            retry_attempt: entry.retry_attempt,
                                            started_at: Some(entry.started_at),
                                            agent_input_tokens: entry.agent_input_tokens,
                                            agent_output_tokens: entry.agent_output_tokens,
                                            agent_total_tokens: entry.agent_total_tokens,
                                            requested_at: Utc::now(),
                                            run_id: entry.run_id.clone(),
                                            issue: Some(entry.issue.clone()),
                                        });
                                        if let Some(input) = Self::transition_input_for_run(
                                            &state,
                                            issue_id,
                                            &entry.identifier,
                                            PipelineTransitionKind::PipelineHalted,
                                            Some(step.clone()),
                                            Some(reason.clone()),
                                            None,
                                        ) {
                                            post_failure_transitions.push(input);
                                        }
                                    }
                                }
                                OnFailure::RetryIssue => {
                                    if let Some(entry) = state.remove_running(issue_id) {
                                        terminal_issue = Some(entry.issue.clone());
                                        let attempt = next_attempt(entry.retry_attempt);
                                        let retry_scheduled = schedule_failure_retry(
                                            &mut state,
                                            FailureRetryRequest {
                                                issue_id,
                                                identifier: &entry.identifier,
                                                attempt,
                                                max_backoff_ms: config_snapshot
                                                    .agent
                                                    .max_retry_backoff_ms,
                                                max_cycles: Self::automatic_recovery_max_attempts(
                                                    &config_snapshot,
                                                ),
                                                error: &reason,
                                                retry_from_step: None,
                                                with_fixup: false,
                                            },
                                        );
                                        final_failure = retry_scheduled.is_exhausted();
                                        if final_failure {
                                            parked_recovery = Self::park_exhausted_recovery(
                                                &mut state,
                                                &config_snapshot,
                                                ParkedRecoveryRequest {
                                                    issue_id,
                                                    entry: &entry,
                                                    step: &step,
                                                    attempt,
                                                    reason: &reason,
                                                },
                                                &mut post_failure_transitions,
                                            );
                                        }
                                        if parked_recovery.is_some() {
                                            final_failure = false;
                                        }
                                        if final_failure {
                                            history_record =
                                                state.get_pipeline_run(issue_id).map(|run| {
                                                    rejection_comment =
                                                        Self::rejection_comment_for_step(
                                                            run, &step,
                                                        );
                                                    self.build_history_record(
                                                        RunningHistoryRecordInput {
                                                            outcome: HISTORY_OUTCOME_FAILED,
                                                            last_error: Some(reason.clone()),
                                                            running_entry: &entry,
                                                            run,
                                                            completed_at,
                                                            artifacts: state
                                                                .artifacts
                                                                .get(issue_id)
                                                                .cloned(),
                                                        },
                                                    )
                                                });
                                        }
                                        if let Some(retry_entry) = retry_scheduled.scheduled() {
                                            if let Some(input) = Self::prepare_whole_issue_retry(
                                                &mut state,
                                                &config_snapshot,
                                                issue_id,
                                                &entry.identifier,
                                                &reason,
                                                retry_entry.clone(),
                                            ) {
                                                post_failure_transitions.push(input);
                                            }
                                        }
                                        if final_failure {
                                            state.running.insert(issue_id.to_string(), entry);
                                        } else {
                                            state.add_runtime_seconds(&entry);
                                        }
                                    }
                                }
                            }

                            let target_state = config_snapshot.on_failure.clone();
                            drop(state);
                            for input in post_failure_transitions {
                                self.append_pipeline_transition(input).await;
                            }
                            if let Some((identifier, attempt, reason)) = parked_recovery {
                                self.report_recovery_exhausted_attention(
                                    issue_id,
                                    &identifier,
                                    attempt,
                                    &reason,
                                )
                                .await;
                                return;
                            }
                            if final_failure {
                                if let Some((step_name, summary)) = rejection_comment {
                                    self.post_rejection_summary_comment(
                                        issue_id, &step_name, &summary,
                                    )
                                    .await;
                                }
                                if let Some(issue) = terminal_issue {
                                    self.begin_terminal_transition(
                                        &issue,
                                        TerminalOutcome::Failed,
                                        target_state,
                                        history_record,
                                    )
                                    .await;
                                }
                            }
                        }
                        PipelineAction::BlockedOnHuman { .. } => {}
                        PipelineAction::AwaitingApproval {
                            step,
                            approval_state,
                        } => {
                            let Some(config_snapshot) = config_snapshot else {
                                warn!(issue_id = %issue_id, "no config snapshot found for pipeline approval");
                                return;
                            };
                            drop(state);
                            if let Err(error) = self
                                .append_successful_step_and_routes(
                                    step_transition,
                                    route_transitions,
                                    issue_snapshot.as_ref(),
                                    route_events,
                                    route_event_contexts,
                                    None,
                                )
                                .await
                            {
                                warn!(issue_id = %issue_id, error = %error, "failed to durably persist route selection before approval");
                                self.handle_pipeline_step_failure(
                                    issue_id,
                                    step_name,
                                    format!("failed to persist route selection: {error}; retry source step '{step_name}'"),
                                    false,
                                )
                                .await;
                                return;
                            }
                            if !self
                                .publish_route_candidate(
                                    issue_id,
                                    route_candidate,
                                    route_previous_snapshot.as_ref(),
                                )
                                .await
                            {
                                self.recover_unpublished_route_candidate(issue_id, step_name)
                                    .await;
                                return;
                            }
                            if let Err(error) = self
                                .handle_post_step_approval(
                                    issue_id,
                                    &step,
                                    approval_state,
                                    approval_request.as_ref(),
                                    issue_snapshot.as_ref(),
                                )
                                .await
                            {
                                warn!(
                                    issue_id = %issue_id,
                                    step = %step,
                                    error = %error,
                                    "failed to create post-step approval checkpoint"
                                );

                                let mut state = self.state.write().await;
                                if let Some(run) = state.get_pipeline_run_mut(issue_id) {
                                    run.step_failed(&step, error.to_string());
                                }
                                let terminal = state.remove_running(issue_id).map(|entry| {
                                    self.schedule_whole_issue_failure_retry(
                                        &mut state,
                                        &config_snapshot,
                                        entry,
                                        &error.to_string(),
                                        ScheduledRetryPipeline::Release,
                                    )
                                });
                                drop(state);
                                self.commit_whole_issue_failure_retry(terminal).await;
                            }
                        }
                        PipelineAction::Waiting | PipelineAction::AwaitingAction { .. } => {
                            debug!(issue_id = %issue_id, "pipeline waiting for other steps");
                            drop(state);
                            if let Err(error) = self
                                .append_successful_step_and_routes(
                                    step_transition,
                                    route_transitions,
                                    issue_snapshot.as_ref(),
                                    route_events,
                                    route_event_contexts,
                                    None,
                                )
                                .await
                            {
                                warn!(issue_id = %issue_id, error = %error, "failed to durably persist route selection before waiting");
                                self.handle_pipeline_step_failure(
                                    issue_id,
                                    step_name,
                                    format!("failed to persist route selection: {error}; retry source step '{step_name}'"),
                                    false,
                                )
                                .await;
                                return;
                            }
                            if !self
                                .publish_route_candidate(
                                    issue_id,
                                    route_candidate,
                                    route_previous_snapshot.as_ref(),
                                )
                                .await
                            {
                                self.recover_unpublished_route_candidate(issue_id, step_name)
                                    .await;
                                return;
                            }

                            if action_is_pending_effect {
                                drop(action_mutation_guard);
                                if let Some(action) =
                                    self.apply_pending_step_actions(issue_id).await
                                {
                                    self.handle_applied_action_outcome(
                                        issue_id,
                                        action,
                                        worker_exit_permit,
                                    )
                                    .await;
                                }
                            }

                            let mut state = self.state.write().await;
                            let issue_waiting_on_human = state.is_waiting_on_human(issue_id);
                            let has_running_steps = state
                                .get_pipeline_run(issue_id)
                                .is_some_and(Self::pipeline_has_running_steps);
                            if issue_waiting_on_human && !has_running_steps {
                                if let Some(entry) = state.remove_running(issue_id) {
                                    state.add_runtime_seconds(&entry);
                                }
                            }
                        }
                    }
                }
            }
            WorkerResult::BlockedOnHuman { request } => {
                // Keep the all-exit Artifact outcome boxed before entering interaction handling.
                let artifact_outcome = self
                    .process_artifacts_after_worker_exit(
                        issue_id,
                        step_name,
                        StepOutput {
                            result: StepResult::Succeeded,
                            summary: None,
                            output: None,
                        },
                        false,
                        workspace_capture_held,
                    )
                    .await;
                let ArtifactWorkerExitOutcome {
                    output,
                    deferred_sibling_exits,
                    integrity_failed,
                    ..
                } = *artifact_outcome;
                for event in deferred_sibling_exits {
                    if self.worker_tx.send(event).await.is_err() {
                        warn!(issue_id = %issue_id, "failed to restore deferred sibling worker exit");
                    }
                }
                if integrity_failed {
                    let reason = match output.result {
                        StepResult::Failed { summary } => summary,
                        StepResult::Succeeded | StepResult::Concern { .. } => {
                            "immutable Artifact input could not be verified".to_string()
                        }
                    };
                    self.handle_pipeline_step_failure(issue_id, step_name, reason, true)
                        .await;
                    return;
                }
                if let Err(error) = self
                    .handle_blocked_on_human(issue_id, step_name, &request, issue_snapshot.as_ref())
                    .await
                {
                    warn!(
                        issue_id = %issue_id,
                        step = step_name,
                        error = %error,
                        "blocked-on-human handling failed"
                    );

                    let mut state = self.state.write().await;
                    let Some(config_snapshot) = state.get_pipeline_config(issue_id).cloned() else {
                        warn!(
                            issue_id = %issue_id,
                            "retaining failed blocked interaction because its config snapshot is missing"
                        );
                        return;
                    };
                    if let Some(run) = state.get_pipeline_run_mut(issue_id) {
                        run.step_failed(step_name, error.to_string());
                    }
                    let terminal = state.remove_running(issue_id).map(|entry| {
                        self.schedule_whole_issue_failure_retry(
                            &mut state,
                            &config_snapshot,
                            entry,
                            &error.to_string(),
                            ScheduledRetryPipeline::Release,
                        )
                    });
                    drop(state);
                    self.commit_whole_issue_failure_retry(terminal).await;
                }
            }
            WorkerResult::Failed { error, kind } => {
                // Keep the #480 Artifact result off this already large failure/retry future.
                let mut artifact_outcome = self
                    .process_artifacts_after_worker_exit(
                        issue_id,
                        step_name,
                        worker_failure_output(error.clone()),
                        false,
                        workspace_capture_held,
                    )
                    .await;
                while let Some(event) = artifact_outcome.deferred_sibling_exits.pop() {
                    if self.worker_tx.send(event).await.is_err() {
                        warn!(issue_id = %issue_id, "failed to restore deferred sibling worker exit");
                    }
                }
                if artifact_outcome.integrity_failed {
                    let reason = match &artifact_outcome.output.result {
                        StepResult::Failed { summary } => summary.clone(),
                        StepResult::Succeeded | StepResult::Concern { .. } => {
                            "immutable Artifact input could not be verified".to_string()
                        }
                    };
                    self.handle_pipeline_step_failure(issue_id, step_name, reason, true)
                        .await;
                    return;
                }
                if kind == WorkerFailureKind::Timeout {
                    warn!(
                        issue_id = %issue_id,
                        step = step_name,
                        error = %error,
                        "worker exited with timeout"
                    );
                    self.handle_pipeline_step_failure(issue_id, step_name, error, false)
                        .await;
                    return;
                }

                let mut state = self.state.write().await;
                let Some(config_snapshot) = state.get_pipeline_config(issue_id).cloned() else {
                    warn!(
                        issue_id = %issue_id,
                        "retaining failed worker because its config snapshot is missing"
                    );
                    return;
                };
                warn!(
                    issue_id = %issue_id,
                    step = step_name,
                    error = %error,
                    "worker exited with failure"
                );

                if let Some(run) = state.get_pipeline_run_mut(issue_id) {
                    run.step_failed(step_name, error.clone());
                }

                let completed_at = Utc::now();
                let mut final_failure = false;
                let mut history_record = None;
                let mut terminal_issue = None;
                let mut retry_transition = None;
                let mut parked_recovery = None;
                let mut parked_transitions = Vec::new();

                if let Some(entry) = state.running.get(issue_id).cloned() {
                    terminal_issue = Some(entry.issue.clone());
                    let retry_scheduled = if retry::is_non_retryable_failure(&error) {
                        None
                    } else {
                        Some(schedule_failure_retry(
                            &mut state,
                            FailureRetryRequest {
                                issue_id,
                                identifier: &entry.identifier,
                                attempt: next_attempt(entry.retry_attempt),
                                max_backoff_ms: config_snapshot.agent.max_retry_backoff_ms,
                                max_cycles: Self::automatic_recovery_max_attempts(&config_snapshot),
                                error: &error,
                                retry_from_step: None,
                                with_fixup: false,
                            },
                        ))
                    };
                    final_failure = retry_scheduled
                        .as_ref()
                        .is_none_or(FailureRetryDisposition::is_exhausted);
                    if final_failure && retry_scheduled.is_some() {
                        let attempt = next_attempt(entry.retry_attempt);
                        parked_recovery = Self::park_exhausted_recovery(
                            &mut state,
                            &config_snapshot,
                            ParkedRecoveryRequest {
                                issue_id,
                                entry: &entry,
                                step: step_name,
                                attempt,
                                reason: &error,
                            },
                            &mut parked_transitions,
                        );
                        final_failure = parked_recovery.is_none();
                    }
                    if final_failure {
                        history_record = state.get_pipeline_run(issue_id).map(|run| {
                            self.build_history_record(RunningHistoryRecordInput {
                                outcome: HISTORY_OUTCOME_FAILED,
                                last_error: Some(error.clone()),
                                running_entry: &entry,
                                run,
                                completed_at,
                                artifacts: state.artifacts.get(issue_id).cloned(),
                            })
                        });
                    } else if let Some(retry_entry) =
                        retry_scheduled.as_ref().and_then(|retry| retry.scheduled())
                    {
                        if let Some(entry) = state.remove_running(issue_id) {
                            state.add_runtime_seconds(&entry);
                        }
                        retry_transition = Self::prepare_whole_issue_retry(
                            &mut state,
                            &config_snapshot,
                            issue_id,
                            &entry.identifier,
                            &error,
                            retry_entry.clone(),
                        );
                    }
                }

                let target_state = config_snapshot.on_failure.clone();
                drop(state);
                if let Some(input) = retry_transition {
                    self.append_pipeline_transition(input).await;
                }
                for input in parked_transitions {
                    self.append_pipeline_transition(input).await;
                }
                if let Some((identifier, attempt, reason)) = parked_recovery {
                    self.report_recovery_exhausted_attention(
                        issue_id,
                        &identifier,
                        attempt,
                        &reason,
                    )
                    .await;
                    return;
                }
                if final_failure {
                    if let Some(issue) = terminal_issue {
                        self.begin_terminal_transition(
                            &issue,
                            TerminalOutcome::Failed,
                            target_state,
                            history_record,
                        )
                        .await;
                    }
                }
            }
        }
    }

    fn schedule_whole_issue_failure_retry(
        &self,
        state: &mut OrchestratorState,
        config: &EnsembleConfig,
        entry: crate::tracker::model::RunningEntry,
        error: &str,
        scheduled_pipeline: ScheduledRetryPipeline,
    ) -> WholeIssueFailureRetry {
        let issue_id = entry.issue.id.clone();
        let disposition = schedule_failure_retry(
            state,
            FailureRetryRequest {
                issue_id: &issue_id,
                identifier: &entry.identifier,
                attempt: next_attempt(entry.retry_attempt),
                max_backoff_ms: config.agent.max_retry_backoff_ms,
                max_cycles: Self::automatic_recovery_max_attempts(config),
                error,
                retry_from_step: None,
                with_fixup: false,
            },
        );

        match disposition {
            FailureRetryDisposition::Scheduled(retry_entry) => {
                state.add_runtime_seconds(&entry);
                let transition = if matches!(scheduled_pipeline, ScheduledRetryPipeline::Release) {
                    Self::prepare_whole_issue_retry(
                        state,
                        config,
                        &issue_id,
                        &entry.identifier,
                        error,
                        retry_entry,
                    )
                } else {
                    Self::transition_input_for_run(
                        state,
                        &issue_id,
                        &entry.identifier,
                        PipelineTransitionKind::StepRetryScheduled,
                        None,
                        Some(error.to_string()),
                        Some(retry_entry),
                    )
                };
                WholeIssueFailureRetry::Scheduled(transition.map(Box::new))
            }
            FailureRetryDisposition::Exhausted => {
                if config.scheduler.recovery.is_some() {
                    let mut transitions = Vec::new();
                    let attempt = next_attempt(entry.retry_attempt);
                    let parked = Self::park_exhausted_recovery(
                        state,
                        config,
                        ParkedRecoveryRequest {
                            issue_id: &issue_id,
                            entry: &entry,
                            step: "runtime",
                            attempt,
                            reason: error,
                        },
                        &mut transitions,
                    )
                    .expect("configured recovery parks exhausted automatic retries");
                    return WholeIssueFailureRetry::Parked {
                        transition: transitions.pop().map(Box::new),
                        identifier: parked.0,
                        attempt: parked.1,
                        reason: parked.2,
                    };
                }
                state.running.insert(issue_id.clone(), entry.clone());
                let history_record = state.get_pipeline_run(&issue_id).map(|run| {
                    self.build_history_record(RunningHistoryRecordInput {
                        outcome: HISTORY_OUTCOME_FAILED,
                        last_error: Some(error.to_string()),
                        running_entry: &entry,
                        run,
                        completed_at: Utc::now(),
                        artifacts: state.artifacts.get(&issue_id).cloned(),
                    })
                });
                WholeIssueFailureRetry::Exhausted(Box::new(ExhaustedRetryTerminal {
                    issue: entry.issue.clone(),
                    target_state: config.on_failure.clone(),
                    history_record,
                }))
            }
        }
    }

    fn prepare_whole_issue_retry(
        state: &mut OrchestratorState,
        config: &EnsembleConfig,
        issue_id: &str,
        identifier: &str,
        error: &str,
        retry_entry: RetryEntry,
    ) -> Option<PipelineTransitionInput> {
        let dag = build_dag(&config.steps).ok()?;
        let acceptance_attempts = state
            .get_pipeline_run(issue_id)
            .map(|run| run.acceptance_attempts.clone())
            .unwrap_or_default();
        let ownership_lease = state
            .get_pipeline_run(issue_id)
            .and_then(PipelineRun::ownership_lease)
            .cloned();
        let workspace_branch_name = state
            .get_pipeline_run(issue_id)
            .and_then(PipelineRun::workspace_branch_name)
            .map(str::to_owned);
        let selected_workflow = state
            .get_pipeline_run(issue_id)
            .and_then(PipelineRun::selected_workflow)
            .cloned();
        let mut next_run = PipelineRun::new(issue_id.to_string(), retry_entry.attempt, dag);
        next_run.acceptance_attempts = acceptance_attempts;
        next_run.resolved_acceptance_plan = Some(ResolvedAcceptancePlan::from_config(config).ok()?);
        if let Some(ownership_lease) = ownership_lease {
            next_run.set_ownership_lease(ownership_lease);
        }
        if let Some(workspace_branch_name) = workspace_branch_name {
            next_run.set_workspace_branch_name(workspace_branch_name);
        }
        if let Some(selected_workflow) = selected_workflow {
            next_run.set_selected_workflow(selected_workflow);
        }
        state.insert_pipeline_run(issue_id, next_run, Arc::new(config.clone()));
        Self::transition_input_for_run(
            state,
            issue_id,
            identifier,
            PipelineTransitionKind::StepRetryScheduled,
            None,
            Some(error.to_string()),
            Some(retry_entry),
        )
    }

    // Keep terminal transition delivery out of the already-large failure scheduling future.
    fn commit_whole_issue_failure_retry(
        &self,
        outcome: Option<WholeIssueFailureRetry>,
    ) -> Pin<Box<dyn Future<Output = ()> + Send + '_>> {
        Box::pin(self.commit_whole_issue_failure_retry_inner(outcome))
    }

    async fn commit_whole_issue_failure_retry_inner(
        &self,
        outcome: Option<WholeIssueFailureRetry>,
    ) {
        match outcome {
            Some(WholeIssueFailureRetry::Scheduled(Some(input))) => {
                self.append_pipeline_transition(*input).await;
            }
            Some(WholeIssueFailureRetry::Exhausted(terminal)) => {
                let terminal = *terminal;
                self.begin_terminal_transition(
                    &terminal.issue,
                    TerminalOutcome::Failed,
                    terminal.target_state,
                    terminal.history_record,
                )
                .await;
            }
            Some(WholeIssueFailureRetry::Parked {
                transition,
                identifier,
                attempt,
                reason,
            }) => {
                let issue_id = transition
                    .as_ref()
                    .map(|input| input.issue_id.clone())
                    .unwrap_or_else(|| identifier.clone());
                if let Some(input) = transition {
                    self.append_pipeline_transition(*input).await;
                }
                self.report_recovery_exhausted_attention(&issue_id, &identifier, attempt, &reason)
                    .await;
            }
            Some(WholeIssueFailureRetry::Scheduled(None)) | None => {}
        }
    }

    async fn handle_pipeline_step_failure(
        &self,
        issue_id: &str,
        step: &str,
        reason: String,
        force_integrity_halt: bool,
    ) {
        let mut state = self.state.write().await;
        let Some(config_snapshot) = state.get_pipeline_config(issue_id).cloned() else {
            warn!(
                issue_id = %issue_id,
                "retaining timed-out worker because its config snapshot is missing"
            );
            return;
        };

        if let Some(run) = state.get_pipeline_run_mut(issue_id) {
            run.step_failed(step, reason.clone());
        }

        let step_failed_transition = Self::transition_input_for_run(
            &state,
            issue_id,
            state
                .running
                .get(issue_id)
                .map(|entry| entry.identifier.as_str())
                .unwrap_or(issue_id),
            PipelineTransitionKind::StepFailed,
            Some(step.to_string()),
            Some(reason.clone()),
            None,
        );
        let completed_at = Utc::now();
        let mut final_failure = false;
        let mut history_record = None;
        let mut terminal_issue = None;
        let mut rejection_comment = None;
        let mut parked_recovery = None;
        let mut post_failure_transitions = Vec::new();
        if let Some(input) = step_failed_transition {
            post_failure_transitions.push(input);
        }
        let step_name = step.to_string();
        let runtime_step = state
            .get_pipeline_run(issue_id)
            .and_then(|run| run.step(step))
            .cloned();
        let step_config = config_snapshot.steps.iter().find(|s| s.name == step);
        let on_failure = if force_integrity_halt {
            OnFailure::Halt
        } else {
            runtime_step
                .as_ref()
                .map(|s| s.on_failure)
                .or_else(|| step_config.map(|s| s.on_failure))
                .unwrap_or_default()
        };

        match on_failure {
            OnFailure::RetryStep => {
                if let Some(run) = state.get_pipeline_run_mut(issue_id) {
                    run.retry_from_step(step);
                }
                if let Some(entry) = state.remove_running(issue_id) {
                    terminal_issue = Some(entry.issue.clone());
                    let attempt = next_attempt(entry.retry_attempt);
                    let retry_scheduled = schedule_failure_retry(
                        &mut state,
                        FailureRetryRequest {
                            issue_id,
                            identifier: &entry.identifier,
                            attempt,
                            max_backoff_ms: config_snapshot.agent.max_retry_backoff_ms,
                            max_cycles: Self::automatic_recovery_max_attempts(&config_snapshot),
                            error: &reason,
                            retry_from_step: Some(step_name.clone()),
                            with_fixup: false,
                        },
                    );
                    final_failure = retry_scheduled.is_exhausted();
                    if final_failure {
                        parked_recovery = Self::park_exhausted_recovery(
                            &mut state,
                            &config_snapshot,
                            ParkedRecoveryRequest {
                                issue_id,
                                entry: &entry,
                                step,
                                attempt,
                                reason: &reason,
                            },
                            &mut post_failure_transitions,
                        );
                        final_failure = parked_recovery.is_none();
                    }
                    if final_failure {
                        history_record = state.get_pipeline_run(issue_id).map(|run| {
                            rejection_comment = Self::rejection_comment_for_step(run, step);
                            self.build_history_record(RunningHistoryRecordInput {
                                outcome: HISTORY_OUTCOME_FAILED,
                                last_error: Some(reason.clone()),
                                running_entry: &entry,
                                run,
                                completed_at,
                                artifacts: state.artifacts.get(issue_id).cloned(),
                            })
                        });
                    }
                    if let Some(retry_entry) = retry_scheduled.scheduled() {
                        if let Some(input) = Self::transition_input_for_run(
                            &state,
                            issue_id,
                            &entry.identifier,
                            PipelineTransitionKind::StepRetryScheduled,
                            Some(step_name.clone()),
                            Some(reason.clone()),
                            Some(retry_entry.clone()),
                        ) {
                            post_failure_transitions.push(input);
                        }
                    }
                    if final_failure {
                        state.running.insert(issue_id.to_string(), entry);
                    } else {
                        state.add_runtime_seconds(&entry);
                    }
                }
            }
            OnFailure::Fixup => {
                let fixup_agent = runtime_step
                    .as_ref()
                    .and_then(|s| s.fixup_agent.as_deref())
                    .or_else(|| step_config.and_then(|s| s.fixup_agent.as_deref()));
                let Some(fixup_agent) = fixup_agent else {
                    error!(
                        issue_id = %issue_id,
                        step = %step,
                        "fixup step missing fixup_agent after config validation"
                    );
                    if let Some(entry) = state.remove_running(issue_id) {
                        state.add_runtime_seconds(&entry);
                    }
                    state.remove_pipeline_run(issue_id);
                    return;
                };

                if let Some(run) = state.get_pipeline_run_mut(issue_id) {
                    run.retry_from_step_with_fixup(step, fixup_agent);
                }
                if let Some(entry) = state.remove_running(issue_id) {
                    terminal_issue = Some(entry.issue.clone());
                    let attempt = next_attempt(entry.retry_attempt);
                    let retry_scheduled = schedule_failure_retry(
                        &mut state,
                        FailureRetryRequest {
                            issue_id,
                            identifier: &entry.identifier,
                            attempt,
                            max_backoff_ms: config_snapshot.agent.max_retry_backoff_ms,
                            max_cycles: Self::automatic_recovery_max_attempts(&config_snapshot),
                            error: &reason,
                            retry_from_step: Some(step_name.clone()),
                            with_fixup: true,
                        },
                    );
                    final_failure = retry_scheduled.is_exhausted();
                    if final_failure {
                        parked_recovery = Self::park_exhausted_recovery(
                            &mut state,
                            &config_snapshot,
                            ParkedRecoveryRequest {
                                issue_id,
                                entry: &entry,
                                step,
                                attempt,
                                reason: &reason,
                            },
                            &mut post_failure_transitions,
                        );
                        final_failure = parked_recovery.is_none();
                    }
                    if final_failure {
                        history_record = state.get_pipeline_run(issue_id).map(|run| {
                            rejection_comment = Self::rejection_comment_for_step(run, step);
                            self.build_history_record(RunningHistoryRecordInput {
                                outcome: HISTORY_OUTCOME_FAILED,
                                last_error: Some(reason.clone()),
                                running_entry: &entry,
                                run,
                                completed_at,
                                artifacts: state.artifacts.get(issue_id).cloned(),
                            })
                        });
                    }
                    if let Some(retry_entry) = retry_scheduled.scheduled() {
                        if let Some(input) = Self::transition_input_for_run(
                            &state,
                            issue_id,
                            &entry.identifier,
                            PipelineTransitionKind::FixupRetryScheduled,
                            Some(step_name.clone()),
                            Some(reason.clone()),
                            Some(retry_entry.clone()),
                        ) {
                            post_failure_transitions.push(input);
                        }
                    }
                    if final_failure {
                        state.running.insert(issue_id.to_string(), entry);
                    } else {
                        state.add_runtime_seconds(&entry);
                    }
                }
            }
            OnFailure::Halt => {
                warn!(
                    issue_id = %issue_id,
                    step = %step,
                    reason = %reason,
                    "pipeline halted, waiting for manual intervention"
                );
                if let Some(entry) = state.remove_running(issue_id) {
                    state.add_runtime_seconds(&entry);
                    let agent_name = runtime_step
                        .as_ref()
                        .map(|s| s.agent.clone())
                        .or_else(|| step_config.map(|s| s.agent.clone()))
                        .unwrap_or_default();
                    state.add_waiting_on_human(WaitingOnHumanEntry {
                        issue_id: issue_id.to_string(),
                        identifier: entry.identifier.clone(),
                        interaction_request_id: format!("halted:{issue_id}:{step}"),
                        step_name: step_name.clone(),
                        kind: InteractionKind::Handoff,
                        prompt: reason.clone(),
                        agent_name,
                        retry_attempt: entry.retry_attempt,
                        started_at: Some(entry.started_at),
                        agent_input_tokens: entry.agent_input_tokens,
                        agent_output_tokens: entry.agent_output_tokens,
                        agent_total_tokens: entry.agent_total_tokens,
                        requested_at: Utc::now(),
                        run_id: entry.run_id.clone(),
                        issue: Some(entry.issue.clone()),
                    });
                    if let Some(input) = Self::transition_input_for_run(
                        &state,
                        issue_id,
                        &entry.identifier,
                        PipelineTransitionKind::PipelineHalted,
                        Some(step_name.clone()),
                        Some(reason.clone()),
                        None,
                    ) {
                        post_failure_transitions.push(input);
                    }
                }
            }
            OnFailure::RetryIssue => {
                if let Some(entry) = state.remove_running(issue_id) {
                    terminal_issue = Some(entry.issue.clone());
                    let attempt = next_attempt(entry.retry_attempt);
                    let retry_scheduled = schedule_failure_retry(
                        &mut state,
                        FailureRetryRequest {
                            issue_id,
                            identifier: &entry.identifier,
                            attempt,
                            max_backoff_ms: config_snapshot.agent.max_retry_backoff_ms,
                            max_cycles: Self::automatic_recovery_max_attempts(&config_snapshot),
                            error: &reason,
                            retry_from_step: None,
                            with_fixup: false,
                        },
                    );
                    final_failure = retry_scheduled.is_exhausted();
                    if final_failure {
                        parked_recovery = Self::park_exhausted_recovery(
                            &mut state,
                            &config_snapshot,
                            ParkedRecoveryRequest {
                                issue_id,
                                entry: &entry,
                                step,
                                attempt,
                                reason: &reason,
                            },
                            &mut post_failure_transitions,
                        );
                        final_failure = parked_recovery.is_none();
                    }
                    if final_failure {
                        history_record = state.get_pipeline_run(issue_id).map(|run| {
                            rejection_comment = Self::rejection_comment_for_step(run, step);
                            self.build_history_record(RunningHistoryRecordInput {
                                outcome: HISTORY_OUTCOME_FAILED,
                                last_error: Some(reason.clone()),
                                running_entry: &entry,
                                run,
                                completed_at,
                                artifacts: state.artifacts.get(issue_id).cloned(),
                            })
                        });
                    }
                    if let Some(retry_entry) = retry_scheduled.scheduled() {
                        if let Some(input) = Self::prepare_whole_issue_retry(
                            &mut state,
                            &config_snapshot,
                            issue_id,
                            &entry.identifier,
                            &reason,
                            retry_entry.clone(),
                        ) {
                            post_failure_transitions.push(input);
                        }
                    }
                    if final_failure {
                        state.running.insert(issue_id.to_string(), entry);
                    } else {
                        state.add_runtime_seconds(&entry);
                    }
                }
            }
        }

        let target_state = config_snapshot.on_failure.clone();
        drop(state);
        for input in post_failure_transitions {
            self.append_pipeline_transition(input).await;
        }
        if let Some((identifier, attempt, reason)) = parked_recovery {
            self.report_recovery_exhausted_attention(issue_id, &identifier, attempt, &reason)
                .await;
            return;
        }
        if final_failure {
            if let Some((step_name, summary)) = rejection_comment {
                self.post_rejection_summary_comment(issue_id, &step_name, &summary)
                    .await;
            }
            if let Some(issue) = terminal_issue {
                self.begin_terminal_transition(
                    &issue,
                    TerminalOutcome::Failed,
                    target_state,
                    history_record,
                )
                .await;
            }
        }
    }

    fn rejection_comment_for_step(run: &PipelineRun, step_name: &str) -> Option<(String, String)> {
        match run.step_states.get(step_name) {
            Some(StepState::Failed { summary }) if !summary.trim().is_empty() => {
                Some((step_name.to_string(), summary.trim().to_string()))
            }
            _ => None,
        }
    }

    fn running_entry_from_waiting(
        waiting: WaitingOnHumanEntry,
        issue: &Issue,
        fallback_run_id: Option<String>,
    ) -> RunningEntry {
        RunningEntry {
            issue_id: issue.id.clone(),
            identifier: issue.identifier.clone(),
            run_id: waiting.run_id.or(fallback_run_id),
            issue: waiting.issue.unwrap_or_else(|| issue.clone()),
            session_id: None,
            agent_pid: None,
            last_agent_event: None,
            last_agent_timestamp: None,
            last_agent_message: None,
            agent_input_tokens: waiting.agent_input_tokens,
            agent_output_tokens: waiting.agent_output_tokens,
            agent_total_tokens: waiting.agent_total_tokens,
            last_reported_input_tokens: waiting.agent_input_tokens,
            last_reported_output_tokens: waiting.agent_output_tokens,
            last_reported_total_tokens: waiting.agent_total_tokens,
            turn_count: 0,
            retry_attempt: waiting.retry_attempt,
            started_at: waiting.started_at.unwrap_or(waiting.requested_at),
        }
    }

    fn restore_rejected_gate_owner(
        state: &mut OrchestratorState,
        issue_id: &str,
        previous: &RejectedGateOwnerSnapshot,
    ) {
        state.remove_retry(issue_id);
        state.remove_running(issue_id);
        state.remove_waiting_on_human(issue_id);
        state
            .pipeline_runs
            .insert(issue_id.to_string(), previous.run.clone());
        state
            .waiting_on_human
            .insert(issue_id.to_string(), previous.waiting.clone());
        if let Some(retry) = &previous.retry {
            state
                .retry_attempts
                .insert(issue_id.to_string(), retry.clone());
        }
        if let Some(running) = &previous.running {
            state.running.insert(issue_id.to_string(), running.clone());
        }
        if previous.claimed {
            state.add_claimed(issue_id);
        } else {
            state.remove_claimed(issue_id);
        }
        if previous.resume_requested {
            state.queue_resume(issue_id);
        } else {
            state.clear_resume_request(issue_id);
        }
    }

    async fn commit_rejected_gate_failure(
        &self,
        issue: &Issue,
        config: &EnsembleConfig,
        step: &crate::pipeline::dag::DagStep,
        reason: String,
        previous_run: PipelineRun,
        interaction_id: &str,
    ) -> Result<bool, EnsembleError> {
        let transaction = self
            .pipeline_journal
            .begin_issue_transition(&issue.id)
            .await;
        let (previous_owner, transition, preserves_waiting_owner, post_commit) = {
            let mut state = self.state.write().await;
            let previous_waiting =
                state
                    .waiting_on_human
                    .get(&issue.id)
                    .cloned()
                    .ok_or_else(|| AgentError::PromptError {
                        reason: format!(
                            "issue '{}' lost its waiting owner during gate rejection",
                            issue.identifier
                        ),
                    })?;
            let previous_retry = state.retry_attempts.get(&issue.id).cloned();
            let previous_running = state.running.get(&issue.id).cloned();
            let was_claimed = state.is_claimed(&issue.id);
            let resume_was_requested = state.is_resume_requested(&issue.id);
            let previous_owner = RejectedGateOwnerSnapshot {
                run: previous_run,
                waiting: previous_waiting,
                retry: previous_retry,
                running: previous_running,
                claimed: was_claimed,
                resume_requested: resume_was_requested,
            };
            let fallback_run_id = state.issue_run_ids.get(&issue.id).cloned();
            let waiting = state
                .remove_waiting_on_human(&issue.id)
                .expect("waiting owner was read while holding the same state lock");
            let running = Self::running_entry_from_waiting(waiting, issue, fallback_run_id);

            let (transition, preserves_waiting_owner, post_commit) = match step.on_failure {
                OnFailure::RetryIssue => {
                    let retry = schedule_failure_retry(
                        &mut state,
                        FailureRetryRequest {
                            issue_id: &issue.id,
                            identifier: &running.identifier,
                            attempt: next_attempt(running.retry_attempt),
                            max_backoff_ms: config.agent.max_retry_backoff_ms,
                            max_cycles: Self::automatic_recovery_max_attempts(config),
                            error: &reason,
                            retry_from_step: None,
                            with_fixup: false,
                        },
                    );
                    match retry {
                        FailureRetryDisposition::Scheduled(retry_entry) => {
                            state.add_runtime_seconds(&running);
                            let Some(mut transition) = Self::prepare_whole_issue_retry(
                                &mut state,
                                config,
                                &issue.id,
                                &running.identifier,
                                &reason,
                                retry_entry,
                            ) else {
                                Self::restore_rejected_gate_owner(
                                    &mut state,
                                    &issue.id,
                                    &previous_owner,
                                );
                                return Err(AgentError::PromptError {
                                    reason: format!(
                                        "gate rejection retry could not prepare a durable disposition for '{}'",
                                        issue.identifier
                                    ),
                                }
                                .into());
                            };
                            transition.step = Some(step.name.clone());
                            (transition, false, RejectedGatePostCommit::None)
                        }
                        FailureRetryDisposition::Exhausted => {
                            let attempt = next_attempt(running.retry_attempt);
                            let mut parked_transitions = Vec::new();
                            if let Some((identifier, attempt, parked_reason)) =
                                Self::park_exhausted_recovery(
                                    &mut state,
                                    config,
                                    ParkedRecoveryRequest {
                                        issue_id: &issue.id,
                                        entry: &running,
                                        step: &step.name,
                                        attempt,
                                        reason: &reason,
                                    },
                                    &mut parked_transitions,
                                )
                            {
                                let transition = parked_transitions.pop().ok_or_else(|| {
                                    AgentError::PromptError {
                                        reason: format!(
                                            "gate rejection could not prepare parked recovery for '{}'",
                                            issue.identifier
                                        ),
                                    }
                                })?;
                                (
                                    transition,
                                    false,
                                    RejectedGatePostCommit::Parked {
                                        identifier,
                                        attempt,
                                        reason: parked_reason,
                                    },
                                )
                            } else {
                                state.add_runtime_seconds(&running);
                                let history_record = state.get_pipeline_run(&issue.id).map(|run| {
                                    self.build_history_record(RunningHistoryRecordInput {
                                        outcome: HISTORY_OUTCOME_FAILED,
                                        last_error: Some(reason.clone()),
                                        running_entry: &running,
                                        run,
                                        completed_at: Utc::now(),
                                        artifacts: state.artifacts.get(&issue.id).cloned(),
                                    })
                                });
                                let terminal = PendingTerminalTransition {
                                    target_state: config.on_failure.clone(),
                                    outcome: TerminalOutcome::Failed,
                                    attempt: 0,
                                    last_error: None,
                                    last_attempted_at: None,
                                    tracker_write_confirmed: false,
                                    history_record,
                                };
                                let run = state.get_pipeline_run(&issue.id).ok_or_else(|| {
                                    AgentError::PromptError {
                                        reason: format!(
                                            "gate rejection lost its pipeline run for '{}'",
                                            issue.identifier
                                        ),
                                    }
                                })?;
                                let transition = PipelineTransitionInput {
                                    kind: PipelineTransitionKind::PendingTerminalTransition,
                                    issue_id: issue.id.clone(),
                                    identifier: running.identifier.clone(),
                                    run_id: running.run_id.clone(),
                                    cycle: run.cycle,
                                    step: Some(step.name.clone()),
                                    reason: Some(reason.clone()),
                                    retry: None,
                                    snapshot: Some(run.to_snapshot()),
                                    terminal_transition: Some(terminal.clone()),
                                    delivery: None,
                                };
                                (
                                    transition,
                                    false,
                                    RejectedGatePostCommit::Terminal {
                                        identifier: running.identifier.clone(),
                                        run_id: running.run_id.clone(),
                                        transition: Box::new(terminal),
                                    },
                                )
                            }
                        }
                    }
                }
                OnFailure::Halt => {
                    state.add_runtime_seconds(&running);
                    state.add_waiting_on_human(WaitingOnHumanEntry {
                        issue_id: issue.id.clone(),
                        identifier: running.identifier.clone(),
                        interaction_request_id: format!("halted:{}:{}", issue.id, step.name),
                        step_name: step.name.clone(),
                        kind: InteractionKind::Handoff,
                        prompt: reason.clone(),
                        agent_name: String::new(),
                        retry_attempt: running.retry_attempt,
                        started_at: Some(running.started_at),
                        agent_input_tokens: running.agent_input_tokens,
                        agent_output_tokens: running.agent_output_tokens,
                        agent_total_tokens: running.agent_total_tokens,
                        requested_at: Utc::now(),
                        run_id: running.run_id.clone(),
                        issue: Some(running.issue.clone()),
                    });
                    let transition = Self::transition_input_for_run(
                        &state,
                        &issue.id,
                        &running.identifier,
                        PipelineTransitionKind::PipelineHalted,
                        Some(step.name.clone()),
                        Some(reason.clone()),
                        None,
                    )
                    .ok_or_else(|| AgentError::PromptError {
                        reason: format!(
                            "gate rejection halt could not prepare a durable disposition for '{}'",
                            issue.identifier
                        ),
                    })?;
                    (transition, true, RejectedGatePostCommit::None)
                }
                _ => {
                    Self::restore_rejected_gate_owner(&mut state, &issue.id, &previous_owner);
                    return Err(AgentError::PromptError {
                        reason: format!(
                            "gate '{}' has unsupported rejection policy {:?}",
                            step.name, step.on_failure
                        ),
                    }
                    .into());
                }
            };

            (
                previous_owner,
                transition,
                preserves_waiting_owner,
                post_commit,
            )
        };

        let expected = transition.clone();
        let disposition_is_durable = match transaction.append(transition).await {
            Ok(_) => true,
            Err(append_error) => match transaction.latest_record_matches(&expected).await {
                Ok(true) => true,
                Ok(false) => {
                    warn!(
                        issue_id = %issue.id,
                        error = %append_error,
                        "gate rejection disposition was not persisted"
                    );
                    false
                }
                Err(reconciliation_error) => {
                    warn!(
                        issue_id = %issue.id,
                        append_error = %append_error,
                        reconciliation_error = %reconciliation_error,
                        "gate rejection disposition is ambiguous"
                    );
                    false
                }
            },
        };
        drop(transaction);

        if !disposition_is_durable {
            let mut state = self.state.write().await;
            Self::restore_rejected_gate_owner(&mut state, &issue.id, &previous_owner);
            return Err(AgentError::PromptError {
                reason: format!(
                    "gate rejection for '{}' was not durably persisted",
                    issue.identifier
                ),
            }
            .into());
        }

        if let RejectedGatePostCommit::Terminal {
            identifier,
            run_id,
            transition,
        } = &post_commit
        {
            let mut state = self.state.write().await;
            state.add_claimed(&issue.id);
            state.pending_terminal_transitions.insert(
                issue.id.clone(),
                PendingTerminalEntry {
                    identifier: identifier.clone(),
                    run_id: run_id.clone(),
                    issue: Some(issue.clone()),
                    transition: (**transition).clone(),
                },
            );
        }

        self.interaction_store.mark_resumed(interaction_id).await?;
        match post_commit {
            RejectedGatePostCommit::None => {}
            RejectedGatePostCommit::Parked {
                identifier,
                attempt,
                reason,
            } => {
                self.report_recovery_exhausted_attention(&issue.id, &identifier, attempt, &reason)
                    .await;
            }
            RejectedGatePostCommit::Terminal {
                identifier,
                run_id: _,
                transition,
            } => {
                self.begin_persisted_terminal_transition(
                    &issue.id,
                    &identifier,
                    Some(issue.clone()),
                    *transition,
                )
                .await;
            }
        }
        Ok(preserves_waiting_owner)
    }

    async fn post_rejection_summary_comment(&self, issue_id: &str, step_name: &str, summary: &str) {
        let body = format!("{REJECTION_COMMENT_PREFIX} at step `{step_name}`:\n\n{summary}");
        match self.tracker.add_comment(issue_id, &body).await {
            Ok(()) => {
                info!(
                    issue_id = %issue_id,
                    step = %step_name,
                    "posted rejection summary to tracker"
                );
            }
            Err(crate::tracker::TrackerError::WritesNotSupported) => {
                debug!(
                    issue_id = %issue_id,
                    step = %step_name,
                    "tracker does not support rejection summary comments"
                );
            }
            Err(error) => {
                warn!(
                    issue_id = %issue_id,
                    step = %step_name,
                    error = %error,
                    "failed to post rejection summary to tracker"
                );
            }
        }
    }

    async fn handle_blocked_on_human(
        &self,
        issue_id: &str,
        step_name: &str,
        request: &InteractionRequestDraft,
        issue_snapshot: Option<&Issue>,
    ) -> Result<(), EnsembleError> {
        let missing_blocked_issue_value = |value: &str| AgentError::PromptError {
            reason: format!("missing {value} for blocked issue {issue_id}"),
        };

        let issue =
            issue_snapshot.ok_or_else(|| missing_blocked_issue_value("running issue snapshot"))?;

        let interaction_context = {
            let state = self.state.read().await;
            let config = state
                .get_pipeline_config(issue_id)
                .ok_or_else(|| missing_blocked_issue_value("pipeline config"))?;
            let step = config
                .steps
                .iter()
                .find(|step| step.name == step_name)
                .ok_or_else(|| AgentError::PromptError {
                    reason: format!("blocked step '{step_name}' no longer exists"),
                })?;
            let run = state
                .get_pipeline_run(issue_id)
                .ok_or_else(|| missing_blocked_issue_value("pipeline run"))?;
            let completed_steps = config
                .steps
                .iter()
                .filter(|candidate| {
                    matches!(
                        run.step_states.get(&candidate.name),
                        Some(crate::pipeline::engine::StepState::Passed)
                    )
                })
                .map(|candidate| candidate.name.clone())
                .collect();
            InteractionRequestContext {
                step_name: step_name.to_string(),
                agent_name: step.agent.clone(),
                pipeline_cycle: run.cycle,
                completed_steps,
                step_depends: step.depends.clone().unwrap_or_default(),
                step_tracker_state: step.tracker_state.clone(),
            }
        };

        let (waiting_started_at, waiting_input_tokens, waiting_output_tokens, waiting_total_tokens) = {
            let state = self.state.read().await;
            let running_entry = state.running.get(issue_id);
            (
                running_entry.map(|entry| entry.started_at),
                running_entry
                    .map(|entry| entry.agent_input_tokens)
                    .unwrap_or(0),
                running_entry
                    .map(|entry| entry.agent_output_tokens)
                    .unwrap_or(0),
                running_entry
                    .map(|entry| entry.agent_total_tokens)
                    .unwrap_or(0),
            )
        };

        let mut interaction = build_interaction_request(
            issue,
            interaction_context,
            request.clone(),
            InteractionResumeStrategy::RerunStep,
        );
        interaction.waiting_started_at = waiting_started_at;
        interaction.agent_input_tokens = waiting_input_tokens;
        interaction.agent_output_tokens = waiting_output_tokens;
        interaction.agent_total_tokens = waiting_total_tokens;
        self.interaction_store.create(interaction.clone()).await?;
        self.report_awaiting_interaction(&interaction).await;
        let root_body = format_interaction_thread_root_comment(&interaction);
        match self
            .tracker
            .create_interaction_thread_root(&interaction.issue_id, &root_body)
            .await
        {
            Ok(root) => {
                if let Err(error) = self
                    .interaction_store
                    .attach_thread_metadata(
                        &interaction.id,
                        root.comment_id.clone(),
                        root.comment_url.clone(),
                    )
                    .await
                {
                    warn!(
                        interaction_id = %interaction.id,
                        error = %error,
                        "failed to persist interaction thread metadata"
                    );
                }
            }
            Err(error) => {
                warn!(
                    interaction_id = %interaction.id,
                    issue_id = %interaction.issue_id,
                    error = %error,
                    "failed to create interaction thread root comment"
                );
            }
        }

        let journal_transaction = self.pipeline_journal.begin_issue_transition(issue_id).await;
        let mut state = self.state.write().await;
        let (run_id, sequence, attempt) = Self::run_context_for_issue(&mut state, issue_id);
        let follow_up_sequence = run_id
            .as_ref()
            .map(|current_run_id| state.next_timeline_sequence(current_run_id));
        if let Some(run) = state.get_pipeline_run_mut(issue_id) {
            run.step_blocked_on_human(step_name, interaction.id.clone());
        }
        state.park_step_waiting_for_human(issue_id, step_name, interaction.id.clone());
        let has_running_steps = state
            .get_pipeline_run(issue_id)
            .is_some_and(Self::pipeline_has_running_steps);

        let (retry_attempt, waiting_issue, waiting_run_id) = {
            let entry = state.running.get(issue_id);
            (
                entry.and_then(|e| e.retry_attempt),
                entry.map(|e| e.issue.clone()),
                entry.and_then(|e| e.run_id.clone()),
            )
        };
        if !has_running_steps {
            if let Some(entry) = state.remove_running(issue_id) {
                state.add_runtime_seconds(&entry);
            }
        }
        state.add_waiting_on_human(WaitingOnHumanEntry {
            issue_id: issue.id.clone(),
            identifier: issue.identifier.clone(),
            interaction_request_id: interaction.id.clone(),
            step_name: step_name.to_string(),
            kind: interaction.kind.clone(),
            prompt: interaction.title.clone(),
            agent_name: interaction.agent_name.clone(),
            retry_attempt,
            started_at: waiting_started_at,
            agent_input_tokens: waiting_input_tokens,
            agent_output_tokens: waiting_output_tokens,
            agent_total_tokens: waiting_total_tokens,
            requested_at: interaction.requested_at,
            run_id: waiting_run_id,
            issue: waiting_issue,
        });
        let blocked_transition = Self::transition_input_for_run(
            &state,
            issue_id,
            &issue.identifier,
            PipelineTransitionKind::StepBlockedOnHuman,
            Some(step_name.to_string()),
            Some(interaction.id.clone()),
            None,
        );
        drop(state);
        if let Some(blocked_transition) = blocked_transition {
            let expected = blocked_transition.clone();
            if let Err(error) = journal_transaction.append(blocked_transition).await {
                match journal_transaction.latest_record_matches(&expected).await {
                    Ok(true) => {}
                    Ok(false) => warn!(
                        issue_id,
                        interaction_id = %interaction.id,
                        error = %error,
                        "blocked interaction checkpoint was not persisted; retaining the durable sidecar owner for reconciliation"
                    ),
                    Err(reconciliation_error) => warn!(
                        issue_id,
                        interaction_id = %interaction.id,
                        append_error = %error,
                        reconciliation_error = %reconciliation_error,
                        "blocked interaction checkpoint outcome is ambiguous; retaining the durable sidecar owner for reconciliation"
                    ),
                }
            }
        }

        self.publish_pipeline_event(
            run_id.clone(),
            sequence,
            attempt,
            PipelineEvent::QuestionAsked {
                issue_identifier: issue.identifier.clone(),
                timestamp: Utc::now(),
                step_name: step_name.to_string(),
                agent_name: interaction.agent_name.clone(),
                ask_id: interaction.id.clone(),
                detail: interaction.title.clone(),
            },
        )
        .await;

        self.publish_pipeline_event(
            run_id,
            follow_up_sequence,
            attempt,
            PipelineEvent::InputRequested {
                issue_identifier: issue.identifier.clone(),
                timestamp: Utc::now(),
                step_name: step_name.to_string(),
                kind: interaction_kind_name(&interaction.kind).to_string(),
                detail: interaction.title.clone(),
            },
        )
        .await;

        Ok(())
    }

    async fn handle_post_step_approval(
        &self,
        issue_id: &str,
        step_name: &str,
        approval_state: Option<String>,
        approval_request: Option<&StepApprovalRequestDraft>,
        issue_snapshot: Option<&Issue>,
    ) -> Result<(), EnsembleError> {
        let issue = issue_snapshot.ok_or_else(|| AgentError::PromptError {
            reason: format!("missing running issue snapshot for approval-gated issue {issue_id}"),
        })?;

        let (interaction_context, gate_evidence) = {
            let state = self.state.read().await;
            let config =
                state
                    .get_pipeline_config(issue_id)
                    .ok_or_else(|| AgentError::PromptError {
                        reason: format!("missing pipeline config for blocked issue {issue_id}"),
                    })?;
            let step = config
                .steps
                .iter()
                .find(|step| step.name == step_name)
                .ok_or_else(|| AgentError::PromptError {
                    reason: format!("approval-gated step '{step_name}' no longer exists"),
                })?;
            let run = state
                .get_pipeline_run(issue_id)
                .ok_or_else(|| AgentError::PromptError {
                    reason: format!("missing pipeline run for blocked issue {issue_id}"),
                })?;
            let completed_steps = config
                .steps
                .iter()
                .filter(|candidate| {
                    matches!(
                        run.step_states.get(&candidate.name),
                        Some(crate::pipeline::engine::StepState::Passed)
                    )
                })
                .map(|candidate| candidate.name.clone())
                .collect();
            (
                InteractionRequestContext {
                    step_name: step_name.to_string(),
                    agent_name: step.agent.clone(),
                    pipeline_cycle: run.cycle,
                    completed_steps,
                    step_depends: step.depends.clone().unwrap_or_default(),
                    step_tracker_state: step.tracker_state.clone(),
                },
                (step.kind == StepKind::Gate)
                    .then(|| run.gate_evidence.get(step_name).cloned())
                    .flatten(),
            )
        };

        let request = approval_request
            .cloned()
            .or_else(|| {
                gate_evidence
                    .as_ref()
                    .map(|evidence| gate_approval_request(step_name, evidence))
            })
            .unwrap_or_else(|| StepApprovalRequestDraft {
                schema_version: 1,
                title: format!("Approve step '{step_name}'"),
                body: format!(
                    "Step '{step_name}' completed successfully. Approve it to continue the pipeline."
                ),
                state: None,
            });
        let mirror_state = request.state.clone().or(approval_state);
        let (waiting_started_at, waiting_input_tokens, waiting_output_tokens, waiting_total_tokens) = {
            let state = self.state.read().await;
            let running_entry = state.running.get(issue_id);
            (
                running_entry.map(|entry| entry.started_at),
                running_entry
                    .map(|entry| entry.agent_input_tokens)
                    .unwrap_or(0),
                running_entry
                    .map(|entry| entry.agent_output_tokens)
                    .unwrap_or(0),
                running_entry
                    .map(|entry| entry.agent_total_tokens)
                    .unwrap_or(0),
            )
        };

        let mut interaction = build_interaction_request(
            issue,
            interaction_context,
            InteractionRequestDraft {
                schema_version: request.schema_version,
                kind: InteractionKind::ApprovalGate,
                blocking: true,
                title: request.title,
                body: request.body,
                options: vec!["approve".to_string(), "reject".to_string()],
                artifacts: vec![],
            },
            InteractionResumeStrategy::AdvanceAfterStep,
        );
        interaction.waiting_started_at = waiting_started_at;
        interaction.agent_input_tokens = waiting_input_tokens;
        interaction.agent_output_tokens = waiting_output_tokens;
        interaction.agent_total_tokens = waiting_total_tokens;
        self.interaction_store.create(interaction.clone()).await?;
        self.report_awaiting_interaction(&interaction).await;

        let root_body = format_interaction_thread_root_comment(&interaction);
        match self
            .tracker
            .create_interaction_thread_root(&interaction.issue_id, &root_body)
            .await
        {
            Ok(root) => {
                if let Err(error) = self
                    .interaction_store
                    .attach_thread_metadata(
                        &interaction.id,
                        root.comment_id.clone(),
                        root.comment_url.clone(),
                    )
                    .await
                {
                    warn!(
                        interaction_id = %interaction.id,
                        error = %error,
                        "failed to persist interaction thread metadata for approval gate"
                    );
                }
            }
            Err(error) => {
                warn!(
                    interaction_id = %interaction.id,
                    issue_id = %interaction.issue_id,
                    error = %error,
                    "failed to create interaction thread root for approval gate"
                );
            }
        }

        if let Some(state_name) = mirror_state {
            if self.tracker.supports_writes() {
                if let Err(error) = self.tracker.set_issue_state(issue_id, &state_name).await {
                    warn!(
                        issue_id = %issue_id,
                        step = %step_name,
                        tracker_state_to = %state_name,
                        error = %error,
                        "failed to set tracker state for approval checkpoint"
                    );
                }
            }
        }

        let journal_transaction = self.pipeline_journal.begin_issue_transition(issue_id).await;
        let mut state = self.state.write().await;
        let (run_id, sequence, attempt) = Self::run_context_for_issue(&mut state, issue_id);
        if let Some(run) = state.get_pipeline_run_mut(issue_id) {
            run.bind_approval_interaction(step_name, interaction.id.clone());
        }
        let has_running_steps = state
            .get_pipeline_run(issue_id)
            .is_some_and(Self::pipeline_has_running_steps);

        let (retry_attempt, waiting_issue, waiting_run_id) = {
            let entry = state.running.get(issue_id);
            (
                entry.and_then(|e| e.retry_attempt),
                entry.map(|e| e.issue.clone()),
                entry.and_then(|e| e.run_id.clone()),
            )
        };
        if !has_running_steps {
            if let Some(entry) = state.remove_running(issue_id) {
                state.add_runtime_seconds(&entry);
            }
        }

        state.add_waiting_on_human(WaitingOnHumanEntry {
            issue_id: issue.id.clone(),
            identifier: issue.identifier.clone(),
            interaction_request_id: interaction.id.clone(),
            step_name: step_name.to_string(),
            kind: interaction.kind.clone(),
            prompt: interaction.title.clone(),
            agent_name: interaction.agent_name.clone(),
            retry_attempt,
            started_at: waiting_started_at,
            agent_input_tokens: waiting_input_tokens,
            agent_output_tokens: waiting_output_tokens,
            agent_total_tokens: waiting_total_tokens,
            requested_at: interaction.requested_at,
            run_id: waiting_run_id,
            issue: waiting_issue,
        });
        let approval_transition = Self::transition_input_for_run(
            &state,
            issue_id,
            &issue.identifier,
            PipelineTransitionKind::StepAwaitingApproval,
            Some(step_name.to_string()),
            Some(interaction.id.clone()),
            None,
        );
        drop(state);
        if let Some(approval_transition) = approval_transition {
            let expected = approval_transition.clone();
            if let Err(error) = journal_transaction.append(approval_transition).await {
                match journal_transaction.latest_record_matches(&expected).await {
                    Ok(true) => {}
                    Ok(false) => warn!(
                        issue_id,
                        interaction_id = %interaction.id,
                        error = %error,
                        "approval checkpoint was not persisted; retaining the durable sidecar owner for reconciliation"
                    ),
                    Err(reconciliation_error) => warn!(
                        issue_id,
                        interaction_id = %interaction.id,
                        append_error = %error,
                        reconciliation_error = %reconciliation_error,
                        "approval checkpoint outcome is ambiguous; retaining the durable sidecar owner for reconciliation"
                    ),
                }
            }
        }

        self.publish_pipeline_event(
            run_id,
            sequence,
            attempt,
            PipelineEvent::InputRequested {
                issue_identifier: issue.identifier.clone(),
                timestamp: Utc::now(),
                step_name: step_name.to_string(),
                kind: interaction_kind_name(&interaction.kind).to_string(),
                detail: interaction.title.clone(),
            },
        )
        .await;

        Ok(())
    }

    async fn process_interaction_thread_commands(&self) {
        let interactions = match self.interaction_store.list_with_thread_roots().await {
            Ok(interactions) => interactions,
            Err(error) => {
                warn!(
                    error = %error,
                    "failed to list interaction threads while processing commands"
                );
                return;
            }
        };

        for mut interaction in interactions {
            let Some(root_comment_id) = interaction.thread_root_comment_id.clone() else {
                continue;
            };

            let anchor_id = interaction
                .last_processed_comment_id
                .as_deref()
                .unwrap_or(&root_comment_id);

            let comments = match self
                .tracker
                .list_comments_after(&interaction.issue_id, anchor_id)
                .await
            {
                Ok(comments) => comments,
                Err(error) => {
                    warn!(
                        interaction_id = %interaction.id,
                        issue_id = %interaction.issue_id,
                        error = %error,
                        "failed to list interaction thread comments"
                    );
                    continue;
                }
            };
            // Each persisted thread retains its own cursor, so completed interactions
            // request only comments after the last durably processed input.

            let mut last_persisted_comment_id = None;

            for comment in comments {
                if interaction
                    .accepted_command
                    .as_ref()
                    .is_some_and(|accepted| accepted.comment_id == comment.comment_id)
                    || interaction
                        .ignored_commands
                        .iter()
                        .any(|ignored| ignored.comment_id == comment.comment_id)
                {
                    last_persisted_comment_id = Some(comment.comment_id.clone());
                    continue;
                }

                if comment
                    .updated_at
                    .zip(comment.created_at)
                    .is_some_and(|(updated, created)| updated > created)
                {
                    let Some(updated) = self
                        .append_ignored_command(
                            &interaction,
                            None,
                            &comment,
                            "edited_comments_not_supported",
                        )
                        .await
                    else {
                        break;
                    };
                    interaction = updated;
                    last_persisted_comment_id = Some(comment.comment_id.clone());
                    continue;
                }

                let parsed = match parse_scoped_interaction_command(&comment.body) {
                    Ok(parsed) if parsed.interaction_id == interaction.id => parsed.command,
                    Ok(_) => {
                        let Some(updated) = self
                            .append_ignored_command(
                                &interaction,
                                None,
                                &comment,
                                "interaction_marker_mismatch",
                            )
                            .await
                        else {
                            break;
                        };
                        interaction = updated;
                        last_persisted_comment_id = Some(comment.comment_id.clone());
                        continue;
                    }
                    Err(ParseScopedInteractionCommandError::MissingMarker) => {
                        let Some(updated) = self
                            .append_ignored_command(
                                &interaction,
                                None,
                                &comment,
                                "comment_not_scoped_to_interaction",
                            )
                            .await
                        else {
                            break;
                        };
                        interaction = updated;
                        last_persisted_comment_id = Some(comment.comment_id.clone());
                        continue;
                    }
                    Err(_) => {
                        let Some(updated) = self
                            .append_ignored_command(
                                &interaction,
                                None,
                                &comment,
                                "not_a_supported_command",
                            )
                            .await
                        else {
                            break;
                        };
                        interaction = updated;
                        last_persisted_comment_id = Some(comment.comment_id.clone());
                        continue;
                    }
                };

                let response = match response_from_command(&interaction.kind, &parsed) {
                    Some(response) => response,
                    None => {
                        let Some(updated) = self
                            .append_ignored_command(
                                &interaction,
                                Some(parsed.command_name()),
                                &comment,
                                "command_invalid_for_interaction_kind",
                            )
                            .await
                        else {
                            break;
                        };
                        interaction = updated;
                        last_persisted_comment_id = Some(comment.comment_id.clone());
                        continue;
                    }
                };

                let accepted_result = self
                    .interaction_store
                    .accept_response(
                        &interaction.id,
                        AcceptedInteractionCommand {
                            command: parsed.command_name().to_string(),
                            raw_body: comment.body.clone(),
                            author: comment.author.clone(),
                            comment_id: comment.comment_id.clone(),
                            received_at: comment.created_at.unwrap_or_else(Utc::now),
                        },
                        response,
                    )
                    .await;

                match accepted_result {
                    Ok(InteractionAcceptance::Accepted(updated)) => {
                        interaction = updated;
                        last_persisted_comment_id = Some(comment.comment_id.clone());
                        let mut state = self.state.write().await;
                        state.queue_resume(&interaction.issue_id);
                    }
                    Ok(InteractionAcceptance::Ignored(updated)) => {
                        interaction = updated;
                        last_persisted_comment_id = Some(comment.comment_id.clone());
                    }
                    Err(error) => {
                        warn!(
                            interaction_id = %interaction.id,
                            error = %error,
                            "failed to accept interaction command"
                        );
                        let Some(updated) = self
                            .append_ignored_command(
                                &interaction,
                                Some(parsed.command_name()),
                                &comment,
                                "interaction_acceptance_failed",
                            )
                            .await
                        else {
                            break;
                        };
                        interaction = updated;
                        last_persisted_comment_id = Some(comment.comment_id.clone());
                    }
                }
            }

            if let Some(last_id) = last_persisted_comment_id {
                if interaction.last_processed_comment_id.as_deref() != Some(&last_id) {
                    if let Err(error) = self
                        .interaction_store
                        .update_last_processed_comment(&interaction.id, last_id)
                        .await
                    {
                        warn!(
                            interaction_id = %interaction.id,
                            error = %error,
                            "failed to update last processed comment cursor"
                        );
                    }
                }
            }
        }
    }

    async fn append_ignored_command(
        &self,
        interaction: &crate::interaction::model::InteractionRequest,
        command: Option<&str>,
        comment: &crate::tracker::model::TrackerComment,
        reason: &str,
    ) -> Option<crate::interaction::model::InteractionRequest> {
        match self
            .interaction_store
            .append_ignored_command(
                &interaction.id,
                IgnoredInteractionCommand {
                    command: command.map(ToString::to_string),
                    raw_body: comment.body.clone(),
                    author: comment.author.clone(),
                    comment_id: comment.comment_id.clone(),
                    received_at: comment.created_at.unwrap_or_else(Utc::now),
                    reason: reason.to_string(),
                },
            )
            .await
        {
            Ok(updated) => Some(updated),
            Err(error) => {
                warn!(
                    interaction_id = %interaction.id,
                    error = %error,
                    "failed to append ignored interaction command"
                );
                None
            }
        }
    }

    async fn repair_interaction_checkpoint(
        &self,
        interaction: &crate::interaction::model::InteractionRequest,
    ) -> bool {
        let journal_transaction = self
            .pipeline_journal
            .begin_issue_transition(&interaction.issue_id)
            .await;
        let latest_record = match journal_transaction.latest_record().await {
            Ok(Some(record)) => record,
            Ok(None) => return true,
            Err(error) => {
                warn!(
                    issue_id = %interaction.issue_id,
                    interaction_id = %interaction.id,
                    error = %error,
                    "cannot inspect the durable owner while repairing interaction checkpoint"
                );
                return false;
            }
        };
        if latest_record.cycle > interaction.pipeline_cycle {
            match self
                .interaction_store
                .retire_waiting_state(&interaction.id)
                .await
            {
                Ok((_, retired)) => {
                    self.reconcile_interaction_attention(&retired).await;
                    warn!(
                        issue_id = %interaction.issue_id,
                        interaction_id = %interaction.id,
                        interaction_cycle = interaction.pipeline_cycle,
                        durable_cycle = latest_record.cycle,
                        "retired stale interaction superseded by a newer pipeline cycle"
                    );
                }
                Err(error) => warn!(
                    issue_id = %interaction.issue_id,
                    interaction_id = %interaction.id,
                    interaction_cycle = interaction.pipeline_cycle,
                    durable_cycle = latest_record.cycle,
                    error = %error,
                    "failed to retire stale interaction superseded by a newer pipeline cycle"
                ),
            }
            return false;
        }
        let repair_matches_durable_predecessor = match interaction.resume_strategy {
            InteractionResumeStrategy::RerunStep => {
                matches!(
                    latest_record.kind,
                    PipelineTransitionKind::StepRunning | PipelineTransitionKind::StepLaunched
                ) && latest_record.cycle == interaction.pipeline_cycle
                    && latest_record.step.as_deref() == Some(interaction.step_name.as_str())
                    && interaction_id_from_resume_reason(latest_record.reason.as_deref()).is_none()
            }
            InteractionResumeStrategy::AdvanceAfterStep => {
                latest_record.kind == PipelineTransitionKind::StepAwaitingApproval
                    && latest_record.cycle == interaction.pipeline_cycle
                    && latest_record.step.as_deref() == Some(interaction.step_name.as_str())
                    && matches!(
                        latest_record
                            .snapshot
                            .as_ref()
                            .and_then(|snapshot| snapshot.step_states.get(&interaction.step_name)),
                        Some(StepState::AwaitingApproval {
                            interaction_request_id: None
                        })
                    )
            }
        };
        if !repair_matches_durable_predecessor {
            return true;
        }
        let transition = {
            let mut state = self.state.write().await;
            let Some(run) = state.get_pipeline_run_mut(&interaction.issue_id) else {
                return true;
            };
            let already_bound = match (
                &interaction.resume_strategy,
                run.step_states.get(&interaction.step_name),
            ) {
                (
                    InteractionResumeStrategy::RerunStep,
                    Some(StepState::BlockedOnHuman {
                        interaction_request_id,
                    }),
                ) => interaction_request_id == &interaction.id,
                (
                    InteractionResumeStrategy::AdvanceAfterStep,
                    Some(StepState::AwaitingApproval {
                        interaction_request_id,
                    }),
                ) => interaction_request_id.as_deref() == Some(interaction.id.as_str()),
                _ => false,
            };
            let kind = match interaction.resume_strategy {
                InteractionResumeStrategy::RerunStep => {
                    if !already_bound {
                        run.step_blocked_on_human(&interaction.step_name, interaction.id.clone());
                    }
                    PipelineTransitionKind::StepBlockedOnHuman
                }
                InteractionResumeStrategy::AdvanceAfterStep => {
                    if !matches!(
                        run.step_states.get(&interaction.step_name),
                        Some(StepState::AwaitingApproval { .. })
                    ) {
                        warn!(
                            issue_id = %interaction.issue_id,
                            interaction_id = %interaction.id,
                            step = %interaction.step_name,
                            "cannot reconstruct approval checkpoint from the durable pipeline state"
                        );
                        return false;
                    }
                    if !already_bound {
                        run.bind_approval_interaction(
                            &interaction.step_name,
                            interaction.id.clone(),
                        );
                    }
                    PipelineTransitionKind::StepAwaitingApproval
                }
            };
            Self::transition_input_for_run(
                &state,
                &interaction.issue_id,
                &interaction.issue_identifier,
                kind,
                Some(interaction.step_name.clone()),
                Some(interaction.id.clone()),
                None,
            )
        };

        let Some(transition) = transition else {
            return false;
        };
        let expected = transition.clone();
        if let Err(error) = journal_transaction.append(transition).await {
            match journal_transaction.latest_record_matches(&expected).await {
                Ok(true) => return true,
                Ok(false) => warn!(
                    issue_id = %interaction.issue_id,
                    interaction_id = %interaction.id,
                    error = %error,
                    "failed to persist reconstructed interaction checkpoint"
                ),
                Err(reconciliation_error) => warn!(
                    issue_id = %interaction.issue_id,
                    interaction_id = %interaction.id,
                    append_error = %error,
                    reconciliation_error = %reconciliation_error,
                    "reconstructed interaction checkpoint outcome is ambiguous"
                ),
            }

            return false;
        }
        true
    }

    async fn report_awaiting_interaction(&self, interaction: &InteractionRequest) -> bool {
        if interaction.status != InteractionStatus::Open || !interaction.awaiting_resume {
            return true;
        }
        let Some(reporter) = &self.attention_reporter else {
            return true;
        };
        let observation = match awaiting_interaction_observation(interaction) {
            Ok(observation) => observation,
            Err(error) => {
                warn!(interaction_id = %interaction.id, error = %error, "interaction could not be represented as operator attention");
                return false;
            }
        };
        if let Err(error) = reporter.upsert_open(observation).await {
            warn!(
                interaction_id = %interaction.id,
                error = %error,
                "failed to persist operator attention; startup reconciliation will retry"
            );
            return false;
        }
        true
    }

    async fn report_recovery_exhausted_attention(
        &self,
        issue_id: &str,
        identifier: &str,
        attempt: u32,
        reason: &str,
    ) -> bool {
        let Some(reporter) = &self.attention_reporter else {
            return true;
        };
        let observation: Result<AttentionUpsert, crate::attention::AttentionError> = (|| {
            Ok(AttentionUpsert::new(
                AttentionIdentity::new(
                    "runtime.scheduler",
                    issue_id,
                    "runtime.scheduler.recovery_exhausted",
                )?,
                AttentionPresentation::new(
                    format!("{identifier} exhausted automatic recovery"),
                    "Provide fresh evidence, then explicitly resume the retained run.",
                    vec![],
                )?,
                AttentionEvidence::new(format!("attempt:{attempt}:{reason}"))?,
            ))
        })();
        let Ok(observation) = observation else {
            return false;
        };
        if let Err(error) = reporter.upsert_open(observation).await {
            warn!(issue_id, error = %error, "failed to persist exhausted-recovery attention");
            return false;
        }
        true
    }

    /// Retry durable attention projection for retained runs without changing their ownership.
    async fn reconcile_parked_recovery_attention(&self) {
        let parked = {
            let state = self.state.read().await;
            state.parked_runs.values().cloned().collect::<Vec<_>>()
        };
        for entry in parked {
            self.report_recovery_exhausted_attention(
                &entry.issue_id,
                &entry.identifier,
                entry.attempt,
                &entry.reason,
            )
            .await;
        }
    }

    async fn reconcile_interaction_attention(&self, interaction: &InteractionRequest) -> bool {
        if interaction.status == InteractionStatus::Open {
            return self.report_awaiting_interaction(interaction).await;
        }
        let Some(reporter) = &self.attention_reporter else {
            return true;
        };
        let identity = match interaction_attention_identity(interaction) {
            Ok(identity) => identity,
            Err(error) => {
                warn!(interaction_id = %interaction.id, error = %error, "interaction could not be reconciled as operator attention");
                return false;
            }
        };
        let open_item = match reporter.open_item(&identity).await {
            Ok(item) => item,
            Err(error) => {
                warn!(interaction_id = %interaction.id, error = %error, "failed to read operator attention during reconciliation");
                return false;
            }
        };
        let Some(open_item) = open_item else {
            return true;
        };
        let close = match interaction_attention_close_from_open(&open_item, interaction) {
            Ok(Some(close)) => close,
            Ok(None) => return true,
            Err(error) => {
                warn!(interaction_id = %interaction.id, error = %error, "failed to derive operator attention close during reconciliation");
                return false;
            }
        };
        if let Err(error) = reporter.resolve(close).await {
            warn!(
                interaction_id = %interaction.id,
                error = %error,
                "failed to reconcile resolved operator attention; startup reconciliation will retry"
            );
            return false;
        }
        true
    }

    async fn reconcile_unbound_approval_checkpoints(&self) {
        let interactions = match self.interaction_store.list_all().await {
            Ok(interactions) => interactions,
            Err(error) => {
                warn!(error = %error, "failed to inspect interactions while reconciling unbound approvals");
                return;
            }
        };
        let existing = interactions
            .into_iter()
            .filter(|interaction| interaction.blocking && interaction.awaiting_resume)
            .map(|interaction| {
                (
                    interaction.issue_id,
                    interaction.pipeline_cycle,
                    interaction.step_name,
                )
            })
            .collect::<HashSet<_>>();
        let candidates = {
            let state = self.state.read().await;
            state
                .pipeline_runs
                .iter()
                .flat_map(|(issue_id, run)| {
                    run.step_states
                        .iter()
                        .filter(|(_, step_state)| {
                            matches!(
                                step_state,
                                StepState::AwaitingApproval {
                                    interaction_request_id: None
                                }
                            )
                        })
                        .map(|(step_name, _)| (issue_id.clone(), run.cycle, step_name.clone()))
                })
                .filter(|candidate| !existing.contains(candidate))
                .collect::<Vec<_>>()
        };
        if candidates.is_empty() {
            return;
        }
        let issue_ids = candidates
            .iter()
            .map(|(issue_id, _, _)| issue_id.clone())
            .collect::<Vec<_>>();
        let issues = match self.tracker.fetch_issue_states_by_ids(&issue_ids).await {
            Ok(issues) => issues
                .into_iter()
                .map(|issue| (issue.id.clone(), issue))
                .collect::<HashMap<_, _>>(),
            Err(error) => {
                warn!(error = %error, "failed to load issues while reconciling unbound approvals");
                return;
            }
        };
        for (issue_id, _, step_name) in candidates {
            let Some(issue) = issues.get(&issue_id) else {
                warn!(issue_id, step = %step_name, "cannot reconcile unbound approval without its issue snapshot");
                continue;
            };
            if let Err(error) = self
                .handle_post_step_approval(&issue_id, &step_name, None, None, Some(issue))
                .await
            {
                warn!(issue_id, step = %step_name, error = %error, "failed to reconcile unbound approval checkpoint");
            }
        }
    }

    async fn hydrate_waiting_on_human_from_store(&self) {
        self.reconcile_unbound_approval_checkpoints().await;
        let reconcile_all = !self.attention_reconciled_on_startup.load(Ordering::Acquire);
        let mut interactions = match if reconcile_all {
            self.interaction_store.list_all().await
        } else {
            self.interaction_store.list_awaiting_resume().await
        } {
            Ok(interactions) => interactions,
            Err(error) => {
                warn!(error = %error, "failed to hydrate waiting interactions from store");
                return;
            }
        };
        let mut attention_reconciled = true;
        for interaction in &interactions {
            attention_reconciled &= self.reconcile_interaction_attention(interaction).await;
        }
        if reconcile_all && attention_reconciled {
            self.attention_reconciled_on_startup
                .store(true, Ordering::Release);
        }
        interactions.retain(|interaction| interaction.blocking && interaction.awaiting_resume);
        interactions.sort_by_key(|interaction| interaction.requested_at);
        if !interactions.is_empty() {
            let live_records = match self.pipeline_journal.latest_live_records().await {
                Ok(records) => records
                    .into_iter()
                    .map(|record| (record.issue_id.clone(), record))
                    .collect::<HashMap<_, _>>(),
                Err(error) => {
                    warn!(
                        error = %error,
                        "failed to reconcile waiting interactions with pipeline journal"
                    );
                    HashMap::new()
                }
            };
            let mut retained = Vec::with_capacity(interactions.len());
            for interaction in interactions {
                let step_dispatch_was_reserved = live_records
                    .get(&interaction.issue_id)
                    .is_some_and(|record| {
                        matches!(
                            record.kind,
                            PipelineTransitionKind::StepRunning
                                | PipelineTransitionKind::StepLaunched
                        ) && interaction.status == InteractionStatus::Resolved
                            && interaction_id_from_resume_reason(record.reason.as_deref())
                                == Some(interaction.id.as_str())
                    })
                    && self
                        .state
                        .read()
                        .await
                        .get_pipeline_run(&interaction.issue_id)
                        .and_then(|run| run.step_states.get(&interaction.step_name))
                        .is_some_and(|step_state| matches!(step_state, StepState::Running { .. }));
                if step_dispatch_was_reserved {
                    match self
                        .interaction_store
                        .retire_waiting_state(&interaction.id)
                        .await
                    {
                        Ok((_, retired)) => {
                            self.reconcile_interaction_attention(&retired).await;
                            let mut state = self.state.write().await;
                            state.remove_waiting_on_human(&interaction.issue_id);
                            state.clear_resume_request(&interaction.issue_id);
                            continue;
                        }
                        Err(error) => {
                            warn!(
                                issue_id = %interaction.issue_id,
                                interaction_id = %interaction.id,
                                error = %error,
                                "failed to reconcile interaction after durable step dispatch"
                            );
                            continue;
                        }
                    }
                }
                let superseded_by_later_approval = interaction.status
                    == InteractionStatus::Resolved
                    && live_records
                        .get(&interaction.issue_id)
                        .is_some_and(|record| {
                            record.kind == PipelineTransitionKind::StepAwaitingApproval
                                && record.cycle == interaction.pipeline_cycle
                                && record.step.as_deref() != Some(interaction.step_name.as_str())
                                && record.step.as_ref().is_some_and(|step_name| {
                                    record.snapshot.as_ref().is_some_and(|snapshot| {
                                        matches!(
                                            snapshot.step_states.get(step_name),
                                            Some(StepState::AwaitingApproval { .. })
                                        )
                                    })
                                })
                        });
                let interaction_step_is_gate = self
                    .state
                    .read()
                    .await
                    .get_pipeline_run(&interaction.issue_id)
                    .and_then(|run| run.step(&interaction.step_name))
                    .is_some_and(|step| step.kind == StepKind::Gate);
                let resolved_gate_disposition_is_durable = interaction.status
                    == InteractionStatus::Resolved
                    && interaction.resume_strategy == InteractionResumeStrategy::AdvanceAfterStep
                    && interaction_step_is_gate
                    && live_records
                        .get(&interaction.issue_id)
                        .is_some_and(|record| {
                            record.step.as_deref() == Some(interaction.step_name.as_str())
                                && matches!(
                                    record.kind,
                                    PipelineTransitionKind::StepRetryScheduled
                                        | PipelineTransitionKind::PipelineHalted
                                        | PipelineTransitionKind::RunParked
                                        | PipelineTransitionKind::PendingTerminalTransition
                                )
                                && record.cycle >= interaction.pipeline_cycle
                        });
                if superseded_by_later_approval || resolved_gate_disposition_is_durable {
                    match self
                        .interaction_store
                        .retire_waiting_state(&interaction.id)
                        .await
                    {
                        Ok((_, retired)) => {
                            self.reconcile_interaction_attention(&retired).await;
                            continue;
                        }
                        Err(error) => {
                            warn!(
                                issue_id = %interaction.issue_id,
                                interaction_id = %interaction.id,
                                error = %error,
                                "failed to retire interaction superseded by a later pipeline checkpoint"
                            );
                            continue;
                        }
                    }
                }
                if !self.repair_interaction_checkpoint(&interaction).await {
                    continue;
                }
                retained.push(interaction);
            }
            interactions = retained;
        }
        {
            let state = self.state.read().await;
            interactions.retain(|interaction| {
                !state.is_running(&interaction.issue_id)
                    && !state.is_waiting_on_human(&interaction.issue_id)
                    && !state.delivery.contains_key(&interaction.issue_id)
                    && !state
                        .pending_terminal_transitions
                        .contains_key(&interaction.issue_id)
            });
        }

        let issue_ids = interactions
            .iter()
            .map(|interaction| interaction.issue_id.clone())
            .collect::<Vec<_>>();
        let issues_by_id = if issue_ids.is_empty() {
            HashMap::new()
        } else {
            self.tracker
                .fetch_issue_states_by_ids(&issue_ids)
                .await
                .map(|issues| {
                    issues
                        .into_iter()
                        .map(|issue| (issue.id.clone(), issue))
                        .collect::<HashMap<_, _>>()
                })
                .unwrap_or_default()
        };

        let mut state = self.state.write().await;
        for interaction in interactions {
            if state.is_running(&interaction.issue_id)
                || state.is_waiting_on_human(&interaction.issue_id)
                || state.delivery.contains_key(&interaction.issue_id)
                || state
                    .pending_terminal_transitions
                    .contains_key(&interaction.issue_id)
            {
                continue;
            }

            state.add_waiting_on_human(WaitingOnHumanEntry {
                issue_id: interaction.issue_id.clone(),
                identifier: interaction.issue_identifier.clone(),
                interaction_request_id: interaction.id.clone(),
                step_name: interaction.step_name.clone(),
                kind: interaction.kind.clone(),
                prompt: interaction.title.clone(),
                agent_name: interaction.agent_name.clone(),
                retry_attempt: Some(interaction.pipeline_cycle.max(1)),
                started_at: interaction.waiting_started_at,
                agent_input_tokens: interaction.agent_input_tokens,
                agent_output_tokens: interaction.agent_output_tokens,
                agent_total_tokens: interaction.agent_total_tokens,
                requested_at: interaction.requested_at,
                run_id: None,
                issue: issues_by_id.get(&interaction.issue_id).cloned(),
            });
        }
    }

    async fn restore_pipeline_runs_from_journal(&self) {
        if self.pipeline_journal_restored.load(Ordering::Acquire) {
            return;
        }

        let records = match self.pipeline_journal.latest_live_records().await {
            Ok(records) => records,
            Err(error) => {
                warn!(
                    error = %error,
                    "failed to read pipeline transition journal during startup"
                );
                return;
            }
        };

        if records.is_empty() {
            self.pipeline_journal_restored
                .store(true, Ordering::Release);
            return;
        }

        let config_snapshot = {
            let config = self.config.read().await;
            Arc::new(config.clone())
        };

        let issue_ids = records
            .iter()
            .map(|record| record.issue_id.clone())
            .collect::<Vec<_>>();
        let issues = self
            .tracker
            .fetch_issue_states_by_ids(&issue_ids)
            .await
            .unwrap_or_default();
        let issues_by_id: HashMap<String, Issue> = issues
            .into_iter()
            .map(|issue| (issue.id.clone(), issue))
            .collect();

        let mut restored_all = true;
        for record in records {
            if let Err(error) = self
                .restore_pipeline_run_record(&record, Arc::clone(&config_snapshot), &issues_by_id)
                .await
            {
                restored_all = false;
                warn!(
                    issue_id = %record.issue_id,
                    error = %error,
                    "failed to restore pipeline run from transition journal"
                );
            }
        }
        if restored_all {
            self.pipeline_journal_restored
                .store(true, Ordering::Release);
        }
    }

    async fn restore_pipeline_run_record(
        &self,
        record: &PipelineTransitionRecord,
        config_snapshot: Arc<EnsembleConfig>,
        issues_by_id: &HashMap<String, Issue>,
    ) -> Result<(), EnsembleError> {
        if let Some(delivery) = record.delivery.clone() {
            let mut state = self.state.write().await;
            if state.delivery.contains_key(&record.issue_id) {
                return Ok(());
            }
            let finalize = Self::finalize_state_from_delivery(&delivery);
            state.add_claimed(&record.issue_id);
            state
                .issue_run_ids
                .insert(record.issue_id.clone(), delivery.run_id.clone());
            state.set_finalize_state(&record.issue_id, finalize);
            state.delivery.insert(record.issue_id.clone(), *delivery);
            return Ok(());
        }
        let snapshot = record
            .snapshot
            .clone()
            .ok_or_else(|| AgentError::PromptError {
                reason: format!(
                    "pipeline journal record {} for issue '{}' has no snapshot",
                    record.seq, record.issue_id
                ),
            })?;

        let config_snapshot = if let Some(selected) = snapshot.selected_workflow.as_ref() {
            let effective = config_snapshot.resolve_selected_workflow(
                &selected.rule,
                &selected.pipeline,
                &selected.lane,
            )?;
            Arc::new(effective)
        } else {
            config_snapshot
        };

        let is_pending_terminal = record.terminal_transition.is_some();
        if !is_pending_terminal {
            validate_restored_snapshot_against_config(&snapshot, &config_snapshot)?;
        }
        let mut run = PipelineRun::from_snapshot(snapshot)?;
        if !is_pending_terminal {
            run.normalize_stale_running_steps();
        }
        {
            let state = self.state.read().await;
            if state.get_pipeline_run(&record.issue_id).is_some()
                || state.is_running(&record.issue_id)
            {
                return Ok(());
            }
        }
        let restored_timeline_sequence = if is_pending_terminal {
            None
        } else if let Some(run_id) = &record.run_id {
            let history_store = self.history_store.as_ref().ok_or_else(|| {
                AgentError::DurableSequenceUnavailable {
                    run_id: run_id.clone(),
                    reason: "history store is unavailable".to_string(),
                }
            })?;
            Some(
                history_store
                    .max_timeline_sequence(run_id)
                    .await
                    .map_err(|error| AgentError::DurableSequenceUnavailable {
                        run_id: run_id.clone(),
                        reason: error.to_string(),
                    })?
                    .unwrap_or(0),
            )
        } else {
            None
        };

        let mut state = self.state.write().await;
        if state.get_pipeline_run(&record.issue_id).is_some() || state.is_running(&record.issue_id)
        {
            return Ok(());
        }

        if is_pending_terminal {
            state.insert_terminal_pipeline_run(&record.issue_id, run);
        } else {
            state.insert_pipeline_run(&record.issue_id, run, Arc::clone(&config_snapshot));
        }
        state.add_claimed(&record.issue_id);
        if let Some(run_id) = record.run_id.clone() {
            if let Some(maximum) = restored_timeline_sequence {
                state.seed_timeline_sequence(&run_id, maximum);
            }
            state.issue_run_ids.insert(record.issue_id.clone(), run_id);
        }

        if let Some(transition) = record.terminal_transition.clone() {
            state.pending_terminal_transitions.insert(
                record.issue_id.clone(),
                PendingTerminalEntry {
                    identifier: record.identifier.clone(),
                    run_id: record.run_id.clone(),
                    issue: Some(
                        issues_by_id
                            .get(&record.issue_id)
                            .cloned()
                            .unwrap_or_else(|| {
                                Self::terminal_issue_placeholder(
                                    &record.issue_id,
                                    &record.identifier,
                                    &transition.target_state,
                                )
                            }),
                    ),
                    transition,
                },
            );
        }

        if let Some(retry) = record.retry.clone() {
            state.add_retry(retry);
        }

        if record.kind == PipelineTransitionKind::PipelineHalted {
            let step_name = record.step.clone().unwrap_or_default();
            let agent_name = state
                .get_pipeline_run(&record.issue_id)
                .and_then(|run| run.step(&step_name))
                .map(|step| step.agent.clone())
                .unwrap_or_default();
            state.add_waiting_on_human(WaitingOnHumanEntry {
                issue_id: record.issue_id.clone(),
                identifier: record.identifier.clone(),
                interaction_request_id: format!("halted:{}:{step_name}", record.issue_id),
                step_name,
                kind: InteractionKind::Handoff,
                prompt: record
                    .reason
                    .clone()
                    .unwrap_or_else(|| "pipeline halted".to_string()),
                agent_name,
                retry_attempt: Some(record.cycle.max(1)),
                started_at: None,
                agent_input_tokens: 0,
                agent_output_tokens: 0,
                agent_total_tokens: 0,
                requested_at: record.written_at,
                run_id: record.run_id.clone(),
                issue: issues_by_id.get(&record.issue_id).cloned(),
            });
        }

        if record.kind == PipelineTransitionKind::RunParked {
            state
                .parked_runs
                .entry(record.issue_id.clone())
                .or_insert_with(|| ParkedRunEntry {
                    issue_id: record.issue_id.clone(),
                    identifier: record.identifier.clone(),
                    condition_key: "runtime.scheduler.recovery_exhausted".to_string(),
                    attempt: record.cycle.max(1),
                    reason: record
                        .reason
                        .clone()
                        .unwrap_or_else(|| "automatic recovery exhausted".to_string()),
                    parked_at: record.written_at,
                });
        }

        Ok(())
    }

    async fn current_config_for_snapshot(
        &self,
        snapshot: Option<&PipelineRunSnapshot>,
    ) -> Result<Arc<EnsembleConfig>, EnsembleError> {
        let config = self.config.read().await;
        let Some(selected) = snapshot.and_then(|snapshot| snapshot.selected_workflow.as_ref())
        else {
            return Ok(Arc::new(config.clone()));
        };
        let effective =
            config.resolve_selected_workflow(&selected.rule, &selected.pipeline, &selected.lane)?;
        Ok(Arc::new(effective))
    }

    async fn append_pipeline_transition(&self, input: PipelineTransitionInput) {
        if let Err(error) = self.pipeline_journal.append(input).await {
            warn!(
                error = %error,
                "failed to append pipeline transition journal record"
            );
        }
    }

    fn sort_route_events(run: &PipelineRun, events: &mut [RouteSelectionEvent]) {
        let positions = run
            .to_snapshot()
            .dag_steps
            .into_iter()
            .enumerate()
            .map(|(position, step)| (step.name, position))
            .collect::<HashMap<_, _>>();
        events.sort_by(|left, right| {
            positions
                .get(&left.route_step)
                .copied()
                .unwrap_or(usize::MAX)
                .cmp(
                    &positions
                        .get(&right.route_step)
                        .copied()
                        .unwrap_or(usize::MAX),
                )
                .then_with(|| left.route_step.cmp(&right.route_step))
        });
        for event in events {
            event.skipped_steps.sort_by(|left, right| {
                positions
                    .get(left)
                    .copied()
                    .unwrap_or(usize::MAX)
                    .cmp(&positions.get(right).copied().unwrap_or(usize::MAX))
                    .then_with(|| left.cmp(right))
            });
        }
    }

    fn route_transition_inputs(
        state: &OrchestratorState,
        issue_id: &str,
        identifier: &str,
        previous_run: &PipelineRun,
        candidate_run: &PipelineRun,
        events: &[RouteSelectionEvent],
    ) -> Vec<PipelineTransitionInput> {
        events
            .iter()
            .enumerate()
            .filter_map(|(index, event)| {
                let snapshot = if index + 1 == events.len() {
                    candidate_run
                } else {
                    previous_run
                };
                Self::transition_input_for_snapshot(
                    state,
                    snapshot,
                    PipelineTransitionTarget {
                        issue_id,
                        identifier,
                    },
                    PipelineTransitionKind::RouteSelected,
                    Some(event.route_step.clone()),
                    Some(format!(
                        "source={} pointer={} selected_case={} source_output_digest={}",
                        event.decision.source_step,
                        event.decision.pointer,
                        event.decision.selected_case,
                        event.decision.source_output_digest,
                    )),
                    None,
                )
            })
            .collect()
    }

    async fn publish_route_candidate(
        &self,
        issue_id: &str,
        candidate: Option<PipelineRun>,
        previous_snapshot: Option<&PipelineRunSnapshot>,
    ) -> bool {
        let Some(candidate) = candidate else {
            return true;
        };
        let Some(previous_snapshot) = previous_snapshot else {
            return false;
        };
        let mut state = self.state.write().await;
        let is_current = state
            .get_pipeline_run(issue_id)
            .is_some_and(|run| run.to_snapshot() == *previous_snapshot);
        if !is_current {
            warn!(
                issue_id,
                "route persistence candidate lost its live run owner"
            );
            return false;
        }
        state.pipeline_runs.insert(issue_id.to_string(), candidate);
        true
    }

    async fn recover_unpublished_route_candidate(&self, issue_id: &str, source_step: &str) {
        let reason = format!(
            "route persistence candidate lost its live owner; retry source step '{source_step}'"
        );
        self.handle_pipeline_step_failure(issue_id, source_step, reason, false)
            .await;
    }

    /// Makes a fully journaled approval route candidate eligible for ordinary tick dispatch.
    ///
    /// Route selection is the commit point for an approval continuation. In particular, do not
    /// put the run back behind the approval checkpoint if later capacity, workspace, or launch
    /// work cannot proceed: that would make live state disagree with the final RouteSelected
    /// record. Retiring the interaction here also prevents a later retry from reprocessing the
    /// already committed approval.
    async fn activate_published_approval_route_candidate(
        &self,
        issue: &Issue,
        interaction: &InteractionRequest,
        fallback_attempt: u32,
        source_step: &str,
    ) -> Result<u32, EnsembleError> {
        let attempt = {
            let mut state = self.state.write().await;
            let attempt = state
                .get_pipeline_run(&issue.id)
                .map(|run| run.cycle)
                .unwrap_or(fallback_attempt.max(1));
            state.add_running(issue, Some(attempt));
            attempt
        };

        let retired = match self
            .interaction_store
            .retire_waiting_state(&interaction.id)
            .await
        {
            Ok((_, retired)) => retired,
            Err(error) => {
                self.handle_pipeline_step_failure(
                    &issue.id,
                    source_step,
                    format!(
                        "failed to retire committed approval interaction '{}': {error}",
                        interaction.id
                    ),
                    false,
                )
                .await;
                return Err(error.into());
            }
        };
        self.reconcile_interaction_attention(&retired).await;
        let mut state = self.state.write().await;
        state.remove_waiting_on_human(&issue.id);
        state.clear_resume_request(&issue.id);
        Ok(attempt)
    }

    async fn restore_route_persistence_checkpoint(
        &self,
        issue_id: &str,
        checkpoint: Option<&PipelineTransitionInput>,
    ) {
        let Some(snapshot) = checkpoint.and_then(|checkpoint| checkpoint.snapshot.clone()) else {
            return;
        };
        let run = match PipelineRun::from_snapshot(snapshot) {
            Ok(run) => run,
            Err(error) => {
                warn!(issue_id, error = %error, "failed to restore route persistence checkpoint");
                return;
            }
        };
        self.state
            .write()
            .await
            .pipeline_runs
            .insert(issue_id.to_string(), run);
    }

    async fn append_successful_step_and_routes(
        &self,
        step_transition: Option<PipelineTransitionInput>,
        transitions: Vec<PipelineTransitionInput>,
        issue: Option<&Issue>,
        events: Vec<RouteSelectionEvent>,
        contexts: Vec<(Option<String>, Option<u64>, u32)>,
        recovery_checkpoint: Option<&PipelineTransitionInput>,
    ) -> Result<(), std::io::Error> {
        // A completed source Step must be durable before its Route transitions.
        // Non-route completions retain the journal's existing best-effort
        // behavior so a transient journal failure cannot strand terminal intent.
        if transitions.is_empty() {
            if let Some(transition) = step_transition {
                self.append_pipeline_transition(transition).await;
            }
            return Ok(());
        }

        let issue_id = step_transition
            .as_ref()
            .or_else(|| transitions.first())
            .map(|transition| transition.issue_id.as_str())
            .ok_or_else(|| std::io::Error::other("route transition has no issue identity"))?;
        let transaction = self.pipeline_journal.begin_issue_transition(issue_id).await;
        if let Some(transition) = step_transition {
            if let Err(error) = transaction.append(transition.clone()).await {
                if !transaction
                    .latest_record_matches(&transition)
                    .await
                    .unwrap_or(false)
                {
                    return Err(error);
                }
            }
        }
        for transition in transitions {
            if let Err(error) = transaction.append(transition.clone()).await {
                if !transaction
                    .latest_record_matches(&transition)
                    .await
                    .unwrap_or(false)
                {
                    if let Some(checkpoint) = recovery_checkpoint {
                        transaction.append(checkpoint.clone()).await?;
                    }
                    return Err(error);
                }
            }
        }

        let Some(issue) = issue else {
            return Ok(());
        };
        let mut contexts = contexts.into_iter();
        for event in events {
            let Some((run_id, sequence, attempt)) = contexts.next() else {
                return Ok(());
            };
            self.publish_pipeline_event(
                run_id,
                sequence,
                attempt,
                PipelineEvent::RouteSelected {
                    issue_identifier: issue.identifier.clone(),
                    timestamp: Utc::now(),
                    step_name: event.route_step.clone(),
                    selected_case: event.decision.selected_case.clone(),
                    detail: format!(
                        "route source '{}' at '{}' (digest {})",
                        event.decision.source_step,
                        event.decision.pointer,
                        event.decision.source_output_digest,
                    ),
                },
            )
            .await;
            for skipped_step in event.skipped_steps {
                let Some((run_id, sequence, attempt)) = contexts.next() else {
                    return Ok(());
                };
                self.publish_pipeline_event(
                    run_id,
                    sequence,
                    attempt,
                    PipelineEvent::StepSkipped {
                        issue_identifier: issue.identifier.clone(),
                        timestamp: Utc::now(),
                        step_name: skipped_step,
                        detail: format!(
                            "skipped by route '{}' selecting '{}'",
                            event.route_step, event.decision.selected_case,
                        ),
                    },
                )
                .await;
            }
        }
        Ok(())
    }

    // The terminal transition serializes the full durable run snapshot. Keep it out of the
    // worker-exit future, which now also owns artifact snapshot state.
    fn begin_terminal_transition<'a>(
        &'a self,
        issue: &'a Issue,
        outcome: TerminalOutcome,
        target_state: String,
        history_record: Option<HistoryRecord>,
    ) -> Pin<Box<dyn Future<Output = ()> + Send + 'a>> {
        Box::pin(self.begin_terminal_transition_inner(issue, outcome, target_state, history_record))
    }

    async fn begin_terminal_transition_inner(
        &self,
        issue: &Issue,
        outcome: TerminalOutcome,
        target_state: String,
        history_record: Option<HistoryRecord>,
    ) {
        self.begin_terminal_transition_for_identity(
            &issue.id,
            &issue.identifier,
            Some(issue.clone()),
            outcome,
            target_state,
            history_record,
        )
        .await;
    }

    async fn persist_terminal_transition(
        &self,
        issue_id: &str,
        identifier: &str,
        outcome: TerminalOutcome,
        target_state: String,
        history_record: Option<HistoryRecord>,
        tracker_write_confirmed: bool,
    ) -> Option<PendingTerminalTransition> {
        let existing_record = self
            .pipeline_journal
            .latest_live_record_for_issue(issue_id)
            .await
            .ok()
            .flatten();
        let current = {
            let state = self.state.read().await;
            state.get_pipeline_run(issue_id).map(|run| {
                let run_id = state
                    .running
                    .get(issue_id)
                    .and_then(|entry| entry.run_id.clone())
                    .or_else(|| {
                        state
                            .waiting_on_human
                            .get(issue_id)
                            .and_then(|entry| entry.run_id.clone())
                    })
                    .or_else(|| state.issue_run_ids.get(issue_id).cloned());
                (run.to_snapshot(), run.cycle, run_id)
            })
        };
        let current = match current {
            Some(current) => Some(current),
            None => existing_record.as_ref().and_then(|record| {
                record
                    .snapshot
                    .clone()
                    .map(|snapshot| (snapshot, record.cycle, record.run_id.clone()))
            }),
        };
        let Some((snapshot, cycle, run_id)) = current else {
            warn!(
                issue_id = %issue_id,
                "cannot persist terminal transition intent without pipeline snapshot"
            );
            return None;
        };
        let existing_transition = existing_record
            .filter(|record| record.run_id == run_id)
            .and_then(|record| record.terminal_transition)
            .filter(|transition| {
                transition.target_state == target_state && transition.outcome == outcome
            });
        let mut transition = existing_transition
            .clone()
            .unwrap_or(PendingTerminalTransition {
                target_state,
                outcome,
                attempt: 0,
                last_error: None,
                last_attempted_at: None,
                tracker_write_confirmed: false,
                history_record: None,
            });
        if history_record.is_some() {
            transition.history_record = history_record;
        }
        if tracker_write_confirmed {
            transition.confirm_tracker_write();
        }
        let input = PipelineTransitionInput {
            kind: if transition.tracker_write_confirmed {
                PipelineTransitionKind::TerminalTransitionApplied
            } else {
                PipelineTransitionKind::PendingTerminalTransition
            },
            issue_id: issue_id.to_string(),
            identifier: identifier.to_string(),
            run_id,
            cycle,
            step: None,
            reason: None,
            retry: None,
            snapshot: Some(snapshot),
            terminal_transition: Some(transition.clone()),
            delivery: None,
        };

        if let Err(error) = self.pipeline_journal.append(input).await {
            warn!(
                issue_id = %issue_id,
                error = %error,
                "failed to persist terminal transition intent"
            );
            return (!tracker_write_confirmed).then_some(transition);
        }
        Some(transition)
    }

    async fn begin_terminal_transition_for_identity(
        &self,
        issue_id: &str,
        identifier: &str,
        issue: Option<Issue>,
        outcome: TerminalOutcome,
        target_state: String,
        history_record: Option<HistoryRecord>,
    ) {
        let Some(transition) = self
            .persist_terminal_transition(
                issue_id,
                identifier,
                outcome,
                target_state,
                history_record,
                false,
            )
            .await
        else {
            return;
        };

        self.begin_persisted_terminal_transition(issue_id, identifier, issue, transition)
            .await;
    }

    async fn begin_confirmed_terminal_transition_for_identity(
        &self,
        issue_id: &str,
        identifier: &str,
        issue: Option<Issue>,
        outcome: TerminalOutcome,
        target_state: String,
        history_record: Option<HistoryRecord>,
    ) {
        let Some(transition) = self
            .persist_terminal_transition(
                issue_id,
                identifier,
                outcome,
                target_state,
                history_record,
                true,
            )
            .await
        else {
            return;
        };

        self.begin_persisted_terminal_transition(issue_id, identifier, issue, transition)
            .await;
    }

    async fn begin_persisted_terminal_transition(
        &self,
        issue_id: &str,
        identifier: &str,
        issue: Option<Issue>,
        transition: PendingTerminalTransition,
    ) {
        let issue = Some(issue.unwrap_or_else(|| {
            Self::terminal_issue_placeholder(issue_id, identifier, &transition.target_state)
        }));
        let restored_run = {
            let state = self.state.read().await;
            if state.get_pipeline_run(issue_id).is_some() {
                None
            } else {
                drop(state);
                self.pipeline_journal
                    .latest_live_record_for_issue(issue_id)
                    .await
                    .ok()
                    .flatten()
                    .and_then(|record| {
                        let run_id = record.run_id;
                        record
                            .snapshot
                            .and_then(|snapshot| PipelineRun::from_snapshot(snapshot).ok())
                            .map(|run| (run, run_id))
                    })
            }
        };
        {
            let mut state = self.state.write().await;
            if state.get_pipeline_run(issue_id).is_none() {
                if let Some((run, run_id)) = restored_run {
                    if let Some(run_id) = run_id {
                        state.issue_run_ids.insert(issue_id.to_string(), run_id);
                    }
                    state.insert_terminal_pipeline_run(issue_id, run);
                }
            }
            let run_id = state
                .running
                .get(issue_id)
                .and_then(|entry| entry.run_id.clone())
                .or_else(|| {
                    state
                        .waiting_on_human
                        .get(issue_id)
                        .and_then(|entry| entry.run_id.clone())
                })
                .or_else(|| state.issue_run_ids.get(issue_id).cloned());

            if let Some(entry) = state.remove_running(issue_id) {
                state.add_runtime_seconds(&entry);
            }
            state.add_claimed(issue_id);
            state.pending_terminal_transitions.insert(
                issue_id.to_string(),
                PendingTerminalEntry {
                    identifier: identifier.to_string(),
                    run_id: run_id.clone(),
                    issue,
                    transition,
                },
            );
        }

        self.reconcile_pending_terminal_transition(issue_id).await;
    }

    async fn reconcile_pending_terminal_transitions(&self) {
        let issue_ids = {
            let state = self.state.read().await;
            state
                .pending_terminal_transitions
                .keys()
                .cloned()
                .collect::<Vec<_>>()
        };

        for issue_id in issue_ids {
            self.reconcile_pending_terminal_transition(&issue_id).await;
        }
    }

    async fn reconcile_pending_terminal_transition(&self, issue_id: &str) {
        let (pending, input) = {
            let state = self.state.read().await;
            let Some(pending) = state.pending_terminal_transitions.get(issue_id).cloned() else {
                return;
            };
            let Some(input) = Self::pending_terminal_transition_input(
                &state,
                issue_id,
                &pending,
                PipelineTransitionKind::PendingTerminalTransition,
            ) else {
                warn!(
                    issue_id = %issue_id,
                    "pending terminal transition has no recoverable pipeline snapshot"
                );
                return;
            };
            (pending, input)
        };

        if pending.transition.tracker_write_confirmed {
            let max_backoff_ms = self.config.read().await.agent.max_retry_backoff_ms;
            if !terminal_transition_retry_due(&pending.transition, max_backoff_ms, Utc::now()) {
                return;
            }
            self.complete_pending_terminal_transition(issue_id, pending.run_id)
                .await;
            return;
        }

        if let Err(error) = self.pipeline_journal.append(input).await {
            warn!(
                issue_id = %issue_id,
                error = %error,
                "failed to persist pending terminal transition before tracker write"
            );
            return;
        }

        if !self.tracker.supports_writes() {
            self.confirm_pending_terminal_transition(issue_id, &pending)
                .await;
            return;
        }

        match self
            .tracker
            .set_issue_state(issue_id, &pending.transition.target_state)
            .await
        {
            Ok(()) => {
                self.confirm_pending_terminal_transition(issue_id, &pending)
                    .await;
            }
            Err(error) => {
                self.record_pending_terminal_transition_failure(
                    issue_id,
                    &pending,
                    error.to_string(),
                )
                .await;
                warn!(
                    issue_id = %issue_id,
                    target_state = %pending.transition.target_state,
                    error = %error,
                    "terminal tracker transition remains pending"
                );
            }
        }
    }

    async fn confirm_pending_terminal_transition(
        &self,
        issue_id: &str,
        expected: &PendingTerminalEntry,
    ) {
        let input = {
            let state = self.state.read().await;
            let Some(current) = state.pending_terminal_transitions.get(issue_id) else {
                return;
            };
            if current.run_id != expected.run_id
                || current.transition.target_state != expected.transition.target_state
                || current.transition.outcome != expected.transition.outcome
            {
                return;
            }

            let mut confirmed = current.clone();
            confirmed.transition.confirm_tracker_write();
            let Some(input) = Self::pending_terminal_transition_input(
                &state,
                issue_id,
                &confirmed,
                PipelineTransitionKind::TerminalTransitionApplied,
            ) else {
                return;
            };
            input
        };

        if let Err(error) = self.pipeline_journal.append(input).await {
            warn!(
                issue_id = %issue_id,
                error = %error,
                "failed to persist confirmed terminal tracker transition"
            );
            return;
        }

        {
            let mut state = self.state.write().await;
            let Some(current) = state.pending_terminal_transitions.get_mut(issue_id) else {
                return;
            };
            if current.run_id != expected.run_id
                || current.transition.target_state != expected.transition.target_state
                || current.transition.outcome != expected.transition.outcome
            {
                return;
            }
            current.transition.confirm_tracker_write();
        }

        self.complete_pending_terminal_transition(issue_id, expected.run_id.clone())
            .await;
    }

    // Box this lifecycle boundary so the already-large tick future does not embed workspace
    // cleanup's state machine and overflow Tokio's worker stack on terminal failure paths.
    fn complete_pending_terminal_transition<'a>(
        &'a self,
        issue_id: &'a str,
        expected_run_id: Option<String>,
    ) -> Pin<Box<dyn Future<Output = ()> + Send + 'a>> {
        Box::pin(async move {
            let pending = {
                let state = self.state.read().await;
                let Some(pending) = state.pending_terminal_transitions.get(issue_id).cloned()
                else {
                    return;
                };
                if pending.run_id != expected_run_id {
                    return;
                }
                if !pending.transition.tracker_write_confirmed {
                    return;
                }
                pending
            };

            if let Err(error) = self
                .clear_terminal_interaction_waiting_state(issue_id)
                .await
            {
                self.record_pending_terminal_transition_failure(
                    issue_id,
                    &pending,
                    error.to_string(),
                )
                .await;
                warn!(
                    issue_id = %issue_id,
                    error = %error,
                    "failed to clear terminal interaction waiting state"
                );
                return;
            }

            if let Some(record) = pending.transition.history_record.as_ref() {
                if let Err(error) = self
                    .persist_history_record(pending.run_id.as_deref(), record)
                    .await
                {
                    self.record_pending_terminal_transition_failure(
                        issue_id,
                        &pending,
                        error.to_string(),
                    )
                    .await;
                    warn!(
                        issue_id = %issue_id,
                        error = %error,
                        "failed to persist terminal run history before release"
                    );
                    return;
                }
            }

            if let Err(error) = self.workspace_mgr.remove_workspace(issue_id).await {
                self.record_pending_terminal_transition_failure(
                    issue_id,
                    &pending,
                    error.to_string(),
                )
                .await;
                warn!(
                    issue_id = %issue_id,
                    identifier = %pending.identifier,
                    error = %error,
                    "failed to clean terminal workspace before release"
                );
                return;
            }

            if let Err(error) = self
                .pipeline_journal
                .append_released(
                    issue_id,
                    &pending.identifier,
                    pending.run_id.clone(),
                    "terminal tracker transition reconciled",
                )
                .await
            {
                warn!(
                    issue_id = %issue_id,
                    error = %error,
                    "failed to persist pipeline release after terminal tracker transition"
                );
                return;
            }

            {
                let mut state = self.state.write().await;
                let Some(current) = state.pending_terminal_transitions.get(issue_id) else {
                    return;
                };
                if current.run_id != pending.run_id
                    || current.transition.target_state != pending.transition.target_state
                    || current.transition.outcome != pending.transition.outcome
                {
                    return;
                }

                let status = match pending.transition.outcome {
                    TerminalOutcome::Succeeded => "completed_succeeded",
                    TerminalOutcome::Failed => "completed_failed",
                };
                state.add_completed(
                    issue_id.to_string(),
                    pending.identifier.clone(),
                    status.to_string(),
                );
                state.release_claim(issue_id);
                state.remove_pipeline_run(issue_id);
                state.clear_finalize_state(issue_id);
            }
        })
    }

    async fn record_pending_terminal_transition_failure(
        &self,
        issue_id: &str,
        expected: &PendingTerminalEntry,
        error: String,
    ) {
        let refreshed_input = {
            let mut state = self.state.write().await;
            let Some(current) = state.pending_terminal_transitions.get_mut(issue_id) else {
                return;
            };
            if current.run_id != expected.run_id
                || current.transition.target_state != expected.transition.target_state
                || current.transition.outcome != expected.transition.outcome
            {
                return;
            }
            current.transition.attempt = current.transition.attempt.saturating_add(1);
            current.transition.last_error = Some(error);
            current.transition.last_attempted_at = Some(Utc::now());
            let current = current.clone();
            Self::pending_terminal_transition_input(
                &state,
                issue_id,
                &current,
                PipelineTransitionKind::PendingTerminalTransition,
            )
        };

        if let Some(input) = refreshed_input {
            if let Err(journal_error) = self.pipeline_journal.append(input).await {
                warn!(
                    issue_id = %issue_id,
                    error = %journal_error,
                    "failed to refresh pending terminal transition retry metadata"
                );
            }
        }
    }

    async fn clear_terminal_interaction_waiting_state(
        &self,
        issue_id: &str,
    ) -> Result<(), EnsembleError> {
        if let Some(interaction) = self
            .interaction_store
            .latest_blocking_for_issue(issue_id)
            .await?
        {
            if interaction.awaiting_resume {
                self.interaction_store
                    .clear_waiting_state(&interaction.id)
                    .await?;
            }
        }
        Ok(())
    }

    fn pending_terminal_transition_input(
        state: &OrchestratorState,
        issue_id: &str,
        pending: &PendingTerminalEntry,
        kind: PipelineTransitionKind,
    ) -> Option<PipelineTransitionInput> {
        let run = state.get_pipeline_run(issue_id)?;
        Some(PipelineTransitionInput {
            kind,
            issue_id: issue_id.to_string(),
            identifier: pending.identifier.clone(),
            run_id: pending.run_id.clone(),
            cycle: run.cycle,
            step: None,
            reason: pending.transition.last_error.clone(),
            retry: None,
            snapshot: Some(run.to_snapshot()),
            terminal_transition: Some(pending.transition.clone()),
            delivery: None,
        })
    }

    fn terminal_issue_placeholder(issue_id: &str, identifier: &str, state: &str) -> Issue {
        Issue {
            id: issue_id.to_string(),
            identifier: identifier.to_string(),
            title: identifier.to_string(),
            description: None,
            priority: None,
            tracker_position: None,
            state: state.to_string(),
            branch_name: None,
            url: None,
            labels: vec![],
            blocked_by: vec![],
            created_at: None,
            updated_at: None,
        }
    }

    fn transition_input_for_run(
        state: &OrchestratorState,
        issue_id: &str,
        identifier: &str,
        kind: PipelineTransitionKind,
        step: Option<String>,
        reason: Option<String>,
        retry: Option<RetryEntry>,
    ) -> Option<PipelineTransitionInput> {
        let run = state.get_pipeline_run(issue_id)?;
        Self::transition_input_for_snapshot(
            state,
            run,
            PipelineTransitionTarget {
                issue_id,
                identifier,
            },
            kind,
            step,
            reason,
            retry,
        )
    }

    fn transition_input_for_snapshot(
        state: &OrchestratorState,
        run: &PipelineRun,
        target: PipelineTransitionTarget<'_>,
        kind: PipelineTransitionKind,
        step: Option<String>,
        reason: Option<String>,
        retry: Option<RetryEntry>,
    ) -> Option<PipelineTransitionInput> {
        let run_id = state
            .running
            .get(target.issue_id)
            .and_then(|entry| entry.run_id.clone())
            .or_else(|| {
                state
                    .waiting_on_human
                    .get(target.issue_id)
                    .and_then(|entry| entry.run_id.clone())
            })
            .or_else(|| state.issue_run_ids.get(target.issue_id).cloned());

        Some(PipelineTransitionInput {
            kind,
            issue_id: target.issue_id.to_string(),
            identifier: target.identifier.to_string(),
            run_id,
            cycle: run.cycle,
            step,
            reason,
            retry,
            snapshot: Some(run.to_snapshot()),
            terminal_transition: None,
            delivery: None,
        })
    }

    fn transition_kind_for_action(action: &PipelineAction) -> PipelineTransitionKind {
        match action {
            PipelineAction::Dispatch(_) | PipelineAction::Succeeded => {
                PipelineTransitionKind::StepCompleted
            }
            PipelineAction::Failed { .. } => PipelineTransitionKind::StepFailed,
            PipelineAction::BlockedOnHuman { .. } => PipelineTransitionKind::StepBlockedOnHuman,
            PipelineAction::AwaitingApproval { .. } => PipelineTransitionKind::StepAwaitingApproval,
            PipelineAction::Waiting | PipelineAction::AwaitingAction { .. } => {
                PipelineTransitionKind::StepCompleted
            }
        }
    }

    async fn cancel_open_interaction(&self, interaction_request_id: Option<String>) {
        let Some(interaction_request_id) = interaction_request_id else {
            return;
        };

        match self
            .interaction_store
            .retire_waiting_state(&interaction_request_id)
            .await
        {
            Ok((_, retired)) => {
                self.reconcile_interaction_attention(&retired).await;
            }
            Err(error) => {
                warn!(
                    interaction_request_id = %interaction_request_id,
                    error = %error,
                    "failed to clear interaction waiting state during waiting-issue cleanup"
                );
            }
        }
    }

    fn is_headless_runtime() -> bool {
        std::env::var("ENSEMBLE_HEADLESS")
            .map(|value| value == "1")
            .unwrap_or(false)
    }

    async fn finalize_and_stage_terminal_transition(
        &self,
        issue_id: &str,
        issue_identifier: &str,
        config: &EnsembleConfig,
    ) -> IssueFinalizeState {
        let attempt = {
            let state = self.state.read().await;
            RunningAttemptIdentity::capture(&state, issue_id)
        };
        // Finalization includes durable delivery reconciliation; heap-allocate its future so
        // terminal failure handling does not inherit the full delivery state machine's stack use.
        let finalize_state =
            Box::pin(self.run_finalize_phase(issue_id, issue_identifier, config)).await;
        #[cfg(test)]
        self.wait_for_finalization_commit_test_barriers().await;
        if attempt.is_some() {
            let state = self.state.read().await;
            if !Self::finalization_attempt_is_current(attempt.as_ref(), &state, issue_id) {
                return finalize_state;
            }
        }
        self.stage_finalization_terminal_transition(
            issue_id,
            issue_identifier,
            config,
            &finalize_state,
        )
        .await;
        finalize_state
    }

    async fn stage_finalization_terminal_transition(
        &self,
        issue_id: &str,
        issue_identifier: &str,
        config: &EnsembleConfig,
        finalize_state: &IssueFinalizeState,
    ) {
        let outcome = match finalize_state.status {
            FinalizeStatus::Succeeded | FinalizeStatus::NotRequired => TerminalOutcome::Succeeded,
            FinalizeStatus::SkippedHeadless => TerminalOutcome::Failed,
            FinalizeStatus::PendingApproval
            | FinalizeStatus::InProgress
            | FinalizeStatus::Failed => return,
        };
        let target_state = match outcome {
            TerminalOutcome::Succeeded => config.on_success.clone(),
            TerminalOutcome::Failed => config.on_failure.clone(),
        };
        let last_error = finalize_state
            .repos
            .iter()
            .find_map(|repo| repo.last_error.clone());
        let completed_at = Utc::now();

        let history_record = {
            let state = self.state.read().await;
            self.build_owned_history_record(
                &state,
                issue_id,
                match outcome {
                    TerminalOutcome::Succeeded => HISTORY_OUTCOME_SUCCEEDED,
                    TerminalOutcome::Failed => HISTORY_OUTCOME_FAILED,
                },
                last_error,
                completed_at,
            )
        };

        let _ = self
            .persist_terminal_transition(
                issue_id,
                issue_identifier,
                outcome,
                target_state,
                history_record,
                false,
            )
            .await;
    }

    async fn run_finalize_phase(
        &self,
        issue_id: &str,
        issue_identifier: &str,
        _config: &EnsembleConfig,
    ) -> IssueFinalizeState {
        #[cfg(test)]
        self.finalization_run_count.fetch_add(1, Ordering::SeqCst);

        let mut repos = Vec::new();
        let headless = Self::is_headless_runtime();

        let configured_repos = self.workspace_mgr.repos();
        let requires_workspace = configured_repos
            .values()
            .any(|repo| repo.finalize.enabled && !matches!(repo.finalize.mode, FinalizeMode::None));

        let prepared_workspace = if requires_workspace {
            match self
                .workspace_mgr
                .prepare_workspace(issue_id, issue_identifier)
                .await
            {
                Ok(workspace) => Some(workspace),
                Err(error) => {
                    return IssueFinalizeState {
                        issue_identifier: issue_identifier.to_string(),
                        status: FinalizeStatus::Failed,
                        repos: vec![RepoFinalizeState {
                            repo: "workspace".to_string(),
                            mode: "prepare".to_string(),
                            approval_required: false,
                            status: FinalizeStatus::Failed,
                            last_error: Some(error.to_string()),
                            observation: None,
                        }],
                    };
                }
            }
        } else {
            None
        };

        let mut delivery_repo_names = Vec::new();
        for (repo_name, repo_config) in configured_repos {
            if !repo_config.finalize.enabled
                || matches!(repo_config.finalize.mode, FinalizeMode::None)
            {
                continue;
            }

            let mode_name = finalize_mode_name(&repo_config.finalize.mode).to_string();

            if repo_config.finalize.approval_required && headless {
                let status = FinalizeStatus::SkippedHeadless;
                repos.push(RepoFinalizeState {
                    repo: repo_name.clone(),
                    mode: mode_name,
                    approval_required: true,
                    status: status.clone(),
                    last_error: None,
                    observation: None,
                });
                self.update_repo_artifact_finalize_status(issue_id, repo_name, status, None)
                    .await;
                continue;
            }
            if repo_config.finalize.approval_required {
                self.update_repo_artifact_finalize_status(
                    issue_id,
                    repo_name,
                    FinalizeStatus::PendingApproval,
                    None,
                )
                .await;
            }
            delivery_repo_names.push(repo_name.clone());
        }

        if !delivery_repo_names.is_empty() {
            let Some(workspace) = prepared_workspace.as_ref() else {
                unreachable!("publication repositories require a prepared workspace");
            };
            {
                let mut state = self.state.write().await;
                if let Some(history) = self.build_owned_history_record(
                    &state,
                    issue_id,
                    HISTORY_OUTCOME_SUCCEEDED,
                    None,
                    Utc::now(),
                ) {
                    state
                        .finalize_terminal_history
                        .insert(issue_id.to_string(), history);
                }
            }
            let prepared = self
                .prepare_delivery_record(
                    issue_id,
                    issue_identifier,
                    workspace,
                    &delivery_repo_names,
                )
                .await;
            let persisted = match prepared {
                Ok((delivery, snapshot)) => {
                    match self
                        .persist_delivery_record(&delivery, snapshot.as_ref())
                        .await
                    {
                        Ok(()) => Ok((delivery, snapshot)),
                        Err(error) => {
                            if let Some(history) = delivery.terminal_history.as_deref().cloned() {
                                self.state
                                    .write()
                                    .await
                                    .finalize_terminal_history
                                    .insert(issue_id.to_string(), history);
                            }
                            Err(error)
                        }
                    }
                }
                Err(error) => Err(error),
            };
            match persisted {
                Ok((delivery, snapshot)) => {
                    let delivery = self
                        .advance_delivery_record(delivery, workspace, snapshot.as_ref())
                        .await;
                    let delivery = self.advance_review_projection(delivery).await;
                    repos.extend(Self::finalize_repositories_from_delivery(&delivery));
                    self.project_delivery_artifacts(issue_id, &delivery).await;
                }
                Err(error) => {
                    for repo_name in delivery_repo_names {
                        let repo_config = &configured_repos[&repo_name];
                        repos.push(RepoFinalizeState {
                            repo: repo_name.clone(),
                            mode: finalize_mode_name(&repo_config.finalize.mode).to_string(),
                            approval_required: repo_config.finalize.approval_required,
                            status: FinalizeStatus::Failed,
                            last_error: Some(error.clone()),
                            observation: None,
                        });
                    }
                }
            }
        }

        let status = if repos.is_empty() {
            FinalizeStatus::NotRequired
        } else if repos
            .iter()
            .any(|repo| repo.status == FinalizeStatus::Failed)
        {
            FinalizeStatus::Failed
        } else if repos
            .iter()
            .any(|repo| repo.status == FinalizeStatus::PendingApproval)
        {
            FinalizeStatus::PendingApproval
        } else if repos
            .iter()
            .any(|repo| repo.status == FinalizeStatus::InProgress)
        {
            FinalizeStatus::InProgress
        } else if repos
            .iter()
            .any(|repo| repo.status == FinalizeStatus::SkippedHeadless)
        {
            FinalizeStatus::SkippedHeadless
        } else {
            // Initial finalize execution in this method is synchronous per repo,
            // so issue-level `InProgress` is not expected here. `InProgress`
            // is used later for operator-approved/retry flows.
            FinalizeStatus::Succeeded
        };

        IssueFinalizeState {
            issue_identifier: issue_identifier.to_string(),
            status,
            repos,
        }
    }

    async fn process_finalize_retries(&self) {
        let pending_retries: Vec<(String, String)> = {
            let state = self.state.read().await;
            state
                .finalize
                .iter()
                .filter(|(issue_id, finalize)| {
                    finalize.repos.iter().any(|repo| {
                        repo.status == FinalizeStatus::InProgress
                            && state.delivery.get(*issue_id).is_none_or(|delivery| {
                                delivery
                                    .repositories
                                    .get(&repo.repo)
                                    .is_none_or(|repository| {
                                        matches!(
                                            repository.phase,
                                            DeliveryPhase::AwaitingApproval
                                                | DeliveryPhase::Blocked
                                        )
                                    })
                            })
                    })
                })
                .map(|(issue_id, finalize)| (issue_id.clone(), finalize.issue_identifier.clone()))
                .collect()
        };

        for (issue_id, issue_identifier) in pending_retries {
            self.retry_finalize_for_issue(&issue_id, &issue_identifier)
                .await;
        }
    }

    async fn retry_finalize_for_issue(&self, issue_id: &str, issue_identifier: &str) {
        let retry_repo_names: Vec<String> = {
            let state = self.state.read().await;
            state
                .get_finalize_state(issue_id)
                .map(|finalize| {
                    finalize
                        .repos
                        .iter()
                        .filter(|repo| repo.status == FinalizeStatus::InProgress)
                        .map(|repo| repo.repo.clone())
                        .collect()
                })
                .unwrap_or_default()
        };

        if retry_repo_names.is_empty() {
            return;
        }

        let workspace = match self
            .workspace_mgr
            .prepare_workspace(issue_id, issue_identifier)
            .await
        {
            Ok(workspace) => workspace,
            Err(error) => {
                {
                    let mut state = self.state.write().await;
                    if let Some(finalize) = state.get_finalize_state_mut(issue_id) {
                        finalize.status = FinalizeStatus::Failed;
                        for repo in &mut finalize.repos {
                            if repo.status == FinalizeStatus::InProgress {
                                repo.status = FinalizeStatus::Failed;
                                repo.last_error = Some(error.to_string());
                            }
                        }
                    }
                }
                warn!(
                    issue_id = %issue_id,
                    error = %error,
                    "finalize retry workspace preparation failed"
                );
                return;
            }
        };

        let existing = self.state.read().await.delivery.get(issue_id).cloned();
        let missing_repo_names = retry_repo_names
            .iter()
            .filter(|repo_name| {
                !existing
                    .as_ref()
                    .is_some_and(|delivery| delivery.repositories.contains_key(repo_name.as_str()))
            })
            .cloned()
            .collect::<Vec<_>>();
        let newly_prepared_repo_names = missing_repo_names.iter().cloned().collect::<HashSet<_>>();
        let (mut delivery, snapshot) = if missing_repo_names.is_empty() {
            let Some(existing) = existing else {
                return;
            };
            let snapshot = match self.load_delivery_snapshot(&existing).await {
                Ok(snapshot) => snapshot,
                Err(error) => {
                    warn!(
                        issue_id,
                        error = %error,
                        "finalize retry could not load its durable delivery snapshot"
                    );
                    return;
                }
            };
            (existing, snapshot)
        } else {
            let (mut prepared, snapshot) = match self
                .prepare_delivery_record(
                    issue_id,
                    issue_identifier,
                    &workspace,
                    &missing_repo_names,
                )
                .await
            {
                Ok(prepared) => prepared,
                Err(error) => {
                    let mut state = self.state.write().await;
                    if let Some(finalize) = state.get_finalize_state_mut(issue_id) {
                        finalize.status = FinalizeStatus::Failed;
                        for repo in &mut finalize.repos {
                            if retry_repo_names.contains(&repo.repo) {
                                repo.status = FinalizeStatus::Failed;
                                repo.last_error = Some(error.clone());
                            }
                        }
                    }
                    return;
                }
            };
            if let Some(existing) = existing {
                if existing.run_id != prepared.run_id {
                    warn!(
                        issue_id = %issue_id,
                        "refusing to merge finalization approval into a different delivery run"
                    );
                    return;
                }
                let existing_projection = existing.review_projection.clone();
                let mut repositories = existing.repositories;
                repositories.extend(prepared.repositories);
                prepared.repositories = repositories;
                if existing_projection.is_some() {
                    prepared.review_projection = existing_projection;
                }
            }
            (prepared, snapshot)
        };
        for repo_name in &retry_repo_names {
            let Some(repository) = delivery.repositories.get_mut(repo_name) else {
                continue;
            };
            if repository.phase == DeliveryPhase::AwaitingApproval {
                if newly_prepared_repo_names.contains(repo_name) {
                    continue;
                }
                repository.phase = DeliveryPhase::Prepared;
                repository.last_error = None;
            } else if repository.phase == DeliveryPhase::Blocked {
                let retry_from = repository.retry_from.unwrap_or(DeliveryPhase::Prepared);
                repository.phase = retry_from;
                if retry_from != DeliveryPhase::Waiting {
                    repository.retry_from = None;
                }
                repository.last_error = None;
            }
        }
        if let Err(error) = self
            .persist_delivery_record(&delivery, snapshot.as_ref())
            .await
        {
            let mut state = self.state.write().await;
            if let Some(finalize) = state.get_finalize_state_mut(issue_id) {
                finalize.status = FinalizeStatus::Failed;
                for repo in &mut finalize.repos {
                    if retry_repo_names.contains(&repo.repo) {
                        repo.status = FinalizeStatus::Failed;
                        repo.last_error = Some(error.clone());
                    }
                }
            }
            return;
        }
        let delivery = self
            .advance_delivery_record(delivery, &workspace, snapshot.as_ref())
            .await;
        let delivery = self.advance_review_projection(delivery).await;
        self.project_delivery_artifacts(issue_id, &delivery).await;
        let terminal_history = self
            .projected_terminal_history(&delivery, HISTORY_OUTCOME_SUCCEEDED)
            .await;

        let (final_status, should_complete, last_error) = {
            let mut state = self.state.write().await;
            let mut final_status = FinalizeStatus::NotRequired;
            let mut last_error = None;

            if let Some(finalize) = state.get_finalize_state_mut(issue_id) {
                for repo in &mut finalize.repos {
                    let Some(repository) = delivery.repositories.get(&repo.repo) else {
                        continue;
                    };
                    repo.status = Self::finalize_status_from_delivery(repository);
                    repo.last_error = repository.last_error.clone();
                }

                final_status = if finalize.repos.is_empty() {
                    FinalizeStatus::NotRequired
                } else if finalize
                    .repos
                    .iter()
                    .any(|repo| repo.status == FinalizeStatus::Failed)
                {
                    FinalizeStatus::Failed
                } else if finalize
                    .repos
                    .iter()
                    .any(|repo| repo.status == FinalizeStatus::PendingApproval)
                {
                    FinalizeStatus::PendingApproval
                } else if finalize
                    .repos
                    .iter()
                    .any(|repo| repo.status == FinalizeStatus::InProgress)
                {
                    FinalizeStatus::InProgress
                } else if finalize
                    .repos
                    .iter()
                    .any(|repo| repo.status == FinalizeStatus::SkippedHeadless)
                {
                    FinalizeStatus::SkippedHeadless
                } else {
                    FinalizeStatus::Succeeded
                };

                finalize.status = final_status.clone();
                last_error = finalize
                    .repos
                    .iter()
                    .find_map(|repo| repo.last_error.clone());
            }

            let should_complete = matches!(
                final_status,
                FinalizeStatus::Succeeded | FinalizeStatus::NotRequired
            );
            (final_status, should_complete, last_error)
        };

        if should_complete {
            let outcome = TerminalOutcome::Succeeded;
            let config_snapshot = match self.current_config_for_snapshot(snapshot.as_ref()).await {
                Ok(config) => config,
                Err(error) => {
                    warn!(
                        issue_id = %issue_id,
                        error = %error,
                        "finalize retry could not resolve its selected workflow"
                    );
                    return;
                }
            };
            let target_state = config_snapshot.on_success.clone();
            if let Some(finalize_state) = self
                .state
                .read()
                .await
                .get_finalize_state(issue_id)
                .cloned()
            {
                self.stage_finalization_terminal_transition(
                    issue_id,
                    issue_identifier,
                    config_snapshot.as_ref(),
                    &finalize_state,
                )
                .await;
            };
            let issue = self
                .tracker
                .fetch_issue_states_by_ids(&[issue_id.to_string()])
                .await
                .ok()
                .and_then(|issues| issues.into_iter().next());
            self.begin_terminal_transition_for_identity(
                issue_id,
                issue_identifier,
                issue,
                outcome,
                target_state,
                terminal_history,
            )
            .await;
        } else if let Some(error) = last_error {
            warn!(
                issue_id = %issue_id,
                status = ?final_status,
                error = %error,
                "finalize retry failed"
            );
        }
    }

    async fn update_repo_artifact_finalize_status(
        &self,
        issue_id: &str,
        repo_name: &str,
        status: FinalizeStatus,
        last_error: Option<String>,
    ) {
        let mut state = self.state.write().await;
        if let Some(artifacts) = state.artifacts.get_mut(issue_id) {
            if let Some(repo_artifact) = artifacts
                .repos
                .iter_mut()
                .find(|artifact| artifact.repo == repo_name)
            {
                repo_artifact.finalize_status = Self::finalize_status_name(&status).to_string();
                repo_artifact.last_error = last_error;
            }
        }
    }

    fn finalize_status_name(status: &FinalizeStatus) -> &'static str {
        match status {
            FinalizeStatus::NotRequired => "not_required",
            FinalizeStatus::PendingApproval => "pending_approval",
            FinalizeStatus::InProgress => "in_progress",
            FinalizeStatus::Succeeded => "succeeded",
            FinalizeStatus::Failed => "failed",
            FinalizeStatus::SkippedHeadless => "skipped_headless",
        }
    }

    fn pipeline_has_running_steps(run: &PipelineRun) -> bool {
        run.step_states
            .values()
            .any(|step_state| matches!(step_state, StepState::Running { .. }))
    }

    // Keep #480 Artifact evidence projection and the resulting HistoryRecord out of lifecycle
    // futures that carry terminal-transition state on Tokio worker stacks.
    #[inline(never)]
    pub(super) fn build_history_record(
        &self,
        input: RunningHistoryRecordInput<'_>,
    ) -> HistoryRecord {
        let steps_traversed = input.run.traversed_steps_in_order();

        let duration_seconds = input
            .completed_at
            .signed_duration_since(input.running_entry.started_at)
            .num_seconds()
            .max(0) as u64;

        let workspace_path = self
            .workspace_mgr
            .workspace_path(&input.running_entry.issue_id)
            .display()
            .to_string();

        HistoryRecord {
            issue_identifier: input.running_entry.identifier.clone(),
            issue_id: input.running_entry.issue_id.clone(),
            outcome: input.outcome.to_string(),
            steps_traversed,
            attempts: input.running_entry.retry_attempt.unwrap_or(1),
            tokens: TokenTotals {
                input_tokens: input.running_entry.agent_input_tokens,
                output_tokens: input.running_entry.agent_output_tokens,
                total_tokens: input.running_entry.agent_total_tokens,
            },
            duration_seconds,
            started_at: input.running_entry.started_at,
            completed_at: input.completed_at,
            last_error: input.last_error,
            verdict: Self::history_verdict(input.run),
            workspace_path: workspace_path.clone(),
            acceptance_attempts: input.run.acceptance_attempts.clone(),
            artifacts: Self::history_artifacts_with_snapshots(
                input.artifacts,
                input.run,
                input.running_entry.run_id.as_deref(),
                &input.running_entry.issue_id,
                &workspace_path,
            ),
        }
    }

    // Keep snapshot projection out of the terminal worker-exit future's stack frame.
    #[inline(never)]
    fn history_artifacts_with_snapshots(
        artifacts: Option<RunArtifacts>,
        run: &PipelineRun,
        run_id: Option<&str>,
        issue_id: &str,
        workspace_path: &str,
    ) -> Option<RunArtifacts> {
        crate::history::artifacts::with_pipeline_evidence(
            artifacts,
            run,
            run_id,
            issue_id,
            workspace_path,
        )
    }

    pub(super) fn build_owned_history_record(
        &self,
        state: &OrchestratorState,
        issue_id: &str,
        outcome: &str,
        last_error: Option<String>,
        completed_at: chrono::DateTime<Utc>,
    ) -> Option<HistoryRecord> {
        state.get_pipeline_run(issue_id).and_then(|run| {
            state
                .running
                .get(issue_id)
                .map(|entry| {
                    self.build_history_record(RunningHistoryRecordInput {
                        outcome,
                        last_error: last_error.clone(),
                        running_entry: entry,
                        run,
                        completed_at,
                        artifacts: state.artifacts.get(issue_id).cloned(),
                    })
                })
                .or_else(|| {
                    state.waiting_on_human.get(issue_id).map(|entry| {
                        self.build_history_record_from_waiting(WaitingHistoryRecordInput {
                            outcome,
                            last_error,
                            waiting_entry: entry,
                            run,
                            completed_at,
                            artifacts: state.artifacts.get(issue_id).cloned(),
                        })
                    })
                })
        })
    }

    fn build_history_record_from_waiting(
        &self,
        input: WaitingHistoryRecordInput<'_>,
    ) -> HistoryRecord {
        let steps_traversed = input.run.traversed_steps_in_order();
        let started_at = input
            .waiting_entry
            .started_at
            .unwrap_or(input.waiting_entry.requested_at);
        let duration_seconds = input
            .completed_at
            .signed_duration_since(started_at)
            .num_seconds()
            .max(0) as u64;
        let workspace_path = self
            .workspace_mgr
            .workspace_path(&input.waiting_entry.issue_id)
            .display()
            .to_string();

        HistoryRecord {
            issue_identifier: input.waiting_entry.identifier.clone(),
            issue_id: input.waiting_entry.issue_id.clone(),
            outcome: input.outcome.to_string(),
            steps_traversed,
            attempts: input.waiting_entry.retry_attempt.unwrap_or(1),
            tokens: TokenTotals {
                input_tokens: input.waiting_entry.agent_input_tokens,
                output_tokens: input.waiting_entry.agent_output_tokens,
                total_tokens: input.waiting_entry.agent_total_tokens,
            },
            duration_seconds,
            started_at,
            completed_at: input.completed_at,
            last_error: input.last_error,
            verdict: Self::history_verdict(input.run),
            artifacts: Self::history_artifacts_with_snapshots(
                input.artifacts,
                input.run,
                input.waiting_entry.run_id.as_deref(),
                &input.waiting_entry.issue_id,
                &workspace_path,
            ),
            workspace_path,
            acceptance_attempts: input.run.acceptance_attempts.clone(),
        }
    }

    fn history_verdict(run: &PipelineRun) -> Option<String> {
        if run
            .step_states
            .values()
            .any(|state| matches!(state, StepState::Failed { .. }))
        {
            return Some(HISTORY_VERDICT_REJECTED.to_string());
        }

        if run
            .step_states
            .values()
            .any(|state| matches!(state, StepState::Errored { .. }))
        {
            return Some(HISTORY_VERDICT_FAILED.to_string());
        }

        if run
            .step_states
            .values()
            .all(|state| matches!(state, StepState::Passed | StepState::Skipped { .. }))
        {
            return Some(HISTORY_VERDICT_APPROVED.to_string());
        }

        None
    }

    async fn persist_history_record(
        &self,
        run_id: Option<&str>,
        record: &HistoryRecord,
    ) -> Result<(), std::io::Error> {
        let sqlite_result = if let (Some(run_id), Some(store)) = (run_id, &self.history_store) {
            store.append_history_record(run_id, record).await
        } else {
            Ok(())
        };

        let history_path = self.workspace_mgr.root().join("ensemble_history.jsonl");
        let _guard = self.history_write_lock.lock().await;
        let writer = HistoryWriter::new(history_path);
        let jsonl_result = writer.append_if_absent(record).await;
        sqlite_result.and(jsonl_result)
    }

    async fn append_history_record(&self, run_id: Option<&str>, record: HistoryRecord) {
        if let Err(error) = self.persist_history_record(run_id, &record).await {
            warn!(
                issue_id = %record.issue_id,
                error = %error,
                "failed to append history record"
            );
        }
    }

    fn restore_previous_running(
        state: &mut OrchestratorState,
        issue_id: &str,
        previous_running: Option<&RunningEntry>,
    ) {
        match previous_running {
            Some(running) => {
                state.running.insert(issue_id.to_string(), running.clone());
            }
            None => {
                state.remove_running(issue_id);
            }
        }
    }

    pub async fn resume_blocked_issue(&self, issue: &Issue) -> Result<(), EnsembleError> {
        let selected = {
            let state = self.state.read().await;
            state
                .get_pipeline_run(&issue.id)
                .and_then(PipelineRun::selected_workflow)
                .cloned()
        };
        let current_config = {
            let config = self.config.read().await;
            if let Some(selected) = selected.as_ref() {
                Arc::new(config.resolve_selected_workflow(
                    &selected.rule,
                    &selected.pipeline,
                    &selected.lane,
                )?)
            } else {
                Arc::new(config.clone())
            }
        };

        self.hydrate_waiting_on_human_from_store().await;

        let interaction = self
            .interaction_store
            .latest_blocking_for_issue(&issue.id)
            .await?
            .ok_or_else(|| AgentError::PromptError {
                reason: format!("issue '{}' is not waiting on human", issue.identifier),
            })?;

        if interaction.status != InteractionStatus::Resolved {
            return Err(AgentError::PromptError {
                reason: format!("interaction '{}' is not resolved", interaction.id),
            }
            .into());
        }

        let waiting = {
            let state = self.state.read().await;
            state
                .waiting_on_human
                .get(&issue.id)
                .cloned()
                .ok_or_else(|| AgentError::PromptError {
                    reason: format!("issue '{}' is not waiting on human", issue.identifier),
                })?
        };
        if waiting.step_name != interaction.step_name {
            return Err(AgentError::PromptError {
                reason: format!(
                    "waiting entry step '{}' does not match resolved interaction step '{}'",
                    waiting.step_name, interaction.step_name
                ),
            }
            .into());
        }

        let current_dag = build_dag(&current_config.steps)?;
        let current_step = current_dag
            .steps
            .iter()
            .find(|candidate| candidate.name == waiting.step_name)
            .cloned()
            .ok_or_else(|| AgentError::PromptError {
                reason: format!("blocked step '{}' no longer exists", waiting.step_name),
            })?;

        if current_step.agent != interaction.agent_name {
            return Err(AgentError::PromptError {
                reason: format!(
                    "blocked step '{}' now references different agent '{}'",
                    waiting.step_name, current_step.agent
                ),
            }
            .into());
        }

        if current_step.depends != interaction.step_depends
            || current_step.tracker_state != interaction.step_tracker_state
        {
            return Err(AgentError::PromptError {
                reason: format!(
                    "blocked step '{}' changed while waiting and requires operator attention",
                    interaction.step_name
                ),
            }
            .into());
        }

        if !interaction
            .step_depends
            .iter()
            .all(|dependency| interaction.completed_steps.contains(dependency))
        {
            return Err(AgentError::PromptError {
                reason: format!(
                    "blocked interaction '{}' is missing completed dependencies for step '{}'",
                    interaction.id, interaction.step_name
                ),
            }
            .into());
        }

        if waiting.interaction_request_id != interaction.id {
            return Err(AgentError::PromptError {
                reason: format!(
                    "waiting entry interaction '{}' does not match resolved interaction '{}'",
                    waiting.interaction_request_id, interaction.id
                ),
            }
            .into());
        }

        {
            let state = self.state.read().await;
            let run = state
                .get_pipeline_run(&issue.id)
                .ok_or_else(|| AgentError::PromptError {
                    reason: format!(
                        "issue '{}' is missing its restored blocked pipeline run",
                        issue.identifier
                    ),
                })?;
            let blocked_step = run
                .step_states
                .iter()
                .find_map(|(step_name, step_state)| match step_state {
                    crate::pipeline::engine::StepState::BlockedOnHuman {
                        interaction_request_id,
                    } if interaction.resume_strategy == InteractionResumeStrategy::RerunStep => {
                        Some((step_name.clone(), interaction_request_id.clone()))
                    }
                    crate::pipeline::engine::StepState::AwaitingApproval {
                        interaction_request_id: Some(interaction_request_id),
                    } if interaction.resume_strategy
                        == InteractionResumeStrategy::AdvanceAfterStep =>
                    {
                        Some((step_name.clone(), interaction_request_id.clone()))
                    }
                    _ => None,
                })
                .ok_or_else(|| AgentError::PromptError {
                    reason: format!(
                        "issue '{}' is not waiting on a blocked step",
                        issue.identifier
                    ),
                })?;

            if blocked_step.0 != waiting.step_name {
                return Err(AgentError::PromptError {
                    reason: format!(
                        "waiting entry step '{}' does not match blocked pipeline step '{}'",
                        waiting.step_name, blocked_step.0
                    ),
                }
                .into());
            }

            if blocked_step.1 != waiting.interaction_request_id {
                return Err(AgentError::PromptError {
                    reason: format!(
                        "waiting entry interaction '{}' does not match blocked pipeline interaction '{}'",
                        waiting.interaction_request_id, blocked_step.1
                    ),
                }
                .into());
            }
        }

        let (pipeline_config, pipeline_step) = {
            let state = self.state.read().await;
            let config = state
                .get_pipeline_config(&issue.id)
                .cloned()
                .ok_or_else(|| AgentError::PromptError {
                    reason: format!(
                        "issue '{}' is missing its pipeline config snapshot",
                        issue.identifier
                    ),
                })?;
            let step = state
                .get_pipeline_run(&issue.id)
                .and_then(|run| run.step(&waiting.step_name))
                .cloned()
                .ok_or_else(|| AgentError::PromptError {
                    reason: format!(
                        "issue '{}' is missing blocked step '{}'",
                        issue.identifier, waiting.step_name
                    ),
                })?;
            (config, step)
        };

        if pipeline_step.kind.requires_agent()
            && !pipeline_config.agents.contains_key(&pipeline_step.agent)
        {
            return Err(AgentError::PromptError {
                reason: format!(
                    "blocked step agent '{}' no longer exists",
                    pipeline_step.agent
                ),
            }
            .into());
        }

        {
            let state = self.state.read().await;
            let workflow_states = build_reconcile_active_states_lower(&current_config);
            if let Some(reason) = is_resume_dispatch_eligible(
                issue,
                &state,
                &workflow_states,
                &current_config.tracker.terminal_states,
            ) {
                return Err(AgentError::PromptError {
                    reason: format!("issue '{}' cannot be resumed: {reason}", issue.identifier),
                }
                .into());
            }
        }

        let Some(resume_permit) = self.quiescing.begin_dispatch() else {
            return Err(EnsembleError::RuntimeBusy);
        };

        let mut interaction_was_retired = false;
        let mut nested_approval = None;
        let mut preserves_waiting_owner = false;
        match interaction.resume_strategy {
            InteractionResumeStrategy::RerunStep => {
                let response =
                    interaction
                        .response
                        .clone()
                        .ok_or_else(|| AgentError::PromptError {
                            reason: format!(
                                "resolved interaction '{}' is missing a response",
                                interaction.id
                            ),
                        })?;
                let resolved_at =
                    interaction
                        .resolved_at
                        .ok_or_else(|| AgentError::PromptError {
                            reason: format!(
                                "resolved interaction '{}' is missing resolved_at",
                                interaction.id
                            ),
                        })?;
                let interaction_response = InteractionResponseEnvelope::new(
                    interaction.schema_version,
                    interaction.id.clone(),
                    interaction.kind.clone(),
                    response,
                    resolved_at,
                );

                if !self
                    .state_worker_capacity_available(issue, &pipeline_config)
                    .await
                {
                    return Err(EnsembleError::RuntimeBusy);
                }

                let (attempt, step_outputs, previous_running) = {
                    let mut state = self.state.write().await;
                    let previous_running = state.get_running(&issue.id).cloned();
                    let attempt = state
                        .get_pipeline_run(&issue.id)
                        .map(|run| run.cycle)
                        .unwrap_or(interaction.pipeline_cycle.max(1));
                    let step_outputs = state
                        .get_pipeline_run(&issue.id)
                        .and_then(|run| run.output_context_for(&pipeline_step.name))
                        .unwrap_or_default();
                    state.add_running(issue, Some(attempt));
                    (attempt, step_outputs, previous_running)
                };

                let workspace_path =
                    match self.prepare_step_workspace(issue, &pipeline_config).await {
                        Ok(path) => path,
                        Err(error) => {
                            let mut state = self.state.write().await;
                            Self::restore_previous_running(
                                &mut state,
                                &issue.id,
                                previous_running.as_ref(),
                            );
                            return Err(AgentError::PromptError {
                                reason: format!("workspace error: {error}"),
                            }
                            .into());
                        }
                    };

                let dispatch_outcome = match self
                    .dispatch_step(
                        issue,
                        Arc::clone(&pipeline_config),
                        StepDispatchContext {
                            step_name: &pipeline_step.name,
                            agent_name: &pipeline_step.agent,
                            step_kind: pipeline_step.kind,
                            tracker_state: pipeline_step.tracker_state.as_deref(),
                            attempt: Some(attempt),
                            timeout_ms: Self::effective_step_timeout_ms(
                                pipeline_step.timeout_ms,
                                &pipeline_config,
                            ),
                            interaction_response: Some(interaction_response),
                            interaction_resume_id: Some(&interaction.id),
                            interaction_to_retire: Some(&interaction.id),
                            interaction_retirement_rollback: None,
                            workspace_path,
                            step_outputs,
                        },
                        &resume_permit,
                    )
                    .await
                {
                    Ok(outcome) => outcome,
                    Err(error) => {
                        if error.kind == StepDispatchFailureKind::ImmutableIntegrity {
                            self.handle_step_dispatch_error(
                                issue,
                                &pipeline_step.name,
                                &pipeline_config,
                                &error,
                            )
                            .await;
                            return Err(error.error);
                        }
                        let dispatch_retains_owner = {
                            let state = self.state.read().await;
                            matches!(
                                state
                                    .get_pipeline_run(&issue.id)
                                    .and_then(|run| run.step_states.get(&pipeline_step.name)),
                                Some(StepState::Running { .. })
                            )
                        };
                        if !dispatch_retains_owner {
                            let mut state = self.state.write().await;
                            Self::restore_previous_running(
                                &mut state,
                                &issue.id,
                                previous_running.as_ref(),
                            );
                        }
                        return Err(error.error);
                    }
                };
                if dispatch_outcome == StepDispatchOutcome::Deferred {
                    let mut state = self.state.write().await;
                    Self::restore_previous_running(
                        &mut state,
                        &issue.id,
                        previous_running.as_ref(),
                    );
                    return Err(EnsembleError::RuntimeBusy);
                }
                interaction_was_retired = true;
            }
            InteractionResumeStrategy::AdvanceAfterStep => {
                let response =
                    interaction
                        .response
                        .clone()
                        .ok_or_else(|| AgentError::PromptError {
                            reason: format!(
                                "resolved interaction '{}' is missing a response",
                                interaction.id
                            ),
                        })?;

                let (
                    action,
                    dispatch_contexts,
                    previous_run,
                    previous_running,
                    candidate_run,
                    step_transition,
                    route_transitions,
                    route_events,
                    route_event_contexts,
                    recovery_checkpoint,
                ) = {
                    let mut state = self.state.write().await;
                    let previous_running = state.get_running(&issue.id).cloned();
                    let previous_run =
                        state.get_pipeline_run(&issue.id).cloned().ok_or_else(|| {
                            AgentError::PromptError {
                                reason: format!(
                                    "issue '{}' is missing a pipeline run during approval resume",
                                    issue.identifier
                                ),
                            }
                        })?;
                    let (candidate_run, action, mut route_events) = {
                        let mut candidate_run = previous_run.clone();
                        let decisions_before_approval = candidate_run
                            .route_decisions
                            .keys()
                            .cloned()
                            .collect::<HashSet<_>>();
                        let action = match response {
                            InteractionResponse::Approval {
                                approved, reason, ..
                            } => {
                                if approved {
                                    candidate_run.approve_gate(&pipeline_step.name, reason)
                                } else {
                                    let failure_reason = reason.clone().unwrap_or_else(|| {
                                        format!(
                                            "approval rejected for step '{}'",
                                            pipeline_step.name
                                        )
                                    });
                                    candidate_run.reject_gate(
                                        &pipeline_step.name,
                                        failure_reason,
                                        reason,
                                    )
                                }
                            }
                            _ => {
                                return Err(AgentError::PromptError {
                                    reason: format!(
                                        "approval gate '{}' resolved with a non-approval response",
                                        interaction.id
                                    ),
                                }
                                .into())
                            }
                        };
                        let route_events = candidate_run
                            .route_decisions
                            .iter()
                            .filter(|(route_step, _)| {
                                !decisions_before_approval.contains(*route_step)
                            })
                            .map(|(route_step, decision)| RouteSelectionEvent {
                                route_step: route_step.clone(),
                                decision: decision.clone(),
                                skipped_steps: candidate_run
                                    .step_states
                                    .iter()
                                    .filter_map(|(step, state)| match state {
                                        StepState::Skipped { provenance }
                                            if provenance
                                                .iter()
                                                .any(|cause| cause.route_step == *route_step) =>
                                        {
                                            Some(step.clone())
                                        }
                                        _ => None,
                                    })
                                    .collect(),
                            })
                            .collect::<Vec<_>>();
                        (candidate_run, action, route_events)
                    };
                    Self::sort_route_events(&candidate_run, &mut route_events);

                    let step_transition = (!route_events.is_empty())
                        .then(|| {
                            Self::transition_input_for_snapshot(
                                &state,
                                &previous_run,
                                PipelineTransitionTarget {
                                    issue_id: &issue.id,
                                    identifier: &issue.identifier,
                                },
                                PipelineTransitionKind::StepCompleted,
                                Some(pipeline_step.name.clone()),
                                Some("approved".to_string()),
                                None,
                            )
                        })
                        .flatten();
                    let route_transitions =
                        route_events.is_empty().then(Vec::new).unwrap_or_else(|| {
                            Self::route_transition_inputs(
                                &state,
                                &issue.id,
                                &issue.identifier,
                                &previous_run,
                                &candidate_run,
                                &route_events,
                            )
                        });
                    let route_event_contexts = (0..route_events
                        .iter()
                        .map(|event| 1 + event.skipped_steps.len())
                        .sum())
                        .map(|_| Self::run_context_for_issue(&mut state, &issue.id))
                        .collect::<Vec<_>>();
                    let recovery_checkpoint =
                        (!route_transitions.is_empty()).then(|| PipelineTransitionInput {
                            kind: PipelineTransitionKind::StepAwaitingApproval,
                            issue_id: issue.id.clone(),
                            identifier: issue.identifier.clone(),
                            run_id: waiting.run_id.clone(),
                            cycle: previous_run.cycle,
                            step: Some(pipeline_step.name.clone()),
                            reason: Some(
                                "route selection persistence failed during approval resume"
                                    .to_string(),
                            ),
                            retry: None,
                            snapshot: Some(previous_run.to_snapshot()),
                            terminal_transition: None,
                            delivery: None,
                        });

                    // Collect output contexts while the run is still accessible
                    let dispatch_contexts: Vec<(DispatchRequest, StepOutputTemplateContext)> =
                        if let PipelineAction::Dispatch(ref requests) = action {
                            requests
                                .iter()
                                .map(|req| {
                                    let step_outputs = candidate_run
                                        .output_context_for(&req.step_name)
                                        .unwrap_or_default();
                                    (req.clone(), step_outputs)
                                })
                                .collect()
                        } else {
                            vec![]
                        };

                    (
                        action,
                        dispatch_contexts,
                        previous_run,
                        previous_running,
                        candidate_run,
                        step_transition,
                        route_transitions,
                        route_events,
                        route_event_contexts,
                        recovery_checkpoint,
                    )
                };

                let published_route_candidate = !route_transitions.is_empty();
                if published_route_candidate {
                    let Some(step_transition) = step_transition else {
                        self.restore_route_persistence_checkpoint(
                            &issue.id,
                            recovery_checkpoint.as_ref(),
                        )
                        .await;
                        return Err(AgentError::PromptError {
                            reason: format!(
                                "cannot persist completed approval step '{}' before route selection",
                                pipeline_step.name
                            ),
                        }
                        .into());
                    };
                    if let Err(error) = self
                        .append_successful_step_and_routes(
                            Some(step_transition),
                            route_transitions,
                            Some(issue),
                            route_events,
                            route_event_contexts,
                            recovery_checkpoint.as_ref(),
                        )
                        .await
                    {
                        self.restore_route_persistence_checkpoint(
                            &issue.id,
                            recovery_checkpoint.as_ref(),
                        )
                        .await;
                        return Err(AgentError::PromptError {
                            reason: format!(
                                "failed to durably persist route selection during approval resume: {error}"
                            ),
                        }
                        .into());
                    }
                }

                if !self
                    .publish_route_candidate(
                        &issue.id,
                        Some(candidate_run),
                        Some(&previous_run.to_snapshot()),
                    )
                    .await
                {
                    self.recover_unpublished_route_candidate(&issue.id, &pipeline_step.name)
                        .await;
                    return Err(AgentError::PromptError {
                        reason: format!(
                            "approval resume for '{}' lost its pipeline owner before publication",
                            pipeline_step.name
                        ),
                    }
                    .into());
                }

                match action {
                    PipelineAction::Dispatch(_requests) => {
                        let attempt = if published_route_candidate {
                            interaction_was_retired = true;
                            self.activate_published_approval_route_candidate(
                                issue,
                                &interaction,
                                interaction.pipeline_cycle,
                                &pipeline_step.name,
                            )
                            .await?
                        } else {
                            if !self
                                .state_worker_capacity_available(issue, &pipeline_config)
                                .await
                            {
                                let mut state = self.state.write().await;
                                state
                                    .pipeline_runs
                                    .insert(issue.id.clone(), previous_run.clone());
                                return Err(EnsembleError::RuntimeBusy);
                            }
                            let mut state = self.state.write().await;
                            let attempt = state
                                .get_pipeline_run(&issue.id)
                                .map(|run| run.cycle)
                                .unwrap_or(interaction.pipeline_cycle.max(1));
                            state.add_running(issue, Some(attempt));
                            attempt
                        };
                        if !self
                            .state_worker_capacity_available(issue, &pipeline_config)
                            .await
                        {
                            if !published_route_candidate {
                                let mut state = self.state.write().await;
                                state
                                    .pipeline_runs
                                    .insert(issue.id.clone(), previous_run.clone());
                            }
                            return Err(EnsembleError::RuntimeBusy);
                        }

                        let workspace_path = match self
                            .prepare_step_workspace(issue, &pipeline_config)
                            .await
                        {
                            Ok(path) => path,
                            Err(error) => {
                                if published_route_candidate {
                                    let reason = format!("workspace error: {error}");
                                    let Some((request, _)) = dispatch_contexts.first() else {
                                        return Err(AgentError::PromptError {
                                                reason: format!(
                                                    "{reason}; approval continuation has no dispatch request"
                                                ),
                                            }
                                            .into());
                                    };
                                    self.handle_step_dispatch_error(
                                        issue,
                                        &request.step_name,
                                        &pipeline_config,
                                        &StepDispatchError::ordinary(AgentError::PromptError {
                                            reason: reason.clone(),
                                        }),
                                    )
                                    .await;
                                    return Err(AgentError::PromptError { reason }.into());
                                }
                                let mut state = self.state.write().await;
                                Self::restore_previous_running(
                                    &mut state,
                                    &issue.id,
                                    previous_running.as_ref(),
                                );
                                state
                                    .pipeline_runs
                                    .insert(issue.id.clone(), previous_run.clone());
                                return Err(AgentError::PromptError {
                                    reason: format!("workspace error: {error}"),
                                }
                                .into());
                            }
                        };

                        let mut dispatched_any = false;
                        for (req, step_outputs) in dispatch_contexts {
                            let dispatch_outcome = match self
                                .dispatch_step(
                                    issue,
                                    Arc::clone(&pipeline_config),
                                    StepDispatchContext {
                                        step_name: &req.step_name,
                                        agent_name: &req.agent_name,
                                        step_kind: req.step_kind,
                                        tracker_state: req.tracker_state.as_deref(),
                                        attempt: Some(attempt),
                                        timeout_ms: Self::effective_step_timeout_ms(
                                            req.timeout_ms,
                                            &pipeline_config,
                                        ),
                                        interaction_response: None,
                                        interaction_resume_id: Some(&interaction.id),
                                        interaction_to_retire: (!interaction_was_retired)
                                            .then_some(interaction.id.as_str()),
                                        interaction_retirement_rollback: (!interaction_was_retired)
                                            .then(|| PipelineTransitionInput {
                                                kind: PipelineTransitionKind::StepAwaitingApproval,
                                                issue_id: issue.id.clone(),
                                                identifier: issue.identifier.clone(),
                                                run_id: waiting.run_id.clone(),
                                                cycle: previous_run.cycle,
                                                step: Some(pipeline_step.name.clone()),
                                                reason: Some(format!(
                                                    "interaction '{}' retirement failed",
                                                    interaction.id
                                                )),
                                                retry: None,
                                                snapshot: Some(previous_run.to_snapshot()),
                                                terminal_transition: None,
                                                delivery: None,
                                            }),
                                        workspace_path: workspace_path.clone(),
                                        step_outputs,
                                    },
                                    &resume_permit,
                                )
                                .await
                            {
                                Ok(outcome) => outcome,
                                Err(error) => {
                                    if published_route_candidate {
                                        self.handle_step_dispatch_error(
                                            issue,
                                            &req.step_name,
                                            &pipeline_config,
                                            &error,
                                        )
                                        .await;
                                        return Err(error.error);
                                    }
                                    if error.kind == StepDispatchFailureKind::ImmutableIntegrity {
                                        self.handle_step_dispatch_error(
                                            issue,
                                            &req.step_name,
                                            &pipeline_config,
                                            &error,
                                        )
                                        .await;
                                        return Err(error.error);
                                    }
                                    let failed_dispatch_retains_owner = {
                                        let state = self.state.read().await;
                                        matches!(
                                            state.get_pipeline_run(&issue.id).and_then(|run| run
                                                .step_states
                                                .get(&req.step_name)),
                                            Some(StepState::Running { .. })
                                        )
                                    };
                                    if !dispatched_any && !failed_dispatch_retains_owner {
                                        let mut state = self.state.write().await;
                                        Self::restore_previous_running(
                                            &mut state,
                                            &issue.id,
                                            previous_running.as_ref(),
                                        );
                                        state
                                            .pipeline_runs
                                            .insert(issue.id.clone(), previous_run.clone());
                                    } else if interaction_was_retired {
                                        let mut state = self.state.write().await;
                                        state.remove_waiting_on_human(&issue.id);
                                        state.clear_resume_request(&issue.id);
                                    }
                                    return Err(error.error);
                                }
                            };
                            if dispatch_outcome == StepDispatchOutcome::Deferred {
                                continue;
                            }
                            if !interaction_was_retired {
                                interaction_was_retired = true;
                            }
                            dispatched_any = true;
                        }
                        if !dispatched_any {
                            if !published_route_candidate {
                                let mut state = self.state.write().await;
                                Self::restore_previous_running(
                                    &mut state,
                                    &issue.id,
                                    previous_running.as_ref(),
                                );
                                state
                                    .pipeline_runs
                                    .insert(issue.id.clone(), previous_run.clone());
                            }
                            return Err(EnsembleError::RuntimeBusy);
                        }
                    }
                    PipelineAction::Succeeded => {
                        match self.run_acceptance_phase(issue, &pipeline_config).await {
                            AcceptancePhaseOutcome::Passed => {}
                            AcceptancePhaseOutcome::Failed { reason, owner } => {
                                if !interaction_was_retired {
                                    self.interaction_store.mark_resumed(&interaction.id).await?;
                                }
                                self.schedule_acceptance_failure(
                                    issue,
                                    &pipeline_config,
                                    &reason,
                                    &owner,
                                )
                                .await;
                                return Ok(());
                            }
                            AcceptancePhaseOutcome::RetainedForRecovery => return Ok(()),
                        }
                        let finalize_state = self
                            .finalize_and_stage_terminal_transition(
                                &issue.id,
                                &issue.identifier,
                                &pipeline_config,
                            )
                            .await;
                        let completed_at = Utc::now();
                        let (terminal_outcome, target_state, history_record) = {
                            let mut state = self.state.write().await;
                            let history_record =
                                state.waiting_on_human.get(&issue.id).and_then(|entry| {
                                    state.get_pipeline_run(&issue.id).map(|run| {
                                        self.build_history_record_from_waiting(
                                            WaitingHistoryRecordInput {
                                                outcome: HISTORY_OUTCOME_SUCCEEDED,
                                                last_error: None,
                                                waiting_entry: entry,
                                                run,
                                                completed_at,
                                                artifacts: state.artifacts.get(&issue.id).cloned(),
                                            },
                                        )
                                    })
                                });

                            if matches!(
                                finalize_state.status,
                                FinalizeStatus::Succeeded | FinalizeStatus::NotRequired
                            ) {
                                (
                                    Some(TerminalOutcome::Succeeded),
                                    Some(pipeline_config.on_success.clone()),
                                    history_record,
                                )
                            } else {
                                let is_terminal_failure = matches!(
                                    finalize_state.status,
                                    FinalizeStatus::Failed | FinalizeStatus::SkippedHeadless
                                );

                                state.set_finalize_state(&issue.id, finalize_state);
                                if !is_terminal_failure {
                                    state.remove_pipeline_run(&issue.id);
                                }
                                (
                                    is_terminal_failure.then_some(TerminalOutcome::Failed),
                                    is_terminal_failure.then(|| pipeline_config.on_failure.clone()),
                                    None,
                                )
                            }
                        };

                        if let (Some(outcome), Some(target_state)) =
                            (terminal_outcome, target_state)
                        {
                            self.begin_terminal_transition(
                                issue,
                                outcome,
                                target_state,
                                history_record,
                            )
                            .await;
                        }
                    }
                    PipelineAction::Failed { reason, .. } => {
                        if pipeline_step.kind == StepKind::Gate {
                            preserves_waiting_owner = self
                                .commit_rejected_gate_failure(
                                    issue,
                                    &pipeline_config,
                                    &pipeline_step,
                                    reason,
                                    previous_run,
                                    &interaction.id,
                                )
                                .await?;
                            interaction_was_retired = true;
                        } else {
                            let completed_at = Utc::now();
                            let history_record = {
                                let state = self.state.read().await;
                                state.waiting_on_human.get(&issue.id).and_then(|entry| {
                                    state.get_pipeline_run(&issue.id).map(|run| {
                                        self.build_history_record_from_waiting(
                                            WaitingHistoryRecordInput {
                                                outcome: HISTORY_OUTCOME_FAILED,
                                                last_error: Some(reason.clone()),
                                                waiting_entry: entry,
                                                run,
                                                completed_at,
                                                artifacts: state.artifacts.get(&issue.id).cloned(),
                                            },
                                        )
                                    })
                                })
                            };

                            self.begin_terminal_transition(
                                issue,
                                TerminalOutcome::Failed,
                                pipeline_config.on_failure.clone(),
                                history_record,
                            )
                            .await;
                        }
                    }
                    PipelineAction::AwaitingApproval {
                        step,
                        approval_state,
                    } => {
                        nested_approval = Some((step, approval_state));
                    }
                    PipelineAction::Waiting
                    | PipelineAction::AwaitingAction { .. }
                    | PipelineAction::BlockedOnHuman { .. } => {}
                }
            }
        }

        if let Some((step_name, approval_state)) = nested_approval.as_ref() {
            self.handle_post_step_approval(
                &issue.id,
                step_name,
                approval_state.clone(),
                None,
                Some(issue),
            )
            .await?;
        }

        if !interaction_was_retired {
            self.interaction_store.mark_resumed(&interaction.id).await?;
        }

        let mut state = self.state.write().await;
        if nested_approval.is_none() && !preserves_waiting_owner {
            state.remove_waiting_on_human(&issue.id);
        }
        let (run_id, sequence, attempt) = Self::run_context_for_issue(&mut state, &issue.id);
        let follow_up_sequence = run_id
            .as_ref()
            .map(|current_run_id| state.next_timeline_sequence(current_run_id));
        drop(state);

        self.publish_pipeline_event(
            run_id.clone(),
            sequence,
            attempt,
            PipelineEvent::InputResumed {
                issue_identifier: issue.identifier.clone(),
                timestamp: Utc::now(),
                step_name: pipeline_step.name.clone(),
                detail: format!("resumed from interaction {}", interaction.id),
            },
        )
        .await;

        self.publish_pipeline_event(
            run_id,
            follow_up_sequence,
            attempt,
            PipelineEvent::StepResumedFromHumanReply {
                issue_identifier: issue.identifier.clone(),
                timestamp: Utc::now(),
                step_name: pipeline_step.name.clone(),
                ask_id: interaction.id.clone(),
                detail: "step resumed after human reply".to_string(),
            },
        )
        .await;

        Ok(())
    }

    /// Handle due retry timer fires.
    async fn handle_retry_fires(&self) {
        if self.quiescing.is_requested() {
            return;
        }

        let due_retries = {
            let state = self.state.read().await;
            get_due_retries(&state)
        };

        for retry_entry in due_retries {
            if self.quiescing.is_requested() {
                break;
            }
            self.handle_single_retry(&retry_entry).await;
        }
    }

    /// Handle a single retry fire.
    async fn handle_single_retry(&self, retry_entry: &crate::tracker::model::RetryEntry) {
        if self.quiescing.is_requested() {
            self.defer_single_retry(retry_entry, "orchestrator quiescing")
                .await;
            return;
        }

        let issue_id = &retry_entry.issue_id;

        // Fetch active candidates
        let candidates = match self.tracker.fetch_candidate_issues().await {
            Ok(issues) => issues,
            Err(e) => {
                warn!(
                    issue_id = %issue_id,
                    error = %e,
                    "retry poll failed, rescheduling"
                );
                self.defer_single_retry(retry_entry, "retry poll failed")
                    .await;
                return;
            }
        };

        // Claimed tracker states may intentionally sit outside the ordinary candidate
        // states. Revalidate remote ownership before treating a missing candidate as a
        // release signal.
        let mut issue = candidates.into_iter().find(|issue| issue.id == *issue_id);
        if issue.is_none() && self.tracker.has_remote_ownership_policy() {
            match self.tracker.recover_owned_claims().await {
                Ok(recovered) => {
                    if let Some((recovered_issue, lease)) = recovered
                        .into_iter()
                        .find(|(recovered_issue, _)| recovered_issue.id == *issue_id)
                    {
                        {
                            let mut state = self.state.write().await;
                            if let Some(run) = state.get_pipeline_run_mut(issue_id) {
                                run.set_ownership_lease(lease.clone());
                            }
                        }
                        self.pending_ownership_leases
                            .lock()
                            .unwrap_or_else(|poisoned| poisoned.into_inner())
                            .insert(issue_id.clone(), lease);
                        issue = Some(recovered_issue);
                    }
                }
                Err(error) => {
                    warn!(
                        issue_id = %issue_id,
                        error = %error,
                        "retry ownership revalidation failed, rescheduling"
                    );
                    self.defer_single_retry(retry_entry, "retry ownership revalidation failed")
                        .await;
                    return;
                }
            }
        }

        match issue.as_ref() {
            None => {
                // Issue not found in candidates — release claim
                info!(
                    issue_id = %issue_id,
                    identifier = %retry_entry.identifier,
                    "issue not found in candidates on retry, releasing claim"
                );
                let release_run_id = {
                    let state = self.state.read().await;
                    (state.retry_attempts.get(issue_id) == Some(retry_entry))
                        .then(|| state.issue_run_ids.get(issue_id).cloned())
                };
                if let Some(run_id) = release_run_id {
                    let release_appended = match self
                        .pipeline_journal
                        .append_released_if_latest_retry_matches(
                            retry_entry,
                            run_id,
                            "retry_candidate_missing",
                        )
                        .await
                    {
                        Ok(Some(_)) => true,
                        Ok(None) => {
                            warn!(
                                issue_id = %issue_id,
                                "durable retry owner changed before release; retaining current ownership"
                            );
                            false
                        }
                        Err(error) => {
                            warn!(
                                issue_id = %issue_id,
                                error = %error,
                                "failed to durably release missing retry candidate; retaining ownership"
                            );
                            false
                        }
                    };

                    if release_appended {
                        let mut state = self.state.write().await;
                        if state.retry_attempts.get(issue_id) == Some(retry_entry) {
                            state.release_claim(issue_id);
                            state.remove_pipeline_run(issue_id);
                        } else {
                            warn!(
                                issue_id = %issue_id,
                                "retry owner changed during durable release; retaining current ownership"
                            );
                        }
                    }
                }
            }
            Some(issue) => {
                let (ready_for_dispatch, transition) = {
                    let mut state = self.state.write().await;
                    if state.retry_attempts.get(issue_id) != Some(retry_entry) {
                        return;
                    }
                    let Some(max_backoff_ms) = state
                        .get_pipeline_config(issue_id)
                        .map(|config| config.agent.max_retry_backoff_ms)
                    else {
                        warn!(
                            issue_id = %issue_id,
                            "retaining retry because its config snapshot is missing"
                        );
                        return;
                    };
                    let max_workers = state.max_concurrent_agents;
                    if has_available_worker_slots(
                        live_worker_count(&self.cancellation_registry),
                        max_workers,
                    ) {
                        (true, None)
                    } else {
                        info!(
                            issue_id = %issue_id,
                            identifier = %retry_entry.identifier,
                            "no slots available for retry, requeuing"
                        );
                        let transition = Self::defer_owned_retry(
                            &mut state,
                            retry_entry,
                            max_backoff_ms,
                            "no available orchestrator slots",
                        );
                        (false, transition)
                    }
                };
                if let Some(input) = transition {
                    self.append_pipeline_transition(input).await;
                }

                if ready_for_dispatch {
                    let Some(permit) = self.quiescing.begin_dispatch() else {
                        self.defer_single_retry(retry_entry, "orchestrator quiescing")
                            .await;
                        return;
                    };
                    self.dispatch_retry_issue_with_permit(issue, retry_entry, &permit)
                        .await;
                }
            }
        }
    }

    fn defer_owned_retry(
        state: &mut OrchestratorState,
        retry_entry: &RetryEntry,
        max_backoff_ms: u64,
        reason: &str,
    ) -> Option<PipelineTransitionInput> {
        if state.retry_attempts.get(&retry_entry.issue_id) != Some(retry_entry) {
            return None;
        }
        let deferred = defer_retry(state, retry_entry, max_backoff_ms, reason);
        let issue_id = deferred.issue_id.clone();
        let identifier = deferred.identifier.clone();
        let retry_from_step = deferred.retry_from_step.clone();
        let transition_reason = deferred.error.clone();
        Self::transition_input_for_run(
            state,
            &issue_id,
            &identifier,
            if deferred.with_fixup {
                PipelineTransitionKind::FixupRetryScheduled
            } else {
                PipelineTransitionKind::StepRetryScheduled
            },
            retry_from_step,
            transition_reason,
            Some(deferred),
        )
    }

    async fn defer_single_retry(&self, retry_entry: &RetryEntry, reason: &str) {
        let transition = {
            let mut state = self.state.write().await;
            let Some(max_backoff_ms) = state
                .get_pipeline_config(&retry_entry.issue_id)
                .map(|config| config.agent.max_retry_backoff_ms)
            else {
                warn!(
                    issue_id = %retry_entry.issue_id,
                    "retaining retry because its config snapshot is missing"
                );
                return;
            };
            Self::defer_owned_retry(&mut state, retry_entry, max_backoff_ms, reason)
        };
        if let Some(input) = transition {
            self.append_pipeline_transition(input).await;
        }
    }

    async fn cancel_active_runs(&self) -> bool {
        // A launch whose journal visibility is still ambiguous has a closed
        // runtime gate and no event bridge. Dropping its pending reservation
        // signals completion and releases its capacity before shutdown waits.
        let pending_launches = std::mem::take(
            &mut *self
                .pending_immutable_launches
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner()),
        );
        drop(pending_launches);
        let mut handles = mark_all_for_drain(&self.cancellation_registry);
        let cancelled = handles.len();
        if cancelled > 0 {
            debug!(cancelled, "cancelled active worker tokens");
        }

        #[cfg(unix)]
        {
            let running = {
                let state = self.state.read().await;
                state
                    .running
                    .iter()
                    .filter_map(|(issue_id, entry)| {
                        entry.agent_pid.as_deref().and_then(|pid| {
                            pid.parse::<i32>()
                                .ok()
                                .filter(|parsed| *parsed > 0)
                                .map(|parsed| (issue_id.clone(), parsed))
                        })
                    })
                    .collect::<Vec<_>>()
            };

            for (issue_id, pid) in running {
                let rc = unsafe { libc::kill(pid, libc::SIGTERM) };
                if rc == -1 {
                    warn!(
                        issue_id,
                        pid, "failed to send SIGTERM during orchestrator shutdown"
                    );
                }
            }
        }

        let quiesced = self
            .await_worker_quiescence_with_event_pump(&mut handles, DrainEventMode::Discard)
            .await;
        if quiesced {
            remove_drained_workers(&self.cancellation_registry, &handles);
        } else {
            warn!(
                workers = handles.len(),
                "worker completion closed before quiescence during shutdown; retaining worker ownership"
            );
        }
        quiesced
    }

    async fn publish_pipeline_event(
        &self,
        run_id: Option<String>,
        sequence: Option<u64>,
        attempt: u32,
        event: PipelineEvent,
    ) {
        let timeline_entry = if let (Some(run_id), Some(sequence)) = (run_id, sequence) {
            Some(event.to_timeline_record(&run_id, sequence, attempt))
        } else {
            None
        };

        self.event_bus.publish(event);

        if let Some(record) = timeline_entry {
            if let Some(ref persistence) = self.timeline_persistence {
                persistence.send(record);
            }
        }
    }

    fn run_context_for_issue(
        state: &mut OrchestratorState,
        issue_id: &str,
    ) -> (Option<String>, Option<u64>, u32) {
        let (run_id, attempt) = Self::run_metadata_for_issue(state, issue_id);
        let sequence = run_id
            .as_ref()
            .map(|run_id| state.next_timeline_sequence(run_id));
        (run_id, sequence, attempt)
    }

    fn run_metadata_for_issue(state: &OrchestratorState, issue_id: &str) -> (Option<String>, u32) {
        let run_id = state
            .running
            .get(issue_id)
            .and_then(|entry| entry.run_id.clone());
        let attempt = state
            .running
            .get(issue_id)
            .and_then(|entry| entry.retry_attempt)
            .unwrap_or(1);
        (run_id, attempt)
    }
}

async fn recv_worker_event(
    worker_rx: &Arc<tokio::sync::Mutex<mpsc::Receiver<OrchestratorWorkerEvent>>>,
) -> Option<OrchestratorWorkerEvent> {
    worker_rx.lock().await.recv().await
}

fn worker_result_halts_pipeline(result: &WorkerResult) -> bool {
    matches!(
        result,
        WorkerResult::Failed { .. }
            | WorkerResult::Success {
                output: crate::pipeline::verdict::StepOutput {
                    result: StepResult::Failed { .. },
                    ..
                },
                ..
            }
    )
}

async fn bridge_worker_events(
    mut local_event_rx: mpsc::Receiver<WorkerEvent>,
    orchestrator_event_tx: mpsc::Sender<OrchestratorWorkerEvent>,
    cancellation_registry: CancellationRegistry,
    identity: WorkerIdentity,
    completion_tx: watch::Sender<bool>,
) {
    while let Some(event) = local_event_rx.recv().await {
        let workspace_capture = if matches!(&event, WorkerEvent::WorkerExited { .. })
            && worker_uses_exclusive_issue_workspace(&cancellation_registry, &identity)
        {
            Some(acquire_issue_workspace_capture(&cancellation_registry, &identity.issue_id).await)
        } else {
            None
        };
        if orchestrator_event_tx
            .send(OrchestratorWorkerEvent {
                identity: identity.clone(),
                event,
                workspace_capture,
            })
            .await
            .is_err()
        {
            return;
        }
    }
    let _ = completion_tx.send(true);
    remove_completed_worker(&cancellation_registry, &identity);
}

#[allow(clippy::too_many_arguments)]
fn spawn_agent_worker(
    runner: Arc<dyn AgentRunner>,
    config: Arc<EnsembleConfig>,
    issue: Issue,
    agent_name: String,
    step_name: String,
    step_kind: StepKind,
    artifact_access: ArtifactAccess,
    attempt: Option<u32>,
    timeout_ms: u64,
    interaction_response: Option<InteractionResponseEnvelope>,
    workspace_path: std::path::PathBuf,
    cancel_token: tokio_util::sync::CancellationToken,
    step_outputs: StepOutputTemplateContext,
    start_gate: Option<oneshot::Receiver<()>>,
) -> mpsc::Receiver<WorkerEvent> {
    let (local_event_tx, local_event_rx) = mpsc::channel(100);
    tokio::spawn(async move {
        if let Some(start_gate) = start_gate {
            tokio::select! {
                result = start_gate => {
                    if result.is_err() {
                        return;
                    }
                }
                () = cancel_token.cancelled() => return,
            }
        }
        if cancel_token.is_cancelled() {
            return;
        }
        let worker_result = catch_worker_panic(
            runner.run(AgentRunRequest {
                config,
                issue: &issue,
                agent_name: &agent_name,
                step_name: &step_name,
                step_kind,
                artifact_access,
                attempt,
                timeout_ms,
                interaction_response,
                workspace_path: &workspace_path,
                event_tx: local_event_tx.clone(),
                cancel_token,
                step_outputs,
            }),
            &issue.id,
            &step_name,
        )
        .await;
        let _ = local_event_tx
            .send(WorkerEvent::WorkerExited {
                issue_id: issue.id,
                step_name,
                result: worker_result,
                timestamp: Utc::now(),
            })
            .await;
    });
    local_event_rx
}

async fn catch_worker_panic<F>(fut: F, issue_id: &str, step_name: &str) -> WorkerResult
where
    F: std::future::Future<Output = Result<WorkerResult, AgentError>>,
{
    match AssertUnwindSafe(fut).catch_unwind().await {
        Ok(Ok(result)) => result,
        Ok(Err(e)) => {
            let kind = if matches!(e, AgentError::TurnTimeout { .. }) {
                WorkerFailureKind::Timeout
            } else {
                WorkerFailureKind::Runtime
            };
            WorkerResult::Failed {
                error: e.to_string(),
                kind,
            }
        }
        Err(_) => {
            warn!(issue_id, step = step_name, "worker task panicked");
            WorkerResult::Failed {
                error: "worker task panicked".to_string(),
                kind: WorkerFailureKind::Runtime,
            }
        }
    }
}

fn transcript_kind_from_agent_kind(
    kind: crate::agent::protocol::TranscriptBlockKind,
) -> TranscriptRecordKind {
    match kind {
        crate::agent::protocol::TranscriptBlockKind::AssistantMessage => {
            TranscriptRecordKind::AssistantMessage
        }
        crate::agent::protocol::TranscriptBlockKind::Reasoning => TranscriptRecordKind::Reasoning,
        crate::agent::protocol::TranscriptBlockKind::ToolCall => TranscriptRecordKind::ToolCall,
        crate::agent::protocol::TranscriptBlockKind::ToolResult => TranscriptRecordKind::ToolResult,
        crate::agent::protocol::TranscriptBlockKind::PermissionRequest => {
            TranscriptRecordKind::PermissionRequest
        }
        crate::agent::protocol::TranscriptBlockKind::TurnComplete => {
            TranscriptRecordKind::TurnComplete
        }
        crate::agent::protocol::TranscriptBlockKind::Raw => TranscriptRecordKind::Raw,
    }
}

fn build_reconcile_active_states_lower(config: &EnsembleConfig) -> Vec<String> {
    let terminal: HashSet<String> = config
        .tracker
        .terminal_states
        .iter()
        .map(|state| state.to_lowercase())
        .collect();
    let mut states = HashSet::new();

    for state in &config.tracker.active_states {
        let state = state.to_lowercase();
        if !terminal.contains(&state) {
            states.insert(state);
        }
    }

    for step in config.steps.iter().chain(
        config
            .pipelines
            .values()
            .flat_map(|pipeline| &pipeline.steps),
    ) {
        if let Some(state) = step.tracker_state.as_deref() {
            let state = state.to_lowercase();
            if !terminal.contains(&state) {
                states.insert(state);
            }
        }

        if let Some(state) = step
            .approval
            .as_ref()
            .and_then(|approval| approval.state.as_deref())
        {
            let state = state.to_lowercase();
            if !terminal.contains(&state) {
                states.insert(state);
            }
        }
    }

    states.into_iter().collect()
}

fn new_run_id() -> String {
    let millis = Utc::now().timestamp_millis();
    let seq = RUN_ID_COUNTER.fetch_add(1, Ordering::Relaxed);
    format!("run-{millis}-{seq}")
}

fn build_interaction_request(
    issue: &Issue,
    context: InteractionRequestContext,
    request: InteractionRequestDraft,
    resume_strategy: InteractionResumeStrategy,
) -> crate::interaction::InteractionRequest {
    let requested_at = Utc::now();
    crate::interaction::InteractionRequest {
        id: format!(
            "interaction-{}-{}-{}",
            sanitize_interaction_fragment(&issue.id),
            sanitize_interaction_fragment(&context.step_name),
            requested_at.timestamp_millis()
        ),
        schema_version: request.schema_version,
        issue_id: issue.id.clone(),
        issue_identifier: issue.identifier.clone(),
        pipeline_cycle: context.pipeline_cycle,
        completed_steps: context.completed_steps,
        step_name: context.step_name,
        agent_name: context.agent_name,
        step_depends: context.step_depends,
        step_tracker_state: context.step_tracker_state,
        kind: request.kind,
        status: InteractionStatus::Open,
        blocking: request.blocking,
        awaiting_resume: request.blocking,
        resume_strategy,
        title: request.title,
        body: request.body,
        options: request.options,
        artifacts: request.artifacts,
        response: None,
        waiting_started_at: None,
        agent_input_tokens: 0,
        agent_output_tokens: 0,
        agent_total_tokens: 0,
        requested_at,
        resolved_at: None,
        thread_root_comment_id: None,
        thread_root_comment_url: None,
        last_processed_comment_id: None,
        accepted_command: None,
        ignored_commands: vec![],
    }
}

fn format_interaction_thread_root_comment(
    interaction: &crate::interaction::InteractionRequest,
) -> String {
    let commands = match interaction.kind {
        InteractionKind::Question => &["/answer <text>"][..],
        InteractionKind::Approval => &["/approve", "/reject <reason>"][..],
        InteractionKind::Handoff => &["/approve", "/reject <reason>", "/answer <text>"][..],
    };
    let snippets = commands
        .iter()
        .map(|command| {
            format!(
                "```text\n{command}\n\n<!-- ensemble:interaction:{} -->\n```",
                interaction.id
            )
        })
        .collect::<Vec<_>>()
        .join("\n\n");
    format!(
        concat!(
            "Ensemble requires input to continue.\n\n",
            "**Interaction ID:** `{}`\n",
            "**Kind:** `{}`\n\n",
            "{}\n\n",
            "Valid commands (copy one complete block):\n\n",
            "{}"
        ),
        interaction.id,
        match interaction.kind {
            InteractionKind::Question => "question",
            InteractionKind::Approval => "approval",
            InteractionKind::Handoff => "handoff",
        },
        interaction.body,
        snippets
    )
}

fn response_from_command(
    kind: &InteractionKind,
    command: &InteractionCommand,
) -> Option<InteractionResponse> {
    match (kind, command) {
        (InteractionKind::Question, InteractionCommand::Answer { text }) => {
            Some(InteractionResponse::Question {
                response_schema_version: 1,
                text: text.clone(),
                selected_option: None,
            })
        }
        (InteractionKind::Approval, InteractionCommand::Approve) => {
            Some(InteractionResponse::Approval {
                response_schema_version: 1,
                approved: true,
                reason: None,
            })
        }
        (InteractionKind::Approval, InteractionCommand::Reject { reason }) => {
            Some(InteractionResponse::Approval {
                response_schema_version: 1,
                approved: false,
                reason: Some(reason.clone()),
            })
        }
        (InteractionKind::Handoff, InteractionCommand::Approve) => {
            Some(InteractionResponse::Handoff {
                response_schema_version: 1,
                completed: true,
                notes: None,
            })
        }
        (InteractionKind::Handoff, InteractionCommand::Reject { reason }) => {
            Some(InteractionResponse::Handoff {
                response_schema_version: 1,
                completed: false,
                notes: Some(reason.clone()),
            })
        }
        (InteractionKind::Handoff, InteractionCommand::Answer { text }) => {
            Some(InteractionResponse::Handoff {
                response_schema_version: 1,
                completed: true,
                notes: Some(text.clone()),
            })
        }
        _ => None,
    }
}

trait InteractionCommandExt {
    fn command_name(&self) -> &'static str;
}

impl InteractionCommandExt for InteractionCommand {
    fn command_name(&self) -> &'static str {
        match self {
            InteractionCommand::Approve => "/approve",
            InteractionCommand::Reject { .. } => "/reject",
            InteractionCommand::Answer { .. } => "/answer",
        }
    }
}

fn sanitize_interaction_fragment(value: &str) -> String {
    value
        .chars()
        .map(|ch| if ch.is_ascii_alphanumeric() { ch } else { '-' })
        .collect()
}

fn interaction_kind_name(kind: &InteractionKind) -> &'static str {
    match kind {
        InteractionKind::Question => "question",
        InteractionKind::Approval => "approval",
        InteractionKind::Handoff => "handoff",
    }
}

fn validate_restored_snapshot_against_config(
    snapshot: &PipelineRunSnapshot,
    config: &EnsembleConfig,
) -> Result<(), EnsembleError> {
    validate_acceptance_attempts(snapshot, config)?;
    for persisted_step in &snapshot.dag_steps {
        if snapshot
            .synthetic_fixup_steps
            .contains(&persisted_step.name)
        {
            continue;
        }

        let Some(config_step) = config
            .steps
            .iter()
            .find(|candidate| candidate.name == persisted_step.name)
        else {
            return Err(AgentError::PromptError {
                reason: format!(
                    "persisted pipeline step '{}' no longer exists in config",
                    persisted_step.name
                ),
            }
            .into());
        };

        if config_step.agent != persisted_step.agent || config_step.kind != persisted_step.kind {
            return Err(AgentError::PromptError {
                reason: format!(
                    "persisted pipeline step '{}' no longer matches config",
                    persisted_step.name
                ),
            }
            .into());
        }
    }

    Ok(())
}

fn legacy_command_plan(config: &EnsembleConfig) -> ResolvedAcceptancePlan {
    ResolvedAcceptancePlan {
        config_digest: String::new(),
        commands: config
            .acceptance
            .commands
            .iter()
            .map(|command| command.name.clone())
            .collect(),
        required_files: Vec::new(),
        required_handoff_sections: Vec::new(),
        required_pull_requests: Vec::new(),
    }
}

fn validate_acceptance_attempts(
    snapshot: &PipelineRunSnapshot,
    config: &EnsembleConfig,
) -> Result<(), EnsembleError> {
    let plan = snapshot
        .resolved_acceptance_plan
        .clone()
        .unwrap_or_else(|| legacy_command_plan(config));
    let mut previous_cycle = 0;
    for attempt in &snapshot.acceptance_attempts {
        if attempt.cycle == 0 || attempt.cycle > snapshot.cycle || attempt.cycle <= previous_cycle {
            return Err(AgentError::PromptError {
                reason: "persisted acceptance attempts have invalid cycle ordering".to_string(),
            }
            .into());
        }
        previous_cycle = attempt.cycle;
        if attempt.cycle != snapshot.cycle {
            continue;
        }
        let pre_final_len = plan.pre_final_len();
        if attempt.results.len() > pre_final_len && plan.required_pull_requests.is_empty() {
            return Err(AgentError::PromptError {
                reason: format!(
                    "persisted acceptance attempt {} has results beyond the frozen acceptance plan",
                    attempt.cycle
                ),
            }
            .into());
        }
        for (index, result) in attempt.results.iter().enumerate() {
            let (expected_name, expected_kind) = if index < plan.commands.len() {
                (&plan.commands[index], "command")
            } else if index < plan.commands.len() + plan.required_files.len() {
                let rule = &plan.required_files[index - plan.commands.len()];
                (&rule.name, "file")
            } else if index < pre_final_len {
                let rule = &plan.required_handoff_sections
                    [index - plan.commands.len() - plan.required_files.len()];
                (&rule.name, "handoff")
            } else {
                let rule_index = (index - pre_final_len) % plan.required_pull_requests.len();
                let rule = &plan.required_pull_requests[rule_index];
                (&rule.name, "pull_request")
            };
            let kind_matches = matches!(
                (&result.evidence, expected_kind),
                (AcceptanceEvidence::Command { .. }, "command")
                    | (AcceptanceEvidence::File { .. }, "file")
                    | (AcceptanceEvidence::Handoff { .. }, "handoff")
                    | (AcceptanceEvidence::PullRequest { .. }, "pull_request")
            );
            if result.name != *expected_name || !kind_matches {
                let noun = if snapshot.resolved_acceptance_plan.is_none() {
                    "configured command"
                } else {
                    "frozen acceptance check"
                };
                return Err(AgentError::PromptError {
                    reason: format!(
                        "persisted acceptance result '{}' no longer matches {noun} '{}'",
                        result.name, expected_name
                    ),
                }
                .into());
            }
        }
    }
    Ok(())
}

