    #[tokio::test]
    async fn worker_identity_quiescing_latch_retains_retry_during_candidate_fetch() {
        let config = Arc::new(RwLock::new(make_config()));
        let fetch_started = Arc::new(tokio::sync::Notify::new());
        let release_fetch = Arc::new(tokio::sync::Notify::new());
        let tracker: Arc<dyn IssueTracker> = Arc::new(BlockingCandidateTracker {
            issues: Arc::new(RwLock::new(vec![test_issue("1", "Todo")])),
            fetch_started: Arc::clone(&fetch_started),
            release_fetch: Arc::clone(&release_fetch),
        });
        let runs = Arc::new(AtomicUsize::new(0));
        let runner: Arc<dyn AgentRunner> = Arc::new(CountingRunner {
            runs: Arc::clone(&runs),
        });
        let dir = tempfile::TempDir::new().unwrap();
        let workspace_mgr = WorkspaceManager::new(dir.path(), None).unwrap();
        let (_shutdown_tx, shutdown_rx) = mpsc::channel(1);
        let orchestrator = Orchestrator::new(
            config,
            tracker,
            runner,
            workspace_mgr,
            dir.path(),
            shutdown_rx,
        );
        let retry = RetryEntry {
            issue_id: "1".to_string(),
            identifier: "repo#1".to_string(),
            attempt: 2,
            due_at_ms: current_time_ms(),
            error: Some("retry".to_string()),
            retry_from_step: None,
            with_fixup: false,
        };
        let original_due_at_ms = retry.due_at_ms;
        install_retry_pipeline_config(&orchestrator, &retry.issue_id).await;
        orchestrator.state.write().await.add_retry(retry.clone());
        let quiescing = orchestrator.quiescing_latch_owner();

        let retry_task = tokio::spawn(async move {
            orchestrator.handle_single_retry(&retry).await;
            orchestrator
        });
        fetch_started.notified().await;
        quiescing.request();
        release_fetch.notify_one();

        let orchestrator = retry_task.await.unwrap();
        let state = orchestrator.state.read().await;
        let retained = state.retry_attempts.get("1").unwrap();
        assert_eq!(retained.attempt, 2);
        assert_eq!(retained.error.as_deref(), Some("orchestrator quiescing"));
        assert!(retained.due_at_ms > original_due_at_ms);
        assert_eq!(runs.load(Ordering::SeqCst), 0);
    }

    async fn create_finalize_repo() -> (tempfile::TempDir, crate::config::ensemble::RepoConfig) {
        let temp = tempfile::TempDir::new().unwrap();
        let repo_path = temp.path().join("source-repo");
        tokio::fs::create_dir_all(&repo_path).await.unwrap();

        for args in [
            vec!["init", "--initial-branch=main"],
            vec!["config", "user.email", "test@example.com"],
            vec!["config", "user.name", "Test User"],
        ] {
            let output = tokio::process::Command::new("git")
                .args(args)
                .current_dir(&repo_path)
                .output()
                .await
                .unwrap();
            assert!(
                output.status.success(),
                "git command failed: {}",
                String::from_utf8_lossy(&output.stderr)
            );
        }

        tokio::fs::write(repo_path.join("README.md"), "# source repo\n")
            .await
            .unwrap();
        for args in [vec!["add", "README.md"], vec!["commit", "-m", "initial"]] {
            let output = tokio::process::Command::new("git")
                .args(args)
                .current_dir(&repo_path)
                .output()
                .await
                .unwrap();
            assert!(
                output.status.success(),
                "git command failed: {}",
                String::from_utf8_lossy(&output.stderr)
            );
        }

        (
            temp,
            crate::config::ensemble::RepoConfig {
                path: repo_path.display().to_string(),
                branch: "main".to_string(),
                git_remote: "origin".to_string(),
                finalize: crate::workspace::finalize::RepoFinalizeConfig {
                    enabled: true,
                    mode: FinalizeMode::Push,
                    approval_required: true,
                },
            },
        )
    }

    struct SuccessfulDeliveryRemote {
        journal: PipelineRunJournal,
        issue_id: String,
        remote_sha: std::sync::Mutex<Option<String>>,
        pull_requests: std::sync::Mutex<Vec<crate::orchestrator::delivery::RemotePullRequest>>,
        mutation_phases: std::sync::Mutex<Vec<crate::orchestrator::delivery::DeliveryPhase>>,
    }

    impl SuccessfulDeliveryRemote {
        async fn latest_phase(&self) -> crate::orchestrator::delivery::DeliveryPhase {
            self.journal
                .latest_live_record_for_issue(&self.issue_id)
                .await
                .unwrap()
                .unwrap()
                .delivery
                .unwrap()
                .repositories
                .get("source-repo")
                .unwrap()
                .phase
        }
    }

    #[async_trait]
    impl crate::orchestrator::delivery::DeliveryRemote for SuccessfulDeliveryRemote {
        async fn local_identity(
            &self,
            _repository_path: &Path,
        ) -> Result<crate::orchestrator::delivery::LocalRepositoryIdentity, String> {
            Ok(crate::orchestrator::delivery::LocalRepositoryIdentity {
                head_branch: "ensemble/repo-1".to_string(),
                local_sha: "0123456789abcdef".to_string(),
            })
        }

        async fn remote_head(
            &self,
            _repository_path: &Path,
            _remote: &str,
            _head_branch: &str,
        ) -> Result<Option<String>, String> {
            Ok(self.remote_sha.lock().unwrap().clone())
        }

        async fn push(
            &self,
            _repository_path: &Path,
            _remote: &str,
            _head_branch: &str,
            local_sha: &str,
        ) -> Result<(), String> {
            assert_eq!(local_sha, "0123456789abcdef");
            let phase = self.latest_phase().await;
            self.mutation_phases.lock().unwrap().push(phase);
            *self.remote_sha.lock().unwrap() = Some("0123456789abcdef".to_string());
            Ok(())
        }

        async fn list_pull_requests(
            &self,
            _repository_path: &Path,
            _repository_key: &str,
            _adoption_policy: Option<&crate::orchestrator::delivery::PullRequestAdoptionPolicy>,
        ) -> Result<Vec<crate::orchestrator::delivery::RemotePullRequest>, String> {
            Ok(self.pull_requests.lock().unwrap().clone())
        }

        async fn create_pull_request(
            &self,
            _repository_path: &Path,
            base_branch: &str,
            head_branch: &str,
            marker: &str,
        ) -> Result<(), String> {
            let phase = self.latest_phase().await;
            self.mutation_phases.lock().unwrap().push(phase);
            self.pull_requests.lock().unwrap().push(
                crate::orchestrator::delivery::RemotePullRequest {
                    repository_key: "source-repo".to_string(),
                    repository: None,
                    head_repository: None,
                    author: None,
                    authored_by_authenticated_viewer: false,
                    head_branch: head_branch.to_string(),
                    base_branch: base_branch.to_string(),
                    head_sha: "0123456789abcdef".to_string(),
                    body: marker.to_string(),
                    number: 420,
                    url: "https://github.com/example/project/pull/420".to_string(),
                },
            );
            Ok(())
        }
    }

    #[tokio::test]
    async fn push_and_pr_persists_delivery_before_remote_mutation_and_releases_worker_capacity() {
        let (repo_temp, mut repo_config) = create_finalize_repo().await;
        repo_config.finalize.mode = FinalizeMode::PushAndPr;
        repo_config.finalize.approval_required = false;
        let mut config = make_config();
        config.delivery_states.waiting = Some("In review".to_string());
        let config = Arc::new(RwLock::new(config));
        let issue = test_issue("1", "Todo");
        let tracker: Arc<dyn IssueTracker> = Arc::new(MockTracker {
            issues: Arc::new(RwLock::new(vec![issue.clone()])),
        });
        let runner: Arc<dyn AgentRunner> = Arc::new(CountingRunner {
            runs: Arc::new(AtomicUsize::new(0)),
        });
        let workspace_temp = tempfile::TempDir::new().unwrap();
        let workspace_mgr =
            WorkspaceManager::new(workspace_temp.path(), Some(vec![repo_config])).unwrap();
        let (_shutdown_tx, shutdown_rx) = mpsc::channel(1);
        let mut orchestrator = Orchestrator::new(
            Arc::clone(&config),
            tracker,
            runner,
            workspace_mgr,
            workspace_temp.path(),
            shutdown_rx,
        );
        let remote = Arc::new(SuccessfulDeliveryRemote {
            journal: orchestrator.pipeline_journal.clone(),
            issue_id: issue.id.clone(),
            remote_sha: std::sync::Mutex::new(None),
            pull_requests: std::sync::Mutex::new(Vec::new()),
            mutation_phases: std::sync::Mutex::new(Vec::new()),
        });
        orchestrator.delivery_remote = remote.clone();
        let review_tracker = Arc::new(ReviewProjectionTracker {
            issues: Arc::new(RwLock::new(vec![issue.clone()])),
            journal: orchestrator.pipeline_journal.clone(),
            issue_id: issue.id.clone(),
            writes: AtomicUsize::new(0),
            saw_in_flight_before_write: AtomicBool::new(false),
            fail_reads: false,
        });
        orchestrator.tracker = review_tracker.clone();

        {
            let cfg = config.read().await;
            let dag = build_dag(&cfg.steps).unwrap();
            let mut run = PipelineRun::new(issue.id.clone(), 1, dag);
            run.start();
            run.mark_running("build", "session-1".to_string());
            let mut state = orchestrator.state.write().await;
            state.add_running(&issue, None);
            state.insert_pipeline_run(&issue.id, run, Arc::new(cfg.clone()));
        }

        orchestrator
            .handle_worker_exit(
                &issue.id,
                "build",
                WorkerResult::Success {
                    output: succeeded_step_output(),
                    approval_request: None,
                },
            )
            .await;

        orchestrator.reconcile_and_recover_deliveries().await;

        let state = orchestrator.state.read().await;
        let delivery = state.delivery.get(&issue.id).expect("delivery owner");
        assert_eq!(
            delivery.repositories["source-repo"].phase,
            crate::orchestrator::delivery::DeliveryPhase::Waiting
        );
        assert_eq!(delivery.repositories["source-repo"].pr_number, Some(420));
        assert!(delivery.terminal_history.is_some());
        assert!(matches!(
            delivery.review_projection.as_ref(),
            Some(crate::orchestrator::delivery::ReviewProjection {
                target,
                phase: crate::orchestrator::delivery::ReviewProjectionPhase::Applied,
                ..
            }) if target == "In review"
        ));
        assert!(!state.is_running(&issue.id));
        assert!(state.is_claimed(&issue.id));
        assert!(!state.completed.contains_key(&issue.id));
        assert_eq!(live_worker_count(&orchestrator.cancellation_registry), 0);
        drop(state);

        assert_eq!(review_tracker.writes.load(Ordering::SeqCst), 1);
        assert!(review_tracker
            .saw_in_flight_before_write
            .load(Ordering::SeqCst));

        assert_eq!(
            *remote.mutation_phases.lock().unwrap(),
            vec![
                crate::orchestrator::delivery::DeliveryPhase::PushInFlight,
                crate::orchestrator::delivery::DeliveryPhase::PrCreateInFlight,
            ]
        );
        let records = orchestrator
            .pipeline_journal
            .read_records_for_issue(&issue.id)
            .await
            .unwrap();
        let prepared = records
            .iter()
            .position(|record| {
                record.delivery.as_ref().is_some_and(|delivery| {
                    delivery.repositories["source-repo"].phase
                        == crate::orchestrator::delivery::DeliveryPhase::Prepared
                })
            })
            .expect("prepared record");
        let first_mutation = records
            .iter()
            .position(|record| {
                record.delivery.as_ref().is_some_and(|delivery| {
                    delivery.repositories["source-repo"].phase
                        == crate::orchestrator::delivery::DeliveryPhase::PushInFlight
                })
            })
            .expect("push in flight record");
        assert!(prepared < first_mutation);

        drop(repo_temp);
    }

    #[tokio::test]
    async fn approval_required_delivery_preserves_terminal_history_before_approval() {
        let (repo_temp, mut repo_config) = create_finalize_repo().await;
        repo_config.finalize.mode = FinalizeMode::PushAndPr;
        repo_config.finalize.approval_required = true;
        let config = Arc::new(RwLock::new(make_config()));
        let issue = test_issue("1", "Todo");
        let tracker_issues = Arc::new(RwLock::new(vec![issue.clone()]));
        let tracker: Arc<dyn IssueTracker> = Arc::new(MockTracker {
            issues: Arc::clone(&tracker_issues),
        });
        let runner: Arc<dyn AgentRunner> = Arc::new(CountingRunner {
            runs: Arc::new(AtomicUsize::new(0)),
        });
        let workspace_temp = tempfile::TempDir::new().unwrap();
        let workspace_mgr =
            WorkspaceManager::new(workspace_temp.path(), Some(vec![repo_config])).unwrap();
        let (_shutdown_tx, shutdown_rx) = mpsc::channel(1);
        let mut orchestrator = Orchestrator::new(
            Arc::clone(&config),
            tracker,
            runner,
            workspace_mgr,
            workspace_temp.path(),
            shutdown_rx,
        );
        let remote = Arc::new(SuccessfulDeliveryRemote {
            journal: orchestrator.pipeline_journal.clone(),
            issue_id: issue.id.clone(),
            remote_sha: std::sync::Mutex::new(None),
            pull_requests: std::sync::Mutex::new(Vec::new()),
            mutation_phases: std::sync::Mutex::new(Vec::new()),
        });
        orchestrator.delivery_remote = remote.clone();

        {
            let cfg = config.read().await;
            let dag = build_dag(&cfg.steps).unwrap();
            let mut run = PipelineRun::new(issue.id.clone(), 1, dag);
            run.start();
            run.mark_running("build", "session-1".to_string());
            let mut state = orchestrator.state.write().await;
            state.add_running(&issue, None);
            state.insert_pipeline_run(&issue.id, run, Arc::new(cfg.clone()));
        }

        orchestrator
            .handle_worker_exit(
                &issue.id,
                "build",
                WorkerResult::Success {
                    output: succeeded_step_output(),
                    approval_request: None,
                },
            )
            .await;

        let state = orchestrator.state.read().await;
        let delivery = state.delivery.get(&issue.id).expect("delivery owner");
        assert!(delivery.terminal_history.is_some());
        assert_eq!(
            delivery.repositories["source-repo"].phase,
            DeliveryPhase::AwaitingApproval
        );
        assert!(delivery.repositories["source-repo"].approval_required);
        assert_eq!(
            state.finalize[&issue.id].status,
            FinalizeStatus::PendingApproval
        );
        assert!(remote.mutation_phases.lock().unwrap().is_empty());
        drop(state);
        let durable = orchestrator
            .pipeline_journal
            .latest_live_record_for_issue(&issue.id)
            .await
            .unwrap()
            .unwrap();
        assert!(durable.snapshot.is_some());
        assert!(durable
            .delivery
            .as_ref()
            .is_some_and(|delivery| delivery.terminal_history.is_some()));

        orchestrator
            .pipeline_journal
            .transaction_append_error_on_call = Some((Arc::new(AtomicUsize::new(0)), 1));
        let (response, result) = tokio::sync::oneshot::channel();
        orchestrator
            .handle_command(OrchestratorCommand::ApproveFinalize {
                command: FinalizeApprovalCommand {
                    issue_id: issue.id.clone(),
                    identifier: issue.identifier.clone(),
                },
                response,
            })
            .await;
        assert!(matches!(
            result.await.unwrap(),
            Err(FinalizeApprovalError::Persistence(_))
        ));
        assert_eq!(
            orchestrator.state.read().await.delivery[&issue.id].repositories["source-repo"].phase,
            DeliveryPhase::AwaitingApproval
        );
        orchestrator
            .pipeline_journal
            .transaction_append_error_on_call = None;
        let mut blocked = orchestrator.state.read().await.delivery[&issue.id].clone();
        let repository = blocked.repositories.get_mut("source-repo").unwrap();
        repository.phase = DeliveryPhase::Blocked;
        repository.retry_from = Some(DeliveryPhase::Prepared);
        repository.last_error = Some("push failed".to_string());
        orchestrator
            .persist_delivery_record(&blocked, None)
            .await
            .unwrap();

        let (response, result) = tokio::sync::oneshot::channel();
        orchestrator
            .handle_command(OrchestratorCommand::ApproveFinalize {
                command: FinalizeApprovalCommand {
                    issue_id: issue.id.clone(),
                    identifier: issue.identifier.clone(),
                },
                response,
            })
            .await;
        assert_eq!(
            result.await.unwrap(),
            Err(FinalizeApprovalError::NotAwaitingApproval)
        );

        let (response, result) = tokio::sync::oneshot::channel();
        orchestrator
            .handle_command(OrchestratorCommand::RetryFinalize {
                command: FinalizeRetryCommand {
                    issue_id: issue.id.clone(),
                    identifier: issue.identifier.clone(),
                },
                response,
            })
            .await;
        assert_eq!(result.await.unwrap(), Ok(()));
        assert_eq!(
            orchestrator.state.read().await.delivery[&issue.id].repositories["source-repo"].phase,
            DeliveryPhase::AwaitingApproval
        );
        assert_eq!(
            orchestrator.state.read().await.delivery[&issue.id].repositories["source-repo"]
                .retry_from,
            Some(DeliveryPhase::Prepared)
        );

        orchestrator.pipeline_journal.transaction_append_late_error = true;
        for newly_approved in [true, false] {
            let (response, result) = tokio::sync::oneshot::channel();
            orchestrator
                .handle_command(OrchestratorCommand::ApproveFinalize {
                    command: FinalizeApprovalCommand {
                        issue_id: issue.id.clone(),
                        identifier: issue.identifier.clone(),
                    },
                    response,
                })
                .await;
            assert_eq!(result.await.unwrap(), Ok(newly_approved));
        }
        orchestrator.pipeline_journal.transaction_append_late_error = false;

        let state = orchestrator.state.read().await;
        assert_eq!(
            state.delivery[&issue.id].repositories["source-repo"].phase,
            DeliveryPhase::Prepared
        );
        assert_eq!(state.finalize[&issue.id].status, FinalizeStatus::InProgress);
        assert!(remote.mutation_phases.lock().unwrap().is_empty());
        drop(state);
        let durable = orchestrator
            .pipeline_journal
            .latest_live_record_for_issue(&issue.id)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(
            durable.delivery.unwrap().repositories["source-repo"].phase,
            DeliveryPhase::Prepared
        );

        orchestrator.reconcile_and_recover_deliveries().await;

        let state = orchestrator.state.read().await;
        let delivery = state.delivery.get(&issue.id).expect("delivery owner");
        assert!(delivery.terminal_history.is_some());
        assert_eq!(
            delivery.repositories["source-repo"].phase,
            DeliveryPhase::Waiting
        );
        drop(state);
        assert_eq!(
            *remote.mutation_phases.lock().unwrap(),
            vec![DeliveryPhase::PushInFlight, DeliveryPhase::PrCreateInFlight,]
        );

        tracker_issues.write().await[0].state = "Done".to_string();
        Box::pin(orchestrator.handle_tick()).await;

        let state = orchestrator.state.read().await;
        assert!(!state.delivery.contains_key(&issue.id));
        assert!(!state.is_claimed(&issue.id));
        assert!(state.completed.contains_key(&issue.id));
        drop(state);
        let history = orchestrator
            .history_store
            .as_ref()
            .unwrap()
            .read_history(&crate::history::reader::HistoryQuery::default())
            .await
            .unwrap();
        assert_eq!(history.total, 1);
        assert_eq!(history.records[0].outcome, HISTORY_OUTCOME_SUCCEEDED);

        drop(repo_temp);
    }

    struct RecoveryDeliveryRemote {
        pull_requests: std::sync::Mutex<Vec<crate::orchestrator::delivery::RemotePullRequest>>,
        pushes: AtomicUsize,
        creates: AtomicUsize,
        lists: AtomicUsize,
    }

    struct FailOnceIdentityRemote {
        inner: RecoveryDeliveryRemote,
        identity_failures: AtomicUsize,
    }

    struct SequencedObservationRemote {
        inner: Arc<RecoveryDeliveryRemote>,
        observations: std::sync::Mutex<
            Vec<crate::orchestrator::delivery_observation::DeliveryObservationRead>,
        >,
    }

    struct ReviewProjectionTracker {
        issues: Arc<RwLock<Vec<Issue>>>,
        journal: PipelineRunJournal,
        issue_id: String,
        writes: AtomicUsize,
        saw_in_flight_before_write: AtomicBool,
        fail_reads: bool,
    }

    #[async_trait]
    impl IssueTracker for ReviewProjectionTracker {
        async fn fetch_candidate_issues(&self) -> Result<Vec<Issue>, crate::tracker::TrackerError> {
            Ok(self.issues.read().await.clone())
        }

        async fn fetch_issues_by_states(
            &self,
            states: &[String],
        ) -> Result<Vec<Issue>, crate::tracker::TrackerError> {
            let issues = self.issues.read().await;
            Ok(issues
                .iter()
                .filter(|issue| {
                    states
                        .iter()
                        .any(|state| state.eq_ignore_ascii_case(&issue.state))
                })
                .cloned()
                .collect())
        }

        async fn fetch_issue_states_by_ids(
            &self,
            ids: &[String],
        ) -> Result<Vec<Issue>, crate::tracker::TrackerError> {
            if self.fail_reads {
                return Err(crate::tracker::TrackerError::ApiRequestFailed {
                    reason: "simulated tracker read failure".to_string(),
                });
            }
            let issues = self.issues.read().await;
            Ok(issues
                .iter()
                .filter(|issue| ids.contains(&issue.id))
                .cloned()
                .collect())
        }

        fn supports_writes(&self) -> bool {
            true
        }

        async fn set_issue_state(
            &self,
            id: &str,
            state: &str,
        ) -> Result<(), crate::tracker::TrackerError> {
            let latest = self
                .journal
                .latest_live_record_for_issue(&self.issue_id)
                .await
                .unwrap()
                .unwrap();
            self.saw_in_flight_before_write.store(
                latest.delivery.as_ref().is_some_and(|delivery| {
                    delivery
                        .review_projection
                        .as_ref()
                        .is_some_and(|projection| {
                            projection.phase
                                == crate::orchestrator::delivery::ReviewProjectionPhase::InFlight
                                && !projection.history_persisted
                        })
                }),
                Ordering::SeqCst,
            );
            self.writes.fetch_add(1, Ordering::SeqCst);
            let mut issues = self.issues.write().await;
            issues
                .iter_mut()
                .find(|issue| issue.id == id)
                .expect("tracker owns issue")
                .state = state.to_string();
            Ok(())
        }
    }

