    async fn finalize_retry_requeues_a_blocked_review_projection() {
        let remote = Arc::new(RecoveryDeliveryRemote {
            pull_requests: std::sync::Mutex::new(Vec::new()),
            pushes: AtomicUsize::new(0),
            creates: AtomicUsize::new(0),
            lists: AtomicUsize::new(0),
        });
        let (mut orchestrator, _workspace, _repo, delivery) =
            recovery_test_orchestrator(remote).await;
        orchestrator.tracker = Arc::new(ReviewProjectionTracker {
            issues: Arc::new(RwLock::new(vec![test_issue("1", "In Progress")])),
            journal: orchestrator.pipeline_journal.clone(),
            issue_id: "1".to_string(),
            writes: AtomicUsize::new(0),
            saw_in_flight_before_write: AtomicBool::new(false),
            fail_reads: true,
        });
        let delivery = review_ready_delivery(delivery);
        orchestrator
            .persist_delivery_record(&delivery, None)
            .await
            .unwrap();
        let blocked = orchestrator.advance_review_projection(delivery).await;
        assert_eq!(
            blocked.review_projection.as_ref().unwrap().phase,
            crate::orchestrator::delivery::ReviewProjectionPhase::Blocked
        );

        assert_eq!(
            orchestrator
                .retry_finalize_delivery("1", &blocked.identifier)
                .await,
            Ok(())
        );

        let state = orchestrator.state.read().await;
        let projection = state.delivery["1"].review_projection.as_ref().unwrap();
        assert_eq!(
            projection.phase,
            crate::orchestrator::delivery::ReviewProjectionPhase::Pending
        );
        assert!(projection.diagnostic.is_none());
        assert_eq!(state.finalize["1"].status, FinalizeStatus::InProgress);
    }

    #[tokio::test]
    async fn finalize_retry_requeues_a_closed_delivery_without_republishing() {
        let remote = Arc::new(RecoveryDeliveryRemote {
            pull_requests: std::sync::Mutex::new(Vec::new()),
            pushes: AtomicUsize::new(0),
            creates: AtomicUsize::new(0),
            lists: AtomicUsize::new(0),
        });
        let (orchestrator, _workspace, _repo, mut delivery) =
            recovery_test_orchestrator(remote.clone()).await;
        let reporter = orchestrator.attention_reporter.clone().unwrap();
        let repository = delivery.repositories.get_mut("source-repo").unwrap();
        repository.phase = DeliveryPhase::Waiting;
        repository.pr_number = Some(420);
        repository.pr_url = Some("https://github.com/example/project/pull/420".to_string());
        repository.observation = Some(DeliveryObservation::successful(
            DeliveryObservationFacts {
                pull_request_number: 420,
                pull_request_url: "https://github.com/example/project/pull/420".to_string(),
                head_sha: repository.local_sha.clone(),
                matches_delivery: true,
                head_diverged: false,
                terminal_state: PullRequestTerminalState::ClosedWithoutMerge,
                mergeability: Mergeability::Mergeable,
                base_freshness: BaseFreshness::UpToDate,
                checks: vec![],
                check_summary: CheckSummary::Passing,
                review_decision: ReviewDecision::Approved,
            },
            Utc::now(),
        ));
        delivery.closed_without_merge_parked = false;
        delivery.review_projection = Some(crate::orchestrator::delivery::ReviewProjection {
            target: "Closed without merge".to_string(),
            repositories: vec!["source-repo".to_string()],
            phase: crate::orchestrator::delivery::ReviewProjectionPhase::Applied,
            diagnostic: None,
            last_observed_state: Some("Closed without merge".to_string()),
            history_record: None,
            history_persisted: false,
        });
        let delivery = orchestrator.park_closed_without_merge(delivery).await;
        assert_eq!(reporter.items_for_subject("1").await.unwrap().len(), 1);

        assert_eq!(
            orchestrator
                .retry_finalize_delivery("1", &delivery.identifier)
                .await,
            Ok(())
        );

        let retained = orchestrator.state.read().await.delivery["1"].clone();
        let repository = &retained.repositories["source-repo"];
        assert!(retained.closed_without_merge_parked);
        assert!(retained.review_projection.is_none());
        assert!(retained.selected_delivery_state.is_none());
        assert!(repository.observation.is_none());
        assert_eq!(repository.pr_number, Some(420));
        assert_eq!(repository.phase, DeliveryPhase::Waiting);
        assert_eq!(remote.pushes.load(Ordering::SeqCst), 0);
        assert_eq!(remote.creates.load(Ordering::SeqCst), 0);
        assert_eq!(remote.lists.load(Ordering::SeqCst), 0);

        let mut fresh = retained;
        fresh
            .repositories
            .get_mut("source-repo")
            .unwrap()
            .observation = Some(DeliveryObservation::successful(
            DeliveryObservationFacts {
                pull_request_number: 420,
                pull_request_url: "https://github.com/example/project/pull/420".to_string(),
                head_sha: "0123456789abcdef".to_string(),
                matches_delivery: true,
                head_diverged: false,
                terminal_state: PullRequestTerminalState::Open,
                mergeability: Mergeability::Mergeable,
                base_freshness: BaseFreshness::UpToDate,
                checks: vec![],
                check_summary: CheckSummary::Passing,
                review_decision: ReviewDecision::ReviewRequired,
            },
            Utc::now(),
        ));
        let resolved = orchestrator.clear_closed_without_merge_park(fresh).await;
        assert!(!resolved.closed_without_merge_parked);
        assert!(reporter.items_for_subject("1").await.unwrap().is_empty());
    }

    #[tokio::test]
    async fn closed_delivery_retry_keeps_attention_until_fresh_open_observation() {
        let inner = Arc::new(RecoveryDeliveryRemote {
            pull_requests: std::sync::Mutex::new(Vec::new()),
            pushes: AtomicUsize::new(0),
            creates: AtomicUsize::new(0),
            lists: AtomicUsize::new(0),
        });
        let (mut orchestrator, _workspace, _repo, mut delivery) =
            recovery_test_orchestrator(inner.clone()).await;
        let reporter = orchestrator.attention_reporter.clone().unwrap();
        let repository = delivery.repositories.get_mut("source-repo").unwrap();
        repository.phase = DeliveryPhase::Waiting;
        repository.pr_number = Some(420);
        repository.pr_url = Some("https://github.com/example/project/pull/420".to_string());
        repository.observation = Some(DeliveryObservation::successful(
            DeliveryObservationFacts {
                pull_request_number: 420,
                pull_request_url: "https://github.com/example/project/pull/420".to_string(),
                head_sha: repository.local_sha.clone(),
                matches_delivery: true,
                head_diverged: false,
                terminal_state: PullRequestTerminalState::ClosedWithoutMerge,
                mergeability: Mergeability::Mergeable,
                base_freshness: BaseFreshness::UpToDate,
                checks: vec![],
                check_summary: CheckSummary::Passing,
                review_decision: ReviewDecision::Approved,
            },
            Utc::now(),
        ));
        let delivery = orchestrator.park_closed_without_merge(delivery).await;
        assert_eq!(reporter.items_for_subject("1").await.unwrap().len(), 1);
        orchestrator
            .retry_finalize_delivery("1", &delivery.identifier)
            .await
            .unwrap();
        let retryable = crate::orchestrator::delivery_observation::DeliveryObservationRead::Retryable(
            crate::orchestrator::delivery_observation::DeliveryObservationFailure::new(crate::orchestrator::delivery_observation::DeliveryObservationFailureKind::Transport, "retry"));
        let open = crate::orchestrator::delivery_observation::DeliveryObservationRead::Observed(
            DeliveryObservationFacts {
                pull_request_number: 420,
                pull_request_url: "https://github.com/example/project/pull/420".to_string(),
                head_sha: "0123456789abcdef".to_string(),
                matches_delivery: true,
                head_diverged: false,
                terminal_state: PullRequestTerminalState::Open,
                mergeability: Mergeability::Mergeable,
                base_freshness: BaseFreshness::UpToDate,
                checks: vec![],
                check_summary: CheckSummary::Passing,
                review_decision: ReviewDecision::ReviewRequired,
            },
        );
        orchestrator.delivery_remote = Arc::new(SequencedObservationRemote {
            inner: inner.clone(),
            observations: std::sync::Mutex::new(vec![retryable, open]),
        });
        orchestrator.config.write().await.tracker.kind = "github".to_string();
        let workspace = orchestrator
            .workspace_mgr
            .prepare_workspace("1", "repo#1")
            .await
            .unwrap();
        assert!(workspace.worktrees.contains_key("source-repo"));
        orchestrator.reconcile_and_recover_deliveries().await;
        assert!(orchestrator.state.read().await.delivery["1"].closed_without_merge_parked);
        assert_eq!(reporter.items_for_subject("1").await.unwrap().len(), 1);
        let mut due = orchestrator.state.read().await.delivery["1"].clone();
        due.repositories
            .get_mut("source-repo")
            .unwrap()
            .observation
            .as_mut()
            .unwrap()
            .retry
            .as_mut()
            .unwrap()
            .due_at = Utc::now();
        orchestrator
            .persist_delivery_record(&due, None)
            .await
            .unwrap();
        orchestrator.reconcile_and_recover_deliveries().await;
        let retained = orchestrator.state.read().await.delivery["1"].clone();
        assert!(!retained.closed_without_merge_parked);
        assert_eq!(retained.repositories["source-repo"].pr_number, Some(420));
        assert!(reporter.items_for_subject("1").await.unwrap().is_empty());
        assert_eq!(inner.pushes.load(Ordering::SeqCst), 0);
        assert_eq!(inner.creates.load(Ordering::SeqCst), 0);
        assert_eq!(inner.lists.load(Ordering::SeqCst), 0);
    }

    #[tokio::test]
    async fn finalize_retry_reconstructs_pre_delivery_approval_failure() {
        let remote = Arc::new(FailOnceIdentityRemote {
            inner: RecoveryDeliveryRemote {
                pull_requests: std::sync::Mutex::new(Vec::new()),
                pushes: AtomicUsize::new(0),
                creates: AtomicUsize::new(0),
                lists: AtomicUsize::new(0),
            },
            identity_failures: AtomicUsize::new(1),
        });
        let (repo_temp, mut repo_config) = create_finalize_repo().await;
        repo_config.finalize.mode = FinalizeMode::PushAndPr;
        repo_config.finalize.approval_required = true;
        let config = Arc::new(RwLock::new(make_config()));
        let tracker: Arc<dyn IssueTracker> = Arc::new(MockTracker {
            issues: Arc::new(RwLock::new(vec![test_issue("1", "Todo")])),
        });
        let runner: Arc<dyn AgentRunner> = Arc::new(CountingRunner {
            runs: Arc::new(AtomicUsize::new(0)),
        });
        let workspace_temp = tempfile::TempDir::new().unwrap();
        let workspace_mgr =
            WorkspaceManager::new(workspace_temp.path(), Some(vec![repo_config])).unwrap();
        let (_shutdown_tx, shutdown_rx) = mpsc::channel(1);
        let mut orchestrator = Orchestrator::new(
            Arc::clone(&config),
            tracker,
            runner,
            workspace_mgr,
            workspace_temp.path(),
            shutdown_rx,
        );
        orchestrator.delivery_remote = remote.clone();
        {
            let cfg = config.read().await;
            let dag = build_dag(&cfg.steps).unwrap();
            let mut run = PipelineRun::new("1".to_string(), 1, dag);
            run.start();
            run.mark_running("build", "session-1".to_string());
            run.step_completed("build", succeeded_step_output(), false);
            let mut state = orchestrator.state.write().await;
            state.add_running(&test_issue("1", "Todo"), None);
            state.insert_pipeline_run("1", run, Arc::new(cfg.clone()));
        }
        let config_snapshot = config.read().await.clone();
        let finalize = orchestrator
            .run_finalize_phase("1", "repo#1", &config_snapshot)
            .await;
        assert_eq!(finalize.status, FinalizeStatus::Failed);
        assert!(orchestrator
            .state
            .read()
            .await
            .finalize_terminal_history
            .contains_key("1"));
        {
            let mut state = orchestrator.state.write().await;
            state.remove_running("1");
            state.remove_pipeline_run("1");
            state.set_finalize_state("1", finalize);
        }

        orchestrator
            .retry_finalize_delivery("1", "repo#1")
            .await
            .unwrap();
        assert_eq!(
            orchestrator.state.read().await.finalize["1"].status,
            FinalizeStatus::InProgress
        );

        orchestrator.process_finalize_retries().await;

        let state = orchestrator.state.read().await;
        assert_eq!(state.finalize["1"].status, FinalizeStatus::PendingApproval);
        assert_eq!(
            state.delivery["1"].repositories["source-repo"].phase,
            DeliveryPhase::AwaitingApproval
        );
        assert!(state.delivery["1"].terminal_history.is_some());
        assert!(!state.finalize_terminal_history.contains_key("1"));
        drop(state);
        assert_eq!(
            orchestrator.approve_finalize_delivery("1", "repo#1").await,
            Ok(true)
        );
        assert_eq!(remote.inner.pushes.load(Ordering::SeqCst), 0);

        drop(repo_temp);
    }

    fn post_finalize_acceptance_snapshot(
        rule_names: &[&str],
        results: Vec<crate::acceptance::AcceptanceResult>,
    ) -> PipelineRunSnapshot {
        let config = make_config();
        let dag = build_dag(&config.steps).unwrap();
        let mut run = PipelineRun::new("1".into(), 1, dag);
        run.resolved_acceptance_plan = Some(ResolvedAcceptancePlan {
            config_digest: "frozen".into(),
            commands: Vec::new(),
            required_files: Vec::new(),
            required_handoff_sections: Vec::new(),
            required_pull_requests: rule_names
                .iter()
                .map(
                    |name| crate::config::ensemble::AcceptancePullRequestConfig {
                        name: (*name).into(),
                        repo: "source-repo".into(),
                    },
                )
                .collect(),
        });
        run.acceptance_attempts = vec![crate::acceptance::AcceptanceAttempt { cycle: 1, results }];
        run.to_snapshot()
    }

    fn retained_pr_result(
        name: &str,
        status: AcceptanceStatus,
    ) -> crate::acceptance::AcceptanceResult {
        crate::acceptance::AcceptanceResult::new(
            name.into(),
            status,
            format!("{name}: {status:?}"),
            AcceptanceEvidence::PullRequest {
                repo: "source-repo".into(),
                delivery_phase: crate::acceptance::PullRequestDeliveryPhase::Waiting,
                base_branch: Some("main".into()),
                head_branch: Some("ensemble/repo-1".into()),
                head_sha: Some("0123456789abcdef".into()),
                pr_number: Some(420),
                pr_url: Some("https://github.com/example/project/pull/420".into()),
            },
        )
    }

    #[tokio::test]
    async fn post_finalize_acceptance_resumes_partial_batch_without_remote_calls() {
        let remote = Arc::new(RecoveryDeliveryRemote {
            pull_requests: std::sync::Mutex::new(Vec::new()),
            pushes: AtomicUsize::new(0),
            creates: AtomicUsize::new(0),
            lists: AtomicUsize::new(0),
        });
        let (orchestrator, _workspace, _repo, mut delivery) =
            recovery_test_orchestrator(Arc::clone(&remote)).await;
        let repository = delivery.repositories.get_mut("source-repo").unwrap();
        repository.phase = DeliveryPhase::Waiting;
        repository.pr_number = Some(420);
        repository.pr_url = Some("https://github.com/example/project/pull/420".into());
        repository.last_error = None;
        let snapshot = post_finalize_acceptance_snapshot(
            &["first", "second"],
            vec![retained_pr_result("first", AcceptanceStatus::Passed)],
        );
        orchestrator
            .persist_delivery_record(&delivery, Some(&snapshot))
            .await
            .unwrap();

        let evaluated = orchestrator
            .evaluate_post_final_acceptance(delivery.clone(), Some(&snapshot))
            .await;

        assert_eq!(evaluated, delivery);
        let latest = orchestrator
            .pipeline_journal
            .latest_live_record_for_issue("1")
            .await
            .unwrap()
            .unwrap();
        let results = &latest.snapshot.unwrap().acceptance_attempts[0].results;
        assert_eq!(
            results
                .iter()
                .map(|result| result.name.as_str())
                .collect::<Vec<_>>(),
            vec!["first", "second"]
        );
        assert_eq!(remote.lists.load(Ordering::SeqCst), 0);
        assert_eq!(remote.creates.load(Ordering::SeqCst), 0);
        assert_eq!(remote.pushes.load(Ordering::SeqCst), 0);
    }

