    #[tokio::test]
    async fn startup_attention_reconciliation_retries_terminal_records_after_a_read_failure() {
        let temp = tempfile::tempdir().unwrap();
        let cfg = make_config();
        let issue = test_issue("attention-retry", "Todo");
        let (mut orchestrator, _) = make_restart_test_orchestrator(&temp, &cfg, &issue);
        let mut interaction = test_question_interaction(&issue, 1, "attention-retry");
        let reporter = AttentionReporter::new(orchestrator.history_store.clone().unwrap());
        reporter
            .upsert_open(awaiting_interaction_observation(&interaction).unwrap())
            .await
            .unwrap();
        interaction.status = InteractionStatus::Resolved;
        interaction.resolved_at = Some(Utc::now());
        orchestrator
            .interaction_store
            .create(interaction)
            .await
            .unwrap();

        orchestrator.attention_reporter = Some(AttentionReporter::new(HistoryStore {
            db_path: temp.path().join("missing/history.db"),
        }));
        orchestrator.hydrate_waiting_on_human_from_store().await;

        assert!(!orchestrator
            .attention_reconciled_on_startup
            .load(Ordering::Acquire));

        orchestrator.attention_reporter = Some(reporter.clone());
        orchestrator.hydrate_waiting_on_human_from_store().await;

        assert!(orchestrator
            .attention_reconciled_on_startup
            .load(Ordering::Acquire));
        assert!(reporter.open_items().await.unwrap().is_empty());
    }

    fn make_retry_step_config() -> EnsembleConfig {
        let yaml = r#"
tracker:
  kind: todo_file
  active_states: ["Todo", "In Progress"]
  terminal_states: ["Done", "Closed"]
agents:
  builder:
    executor: claude
    model: opus
    prompt: "Work on {{ issue.identifier }}."
steps:
  - name: build
    agent: builder
    on_failure: retry_step
  - name: test
    agent: builder
max_cycles: 10
on_success: Done
on_failure: Todo
concurrency:
  max_concurrent_agents: 5
polling:
  interval_ms: 100
workspace:
  root: /tmp/ensemble-test
agent:
  command: "echo test"
  session_mode: code
  permission_request_policy:
    mode: approve_all
  turn_timeout_ms: 30000
  read_timeout_ms: 5000
  max_retry_backoff_ms: 300000
  stall_timeout_ms: 300000
"#;
        parse_config(yaml).unwrap()
    }

    fn make_restart_test_orchestrator(
        temp: &tempfile::TempDir,
        cfg: &EnsembleConfig,
        issue: &Issue,
    ) -> (Orchestrator, Arc<RwLock<OrchestratorState>>) {
        let runner: Arc<dyn AgentRunner> = Arc::new(MockRunner {
            delay_ms: 0,
            observed_commands: None,
            observed_timeouts: None,
            cancellation_probe: None,
        });
        make_restart_test_orchestrator_with_runner(temp, cfg, issue, runner)
    }

    fn make_restart_test_orchestrator_with_runner(
        temp: &tempfile::TempDir,
        cfg: &EnsembleConfig,
        issue: &Issue,
        runner: Arc<dyn AgentRunner>,
    ) -> (Orchestrator, Arc<RwLock<OrchestratorState>>) {
        let tracker: Arc<dyn IssueTracker> = Arc::new(MockTracker {
            issues: Arc::new(RwLock::new(vec![issue.clone()])),
        });
        let state = Arc::new(RwLock::new(OrchestratorState::new(
            cfg.polling.interval_ms,
            &cfg.concurrency,
        )));
        let workspace_root = temp.path().join("workspaces");
        let (_shutdown_tx, shutdown_rx) = mpsc::channel(1);
        let orchestrator = Orchestrator::new_with_state(
            OrchestratorRuntimeParts {
                state: Arc::clone(&state),
                config: Arc::new(RwLock::new(cfg.clone())),
                tracker,
                agent_runner: runner,
                acceptance_runner: Arc::new(ShellAcceptanceCommandRunner),
                workspace_mgr: WorkspaceManager::new(&workspace_root, Some(cfg.repos.clone()))
                    .unwrap(),
                refresh_requested: Arc::new(tokio::sync::Notify::new()),
                cancellation_registry: new_cancellation_registry(),
                event_bus: EventBus::new(),
                transcript_event_bus: TranscriptEventBus::new(),
                workspace_root,
            },
            temp.path(),
            shutdown_rx,
        );
        (orchestrator, state)
    }

