    fn make_acceptance_test_orchestrator(
        temp: &tempfile::TempDir,
        cfg: &EnsembleConfig,
        issue: &Issue,
        acceptance_runner: Arc<dyn AcceptanceCommandRunner>,
    ) -> (Orchestrator, Arc<RwLock<OrchestratorState>>) {
        let tracker: Arc<dyn IssueTracker> = Arc::new(MockTracker {
            issues: Arc::new(RwLock::new(vec![issue.clone()])),
        });
        let state = Arc::new(RwLock::new(OrchestratorState::new(
            cfg.polling.interval_ms,
            &cfg.concurrency,
        )));
        let workspace_root = temp.path().join("workspaces");
        let (_shutdown_tx, shutdown_rx) = mpsc::channel(1);
        let orchestrator = Orchestrator::new_with_state(
            OrchestratorRuntimeParts {
                state: Arc::clone(&state),
                config: Arc::new(RwLock::new(cfg.clone())),
                tracker,
                agent_runner: Arc::new(MockRunner {
                    delay_ms: 0,
                    observed_commands: None,
                    observed_timeouts: None,
                    cancellation_probe: None,
                }),
                acceptance_runner,
                workspace_mgr: WorkspaceManager::new(&workspace_root, Some(cfg.repos.clone()))
                    .unwrap(),
                refresh_requested: Arc::new(tokio::sync::Notify::new()),
                cancellation_registry: new_cancellation_registry(),
                event_bus: EventBus::new(),
                transcript_event_bus: TranscriptEventBus::new(),
                workspace_root,
            },
            temp.path(),
            shutdown_rx,
        );
        (orchestrator, state)
    }

    fn acceptance_config(names: &[&str]) -> EnsembleConfig {
        let mut config = make_config();
        config.acceptance.commands = names
            .iter()
            .map(|name| crate::config::ensemble::AcceptanceCommandConfig {
                name: (*name).to_string(),
                run: format!("run-{name}"),
                timeout_ms: 1_000,
            })
            .collect();
        config
    }

    fn acceptance_command_result(
        name: &str,
        status: AcceptanceStatus,
        summary: String,
    ) -> crate::acceptance::AcceptanceResult {
        crate::acceptance::AcceptanceResult::command(
            name.to_string(),
            status.clone(),
            summary,
            (status == AcceptanceStatus::Passed).then_some(0),
            crate::acceptance::AcceptanceOutput {
                tail: String::new(),
                total_bytes: 0,
                truncated: false,
            },
            crate::acceptance::AcceptanceOutput {
                tail: String::new(),
                total_bytes: 0,
                truncated: false,
            },
        )
    }

    async fn install_succeeded_run(
        state: &Arc<RwLock<OrchestratorState>>,
        issue: &Issue,
        config: &EnsembleConfig,
    ) {
        let dag = build_dag(&config.steps).unwrap();
        let mut run = PipelineRun::new(issue.id.clone(), 1, dag);
        run.resolved_acceptance_plan = Some(ResolvedAcceptancePlan::from_config(config).unwrap());
        for step in run.step_states.values_mut() {
            *step = StepState::Passed;
        }
        let mut state = state.write().await;
        state.insert_pipeline_run(&issue.id, run, Arc::new(config.clone()));
        state.add_running(issue, None);
    }

    async fn install_acceptance_started(
        orchestrator: &Orchestrator,
        state: &Arc<RwLock<OrchestratorState>>,
        issue: &Issue,
    ) {
        let transition = {
            let mut state = state.write().await;
            let run = state.get_pipeline_run_mut(&issue.id).unwrap();
            run.acceptance_attempts
                .push(crate::acceptance::AcceptanceAttempt {
                    cycle: run.cycle,
                    results: Vec::new(),
                });
            Orchestrator::transition_input_for_run(
                &state,
                &issue.id,
                &issue.identifier,
                PipelineTransitionKind::AcceptanceStarted,
                None,
                None,
                None,
            )
            .unwrap()
        };
        orchestrator
            .pipeline_journal
            .append(transition)
            .await
            .unwrap();
    }

    async fn install_acceptance_waiting_owner(
        orchestrator: &Orchestrator,
        state: &Arc<RwLock<OrchestratorState>>,
        issue: &Issue,
        interaction_id: &str,
    ) {
        let mut interaction = test_question_interaction(issue, 1, interaction_id);
        interaction.status = InteractionStatus::Resolved;
        interaction.awaiting_resume = true;
        interaction.response = Some(InteractionResponse::Question {
            response_schema_version: 1,
            text: "continue".to_string(),
            selected_option: None,
        });
        interaction.resolved_at = Some(Utc::now());
        orchestrator
            .interaction_store
            .create(interaction.clone())
            .await
            .unwrap();
        let mut state = state.write().await;
        let running = state.remove_running(&issue.id).unwrap();
        state.add_waiting_on_human(WaitingOnHumanEntry {
            issue_id: issue.id.clone(),
            identifier: issue.identifier.clone(),
            interaction_request_id: interaction_id.to_string(),
            step_name: "build".to_string(),
            kind: InteractionKind::Question,
            prompt: "continue".to_string(),
            agent_name: "builder".to_string(),
            retry_attempt: Some(1),
            started_at: Some(running.started_at),
            agent_input_tokens: 0,
            agent_output_tokens: 0,
            agent_total_tokens: 0,
            requested_at: interaction.requested_at,
            run_id: running.run_id,
            issue: Some(issue.clone()),
        });
    }

    #[tokio::test]
    async fn acceptance_runs_all_commands_in_order_and_journals_before_advancing() {
        let temp = tempfile::TempDir::new().unwrap();
        let issue = test_issue("acceptance-order", "In Progress");
        let config = acceptance_config(&["first", "second", "third"]);
        let calls = Arc::new(std::sync::Mutex::new(Vec::new()));
        let runner = Arc::new(RecordingAcceptanceRunner {
            statuses: std::sync::Mutex::new(
                [
                    AcceptanceStatus::Failed,
                    AcceptanceStatus::Passed,
                    AcceptanceStatus::TimedOut,
                ]
                .into(),
            ),
            calls: Arc::clone(&calls),
        });
        let (orchestrator, state) =
            make_acceptance_test_orchestrator(&temp, &config, &issue, runner);
        install_succeeded_run(&state, &issue, &config).await;

        let outcome = orchestrator.run_acceptance_phase(&issue, &config).await;

        assert!(matches!(outcome, AcceptancePhaseOutcome::Failed { .. }));
        assert_eq!(
            *calls
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner()),
            vec!["first", "second", "third"]
        );
        let records = orchestrator
            .pipeline_journal
            .read_records_for_issue(&issue.id)
            .await
            .unwrap();
        assert_eq!(records[0].kind, PipelineTransitionKind::AcceptanceStarted);
        assert!(records[1..]
            .iter()
            .all(|record| record.kind == PipelineTransitionKind::AcceptanceCheckCompleted));
        for pair in records.windows(2) {
            assert!(pair[0].seq < pair[1].seq);
            assert!(
                pair[0].snapshot.as_ref().unwrap().acceptance_attempts[0]
                    .results
                    .len()
                    < pair[1].snapshot.as_ref().unwrap().acceptance_attempts[0]
                        .results
                        .len()
            );
        }
    }

    #[tokio::test]
    async fn acceptance_creates_a_durable_attempt_for_a_pull_request_only_plan() {
        let temp = tempfile::TempDir::new().unwrap();
        let issue = test_issue("acceptance-pr-only", "In Progress");
        let mut config = acceptance_config(&[]);
        let mut repo = crate::config::ensemble::RepoConfig {
            path: "/tmp/primary".into(),
            branch: "main".into(),
            git_remote: "origin".into(),
            finalize: Default::default(),
        };
        repo.finalize.mode = crate::workspace::finalize::FinalizeMode::PushAndPr;
        config.repos = vec![repo];
        config.acceptance.required_pull_requests =
            vec![crate::config::ensemble::AcceptancePullRequestConfig {
                name: "primary-pr".into(),
                repo: "primary".into(),
            }];
        let runner = Arc::new(RecordingAcceptanceRunner {
            statuses: std::sync::Mutex::new(Default::default()),
            calls: Arc::new(std::sync::Mutex::new(Vec::new())),
        });
        let (orchestrator, state) =
            make_acceptance_test_orchestrator(&temp, &config, &issue, runner);
        install_succeeded_run(&state, &issue, &config).await;

        let outcome = orchestrator.run_acceptance_phase(&issue, &config).await;

        assert!(matches!(outcome, AcceptancePhaseOutcome::Passed));
        let state = state.read().await;
        let attempts = &state
            .get_pipeline_run(&issue.id)
            .unwrap()
            .acceptance_attempts;
        assert_eq!(attempts.len(), 1);
        assert_eq!(attempts[0].cycle, 1);
        assert!(attempts[0].results.is_empty());
        drop(state);
        let records = orchestrator
            .pipeline_journal
            .read_records_for_issue(&issue.id)
            .await
            .unwrap();
        assert_eq!(records.len(), 1);
        assert_eq!(records[0].kind, PipelineTransitionKind::AcceptanceStarted);
    }

    fn mixed_acceptance_config() -> EnsembleConfig {
        let mut config = acceptance_config(&["command"]);
        config.repos = vec![crate::config::ensemble::RepoConfig {
            path: "/tmp/repo".into(),
            branch: "main".into(),
            git_remote: "origin".into(),
            finalize: Default::default(),
        }];
        config.acceptance.required_files = vec![crate::config::ensemble::AcceptanceFileConfig {
            name: "file".into(),
            repo: "repo".into(),
            path: "artifact.txt".into(),
        }];
        config.acceptance.required_handoff_sections =
            vec![crate::config::ensemble::AcceptanceHandoffConfig {
                name: "handoff".into(),
                step: "build".into(),
                sections: vec!["summary".into()],
            }];
        config
    }

    #[tokio::test]
    async fn acceptance_runs_the_complete_mixed_prefix_in_frozen_order() {
        let temp = tempfile::TempDir::new().unwrap();
        let issue = test_issue("acceptance-mixed", "In Progress");
        let config = mixed_acceptance_config();
        let calls = Arc::new(std::sync::Mutex::new(Vec::new()));
        let runner = Arc::new(RecordingAcceptanceRunner {
            statuses: std::sync::Mutex::new([AcceptanceStatus::Failed].into()),
            calls: Arc::clone(&calls),
        });
        let (orchestrator, state) =
            make_acceptance_test_orchestrator(&temp, &config, &issue, runner);
        install_succeeded_run(&state, &issue, &config).await;
        state
            .write()
            .await
            .get_pipeline_run_mut(&issue.id)
            .unwrap()
            .step_outputs
            .insert(
                "build".into(),
                crate::pipeline::verdict::StepOutput {
                    result: StepResult::Succeeded,
                    summary: None,
                    output: Some(serde_json::json!({"summary": "done"})),
                },
            );

        let outcome = orchestrator.run_acceptance_phase(&issue, &config).await;

        assert!(matches!(outcome, AcceptancePhaseOutcome::Failed { .. }));
        assert_eq!(
            *calls
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner()),
            vec!["command"]
        );
        let state = state.read().await;
        let results = &state
            .get_pipeline_run(&issue.id)
            .unwrap()
            .acceptance_attempts[0]
            .results;
        assert_eq!(
            results
                .iter()
                .map(|result| result.name.as_str())
                .collect::<Vec<_>>(),
            vec!["command", "file", "handoff"]
        );
        assert!(matches!(
            results[0].evidence,
            AcceptanceEvidence::Command { .. }
        ));
        assert!(matches!(
            results[1].evidence,
            AcceptanceEvidence::File { .. }
        ));
        assert!(matches!(
            results[2].evidence,
            AcceptanceEvidence::Handoff { .. }
        ));
    }

