    #[tokio::test]
    async fn state_worker_dispatch_resume_uses_latest_reconciled_state() {
        let mut raw_config = make_config();
        raw_config.concurrency.max_concurrent_agents = 3;
        raw_config.tracker.active_states.push("Review".to_string());
        raw_config
            .agent
            .max_concurrent_agents_by_state
            .insert("todo".to_string(), 1);
        raw_config
            .agent
            .max_concurrent_agents_by_state
            .insert("review".to_string(), 1);
        let config = Arc::new(RwLock::new(raw_config));
        let tracker: Arc<dyn IssueTracker> = Arc::new(MockTracker {
            issues: Arc::new(RwLock::new(vec![])),
        });
        let runner: Arc<dyn AgentRunner> = Arc::new(MockRunner {
            delay_ms: 0,
            observed_commands: None,
            observed_timeouts: None,
            cancellation_probe: None,
        });
        let config_dir = tempfile::TempDir::new().unwrap();
        let workspace_mgr = WorkspaceManager::new(config_dir.path(), None).unwrap();
        let (_shutdown_tx, shutdown_rx) = mpsc::channel(1);
        let orchestrator = Orchestrator::new(
            Arc::clone(&config),
            tracker,
            runner,
            workspace_mgr,
            config_dir.path(),
            shutdown_rx,
        );
        let issue = test_issue("1", "Todo");

        {
            let cfg = config.read().await;
            let dag = build_dag(&cfg.steps).unwrap();
            let mut run = PipelineRun::new(issue.id.clone(), 1, dag);
            run.start();
            run.mark_running("build", "session-1".to_string());
            let mut state = orchestrator.state.write().await;
            state.add_running(&issue, None);
            state.insert_pipeline_run(&issue.id, run, Arc::new(cfg.clone()));
        }
        orchestrator
            .handle_worker_exit(
                &issue.id,
                "build",
                WorkerResult::BlockedOnHuman {
                    request: InteractionRequestDraft {
                        schema_version: 1,
                        kind: InteractionKind::BrainstormPrompt,
                        blocking: true,
                        title: "Need input".to_string(),
                        body: "Choose environment".to_string(),
                        options: vec!["staging".to_string(), "production".to_string()],
                        artifacts: Vec::new(),
                    },
                },
            )
            .await;
        let interaction_id = orchestrator
            .state
            .read()
            .await
            .waiting_on_human
            .get(&issue.id)
            .unwrap()
            .interaction_request_id
            .clone();
        orchestrator
            .interaction_store
            .resolve(
                &interaction_id,
                InteractionResponse::Question {
                    response_schema_version: 1,
                    text: "staging".to_string(),
                    selected_option: Some("staging".to_string()),
                },
            )
            .await
            .unwrap();

        let peer = WorkerIdentity {
            issue_id: "2".to_string(),
            run_id: "peer-run".to_string(),
            cycle: 1,
            step_name: "build".to_string(),
            started_at: Utc::now(),
        };
        let (_, peer_completion) = watch::channel(false);
        try_reserve_worker(
            &orchestrator.cancellation_registry,
            peer.clone(),
            tokio_util::sync::CancellationToken::new(),
            peer_completion,
            3,
            1,
            StateWorkerCapacity::new(
                "Todo",
                &config.read().await.agent.max_concurrent_agents_by_state,
            ),
        )
        .unwrap();
        assert!(mark_worker_launched(
            &orchestrator.cancellation_registry,
            &peer
        ));

        orchestrator
            .resume_blocked_issue(&issue)
            .await
            .expect_err("capacity deferral must retain the waiting owner");

        let state = orchestrator.state.read().await;
        assert!(!state.is_running(&issue.id));
        assert!(state.is_waiting_on_human(&issue.id));
        assert!(matches!(
            state
                .get_pipeline_run(&issue.id)
                .unwrap()
                .step_states
                .get("build"),
            Some(StepState::BlockedOnHuman { .. })
        ));
        drop(state);
        assert!(
            orchestrator
                .interaction_store
                .get(&interaction_id)
                .await
                .unwrap()
                .unwrap()
                .awaiting_resume
        );

        let review_issue = Issue {
            state: "Review".to_string(),
            ..issue
        };
        config
            .write()
            .await
            .agent
            .max_concurrent_agents_by_state
            .remove("review");
        let review_peer = WorkerIdentity {
            issue_id: "3".to_string(),
            run_id: "review-peer-run".to_string(),
            cycle: 1,
            step_name: "build".to_string(),
            started_at: Utc::now(),
        };
        let (review_peer_complete_tx, review_peer_completion) = watch::channel(false);
        let pipeline_config = orchestrator
            .state
            .read()
            .await
            .get_pipeline_config(&review_issue.id)
            .unwrap()
            .clone();
        try_reserve_worker(
            &orchestrator.cancellation_registry,
            review_peer.clone(),
            tokio_util::sync::CancellationToken::new(),
            review_peer_completion,
            3,
            1,
            StateWorkerCapacity::new(
                "Review",
                &pipeline_config.agent.max_concurrent_agents_by_state,
            ),
        )
        .unwrap();
        assert!(mark_worker_launched(
            &orchestrator.cancellation_registry,
            &review_peer
        ));

        orchestrator
            .resume_blocked_issue(&review_issue)
            .await
            .expect_err("resume must retain the owning pipeline's state caps");
        assert!(orchestrator
            .state
            .read()
            .await
            .is_waiting_on_human(&review_issue.id));

        review_peer_complete_tx.send(true).unwrap();
        assert!(remove_completed_worker(
            &orchestrator.cancellation_registry,
            &review_peer
        ));
        orchestrator
            .resume_blocked_issue(&review_issue)
            .await
            .expect("latest reconciled state must select the next reservation bucket");

        let state = orchestrator.state.read().await;
        assert!(state.is_running(&review_issue.id));
        assert!(!state.is_waiting_on_human(&review_issue.id));
        assert!(!state.retry_attempts.contains_key(&review_issue.id));
        drop(state);
        assert_eq!(live_worker_count(&orchestrator.cancellation_registry), 2);
    }

