        write_raw_interaction(
            config_dir.path(),
            "approval-1",
            serde_json::json!({
                "id": "approval-1",
                "schema_version": 1,
                "issue_id": "1",
                "issue_identifier": "repo#1",
                "pipeline_cycle": 1,
                "completed_steps": [],
                "step_name": "build",
                "agent_name": "builder",
                "step_depends": [],
                "step_tracker_state": null,
                "kind": "approval_gate",
                "status": "resolved",
                "blocking": true,
                "awaiting_resume": true,
                "resume_strategy": "advance_after_step",
                "title": "Approve build",
                "body": "Please review the build output.",
                "options": [],
                "artifacts": [],
                "response": {
                    "kind": "approval",
                    "response_schema_version": 1,
                    "approved": false,
                    "reason": "needs more work"
                },
                "requested_at": Utc::now(),
                "resolved_at": Utc::now(),
            }),
        )
        .await;

        orchestrator.state.write().await.artifacts.insert(
            "1".to_string(),
            RunArtifacts {
                run_id: "run-1".to_string(),
                workspace_path: config_dir.path().display().to_string(),
                repos: vec![],
                transcripts: vec![],
                artifact_snapshots: Vec::new(),
                artifact_integrity_violations: Vec::new(),
                artifact_access_evidence: Vec::new(),
                gate_evidence: Default::default(),
                applied_actions: vec![crate::pipeline::engine::AppliedStepActionEvidence {
                    step: "build".to_string(),
                    identity: "action:terminal".to_string(),
                    source_output_digest: "digest-terminal".to_string(),
                    kind: "tracker_comment".to_string(),
                    receipt: "action:terminal".to_string(),
                }],
            },
        );

        orchestrator
            .resume_blocked_issue(&test_issue("1", "Todo"))
            .await
            .expect("rejected approval gate should become pending reconciliation");

